INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('József Attila összes költeménye', 'https://mek.oszk.hu/00700/00708', 'Kivettem a részemet az üzletek előtt való álldogálásokból - volt úgy, hogy este <span class="marked">kilenc órakor</span> odaálltam az élelmiszerüzem előtt várakozó sorba és reggel fél nyolckor, mikor már sorra kerültem volna, jelentették ki az orrom előtt, hogy nincs több zsír.', true, '21:00', '21:00', '21:00', 1260, 1260, 1260, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2707', 'József Attila', 'poems', 'https://mek.oszk.hu/00700/00708/html/kolto00000/kotet00718.htm', 'deep_extract', false);
