INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A lélekidomár', 'https://mek.oszk.hu/00800/00838', 'a fokhagymás felsár káposztacikával és zöldpaprikasalátával, egyszóval mindaz, amivel a kegyetlen „thugok” a vendégeiket agyon szokták fojtogatni; hozzá keresdi bor, amely mellett elbújhat minden rajnai! Leültek <span class="marked">egy órakor</span> az ebédhez, igaz magyar szokás szerint, s felkeltek fél nyolckor – ugyanazon szerint.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2837', 'Jókai Mór', 'novel', 'https://mek.oszk.hu/00800/00838/html/jokai37.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A lélekidomár', 'https://mek.oszk.hu/00800/00838', 'Leültek egy órakor az ebédhez, igaz magyar szokás szerint, s felkeltek <span class="marked">fél nyolckor</span> – ugyanazon szerint. Akkor már sötétedni kezdett, s a vendég uraknak még messzi volt hazáig. Mikor végre magukra maradának, akkor azt mondá Sidonia Lyonelnek. Ez mind igen szép volt, édes fiam; hanem mármost szeretnék', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2837', 'Jókai Mór', 'novel', 'https://mek.oszk.hu/00800/00838/html/jokai37.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Tollpihék az úton', 'https://mek.oszk.hu/11500/11570', 'A csütörtök reggel mindig bonyolultabb. A hét első felében Lizi otthonról hozott pénze segít be, de a vonatjegy, valami harapnivaló az iskolában, nagy részét elviszi. Hétfő, kedd, szerda iskola a városban. A vonat <span class="marked">háromnegyed hatkor</span> indul. Ha a hármas vonattal vissza tud jönni, be kell menni az üzletbe dolgozni, mert Terike néni elvárja. Hétfőn nincs nyitva az üzlet, ilyenkor marad idő takarításra, tanulásra. Csütörtöktől Vica borravalójából', true, '05:45', '05:45', '05:45', 345, 345, 345, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-107449', 'Kürtösi Gizella', 'short stories', 'https://mek.oszk.hu/11500/11570/html/seged/06.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Tollpihék az úton', 'https://mek.oszk.hu/11500/11570', 'akar többet fizetni, nem lehet ezt kiszámolni. Inkább átvesz egy másod éves tanulót valakitől. Annak nem kell fizetni, és állítólag ügyes. Délben még két befejezésre váró női, és három férfi vendég volt az üzletben. <span class="marked">Egy óra</span> után mentek haza. Megették a kifliket, a hazafelé vásárolt egy-egy tejföllel. Kimostak pár darab leáztatott ruhát, és indultak vissza. Este fél nyolckor tudtak bezárni, mint általában. Zárás után hazamentek. Vica', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-107449', 'Kürtösi Gizella', 'short stories', 'https://mek.oszk.hu/11500/11570/html/seged/06.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Tollpihék az úton', 'https://mek.oszk.hu/11500/11570', 'még két befejezésre váró női, és három férfi vendég volt az üzletben. Egy óra után mentek haza. Megették a kifliket, a hazafelé vásárolt egy-egy tejföllel. Kimostak pár darab leáztatott ruhát, és indultak vissza. Este <span class="marked">fél nyolckor</span> tudtak bezárni, mint általában.', true, '19:30', '19:30', '19:30', 1170, 1170, 1170, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-107449', 'Kürtösi Gizella', 'short stories', 'https://mek.oszk.hu/11500/11570/html/seged/06.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Tollpihék az úton', 'https://mek.oszk.hu/11500/11570', 'Ősz van, a fák már hullajtják leveleiket. Búcsú a nyártól, lecsó lesz. Ez sem olcsó. Amikor alkalmanként bevásárolnak a főzéshez, többe kerül, mintha ennének egy-egy menüt. Mégis luxusnak tűnik vendéglőben enni. <span class="marked">Tizenegykor</span> feküdtek le. A rádióban halkan szólt a zene. "Sajtból van a Hold, sajtból van a Hold, sajtból van a Hoold" Reggel Lizi frissen ébredt. Sokáig gondolkodott mit vegyen fel. Jól kellene kinézni. A délelőtt még nyugis', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-107449', 'Kürtösi Gizella', 'short stories', 'https://mek.oszk.hu/11500/11570/html/seged/06.htm', 'deep_extract', false);
