INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Balatoni utazás', 'https://mek.oszk.hu/04900/04924', 'Talán el is felejtették már az emberek, mi volt <span class="marked">egykor</span> a püspöki várpalota. Talán rendőr állana ottan, hogy megvédje a kéregetők tömegétől palotád nyugalmát. De ha végigmennél a Cserháton, a Buhimvölgyön, a Jeruzsálemhegy oldalán s a Csapószeren, és benéznél a sziklák', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-7456', 'Eötvös Károly', 'memoirs', 'https://mek.oszk.hu/04900/04924/html/balaton0003.html', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Balatoni utazás', 'https://mek.oszk.hu/04900/04924', 'De ha végigmennél a Cserháton, a Buhimvölgyön, a Jeruzsálemhegy oldalán s a Csapószeren, és benéznél a sziklák tövén, a hegyek oldalán s a folyó partjain épült kis házacskákba, hol <span class="marked">egykor</span> a kisiparos családja szerény jólétben élt: akkor vagy visszamennél palotádba, s háromezer szegény előtt nyitnád meg naponként szívedet és éléskamrádat, s bizony nem maradna el onnan tőled egy se – vagy visszamennél', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-7456', 'Eötvös Károly', 'memoirs', 'https://mek.oszk.hu/04900/04924/html/balaton0003.html', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Balatoni utazás', 'https://mek.oszk.hu/04900/04924', 'el Zrínyivel együtt. Annak volt egyik hadnagya. Amint ezt a költő Zrínyi Miklós megénekli. A vacsora rövid volt. Az egész napi utazás, hideg, a tapolcai nagy ebéd kissé kifárasztott bennünket. Korán lefeküdtünk. Reggel <span class="marked">hat órakor</span> megszólalt a kürt a várudvaron.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-7456', 'Eötvös Károly', 'memoirs', 'https://mek.oszk.hu/04900/04924/html/balaton0003.html', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Balatoni utazás', 'https://mek.oszk.hu/04900/04924', 'tapolcai nagy ebéd kissé kifárasztott bennünket. Korán lefeküdtünk. Reggel hat órakor megszólalt a kürt a várudvaron. Tessék fölébredni. Hét órakor újra megszólalt a kürt. Tessék früstökre megjelenni a nagy ebédlőben. <span class="marked">Fél nyolckor</span> újra teleharsogta a kürt a vár udvarát.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-7456', 'Eötvös Károly', 'memoirs', 'https://mek.oszk.hu/04900/04924/html/balaton0003.html', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Balatoni utazás', 'https://mek.oszk.hu/04900/04924', 'sültet, az italt, a jó szót és parancsot. Mint Napóleon az austerlitzi csatában. Ez volt a reggeli a sarvalyi rengetegben. Egyszerre fölharsan a kürt, előállanak a kocsik, előre, föl a sümegi várpalotába! Négykor ebéd, <span class="marked">nyolckor</span> táncvigalom. A város és környék ragyogó szépségei együtt. Hajnali három órakor tértünk nyugovóra. Mert hiszen pár óra múlva, reggeli hat órakor újra megszólal a kürt a várpalota udvarán. Újra ki a pagonyba! Így volt', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-7456', 'Eötvös Károly', 'memoirs', 'https://mek.oszk.hu/04900/04924/html/balaton0003.html', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Balatoni utazás', 'https://mek.oszk.hu/04900/04924', 'Mert hiszen pár óra múlva, reggeli <span class="marked">hat órakor</span> újra megszólal a kürt a várpalota udvarán.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-7456', 'Eötvös Károly', 'memoirs', 'https://mek.oszk.hu/04900/04924/html/balaton0003.html', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Balatoni utazás', 'https://mek.oszk.hu/04900/04924', 'nekem lakóházat, s fölöttem, a bazalttorony tetejére emeljetek egy óriási keresztet a mi Üdvözítőnk emlékezetére. És vegyétek meg nekem az elpusztult szőlőket, és tanítsátok az embereket az okos szőlőművelésre. <span class="marked">Egykor</span> az idegen nemzetek utazói ezren és százezren jönnek ide majd, hogy amikor már minden szépet láttak: minden szépséget itt együtt lássanak!', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-7456', 'Eötvös Károly', 'memoirs', 'https://mek.oszk.hu/04900/04924/html/balaton0003.html', 'deep_extract', false);
