INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Szexmozi', 'https://mek.oszk.hu/02400/02494', 'Éjfélre Bécsben leszünk, holnap reggel <span class="marked">kilenckor</span> a Mozart Hallban mi is ott leszünk egy igazi kongresszuson, igazi küldöttekként...', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4379', 'Fehér Klára', 'short stories', 'https://mek.oszk.hu/02400/02494/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Szexmozi', 'https://mek.oszk.hu/02400/02494', 'De hát sebaj, hol van még a reggel <span class="marked">kilenc óra</span>! Udvarias és kedves volt a határőrség. Udvariasan és kedvesen gratuláltak kongresszusi küldeté­sünk­höz, és kérték az iratokat. Rendben is volt minden. Útlevél, vízum, megbízólevél, ilyen engedély, olyan engedély. -', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4379', 'Fehér Klára', 'short stories', 'https://mek.oszk.hu/02400/02494/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Szexmozi', 'https://mek.oszk.hu/02400/02494', '- A kongresszus holnap reggel <span class="marked">kilenckor</span> kezdődik a Mozart Hallban. Nekünk, mint a magyar ifjúság képviselőinek... - Menjenek vonaton - tanácsolta újra barátságosan a határőr. - És hol a vonat? - Várjanak csak. Félóra. Egy óra. Másfél óra. Komoran, leszegett', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4379', 'Fehér Klára', 'short stories', 'https://mek.oszk.hu/02400/02494/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Szexmozi', 'https://mek.oszk.hu/02400/02494', '- A kongresszus holnap reggel kilenckor kezdődik a Mozart Hallban. Nekünk, mint a magyar ifjúság képviselőinek... - Menjenek vonaton - tanácsolta újra barátságosan a határőr. - És hol a vonat? - Várjanak csak. Félóra. <span class="marked">Egy óra</span>. Másfél óra. Komoran, leszegett fejjel ülünk a tintapacnis íróasztal körül. A szomszéd szobában izgatott német nyelvű telefonálás. Feri háttal ül nekünk, mi nem merünk hozzá szólni. A határőrparancsnok visszajön.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4379', 'Fehér Klára', 'short stories', 'https://mek.oszk.hu/02400/02494/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Szexmozi', 'https://mek.oszk.hu/02400/02494', 'A vonat különben egy óra múlva indul, és <span class="marked">tizenegykor</span> Bécsben lesz. - Tizenegykor? Hiszen a kongresszus kilenckor... - Akkor menjetek gyalog - felelte Erzsi sértődötten. Beláttuk, hogy igaza van, és elfogadtuk a csempészek feltételeit. Felragadtuk cókmókunkat, amelyet az', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4379', 'Fehér Klára', 'short stories', 'https://mek.oszk.hu/02400/02494/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Szexmozi', 'https://mek.oszk.hu/02400/02494', 'akik azt üzenik, hogy nyugodtan felszállhatunk mi is, de csak akkor, ha olyan halkan jövünk, hogy nem hozzuk a nyakukra a határőrséget. A vonat különben egy óra múlva indul, és tizenegykor Bécsben lesz. - <span class="marked">Tizenegykor</span>? Hiszen a kongresszus kilenckor... - Akkor menjetek gyalog - felelte Erzsi sértődötten. Beláttuk, hogy igaza van, és elfogadtuk a csempészek feltételeit. Felragadtuk cókmókunkat, amelyet az eső alaposan átjárt, és', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4379', 'Fehér Klára', 'short stories', 'https://mek.oszk.hu/02400/02494/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Szexmozi', 'https://mek.oszk.hu/02400/02494', 'nyugodtan felszállhatunk mi is, de csak akkor, ha olyan halkan jövünk, hogy nem hozzuk a nyakukra a határőrséget. A vonat különben egy óra múlva indul, és tizenegykor Bécsben lesz. - Tizenegykor? Hiszen a kongresszus <span class="marked">kilenckor</span>... - Akkor menjetek gyalog - felelte Erzsi sértődötten. Beláttuk, hogy igaza van, és elfogadtuk a csempészek feltételeit. Felragadtuk cókmókunkat, amelyet az eső alaposan átjárt, és mázsányi súlyúvá tett, és', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4379', 'Fehér Klára', 'short stories', 'https://mek.oszk.hu/02400/02494/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Szexmozi', 'https://mek.oszk.hu/02400/02494', 'hogy csekély ajándékként fogadják szeretettel... - A, ajándékot nem illik elkérni - mondta Erzsi -, majd mi is úgy csinálunk, mintha nem tudnánk a vázáról, meg ők is... Dél volt, és a vonat még mindig nem ért Bécsbe. <span class="marked">Fél egykor</span> kisült, hogy soha nem is fog.', true, '00:30', '00:30', '00:30', 30, 30, 30, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4379', 'Fehér Klára', 'short stories', 'https://mek.oszk.hu/02400/02494/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Szexmozi', 'https://mek.oszk.hu/02400/02494', 'még nem döntöttem, melyiktek, lemegy a csónakhoz. Civil ruhában. Mintha ember volna. Egy korsó vizet és egy kenyeret tesz a csónakba. És este hatig azt csinálhat, amit akar. A másik itt áll az ablakban, és nézi. Este <span class="marked">hatkor</span>, amikor a harang megszólal, itt lesz újra.', true, '18:00', '18:00', '18:00', 1080, 1080, 1080, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4379', 'Fehér Klára', 'short stories', 'https://mek.oszk.hu/02400/02494/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Szexmozi', 'https://mek.oszk.hu/02400/02494', 'újra, uram... Én... KURT Ez szép... és te? AZ ÖREG Én megszöknék. KURT Uram, vagy szájon váglak. Nocsak... nem, nem, tőlem mondhatod, ahogy akarod. Nem vagy ember, féreg vagy, egy féreg, azt nyüszít, amit tud. Te már <span class="marked">fél hatkor</span> itt lennél... ÖREG Nem. Én megmondtam, hogy megszöknék. KURT Ez izgalmas. Hiszen azt sem tudod, nyomorult, hogy hol vagy. AZ ÖREG Hogyne tudnám, amikor én mindent tudok. Nekem barátom a szél, a tenger, még a legvadabb', true, '05:30', '05:30', '05:30', 330, 330, 330, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4379', 'Fehér Klára', 'short stories', 'https://mek.oszk.hu/02400/02494/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Szexmozi', 'https://mek.oszk.hu/02400/02494', 'órát eveznék Igoumenica felé, azt mondanám, Leonidasz, és utána szabadon járnék újra a mi drága hegyeinkben, ahol kék méhkasokban méhek gyűjtik a mézet, ahol a források vize tiszta, ahol énekelni lehet. KURT Pontosan <span class="marked">hat óra egy perckor</span> a társadat odaállítanám a kolostorudvar falához.', true, '06:01', '06:01', '06:01', 361, 361, 361, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4379', 'Fehér Klára', 'short stories', 'https://mek.oszk.hu/02400/02494/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Szexmozi', 'https://mek.oszk.hu/02400/02494', 'és mindenki rádobna egy követ. Egy olyan kicsit. Félkilósat, kétkilósat. Egyenként. Amíg elcsendesedik. A FIATAL Én... uram... én csak fürdeni szeretnék... én itt volnék pontosan hatra, háromnegyed hatra... én már <span class="marked">háromnegyed hatkor</span> itt volnék, csak egypár szem fügét ennék és visszajönnék, nektek is hoznék narancsot, elhoznám, és együtt ennénk meg.', true, '05:45', '05:45', '05:45', 345, 345, 345, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4379', 'Fehér Klára', 'short stories', 'https://mek.oszk.hu/02400/02494/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Szexmozi', 'https://mek.oszk.hu/02400/02494', 'nem fogom még egyszer látni a csillagokat. Jövőre cseresznyék fognak érni a fán. Hogyhogy én már nem eszem cseresznyét?" Ez a költő tetszett nekem. Ezt majd külön beleírom a tanulmányomba. (Két harangkondulás.) KURT <span class="marked">Fél hat</span> van. Szürkül. Egyszer kivégeztettem egy tanítót. Valami kétértelmű dalt énekeltetett az iskolában. Holmi elnyomókról locsogott. Tulajdonképpen megkegyelmeztem volna neki. Aznap már untam a kivégzést. Azt mondtam:', true, '05:30', '05:30', '05:30', 330, 330, 330, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4379', 'Fehér Klára', 'short stories', 'https://mek.oszk.hu/02400/02494/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Szexmozi', 'https://mek.oszk.hu/02400/02494', 'Nem nekem ígérte, hanem neked. A te halálod árán szökött meg. Átkozd meg, görög, még van egy perc időd, hogy megátkozd. AZ ÖREG Boldog vagyok, hogy megértette a parancsot. KURT Félrebeszélsz? Hallod a harangot? <span class="marked">Hat óra</span> van! Hallod, hogyan kondul? Nem iszonyodsz? A halálharangod. AZ ÖREG Hallom a harangot. Ünnepet hirdet. Közülünk egy megmenekült. (A harangszó egyre erősebb.) Furcsa éjszaka Szín: elhagyott fogadó a francia Riviérán.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4379', 'Fehér Klára', 'short stories', 'https://mek.oszk.hu/02400/02494/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Szexmozi', 'https://mek.oszk.hu/02400/02494', 'ÁKOS Elhoztam a meghívókat, holnap reggel <span class="marked">fél nyolckor</span>... COLLE Mondtam, hogy ne gyere ide! ÁKOS Már megbocsáss, ha én nem félek veled találkozni... COLLE Hogy érted ezt? ÁKOS Jól tudod. Kettőnk közül, ha valakinek oka van rá, hogy kerülje a másikat... COLLE Nem fogsz', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4379', 'Fehér Klára', 'short stories', 'https://mek.oszk.hu/02400/02494/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Szexmozi', 'https://mek.oszk.hu/02400/02494', 'Akkor is játszhat babával..." A gyerekek hat órára ígérkeztek, de <span class="marked">negyed kilenc</span> után jöttek csak. Gyuri rögtön végigterült a vászonhuzatos fotelon, lábát egy székre rakta, és az újsággal legyezte magát. - Micsoda hőség van, mama! És milyen fáradt vagyok. - Most pedig ne legyél fáradt. Mit szólsz', true, '08:15', '08:15', '08:15', 495, 495, 495, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4379', 'Fehér Klára', 'short stories', 'https://mek.oszk.hu/02400/02494/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Szexmozi', 'https://mek.oszk.hu/02400/02494', 'dolgozni, legalább számolhatnak vele. Hát mondja, mama, azért végeztem el az egyetemet, hogy minden derékba törjön? Huszonnégy éves vagyok, még várhattunk volna... A mama nem felel erre, mit is feleljen? De amikor <span class="marked">tizenegy óra</span> tájban elmennek, nem tud lefeküdni, csak ül az asztalnál, ölbe ejtett kézzel, és nézi a szobát, külön-külön minden bútordarabot, a kis könyvespolcot, a fiókos szek­rényt, a rádiót, a horgolt terítőt a kisasztalon.', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4379', 'Fehér Klára', 'short stories', 'https://mek.oszk.hu/02400/02494/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Szexmozi', 'https://mek.oszk.hu/02400/02494', 'felé kérnek vacsorát. Ugye nem haragszik a mama, nincs semmi különös programja? Nem, persze hogy nem haragszik, persze hogy nincs. És most félredobja a lejárt bérletet. Nem, ősszel semmi esetre sem vált újat. A mama <span class="marked">hat órakor</span> már lenn van a tejesnél. De akárhogy igyekszik, csak nyolcadik-tizedik a sorban. Előtte is csupa nagymama áll, tejesüveggel, piros zománcú fazékkal, bevásárlókosárral felszerelve, aggódva pislognak a villanyóra sebes', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4379', 'Fehér Klára', 'short stories', 'https://mek.oszk.hu/02400/02494/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Szexmozi', 'https://mek.oszk.hu/02400/02494', 'is csupa nagymama áll, tejesüveggel, piros zománcú fazékkal, bevásárlókosárral felszerelve, aggódva pislognak a villanyóra sebes mutatójára, és szótlanul hallgatják az utánuk érkező fiatalok morgását. "Jöjjenek maguk <span class="marked">nyolc óra</span> után, mi dolgozók vagyunk." A mama felforralja a tejet, tálcára rakja a friss kiflit és a kék szélű csészéket.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4379', 'Fehér Klára', 'short stories', 'https://mek.oszk.hu/02400/02494/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Szexmozi', 'https://mek.oszk.hu/02400/02494', '- De igazán, úgy röstellem, a világoskék blúzt szeretném felvenni, elfelejtettem rávarrni a gallért, a fehér blúzom már nem megy rám, és <span class="marked">fél nyolckor</span> osztályértekezlet. - Jó, add csak ide. Másnap reggel: - Ugye nem haragszik, drága mama, de Gyurinak nincs stoppolt zoknija, a mama inkább ráér... És a mama megstoppolja a zoknit, beszegi a szoknyát, összeszedi a', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4379', 'Fehér Klára', 'short stories', 'https://mek.oszk.hu/02400/02494/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Szexmozi', 'https://mek.oszk.hu/02400/02494', 'igen, egy... egy szép ruháravalót... már odaadtam a szabóhoz - feleli, és piros lesz, mint a pipacs. Petényiné elmegy, a mama áll, nézi a rózsát, szegfűt, ötvenéves... Gyuriék se felejtették el a születésnapot. Este <span class="marked">kilenckor</span> moziba mentek. (A mamának majd azt mondják, hogy értekezleten voltak, nem szabad szegényt megbántani.) De még jóval mozi előtt találkoztak, fél hatkor, amikor az áruházak még nyitva vannak. Egymásba karolva végigjárták', true, '21:00', '21:00', '21:00', 1260, 1260, 1260, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4379', 'Fehér Klára', 'short stories', 'https://mek.oszk.hu/02400/02494/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Szexmozi', 'https://mek.oszk.hu/02400/02494', '(A mamának majd azt mondják, hogy értekezleten voltak, nem szabad szegényt megbántani.) De még jóval mozi előtt találkoztak, <span class="marked">fél hatkor</span>, amikor az áruházak még nyitva vannak.', true, '05:30', '05:30', '05:30', 330, 330, 330, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4379', 'Fehér Klára', 'short stories', 'https://mek.oszk.hu/02400/02494/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az Északi-Park felfedezése', 'https://mek.oszk.hu/02100/02122', 'Az órájára nézett, amely átmenetileg éppen járt és csaknem felkiáltott ijedtében: <span class="marked">kilenc óra</span> volt! Lecsatolta a talpakat s az ajtóhoz rohant. Az ajtó be volt zárva! A pedellus éjszakára bezárta az ajtókat! Borzalom! Müller sírvafakadt ijedtében. Az ablakokat vasrács védte. Kiabálni kezdett. A falak', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Gyermek- és ifjúsági irodalom"}', 'urn:nbn:hu-4105', 'Aszlányi Károly', 'short novel', 'https://mek.oszk.hu/02100/02122/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az Északi-Park felfedezése', 'https://mek.oszk.hu/02100/02122', 'ablakokat vasrács védte. Kiabálni kezdett. A falak visszaverték a hangját, de senki sem hallotta. Az épület koromsötét és teljesen néma volt. Szegény Müller hol az ajtókat döngette, hol a sarokban ült és a hideg rázta. <span class="marked">Háromnegyed tizenegy</span> körül elaludt. Hirtelen felébredt, mert azt álmodta, hogy indul a bécsi gyors és ő lemarad! Ez a lehetőség nem is volt olyan valószínűtlen. Felugrott és egyre fokozódó kétségbeeséssel ütötte-verte az ajtót és', true, '10:45', '10:45', '10:45', 645, 645, 645, '{"Szépirodalom, népköltészet","Gyermek- és ifjúsági irodalom"}', 'urn:nbn:hu-4105', 'Aszlányi Károly', 'short novel', 'https://mek.oszk.hu/02100/02122/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az Északi-Park felfedezése', 'https://mek.oszk.hu/02100/02122', 'a pillanatban, amikor a szalámi. Az éhség csodát művel. 2. Amint leértünk a faluba, pengő fülekkel, vörös orral, már a második ház falán hatalmas, kézzel festett plakátot láttunk: BIKAVIADAL ALMENHOFBAN! Kezdete <span class="marked">8 órakor</span> A NAGYVENDÉGLŐ SZÍNPADÁN. Belépődíj 30 garas. - De már erre kíváncsi vagyok! - mondta a tanár úr. És mondhatom, mi is kíváncsiak vagyunk. Üsti szerint csaknem elképzelhetetlen, hogy az osztrákok ilyesmit csináljanak.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Gyermek- és ifjúsági irodalom"}', 'urn:nbn:hu-4105', 'Aszlányi Károly', 'short novel', 'https://mek.oszk.hu/02100/02122/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az Északi-Park felfedezése', 'https://mek.oszk.hu/02100/02122', 'vagyunk. Üsti szerint csaknem elképzelhetetlen, hogy az osztrákok ilyesmit csináljanak. Megkérdeztük Müllert, aki egész nap itthon volt, hogy mit hallott a bikaviadalról, de Müller nem hallott semmit. 3. Este, már <span class="marked">fél nyolckor</span>, valóságos népvándorlás indult a Nagyvendéglő felé.', true, '19:30', '19:30', '19:30', 1170, 1170, 1170, '{"Szépirodalom, népköltészet","Gyermek- és ifjúsági irodalom"}', 'urn:nbn:hu-4105', 'Aszlányi Károly', 'short novel', 'https://mek.oszk.hu/02100/02122/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az Északi-Park felfedezése', 'https://mek.oszk.hu/02100/02122', 'A tegnap esti rendezőtől elkértem a nevezési listát s azon tényleg rajta volt Müller: "elindult <span class="marked">4 óra 20 perckor</span>." Hát ez csodálatos! A délelőtt folyamán havi kétszáz schilling fizetést ajánlott a községi tanács Müllernek, aminek fejében csupán annyi dolga lenne, hogy évente három hónapig Jedlerbergben lakjon ingyen. Müller már', true, '04:20', '04:20', '04:20', 260, 260, 260, '{"Szépirodalom, népköltészet","Gyermek- és ifjúsági irodalom"}', 'urn:nbn:hu-4105', 'Aszlányi Károly', 'short novel', 'https://mek.oszk.hu/02100/02122/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az Északi-Park felfedezése', 'https://mek.oszk.hu/02100/02122', 'harmadik elöl emelte és így simán visszatették a vágányra. Közben azonban kifolyt a víz a kazánból és a hó teljesen belepte a vonatot. Megkérdeztük a kalauzt, mennyi idő kell ahhoz, hogy sítalpakon Almenhofba érjünk. - <span class="marked">Egy óra</span> - felelte. Elindultunk tehát. Mintegy félóra hosszat küzködtünk az ellenszéllel és sűrű hóval, amikor egy szintén sítalpakon futó benszülöttel találkoztunk. Megkérdeztük tőle: - Mondja bácsi, mennyire van még', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Gyermek- és ifjúsági irodalom"}', 'urn:nbn:hu-4105', 'Aszlányi Károly', 'short novel', 'https://mek.oszk.hu/02100/02122/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az Északi-Park felfedezése', 'https://mek.oszk.hu/02100/02122', 'erről. A tanár úr megmérte Müller lázát és - én nem tudom, hogy csinálta az a csirkefogó -, de tényleg láza volt. - Nehogy fel merj kelni! - így búcsúzott a tanár úr tőle. És Müller nem felelt, csak nyögött. Már <span class="marked">hat órakor</span> Üsti, Gomb és a tanár úr, gálaruhában persze, elindultak a panzió felé.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Gyermek- és ifjúsági irodalom"}', 'urn:nbn:hu-4105', 'Aszlányi Károly', 'short novel', 'https://mek.oszk.hu/02100/02122/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az Északi-Park felfedezése', 'https://mek.oszk.hu/02100/02122', 'diák, akik vakációra jöttek haza. Ezeknek a puskája vizet fecskendezett és ennél kellemetlenebb harcmodort el se lehet képzelni, tekintve, hogy a víz mindjárt megfagy az ember bőrén és ruháján. Ez a támadás reggel <span class="marked">fél nyolckor</span> zajlott le és teljesen készületlenül talált minket.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Gyermek- és ifjúsági irodalom"}', 'urn:nbn:hu-4105', 'Aszlányi Károly', 'short novel', 'https://mek.oszk.hu/02100/02122/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Animus és Anima', 'https://mek.oszk.hu/03800/03894', 'hová megy? ORVOS A kórházba... vagy haza... mindegy, rám nem lehet számítani... GIZELLA Vasárnap sem... hétvégeken? ORVOS Az mindegy... koncertre sem járok, mert pontosan kezdődik... hétkor az operában... az Akadémián <span class="marked">fél nyolckor</span>... a partitúra pedig akkor, amikor kinyitom... GIZELLA Hogy? Maga olvassa a zenét? ORVOS (mosolyog) Ühüm... GIZELLA És hallja? ORVOS Évekig zongoráztam... De ne rólam beszéljünk... Reggel mutatni akart valamit...', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-5884', 'Kiss Csaba', 'plays', 'https://mek.oszk.hu/03800/03894/03894.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Animus és Anima', 'https://mek.oszk.hu/03800/03894', 'Én őszinte ember vagyok... Figyel? GIZELLA Figyelek... KÖNIG Ma olyan különleges, vidám nap van... kár lenne ágybavinni ezt a jókedvet... egyetért velem? GIZELLA Ühüm. KÖNIG Jöjjön el velem vacsorázni, ma este... <span class="marked">fél nyolckor</span> magáért jövök, utána hazakísérem.', true, '19:30', '19:30', '19:30', 1170, 1170, 1170, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-5884', 'Kiss Csaba', 'plays', 'https://mek.oszk.hu/03800/03894/03894.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Animus és Anima', 'https://mek.oszk.hu/03800/03894', 'GIZELLA Valaki jön! (kinéz a folyosóra) ANIMUS Nem jön senki. GIZELLA Megnézem, hátha ő az... Csak ide megyek a lépcsőfordulóig... (kimegy, eltűnik pár pillanatra, visszajön) Pedig tisztán hallottam. ANIMUS (feláll) <span class="marked">Negyed nyolc</span>. GIZELLA (halk fájdalommal) Becsukom az ajtót... Körülnéz a szobában, hogy minden rendben van-e. Elfújja a gyertyákat, a gyertyatartót visszateszi az éjjeliszekrényre. Odalép Animushoz, szorosan elé áll, testük már-már', true, '07:15', '07:15', '07:15', 435, 435, 435, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-5884', 'Kiss Csaba', 'plays', 'https://mek.oszk.hu/03800/03894/03894.htm', 'deep_extract', false);
