INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Babett hazudik', 'https://mek.oszk.hu/17100/17101', 'van. Szerintem nem akar hazamenni. SIMON - Kicsoda? NINA - Az új lány. Valami Babszi. Vagy Betti. Elfelejtettem. Minket néz. SIMON - Én meg se jegyeztem. De szar megint suliba járni. Hogy unom. Utálom. Hé, mindjárt <span class="marked">hat óra</span>! NINA - Te engem csókolgatsz, közben meg az eget lesed? SIMON - Tudok kétfelé figyelni, semmi gond. NINA - De ez pofátlanság. Mit képzelsz? SIMON - Jaj, de kis nebáncsvirág vagy, te Jóisten... NINA - Ezt ne, nem', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-142024', 'Németh Ákos', 'plays', 'https://mek.oszk.hu/17100/17101/17101.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Babett hazudik', 'https://mek.oszk.hu/17100/17101', 'BABETT - Szóval el akartok hozzánk jönni? Mondjuk, most este nincs otthon senki. KARIN - Hülye vagy? BABETT - Igazán akartok? KARIN - Naná. Jacuzzi, meg hangterápiás szauna, vagy milyen. Király. BABETT - Na jó. Este <span class="marked">fél nyolckor</span> gyertek a recepcióra. SIMON - És ott mit mondjunk? NINA - Ezt te kérded? Mondjuk, elég lenne, ha köszönnél néha. SIMON - Egyszer nem köszöntem anyádnak, egyszer! Úristen... NINA - Ilyenkor persze mindig ölelgetsz. Vedd', true, '19:30', '19:30', '19:30', 1170, 1170, 1170, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-142024', 'Németh Ákos', 'plays', 'https://mek.oszk.hu/17100/17101/17101.htm', 'deep_extract', false);
