INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az auschwitzi fényképész várja az első turnust. Megérkeznek, kiadja az első parancsot: mosolyogni!', 'https://mek.oszk.hu/15800/15849', 'Fejben átgondolta a szomszéd életmódját: napi két üveg rum, két liter bor, s <span class="marked">16 óra</span> a számítógép előtt, semmi mozgás, de láncdohányzás igen.', true, '16:00', '16:00', '16:00', 960, 960, 960, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-136767', 'Kerekes Tamás', 'short stories', 'https://mek.oszk.hu/15800/15849/15849.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az auschwitzi fényképész várja az első turnust. Megérkeznek, kiadja az első parancsot: mosolyogni!', 'https://mek.oszk.hu/15800/15849', 'Az író adott. Aztán pénze fogytán, reggel el-elküldte Bélát (ki valaha nehézsúlyú ökölvívó volt) bevásárolni. Béla két alkalommal nem tudott a pénzzel elszámolni. Harmadszorra is ez történt. Béla útnak eredt <span class="marked">fél nyolckor</span>, hogy a romhányi vetőmagboltból vetőkrumplit, és dughagymát hozzon.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-136767', 'Kerekes Tamás', 'short stories', 'https://mek.oszk.hu/15800/15849/15849.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az auschwitzi fényképész várja az első turnust. Megérkeznek, kiadja az első parancsot: mosolyogni!', 'https://mek.oszk.hu/15800/15849', 'állapítottak meg, két csomó is volt a nyakán, már olyan későn fordult orvoshoz, hogy műteni nem lehetett. Kemoterápiát kapott több alkalommal, de megmondták neki az orvosok, hogy áttétek keletkeztek a tüdőben. Az <span class="marked">egykor</span> izmos negyvenes férfi két hónap alatt lett aszott haldokló.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-136767', 'Kerekes Tamás', 'short stories', 'https://mek.oszk.hu/15800/15849/15849.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az auschwitzi fényképész várja az első turnust. Megérkeznek, kiadja az első parancsot: mosolyogni!', 'https://mek.oszk.hu/15800/15849', 'Egy hétköznapi nap a hajléktalanszállón Mindenki máskor kel, de a csődület a mikrosütő (grill) mellett <span class="marked">fél nyolckor</span> tetőzik. Ez ahhoz kell, hogy az ember a neszkávéjához megmelegítse a vizet. Mindenki igyekszik, noha még a zöme kába az álmatlanságtól, vagy a másnaposságtól. A reggeli kávézás jó alkalom, hogy megtárgyalják, hogy az', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-136767', 'Kerekes Tamás', 'short stories', 'https://mek.oszk.hu/15800/15849/15849.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az auschwitzi fényképész várja az első turnust. Megérkeznek, kiadja az első parancsot: mosolyogni!', 'https://mek.oszk.hu/15800/15849', 'vizet. Mindenki igyekszik, noha még a zöme kába az álmatlanságtól, vagy a másnaposságtól. A reggeli kávézás jó alkalom, hogy megtárgyalják, hogy az éjjel kitől mi tűnt el, sűrű harákolás közben. Reggeli még nincs, csak <span class="marked">nyolckor</span> nyit a Vöröskereszt épülete, ahol a reggelit adják.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-136767', 'Kerekes Tamás', 'short stories', 'https://mek.oszk.hu/15800/15849/15849.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az auschwitzi fényképész várja az első turnust. Megérkeznek, kiadja az első parancsot: mosolyogni!', 'https://mek.oszk.hu/15800/15849', 'Szürkeség A hajléktalanszálló <span class="marked">hatkor</span> ébredezik. Abban a szobában, ahol egy fedél alatt tizenkét ember lakik, aligha marad titok. Mindenki tudja, hogy a másiknak hány krajcár kuncog a zsebében. Egyedüllétre nincs esély, még a wc-n sem, ahol nem választják', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-136767', 'Kerekes Tamás', 'short stories', 'https://mek.oszk.hu/15800/15849/15849.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az auschwitzi fényképész várja az első turnust. Megérkeznek, kiadja az első parancsot: mosolyogni!', 'https://mek.oszk.hu/15800/15849', 'jól jöhet valamilyen összehasonlításban. A kollégiumnak általában nyugdíjas éjszakai portásai voltak. Köztük a kedvencem alighanem a Laci bácsi volt. Ő nem cifrázta a dolgot, saját demizsonjával járt el dolgozni. ESTE <span class="marked">KILENCKOR</span> JÖTT EL A KÖTELEZŐ LÁMPAOLTÁS.', true, '21:00', '21:00', '21:00', 1260, 1260, 1260, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-136767', 'Kerekes Tamás', 'short stories', 'https://mek.oszk.hu/15800/15849/15849.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az auschwitzi fényképész várja az első turnust. Megérkeznek, kiadja az első parancsot: mosolyogni!', 'https://mek.oszk.hu/15800/15849', 'Ennek sok értelme nem volt, mert este <span class="marked">nyolckor</span> jött a váltás, megjött Kati gondozónő, a legfajsúlyosabb egyéniség a garnitúrából, állandóan azt hajtogatva, hogy lelkészi diplomája van, és tulképp neki kéne a kócerájt irányítania, s kihajintotta az éjszakai szállásra készülő Andrást.', true, '20:00', '20:00', '20:00', 1200, 1200, 1200, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-136767', 'Kerekes Tamás', 'short stories', 'https://mek.oszk.hu/15800/15849/15849.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az auschwitzi fényképész várja az első turnust. Megérkeznek, kiadja az első parancsot: mosolyogni!', 'https://mek.oszk.hu/15800/15849', 'A memoire egyik példányát Walton kívánságára kötötték saját bőrébe és juttatták el <span class="marked">egykor</span> kiszemelt áldozatához. Azt sajnos nem tudni, hogy mennyi irónia volt e kívánságban, de talán megfordult John fejében, hogy legközelebb inkább mellőzi az ellenállást". Így fonódik össze dermatológia és nyomdászat R.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-136767', 'Kerekes Tamás', 'short stories', 'https://mek.oszk.hu/15800/15849/15849.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Szexmozi', 'https://mek.oszk.hu/02400/02494', 'Arnold bácsi minden délben pontosan <span class="marked">egy órakor</span> felkapaszkodott hozzánk a harmadik emeletre, anyunak kezet csókolt, azt mondta, ha nem volna ilyen remek a főztje, akkor sosem mászna meg ezt a három dög emeletet.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4379', 'Fehér Klára', 'short stories', 'https://mek.oszk.hu/02400/02494/html/04.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Szexmozi', 'https://mek.oszk.hu/02400/02494', 'és mindenkorra abbahagynám az írást (majd azért még megérdeklődöm, melyik kritikus rokona a főorvos úrnak!), mindenesetre jöjjek vissza holnap reggel. A gézt le is szedte a karomról, bedobta a szemétvödörbe. Este <span class="marked">fél nyolckor</span> újra benn voltam a tévében. - Mi van a karjával? - kérdezte a rendező. - Kösz a kedves érdeklődést. Hydrocortisont... - A fene érdeklődik. Hol a gipsz? Hol a kötés? - Nem kell. - Mi az, hogy nem kell? Ez a kezdő', true, '19:30', '19:30', '19:30', 1170, 1170, 1170, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4379', 'Fehér Klára', 'short stories', 'https://mek.oszk.hu/02400/02494/html/04.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Szexmozi', 'https://mek.oszk.hu/02400/02494', 'se kell... A rejtélyes harmadik Az üdülő éttermében a 47-es asztalnál ültünk. Az asztalon három teríték volt. De - bár negyedik napja nyaraltunk - a harmadik asztaltárssal még egyszer sem találkoztunk. Ha pontosan <span class="marked">egy órakor</span> mentünk ebédelni - vagy ha fél kettőre -, az ismeretlen tányérja még érintetlen volt.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4379', 'Fehér Klára', 'short stories', 'https://mek.oszk.hu/02400/02494/html/04.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Szexmozi', 'https://mek.oszk.hu/02400/02494', 'között ott élt Tennessee Williams, ott játszódnak drámái a Mississippi-delta erkélyes, emeletes, fehér ültetvényes házaiban, ott van a Vágy Utcája, ott játszódik legszívbemarkolóbb drámája, A vágy villamosa is. Este <span class="marked">tizenegykor</span> indult a busz Atlantából. Elneveztük a Vágy Autóbuszának. Egész éjszaka törődtünk, zötykölődtünk, hánykolódtunk, fel-felriadtunk. Reggel kilenckor hullafáradtan meg­érkeztünk New Orleansba. Úgy-ahogy rendbe szedtük', true, '23:00', '23:00', '23:00', 1380, 1380, 1380, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4379', 'Fehér Klára', 'short stories', 'https://mek.oszk.hu/02400/02494/html/04.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Szexmozi', 'https://mek.oszk.hu/02400/02494', 'ott játszódik legszívbemarkolóbb drámája, A vágy villamosa is. Este tizenegykor indult a busz Atlantából. Elneveztük a Vágy Autóbuszának. Egész éjszaka törődtünk, zötykölődtünk, hánykolódtunk, fel-felriadtunk. Reggel <span class="marked">kilenckor</span> hullafáradtan meg­érkeztünk New Orleansba.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4379', 'Fehér Klára', 'short stories', 'https://mek.oszk.hu/02400/02494/html/04.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Szexmozi', 'https://mek.oszk.hu/02400/02494', 'Délután kettőkor pedig üljünk <span class="marked">fel egy</span> városnéző autóbuszra, úgy ismerkedjünk meg a szárazföldi nevezetességekkel.', true, '12:30', '12:30', '12:30', 750, 750, 750, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4379', 'Fehér Klára', 'short stories', 'https://mek.oszk.hu/02400/02494/html/04.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'Anne Frank naplója Anne Frank naplója (A hátsó traktus) Fordította F. Solti Erzsébet A versbetéteket fordította Frank László 1942. június 14, vasárnap Pénteken, június 12-én már reggel <span class="marked">hatkor</span> felébredtem. Érthető, hiszen akkor volt a születésnapom. Ilyen korán azonban nem szabad felkelnem. Háromnegyed hétig legyőztem hát a kíváncsiságomat, de tovább nem bírtam. Kiugrottam az ágyból s besiettem az ebédlőbe.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'Eszerint én valamiféle ébresztőszer vagyok számára. Ja, senki sem tudhatja, mi mindenre nem alkalmas. Szombaton nálunk aludt Jopie, vasárnap azonban Liesnél volt, s én rettentően unatkoztam. Harryt estére vártam, de <span class="marked">hat órakor</span> felhívott: - Itt Harry Goldberg.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'Sétálni mentünk, és bizony tíz perccel elmúlt már <span class="marked">nyolc óra</span>, amikor hazaértünk. Apa nagyon haragudott, szerinte illetlenség ilyenkor hazajönni, ezenkívül zsidóknak nyolc óra után veszedelmes az utcán járni. Megígértem, hogy ezentúl tíz perccel nyolc előtt otthon leszek. Harry', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'Apa nagyon haragudott, szerinte illetlenség ilyenkor hazajönni, ezenkívül zsidóknak <span class="marked">nyolc óra</span> után veszedelmes az utcán járni.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'nevű, harminc év körüli embernek, aki ezen az estén - nem lévén jobb dolga - körülbelül tíz óráig nálunk ténfergett, s noha igyekeztünk udvariasan tudtára adni, hogy felesleges, képtelenek voltunk szabadulni tőle. <span class="marked">Tizenegy óra</span> tájban megérkezett Miep és férje, Henk van Santen.', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'hát kit érdekelt ez akkor? Margot teletömte iskolakönyvekkel a táskáját, kihozta a garázsból a kerékpárját s Miep mögött elkarikázott előttem ismeretlen tájak felé. Én ugyanis még mindig nem tudtam, hová visz az utunk. <span class="marked">Fél nyolckor</span> végül mi is becsuktuk magunk mögött az ajtót.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'Van Daan a következőket mesélte: - Hétfő reggel <span class="marked">kilenc órakor</span> Goudsmit úr felhívott telefonon és kért, hogy keressem fel.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'Őnagysága igazat adott anyának, de elvileg helytelennek tartotta, hogy serdülő korban levő gyerekek felnőtteknek való könyveket olvassanak. Peter közben kileste, hogy mikor juthat észrevétlenül a könyvhöz. Este <span class="marked">fél nyolckor</span>, amikor az egész család rádiót hallgatott a főnöki szobában, felsurrant kincsével a padlásra.', true, '19:30', '19:30', '19:30', 1170, 1170, 1170, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'még ennél is tízszer rosszabb. Háromnapi lapítás után már fájt és teljesen elzsibbadt a hátsórészem; csak az esti torna segített rajta. Anned 1942. október 1, csütörtök Drága Kittym! Tegnap szörnyen megijedtem. Este <span class="marked">nyolckor</span> hirtelen erélyesen csengettek.', true, '20:00', '20:00', '20:00', 1200, 1200, 1200, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'Ma reggel igen korán keltem, mert Henknek már <span class="marked">fél nyolckor</span> el kellett mennie. Kedélyes reggelizés után Miep is lement. Kint ömlött az eső, és Miep boldog volt, hogy nem kellett hazulról az irodába kerékpároznia. Jövő héten Elli marad nálunk éjszakára. Anned 1942. október 29,', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'A legnagyobb meglepetést Van Daan úr szerezte, aki <span class="marked">egy órakor</span> elújságolta, hogy az angolok partra szálltak Tuniszban, Algírban, Casablancában és Oranban.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'kezelheti. Mire való ez a halogatás? Szerintem helytelen, hogy apa ebbe belement. Máskülönben semmi újság. Anned 1942. november 17, kedd Drága Kittym! Dussel megérkezett. Minden jól sikerült. Miep meghagyta neki, hogy <span class="marked">tizenegy órakor</span> legyen a megbeszélt helyen a postahivatal előtt, s onnan majd egy férfi tovább kíséri.', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'Csendes órák: Este tíztől reggel <span class="marked">fél nyolc</span> óráig. Vasárnaponként negyed tizenegyig. Csendes órákat a körülményekre való tekintettel az igazgatóság napközben is elrendelhet. A közbiztonság érdekében a csendes órák szigorúan betartandók!!! Kijárás. A házon kívül', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'Étkezés rendje: reggeli vasár- és ünnepnapok kivételével naponta <span class="marked">kilenc órakor</span>. Vasár- és ünnepnapokon körülbelül fél tizenkettőkor. Ebéd: esetenként déli egynegyed kettőtől háromnegyed kettőig. Vacsora: hideg, meleg. A rádióleadásokra való tekintettel nincsen időhöz kötve. Az élelmezési', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'hát semmi sem hiányzott. A szombati Mikulás-este azonban sokkal jobban sikerült. Elli és Miep próbára tette kíváncsiságunkat, mert egyre suttogtak apával, s így már előre tudtuk, hogy készülődnek valamire. És tényleg, <span class="marked">nyolc órakor</span> mindnyájan levonultunk a falépcsőn és a koromsötét folyosón át a kisszobába.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'Apa arca felderült, s tegnap reggel <span class="marked">fél tizenegykor</span> Margot és Pim elfoglalta őrhelyét a padlón.', true, '10:30', '10:30', '10:30', 630, 630, 630, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'a bombaeső a város másik végén, az angol rádió szerint Schipholra. A repülőgépek hol lebuktak, hol felszálltak, s borzasztó volt a zaj. Rettenetes. Minden pillanatban azt hittem: most esik rám egy bomba és meghalok. <span class="marked">Kilenc órakor</span>, lefekvés előtt, már alig álltam a lábamon.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'Ma az estével és az éjszakával kezdem: Este <span class="marked">kilenckor</span> a hátsó traktusban megkezdődik a lefekvés előtti sürgés-forgás.', true, '21:00', '21:00', '21:00', 1260, 1260, 1260, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'Hogy puhább legyen, takarókat és díványpárnákat tesz a lécekre. Fejünk felett mennydörgésszerű robaj. Őnagysága ágyát az ablakhoz húzzák, mert a rózsaszín ágykabátos delnő apró orrlyukai friss levegőre áhítoznak. <span class="marked">Kilenc óra</span>: Peter után most én megyek a mosdóba.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'hét: Trrrrrr... a vekker, amelynek megvan az a hajlandósága, hogy a nap bármely órájában megszólaljon (akkor is, ha megkérik rá, sőt néha anélkül is). Kraak... Van Daan úr felkel. Vizet melegít, aztán lesiet a mosdóba. <span class="marked">Negyed nyolc</span>: Újabb ajtónyikorgás. Most Dussel megy mosdani. Végre egyedül. Félrehúzom az elsötétítő függönyt... A hátsó traktus új napra virrad. Anned 1943. augusztus 5, csütörtök Ma pedig beszéljünk a déli ebédszünetről. Ilyenkor', true, '07:15', '07:15', '07:15', 435, 435, 435, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'egy sarokba vonul elmaradhatatlan Dickens-kötetével, s boldog, hogy végre békessége van. Anya a felső emeletre siet; segít a szorgalmas háziasszonynak, én pedig a mosdóba megyek s magammal együtt azt is rendbehozom. <span class="marked">Háromnegyed egy</span>: Telt ház. Megérkezik Van Santen úr, azután Koophuis vagy Kraler, Elli és néha Miep is. Egy óra: Mindnyájan feszült figyelemmel hallgatjuk a BBC-t. Körülüljük a törperádiót. Ezek azok a ritka percek, amikor a hátsó', true, '00:45', '00:45', '00:45', 45, 45, 45, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'emeletre siet; segít a szorgalmas háziasszonynak, én pedig a mosdóba megyek s magammal együtt azt is rendbehozom. Háromnegyed egy: Telt ház. Megérkezik Van Santen úr, azután Koophuis vagy Kraler, Elli és néha Miep is. <span class="marked">Egy óra</span>: Mindnyájan feszült figyelemmel hallgatjuk a BBC-t.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'felnéz a macska észreveszi és huss... már el is tűnt a nyitott padlásablakon át, az ereszcsatornába. Peter szitkozódik, én elnevetem magam és már ott se vagyok. Anned 1943. augusztus 20, péntek Drága Kittym! Pontosan <span class="marked">fél hatkor</span> a munkások elhagyják a raktárt s mi felszabadulunk.', true, '05:30', '05:30', '05:30', 330, 330, 330, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'padlásablakon át, az ereszcsatornába. Peter szitkozódik, én elnevetem magam és már ott se vagyok. Anned 1943. augusztus 20, péntek Drága Kittym! Pontosan fél hatkor a munkások elhagyják a raktárt s mi felszabadulunk. <span class="marked">Fél hat</span>: Elli megajándékoz bennünket az estéli szabadsággal.', true, '05:30', '05:30', '05:30', 330, 330, 330, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', '"Jaj, Elli, volna egy kérésem..." Elli rám kacsint. Őnagysága egyszer se mulasztja el, hogy kérjen valamit azoktól, akik feljönnek hozzá. Valószínűleg ez az egyik oka annak, hogy senki sem jön fel hozzá szívesen. <span class="marked">Háromnegyed hat</span>: Elli hazamegy. Leszaladok a földszintre. Előbb a konyhába, aztán a főnöki szobába, végül a szénraktárba, s kinyitom az egérfogó ajtaját Mouschi számára. Hosszú ellenőrző körutam végeztével Kraler szobájában kötök ki.', true, '05:45', '05:45', '05:45', 345, 345, 345, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'Folytatom a hátsó traktus napi időbeosztásának ismertetését: Reggel <span class="marked">fél kilenckor</span> megkondul a harang! Margot és anya ideges: - Csitt, apa, csendesen, Ottó, pszt... Pim! Fél kilenc; gyere onnan, ne folyasd tovább a vizet; csendesebben járj! - Így szólongatjuk apát, aki a mosdóban van. Amikor a', true, '08:30', '08:30', '08:30', 510, 510, 510, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'Anned 1943. augusztus 23, hétfő Drága Kittym! Folytatom a hátsó traktus napi időbeosztásának ismertetését: Reggel fél kilenckor megkondul a harang! Margot és anya ideges: - Csitt, apa, csendesen, Ottó, pszt... Pim! <span class="marked">Fél kilenc</span>; gyere onnan, ne folyasd tovább a vizet; csendesebben járj!', true, '08:30', '08:30', '08:30', 510, 510, 510, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'a fél kilencet, neki már a szobában kell ülnie. Attól kezdve tilos vizet folyatni és a W. C.-t meghúzni. Csendnek kell lenni. Ha az irodában még senki nincs, annál jobban behallatszik minden zaj a raktárba. Tíz perccel <span class="marked">fél kilenc</span> előtt kinyílik az ajtó, s nyomban utána hármat koppantanak a padlóra: Anne számára elkészült a kása.', true, '08:30', '08:30', '08:30', 510, 510, 510, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'könyvét. Apa tréfásan összevonja szemöldökét, de aztán megint csak a homlokát ráncolja és belemerül az olvasásba. Anya most tereferél Margot-val. Kíváncsi vagyok s odafigyelek! Pimet is bevonják a beszélgetésbe... <span class="marked">Kilenc óra</span>! Jöhet a reggeli! Anned 1943. szeptember 10, péntek Drága Kittym! Mindig olyankor írok, amikor valami rendkívüli esemény történik, ami sajnos rendszerint inkább kellemetlen, mint kellemes. Most azonban jó hírt', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'Szeptember 8-án, szerdán este hét órakor, amikor a rádiót bekapcsoltuk, legelőször ezt hallottuk: - "Here follows the best news of the whole war. Italy has capitulated" - Olaszország feltétel nélkül megadta magát! <span class="marked">Negyed kilenckor</span> megszólalt az Oranje-adó is: "Kedves hallgatóim, egy órával ezelőtt, éppen amikor befejeztem a napi hírek leadását, befutott a szenzációs hír: Olaszország kapitulált." Mondhatom, sosem dobtam még olyan élvezettel a', true, '08:15', '08:15', '08:15', 495, 495, 495, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'különösebben a véleménye, ha nem volna olyan kíváncsi természetű. De így nem lehet valami olcsó kifogással hazaküldeni. S méghozzá ez az ember nem is megbízható. Egy napon Kraler igen éber akart lenni. Tíz perccel <span class="marked">egy óra</span> előtt felvette a kabátját s átment a sarki drogériába.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'Töltőtollam érintetlenül feküdt az asztalon, tulajdonosa pedig sóhajtozva beérte az asztal sarkával és hozzáfogott a babfényesítéshez. Nálunk ez azt jelenti, hogy ledörzsöljük a babszemekről a rárakódott penészt. <span class="marked">Háromnegyed hatkor</span> összesepertem a szemetet s a rothadt babszemekkel együtt újságpapírba göngyölve bedobtam a kályhába.', true, '05:45', '05:45', '05:45', 345, 345, 345, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 's főként én sajnáltam, hogy idén nem ünnepelhetünk. Addig-addig gondolkoztam, amíg ki nem találtam valami mulatságosat. Tanácskoztam Pimmel, s egy héttel ezelőtt verset gyártottunk mind a nyolcunkról. Vasárnap este <span class="marked">negyed kilenckor</span> mindnyájan felmentünk a felső emeletre s magunkkal vittük a nagy ruháskosarat is, melyet rózsaszín és világoskék selyempapír mintákkal és rózsákkal díszítettünk fel.', true, '20:15', '20:15', '20:15', 1215, 1215, 1215, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'hétfő Drága Kittym! Vasárnap este Pimen és rajtam kívül mindenki rádiót hallgatott. A "német mesterek halhatatlan muzsikáját" közvetítették. Dussel folyton babrálta a készüléket. Peter és a többiek bosszankodtak. Este <span class="marked">tizenegykor</span> aztán Peterből kitört a visszafojtott idegesség s kissé ingerülten arra kérte Dusselt, hogy hagyja végre abba a csavargatást.', true, '23:00', '23:00', '23:00', 1380, 1380, 1380, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'Tegnap este, amikor Van Daan úr szokás szerint <span class="marked">fél nyolckor</span> lement Kraler irodájába, észrevette, hogy az üvegajtók tárva-nyitva állnak s nyitva felejtették az irodaajtót is.', true, '19:30', '19:30', '19:30', 1170, 1170, 1170, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'Letettem a lábast a földre s csak <span class="marked">negyed hatkor</span> (egy órával később) vittem le a krumplit a szobába.', true, '05:15', '05:15', '05:15', 315, 315, 315, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'és megmagyaráztam valamit Peternek, aztán pedig áttértünk az angolra. Apa felolvasott egy Dickens-könyvből, és én földöntúli boldogságban úsztam, hogyne, hiszen apával egy széken, szorosan Peter mellett ültem. <span class="marked">Tizenegy órakor</span> leszaladtam. Fél tizenkettőkor ismét felmentem. Peter már várt rám a lépcsőn. Háromnegyed egyig beszélgettünk. Amikor csak alkalmam nyílik rá, például étkezés után, ha kimegyek a szobából és senki sem hallja, odasúgja:', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'fekszik. Valóságos veszteséglista. A raktári munkások holnapra szabadságot kaptak. Ha Elli nem jön be, zárva marad az iroda, s nekünk csendben kell maradnunk, nehogy meghalljanak a szomszédok. Majd akkor Henk <span class="marked">egy óra</span> tájban felkeresi az elhagyottakat s megjátssza az állatkerti őr szerepét.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'Azt válaszolta, hogy reggel nyolc és <span class="marked">kilenc óra</span> között érte jöhetek. Ha a betegség súlyos, a doktor maga jön egy percre a telefonhoz s így szól: Nyújtsa csak ki a nyelvét s mondja: ááh. Hallom, be van rekedve. Majd felírok valamit, szerezze be a gyógyszertárból. A', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'Ha a felső emeletre megyek, megkérdezik, mit keresek ott, az ételt nem szabad megsóznom, este pontosan <span class="marked">negyed kilenckor</span> anya megkérdi, miért nem vetkőzöm már le, s minden könyvet ellenőriznek, amit csak a kezembe veszek.', true, '20:15', '20:15', '20:15', 1215, 1215, 1215, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'számára persze már nem olyan nagy tragédia a kiszáradás. Hogy élő példával is szolgáljak, legjobb lesz, ha leírom, hogyan hallgattuk meg mindnyájunk eszményképének, Winston Churchillnek rádiószózatát. Vasárnap este <span class="marked">kilenc óra</span>. A tea az asztalon, a melegítő alatt. A család bevonul. A rádiónál balról Dussel, középen Van Daan úr, mellette Peter. Anya Van Daan mellett, mögötte őnagysága. Apa, Margot meg én az asztalhoz telepedtünk. Úgy látom,', true, '21:00', '21:00', '21:00', 1260, 1260, 1260, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'Lerogytam az ágy szélére és ott kínlódtam tovább, de pár perccel <span class="marked">fél tizenegy</span> előtt erőt vettem magamon és lefeküdtem.', true, '10:30', '10:30', '10:30', 630, 630, 630, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'Vasárnap délután Petert fél ötre meghívtam a szobámba, <span class="marked">negyed hatkor</span> pedig felmentünk az utcai rész padlására s ott is maradtunk hatig.', true, '17:15', '17:15', '17:15', 1035, 1035, 1035, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'szép Mozart-hangversenyt hallgattunk rádión. Főként a Kis éji zene tetszett nekem. A nappali szobában, a többiek jelenlétében nem szívesen hallgatok rádiót, mert a szép muzsika egész bensőmet felkavarja. Vasárnap este <span class="marked">nyolckor</span> Peterrel felmentünk a padlásra, s hogy kényelmesebben ülhessünk, összeszedtünk minden párnát, amit csak a szobákban találtunk.', true, '20:00', '20:00', '20:00', 1200, 1200, 1200, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'Fent egy ládán helyezkedtünk el. A láda is, a párnák is keskenyek voltak, ezért szorosan egymás mellé ültünk s két másik ládához támaszkodtunk. A Mouschi cica is ott lebzselt, tehát nem voltunk "felügyelet" nélkül. <span class="marked">Háromnegyed kilenckor</span> Van Daan úr felfütyült hozzánk s érdeklődött, nincs-e nálunk Dussel úr párnája.', true, '08:45', '08:45', '08:45', 525, 525, 525, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'keresztül ilyen rettegésben élni! Még csak nem is gondolkoztunk, ültünk a vaksötétségben, mert Van Daanné ijedtében még a lámpát is eloltotta. Suttogva beszéltünk, s ha valamelyikünk megmozdult, nyomban lepisszegtük. <span class="marked">Fél tizenegy</span>, tizenegy. Semmi nesz. Apa és Van Daan felváltva lejött hozzánk. Negyed tizenkettőkor lentről zajt hallottunk. Egymás lélegzetvételét figyeltük s nem mozdultunk. Léptek a házban, az irodában, a konyhában, azután... a', true, '10:30', '10:30', '10:30', 630, 630, 630, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'múlva Van Daan úr helyet cserélt a feleségével, apa pedig mellém feküdt. A férfiak szüntelenül füstöltek. Olykor egyikünk felsóhajtott, egy másik könnyített magán, de az izgalom maradt a régi. Négy óra, öt óra, azután <span class="marked">fél hat</span>. Felmentem Peterhez, s az ablaknál hallgatóztunk. Szorosan ültünk egymás mellett; éreztük egymás testének remegését. Feszülten figyeltünk s csak néha váltottunk egy-egy szót. A szomszéd szobában leszedték az elsötétítő', true, '05:30', '05:30', '05:30', 330, 330, 330, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'a konyhába. Addigra ott már leszedték az asztalt. Kávét, teát készítettünk, tejet forraltunk, és megterítettünk. Apa és Peter kiürítette az éjjelinek használt edényt, majd kimosták forró vízzel és klórmésszel. <span class="marked">Tizenegy órakor</span> már az asztal körül ültünk Henkkel, aki időközben visszaérkezett.', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'Mire Henk elment, és elmostuk az edényt, már <span class="marked">egy óra</span> volt. Mind a nyolcan aludni tértünk. Háromnegyed háromkor felébredtem s láttam, hogy Dussel úr már nincs a szobában. Álmos képpel kisiettem a fürdőszobába s véletlenül összetalálkoztam Peterrel, aki éppen akkor jött', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'már megmenekültünk, óvj meg minket továbbra is! - Így fohászkodtunk. Ez az esemény különböző változásokat idézett elő életmódunkban. Dussel úr esténként a fürdőszobában tanul, s nem ülhet lent Kraler irodájában. Peter <span class="marked">fél kilenc</span> és fél tíz között végigjárja a házat.', true, '08:30', '08:30', '08:30', 510, 510, 510, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'április 16, vasárnap reggel, kevéssel <span class="marked">11 óra</span> előtt Drága Kittym! Jegyezd meg a tegnapi napot, mert ez egyik legdöntőbb napja életemnek. Ugye minden lánynál nagy esemény az első csók? Hát nálam sem kevésbé fontos. Mert az a csók, amelyet valamikor Bramtól a jobb', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'Mert az a csók, amelyet valamikor Bramtól a jobb arcomra kaptam, nem számít, s még ennél is jelentéktelenebb Walker úr csókja a jobb kezemen. S most elmesélem, hogyan jutottam hirtelen ehhez a csókhoz. Tegnap este <span class="marked">nyolc órakor</span> együtt ültem Peterrel a díványon, amikor egyszerre csak átfogott a karjával.', true, '20:00', '20:00', '20:00', 1200, 1200, 1200, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'Azután esetlenül megsimogatta az arcom meg a karom, majd felborzolta a hajamat. Eközben összeborult a fejünk. Édes Kittym, le sem tudom írni, mit éreztem, de azt hiszem, mind a ketten mérhetetlenül boldogok voltunk. <span class="marked">Fél kilenckor</span> aztán felálltunk. Peter tornacipőt húzott, mert abban nesztelenebbül jár; készült ellenőrző körútjára. Megvártam. S akkor - fogalmam sincs, hogyan történt - mielőtt elindultunk, egyszerre csak megcsókolta a bal orcámat', true, '08:30', '08:30', '08:30', 510, 510, 510, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'ugyancsak az overalljára potyogtak. Nem tudom, észrevette-e, de nem árulta el egyetlen mozdulattal sem. Velem érzett-e vajon? Alig szólt hozzám. Tudta-e, hogy két Anne ül mellette? Nehéz válaszolni ezekre a kérdésekre. <span class="marked">Fél kilenckor</span> felálltam, odamentem az ablakhoz; ott szoktunk búcsúzni egymástól.', true, '08:30', '08:30', '08:30', 510, 510, 510, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'a szám összeért az övével s egyetlen csókban forrt össze. Szédülten öleltük egymást, s újabb és újabb csókok következtek, mintha sohasem akarnánk abbahagyni. Ó! Peter vágyik a gyengédségre. Életében először fedezett <span class="marked">fel egy</span> lányt, először győződött meg róla, hogy a leghuncutabb lánynak is van szíve és lelke, s megváltozik, mihelyt kettesben marad vele.', true, '00:30', '00:30', '00:30', 30, 30, 30, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'kell tartanunk! Talán egyszer bennünket is... nem, nem, ilyet le se szabad írnom, de amikor képtelen vagyok elhessegetni magamtól ezt a gondolatot, sőt folyton visszatér a múltkori szörnyű félelem és ijedség. Ma este <span class="marked">nyolckor</span> egyedül mentem le a W. C.-re. Más nem volt az alsó emeleten, mindnyájan rádiót hallgattak. Bátorságot erőszakoltam magamra, bár elég nehezemre esett. Itt fent, ahol most ezt írom, még mindig nagyobb biztonságban érzem', true, '20:00', '20:00', '20:00', 1200, 1200, 1200, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', '"This is the D-day", jelentette <span class="marked">12 órakor</span> az angol rádió és joggal. "This is the Day", [21] mert megindult az invázió! Reggel nyolc órakor angol jelentés: nagy légitámadás Calais, Boulogne, Le Havre, Cherbourg és (mint rendesen) a calais-i öböl felett. További', true, '12:00', '12:00', '12:00', 720, 720, 720, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'és a francia partvidéket szakadatlanul bombázzák. Anned 1944. június 6, kedd Drága Kittym! "This is the D-day", jelentette 12 órakor az angol rádió és joggal. "This is the Day", [21] mert megindult az invázió! Reggel <span class="marked">nyolc órakor</span> angol jelentés: nagy légitámadás Calais, Boulogne, Le Havre, Cherbourg és (mint rendesen) a calais-i öböl felett.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'előtt röplapokat szórnak le. Német jelentés szerint angol ejtőernyős csapatok szálltak le a francia partvidéken. A BBC közli, hogy a csapatszállító hajóegységek már harcolnak a német tengerészekkel. Rejtekhelyünk lakói <span class="marked">kilenc órakor</span>, reggelizés közben azon vitáznak, nem lesz-e ez is csak próba-partraszállás, mint Dieppe-nél két évvel ezelőtt?', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'azon vitáznak, nem lesz-e ez is csak próba-partraszállás, mint Dieppe-nél két évvel ezelőtt? Tíz órakor angol leadás német, holland, francia és más nyelveken: "The invasion is begun!" [22] Ez tehát "igazi" invázió. <span class="marked">11 órakor</span> német nyelvű jelentés: Dwight Eisenhower tábornok főparancsnok beszéde.', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'The year 1944 is the year of complete victory, good luck!" [23] Fordításban írom le az angol rádiónak <span class="marked">egy órakor</span> leadott angol nyelvű jelentését: tizenegyezer repülőgép szállítja a csapatokat és dob le állandóan bombákat a front mögé.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'hagytak, ez az egyetlen megoldás. Kralert újból behívták négy hétre sáncot ásni. Majd igyekszik felmentetni magát egy orvosi bizonyítvány és egy vállalati levél alapján. Koophuisnak megoperálják a gyomrát. Tegnap <span class="marked">tizenegy órakor</span> kikapcsoltak minden magántelefont.', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'azon porosan, homokosan, 24 ládában szállítottak ide a magunk meg az iroda részére. Még aznap este hat üveg befőttet és nyolc üveg lekvárt készítettünk. Miep másnap szándékozott lekvárt főzni az iroda számára. Déli <span class="marked">fél egykor</span>, amikor senki idegen nem volt a házban, lezárták az utcai ajtót; s Peter, apa meg Van Daan lerobogtak a lépcsőn és felhordták az epresládákat.', true, '00:30', '00:30', '00:30', 30, 30, 30, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'Betartottuk a rejtőzködők törvényét: "Ha idegen lép a házba, minden csapot el kell zárni, nehogy a zaj árulónk legyen." <span class="marked">Egy órakor</span> feljött Henk. Tőle tudtuk meg, hogy az imént a postás csengetett. Peter újból lerobogott a lépcsőn, közben megint megszólalt a csengő, s máris szaladt vissza. Én meg előbb a forgószekrénynél álltam, aztán felosontam a', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anne Frank naplója', 'https://mek.oszk.hu/00200/00261', 'borsóhüvely lehámozása rendkívül aprólékos és piszmogós foglalkozás, legfeljebb csak pedáns fogorvosoknak vagy pontos irodistáknak való, de annál szörnyűbb egy türelmetlen kamaszleány számára. Fél tízkor fogtunk hozzá. <span class="marked">Fél tizenegykor</span> hagytam abba, de már fél tizenkettőkor folytattam.', true, '10:30', '10:30', '10:30', 630, 630, 630, '{"Szépirodalom, népköltészet","Kortárs világirodalom"}', 'urn:nbn:hu-2260', 'Frank Anne', 'diary', 'https://mek.oszk.hu/00200/00261/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Legény a talpán', 'https://mek.oszk.hu/12400/12493', 'Nem is változott, csak a szakálla volt sokkal piszkosabb, de háromszoros saskarmaival éppúgy babrált benne, mint <span class="marked">egykor</span>. - Meglátom! De újra figyelmeztetem, Birks, hogy mindenben tartsa magát a megállapodásunkhoz. Még hevertem volna egy kissé lehúnyt szemmel, Birks azonban beszélni akart velem, tehát mintegy gyors elsősegélyt', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-116787', 'Rejtő Jenő', 'short novel', 'https://mek.oszk.hu/12400/12493/12493.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Legény a talpán', 'https://mek.oszk.hu/12400/12493', 'megpillantottam ujjamon a gyűrűt, amelynek egyik háromszögű hegye iránytűre emlékeztetett. Tréfás ötletem támadt. A gyűrű hozott ide, ő vezessen tovább is. Feldobom. Hátha keletre mutat a nyavalyás háromszög. És ahogy <span class="marked">egykor</span> Pretoria felé, itt is felhajítottam a gyűrűt, azután továbbvergődtem abba az irányba, amerre a lehullott gyűrű csúcsa mutatott.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-116787', 'Rejtő Jenő', 'short novel', 'https://mek.oszk.hu/12400/12493/12493.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Legény a talpán', 'https://mek.oszk.hu/12400/12493', 'A második oldalon ez állt: "Szerdán reggel <span class="marked">nyolc órakor</span> végzik ki a georgetowni fegyház udvarán Sir Robert Raleighet, Lady Shelton gyilkosát." Képzeljétek helyzetemet az asszonnyal.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-116787', 'Rejtő Jenő', 'short novel', 'https://mek.oszk.hu/12400/12493/12493.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Legény a talpán', 'https://mek.oszk.hu/12400/12493', 'csillannak fel, ha halvány, vakító fényével ellobban a villám és megremeg minden hördülésétől. Három órán át tombolt a vihar, azután egy másodperc alatt kitisztult. Durban megostromolt, legyőzött városhoz hasonlított. <span class="marked">Egy óra</span> mulva mégis a levegőben voltunk, útban Johannesburg felé.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-116787', 'Rejtő Jenő', 'short novel', 'https://mek.oszk.hu/12400/12493/12493.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Legény a talpán', 'https://mek.oszk.hu/12400/12493', 'látszott, komoly tettekre szánta el magát, arra az esetre, ha Robertet nem sikerül megmenteni. A vihar végigment az egész déli zónán. Amerre alacsonyan szálltunk, romok, kitépett fák, vágtató esőlé... Kedden délelőtt <span class="marked">tizenegy órakor</span> megérkeztünk a johannesburgi kormányzóságra.', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-116787', 'Rejtő Jenő', 'short novel', 'https://mek.oszk.hu/12400/12493/12493.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Legény a talpán', 'https://mek.oszk.hu/12400/12493', '- A villa, sajnos, a Vaal folyó partján van, körülbelül <span class="marked">egy óra</span>... Még ez is! A soffőrt életveszélyes fenyegetésekkel ösztökéltem. Végre itt a kormányzó villája. Az inas nem hiszi, hogy az excellenciás úr fogad. Én biztos vagyok benne. Az inas kérdezi, hogy milyen ügyben és kit', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-116787', 'Rejtő Jenő', 'short novel', 'https://mek.oszk.hu/12400/12493/12493.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Legény a talpán', 'https://mek.oszk.hu/12400/12493', 'küldött a sírjára. Azután kiugrik az ágyból és olyan gyorsan kapkodja magára a ruháit, hogy ha minden kötél szakad, mint átváltozó-művész is megél. Persze ti most nevettek! De akkor! Akkor, barátom! Másnap reggel pont <span class="marked">nyolc órakor</span> egy embert akasztanak, egy állítólagos gyilkost és az áldozat melletted az autóban, a körülményekhez képest él.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-116787', 'Rejtő Jenő', 'short novel', 'https://mek.oszk.hu/12400/12493/12493.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Legény a talpán', 'https://mek.oszk.hu/12400/12493', 'repülünk és lassan mulik az éjszaka. Csak felhők fölött haladhatunk és a pilóta nem tud jól tájékozódni. Az asszony karóráján hét óra. Világos van, de vadul csapkod mindenfelől az eső, a gép néha veszélyesen inog. <span class="marked">Fél nyolc</span>. Nagyon eltértünk nyugat felé, mert keletről tűnik fel, messze Georgetown. Egyre közelebb jön, azután hirtelen ferde síkban emelkedik a város, forognak a házak... A karóra háromnegyed nyolcat mutat. Kiugrunk a gépből,', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-116787', 'Rejtő Jenő', 'short novel', 'https://mek.oszk.hu/12400/12493/12493.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Legény a talpán', 'https://mek.oszk.hu/12400/12493', 'A repülőtér előtti villanyórán <span class="marked">nyolc óra</span> mult! Lady Shelton karórája 15 percet késett! Csak annyi időm volt, hogy elkaphattam a zuhanó asszonyt. Mindennek vége... Szegény, szegény Raleigh. Harangoznak. Nyolcat. 16. ...Virradt. Raleigh olvasott. Swinburne', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-116787', 'Rejtő Jenő', 'short novel', 'https://mek.oszk.hu/12400/12493/12493.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Legény a talpán', 'https://mek.oszk.hu/12400/12493', 'langyos sugarak nyájasan terültek szét a siralomház kőpadlóján. A pap jött. Sir Robert Raleigh azzal a sóhajjal csukta be a könyvet, amellyel udvarias emberek elkerülhetetlen, sablónos látogatóikat fogadják megadással. <span class="marked">Fél nyolckor</span> megivott egy csésze teát és pirított zsemlyét kért hozzá vajjal.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-116787', 'Rejtő Jenő', 'short novel', 'https://mek.oszk.hu/12400/12493/12493.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Legény a talpán', 'https://mek.oszk.hu/12400/12493', 'Azzal a csendes gőggel készült a halálra, amellyel <span class="marked">egykor</span> néhány Raleigh, Morus Tamást követte a vérpadra Istenért és az alkotmányért.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-116787', 'Rejtő Jenő', 'short novel', 'https://mek.oszk.hu/12400/12493/12493.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Legény a talpán', 'https://mek.oszk.hu/12400/12493', 'előtt lehetnek óhajai. - Köszönöm. Nem kérek semmit. Bosszantana, ha miattam csorbát szenvedne a joggyakorlat. - Majd beküldőm önhöz az ügyvédjét egy kis beszélgetésre. - Én már azt sem bánom, uram. * Ez történt <span class="marked">félnyolckor</span> reggel. Délben egy órakor, midőn a hóhér gőzöse némi reparaturák után folytatta az útját, Sir Robert Raleighet már szabadlábra helyezték és Lady Shelton óvadéka ellenében az én letartóztatásomtól is eltekintettek.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-116787', 'Rejtő Jenő', 'short novel', 'https://mek.oszk.hu/12400/12493/12493.htm', 'deep_extract', false);
