INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Naplók', 'https://mek.oszk.hu/01300/01327', 'Fújhatja a körmét, aki ott kaparász. Sanyi is fútta. De lassanként hozzá szokott. Csak az orrával volt sok baja. Mindig szivárgott. Azonban ez az inasi testedzés csak hajnali háromtól reggeli fél nyolcig tartott. <span class="marked">Fél nyolckor</span> bevágott Sanyi egy jó darab kenyeret, hóna alá csapta a könyvet, sebes léptekkel ment az iskolába.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-3337', 'Oláh Gábor', 'diary', 'https://mek.oszk.hu/01300/01327/html/olah1_1.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Naplók', 'https://mek.oszk.hu/01300/01327', 'Ha hét órakor kezdődik a játék, <span class="marked">félhatkor</span> már ott volt. Várt töredelmesen és szívdobogva. Gyönyörű, felejthetetlen estéi voltak ezek! Egészen új világ, valami tündéri világ ejtette varázsába. Sokszor sírt örömében a bolond fiú. Óh, be tudta honorálni a szegény', true, '05:30', '05:30', '05:30', 330, 330, 330, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-3337', 'Oláh Gábor', 'diary', 'https://mek.oszk.hu/01300/01327/html/olah1_1.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Naplók', 'https://mek.oszk.hu/01300/01327', 'mikor kilépve a hűvös hortobágyi szellő csapta meg fejét, s tüzes szemű kocsik robogtak mellette, s kacarászó emberek lökdösték jobbra-balra. A tündér világ eloszlott... De lelkében tovább élt! Színház után, úgy esti <span class="marked">tizenegy óra</span> tájban következett aztán Sanyinak legnehezebb és legérdekesebb tette.', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-3337', 'Oláh Gábor', 'diary', 'https://mek.oszk.hu/01300/01327/html/olah1_1.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Naplók', 'https://mek.oszk.hu/01300/01327', 's kacarászó emberek lökdösték jobbra-balra. A tündér világ eloszlott... De lelkében tovább élt! Színház után, úgy esti tizenegy óra tájban következett aztán Sanyinak legnehezebb és legérdekesebb tette. Odahaza, persze, <span class="marked">kilenc órakor</span> már bezárták az ajtót. Egy kulcs volt az udvarban. Ide másképp be nem mehet az ember, csak ha megzörgeti az ablakot. Igen, de akkor meg az ébren alvó Tasnádi pattan fel legelőször, s ha ő nyit ajtót éjszaka járó', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-3337', 'Oláh Gábor', 'diary', 'https://mek.oszk.hu/01300/01327/html/olah1_1.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Naplók', 'https://mek.oszk.hu/01300/01327', 'a nemes ifjúság minden változata; lehetett bírálni, erősen vitatkozni és szavalni a Pán halálá-t [35] meg a Visszavárlak-ot [36] . Bölcsészkisasszonyok is tündériesítették ezeket a nemesen szórakoztató estéket. Itt lép <span class="marked">fel egy</span> este Tasnádi Sándor. Nem igen ismerik; mert nem jár biliárdozni, párbajoknál sem segédkezik. Elkezdi szavalni A magyar tánc-ról [37] irt debreceni nyelvű versét. Az egész irodalmi szakosztály megdöbbent gyönyörűséggel', true, '12:30', '12:30', '12:30', 750, 750, 750, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-3337', 'Oláh Gábor', 'diary', 'https://mek.oszk.hu/01300/01327/html/olah1_1.htm', 'deep_extract', false);
