INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Gyere, kicsim!... Gyere!', 'https://mek.oszk.hu/01100/01102', 'és szó nélkül nézett reá. A két arcon kinyílott most egy-egy mosolyból született nevetés s azután megcsókolta egymást az örömtelen napon boldogságot találó két szülő. * * * Elérkezett a félvevárt nap. Szigeti mérnököt <span class="marked">fél nyolckor</span> a villa kapujáig kísérte a felesége és a kapunál csókkal búcsúztak egymástól az eltagadott félelemmel bizakodók.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-3109', 'Tornyai János', 'novel', 'https://mek.oszk.hu/01100/01102/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Gyere, kicsim!... Gyere!', 'https://mek.oszk.hu/01100/01102', 'kis fejét szundikáló párja fejéhez és talán a fülébe súgott valami szomorú, valami borzalmas, valami szörnyűséges álmot... * * * Az ébrenlét harca már reggel öt órakor elkezdődött a Szigeti-lakásban. A garázst <span class="marked">hat órakor</span> nyitják s ekkor már minden munkásnak el kell foglalnia a helyét, akár van munka, akár nincs.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-3109', 'Tornyai János', 'novel', 'https://mek.oszk.hu/01100/01102/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Gyere, kicsim!... Gyere!', 'https://mek.oszk.hu/01100/01102', 'van a háznál! Keresett kutatott a sovány lehetőségek között s addig kereste, míg meg nem találta a megoldást - úgyahogy - nyitját... - Hát így muszáj - hangzottak a megalkuvás békítő szavai ajakán s az órára nézett. <span class="marked">Nyolc óra</span>! Ebben a pillanatban Évike hangja csilingelt ki a hálószobából: - Anyutám! - Megyek, kedvesem! Megyek! Itt vagyok! - S a következő percben, Évike kuszáltra aludt kis haját igazgatta okos kis fején, anyuka karjai', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-3109', 'Tornyai János', 'novel', 'https://mek.oszk.hu/01100/01102/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Ábel Amerikában', 'https://mek.oszk.hu/01000/01084', 'bé is teszem, akkor csak ama időpontig maradok, amikor az emberek igazgatni kezdik a nadrágszíjat. Ez a fogadalom helyrehozott egy kicsit, s mivel Gáspár bácsi is éppen hazajött, újabb kirándulásra kezdtünk készülődni. <span class="marked">Fél nyolckor</span> indultunk el nagy összetartásban, s egymást dicsérgettük.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-3091', 'Tamási Áron', 'novel', 'https://mek.oszk.hu/01000/01084/html/02.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Ábel Amerikában', 'https://mek.oszk.hu/01000/01084', 'rontottam el, pedig mindenki elhiheti, hogy törekedtem az eredményre. A nagy igyekezetben aztán a délebéd ideje is hamar elérkezett. De én még egyetlen alkalmas mintát sem tudtam az időre csinálni! - Hagyja abba, majd <span class="marked">egy órakor</span> folytatjuk! - mondta Vilmos. Abbahagytam a munkát, de nem szóltam semmit, hanem szomorúan lógattam a fejemet. S közben arra kértem az Istent, hogy Dávid úr oda ne jöjjön. De maga az Úr is elhagyott engem azon a hétfői', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-3091', 'Tamási Áron', 'novel', 'https://mek.oszk.hu/01000/01084/html/02.htm', 'deep_extract', false);
