INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A canterville-i kísértet', 'https://mek.oszk.hu/04900/04941', 'angol házakban is; hogy milyen kellemes a New York-i kiejtés a londoni lompos beszédhez képest. Semmi természetfölötti dolgo t nem hoztak szóba, sőt még csak célzás sem történt Sir Simon de Canterville személyére. <span class="marked">Tizenegy órakor</span> a család visszavonult, és fél tizenkettőkor minden világosság kialudt.', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-7474', 'Wilde Oscar', 'short stories', 'https://mek.oszk.hu/04900/04941/04941.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A canterville-i kísértet', 'https://mek.oszk.hu/04900/04941', 'azután Mr. Otis arra ébredt, hogy valami különös zaj hallatszik a folyo són a szobája előtt. Mintha lánccsörgés lett volna, amely egyre közeledett. Rögtön fölkelt, gyufát gyújtott és megnézte az óráját. Pontosan <span class="marked">egy óra</span> volt. Ő maga egészen nyugodtnak érezte magát, megtapogatta a pulzusát, semmi nyoma a láznak. A furcsa nesz e gyre közeledett, s most már határozottan lépések zaját is hallotta. Belebújt papucsába, kivett a szekrényből', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-7474', 'Wilde Oscar', 'short stories', 'https://mek.oszk.hu/04900/04941/04941.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A canterville-i kísértet', 'https://mek.oszk.hu/04900/04941', 'a szobában "Duhaj Dániel vagy az Öngyilkos Ördög" szerepében. Ezt már nemegyszer játszotta el, és óriási sikerrel versenyzett másik hírhedt alakításával a "Marcona Márton vagy a Maskarás Misztérium" cíművel. <span class="marked">Fél tizenegy</span> óra tájban hallotta, hogy a család aludni tér.', true, '10:30', '10:30', '10:30', 630, 630, 630, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-7474', 'Wilde Oscar', 'short stories', 'https://mek.oszk.hu/04900/04941/04941.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A canterville-i kísértet', 'https://mek.oszk.hu/04900/04941', 'esküjét, egy távoli major vörös cserepes tetején megszólalt a kakas. A kísértet hosszú, halk, keserű nevetést hallatott és várt. Órák hosszat várt, de a kakas valami külön oknál fogva nem kukorékolt másodszor. Végre <span class="marked">fél nyolckor</span> megérkeztek a szobalányok, és fölzavarták félelmetes virrasztásából.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-7474', 'Wilde Oscar', 'short stories', 'https://mek.oszk.hu/04900/04941/04941.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A canterville-i kísértet', 'https://mek.oszk.hu/04900/04941', 'Itt fölverték az összes mezőőröket, de semmi felvilágosítást nem kaptak tőlük, s miután keresztül-kasul kutatták a rétet, visszafordultak hazafelé, s <span class="marked">tizenegy óra</span> tájban elérték a kastélyt, holtra fáradva és kétség beesett szívvel.', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-7474', 'Wilde Oscar', 'short stories', 'https://mek.oszk.hu/04900/04941/04941.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A canterville-i kísértet', 'https://mek.oszk.hu/04900/04941', 'Négy nappal e különös események utáni temetési menet hagyta el a canterville-i kastélyt éjjel <span class="marked">tizenegy óra</span> tájban. A gyászhintót nyolc fekete ló húzta, valamennyinek a fején hatalmas strucctollas bóbita lengett: az ólomkoporsót bíborszínű bársony födte, amelyre arannyal hímezték rá a canterville-i címert. A gyászhintó és a', true, '23:00', '23:00', '23:00', 1380, 1380, 1380, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-7474', 'Wilde Oscar', 'short stories', 'https://mek.oszk.hu/04900/04941/04941.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A canterville-i kísértet', 'https://mek.oszk.hu/04900/04941', 'egy háború, amelyben egy férfi meghalhat, valamely ügy, amelyért az ember odaadja az életét, és mivel az életben nincs öröm számára, nem fél a haláltól sem. Végezze a sors a maga dolgát. Ő bizony nem lesz segítségére. <span class="marked">Fél nyolckor</span> felöltözött, és elment a klubjába.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-7474', 'Wilde Oscar', 'short stories', 'https://mek.oszk.hu/04900/04941/04941.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A canterville-i kísértet', 'https://mek.oszk.hu/04900/04941', 'A gyerek pedig rámosolygott az óriásra és így szólt hozzá: - <span class="marked">Egykor</span> te játszani hagytál engem a te kertedben; de ma te jössz velem az én kertembe, a Paradicsomba.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-7474', 'Wilde Oscar', 'short stories', 'https://mek.oszk.hu/04900/04941/04941.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Négyen meg a Béka', 'https://mek.oszk.hu/02400/02491', '- Ide figyelj, Jutka, nekem pontosan <span class="marked">egy óra</span> időm van. Ha azalatt el akarod mondani... Elmondani? Dehogy akarja elmondani. Senkinek se akarja... De amikor olyan nehéz a szíve! És Palkó jó barát. Amikor Jutka első általánosba járt, Palkó már érettségi előtt állt,', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4376', 'Fehér Klára', 'novel', 'https://mek.oszk.hu/02400/02491/02491.htm', 'deep_extract', false);
