INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Négyen meg a Béka', 'https://mek.oszk.hu/02400/02491', 'mesélsz! - Öcsi, mezítláb? - kérdi anyu megdöbbenve. - Majd ide bújok lábtól Jutka ágyába. - Mit meséltél Jutkának? - kérdi Kari. - Szerencsétek, hogy apu csak holnap érkezik haza, mert mindannyiunkat agyonütne. Este <span class="marked">tizenegy óra</span>, és még nem alusztok! - csóválja a fejét anyu, de azért nem haragszik igazán. - Egy félórát beszélgetünk, azután mars aludni. - Miről beszéltetek? - Arról, hogy nem is olyan egyszerű dolog mindig jónak lenni - mondja', true, '23:00', '23:00', '23:00', 1380, 1380, 1380, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4376', 'Fehér Klára', 'novel', 'https://mek.oszk.hu/02400/02491/02491.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Négyen meg a Béka', 'https://mek.oszk.hu/02400/02491', 'A szobaajtó hirtelen kinyílt. Édesanya jött be. - Mi ez a veszekedés? - Semmi... - felelték kórusban mind a hárman. - Semmi veszekedés nem volt. A leckét csináljuk. - Hát csak igyekezzetek, mindjárt hazajön édesapa. <span class="marked">Fél hat</span> elmúlt. Öcsi gyorsan zsebébe süllyesztette a papírt, és hozzálátott a számtanhoz. Kari befejezte a mértani rajzot, Jutka pedig folytatta a földrajz ismétlést. A Dunántúl. Igen, a Dunántúl! Ó, de jó lesz utazni! Lehet,', true, '05:30', '05:30', '05:30', 330, 330, 330, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4376', 'Fehér Klára', 'novel', 'https://mek.oszk.hu/02400/02491/02491.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Négyen meg a Béka', 'https://mek.oszk.hu/02400/02491', 'tíz percig tanulok még - kapott észbe Jutka. - Csak tanulj - húzta be édesanya az ajtót. Jutka pedig most már igazán csak a Dunántúlra figyelt. Nem baj, a vakációig már csak tizenegy nap. ÖTÖDIK FEJEZET Teréz, a Béka <span class="marked">Fél nyolckor</span> már együtt volt az osztály. Az idén ez az utolsó tanítási nap, aztán már csak a vizsgák jönnek. Az ötödikesek virággal borították a katedrát, mindenkin tiszta fehér blúz virított, Bartal Jutka a táblánál állt. Színes', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4376', 'Fehér Klára', 'novel', 'https://mek.oszk.hu/02400/02491/02491.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Négyen meg a Béka', 'https://mek.oszk.hu/02400/02491', 'Éva néni már itt van, és a napos nem jelentheti büszkén, hogy nem hiányzik senki, mert a Béka majd <span class="marked">negyed kilenckor</span> fog lihegve befutni, és biztosan azt is elfelejtette, hogy az ünnepi fehér blúzt kell felvennie.', true, '08:15', '08:15', '08:15', 495, 495, 495, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4376', 'Fehér Klára', 'novel', 'https://mek.oszk.hu/02400/02491/02491.htm', 'deep_extract', false);
