INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Négyen meg a Béka', 'https://mek.oszk.hu/02400/02491', 'is, paradicsom is, de amikor a főzéshez láttak volna, elment tőle a kedvük. Öcsi álmosan, nagyokat szuszogva fogott a krumplihámozáshoz , Jutka pedig aggodalmasan mondta: - Már fél nyolc van. Mire megvacsorázunk, <span class="marked">fél kilenc</span>, s aztán még mosogathatunk. Legszívesebben máris ágyba bújnék. - Tudjátok mit - javasolta Palkó -, ma kivételesen ne együnk főtt ételt, együnk szalonnát, kenyérrel és zöldpaprikával. Így történt, hogy a gyerekek', true, '08:30', '08:30', '08:30', 510, 510, 510, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4376', 'Fehér Klára', 'novel', 'https://mek.oszk.hu/02400/02491/02491.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Négyen meg a Béka', 'https://mek.oszk.hu/02400/02491', 'Úgy gondolta, hogy rajzol egy nagy kört, és abba belerajzolja a csillagokat, úgy, ahogy este <span class="marked">nyolckor</span> látta. Azután rajzol egy másik kört, éjfélkor felkel, és a körbe belerajzolja a csillagokat úgy, ahogy azok éjfélkor állnak. Azután rajzol még egy kört, és abba hajnali négykor rajzolja be a csillagokat... Ez', true, '20:00', '20:00', '20:00', 1200, 1200, 1200, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4376', 'Fehér Klára', 'novel', 'https://mek.oszk.hu/02400/02491/02491.htm', 'deep_extract', false);
