INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Négyen meg a Béka', 'https://mek.oszk.hu/02400/02491', 'virágszirmot kevernek etetéskor a cukoroldatba, olyan virágra szokik. - Pajtás, nem kell még hazamenned? - kérdezte Szabó, a barátságtalan őr, de most egészen barátságos volt. - Van már hét óra? - kérdezte Öcsi. - Hét? <span class="marked">Fél kilenc</span> is elmúlt. - Akkor... akkor... nagyon igen... - mondta erre Öcsi -, akkor én itt hagynám ezt a ruhát is! - Majd visszahozod délután - mondta Szabó, de Öcsi addigra már könnyelműen levette a sisakját. Egy méhecske pedig', true, '08:30', '08:30', '08:30', 510, 510, 510, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4376', 'Fehér Klára', 'novel', 'https://mek.oszk.hu/02400/02491/02491.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Négyen meg a Béka', 'https://mek.oszk.hu/02400/02491', 'TIZENHETEDIK FEJEZET Két kislány titka Este <span class="marked">kilenckor</span> Jutka úgy érezte, mintha a Béka mindig is náluk lett volna.', true, '21:00', '21:00', '21:00', 1260, 1260, 1260, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4376', 'Fehér Klára', 'novel', 'https://mek.oszk.hu/02400/02491/02491.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Négyen meg a Béka', 'https://mek.oszk.hu/02400/02491', 'de még külön Öcsivel is. A motorbicikli elrobogott, a hős életmentők pedig hozzáláttak a megrongált kikötő és a kerítés rendbehozásához. Szerencsére nem volt olyan nagy a baj, mint ahogy első ijedtségükben látták. <span class="marked">Egy óra</span> alatt felépítették a csónakkikötő gátját, este hat órára p edig már a kerítés is készen állt.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4376', 'Fehér Klára', 'novel', 'https://mek.oszk.hu/02400/02491/02491.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Négyen meg a Béka', 'https://mek.oszk.hu/02400/02491', 'kozmás lábasra pislogott -, mosogasson a főszakács. Én majd segítek neki. HUSZADIK FEJEZET Sasok Sziklája és Mesélő Part - Megint nyár van! Megint nyár van! - harsogott kora reggel Öcsi boldog kiabálása. Még csak <span class="marked">fél hat</span> volt, de valamennyien kibújtak a sátorból.', true, '05:30', '05:30', '05:30', 330, 330, 330, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4376', 'Fehér Klára', 'novel', 'https://mek.oszk.hu/02400/02491/02491.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Négyen meg a Béka', 'https://mek.oszk.hu/02400/02491', 'méltóságteljesen. - Javasolom, hogy csak este hozzunk tejet. Reggelire teát iszunk zsíros kenyérrel, hogy minél korábban vízre szállhassunk, kedves Bölcs Nyaralók! - indítványozta Palkó. Így történt, hogy alig múlt <span class="marked">hat óra</span>, a Száguldó kifutott az öbölből.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4376', 'Fehér Klára', 'novel', 'https://mek.oszk.hu/02400/02491/02491.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Négyen meg a Béka', 'https://mek.oszk.hu/02400/02491', 'A nap forrón tüzelt, és olyan sokan úsztak a Balatonban, hogy a Bölcs Nyaralók elhatározták - inkább holnapra hagyják a Balaton túlsó csücskét, de ma strandolni fognak. - Itt maradunk - mondta a kormányos. - Délután <span class="marked">hatkor</span> indulás haza. Miután ebbe mindenki beleegyezett, még Öcsi, a kapitány is, lementek a strandra. Itt nem lehetett a homokból a vízbe lépni, hosszú, benyúló fahíd - magyarul "stég" - vezetett a Balatonba. Öcsi mezítláb', true, '18:00', '18:00', '18:00', 1080, 1080, 1080, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4376', 'Fehér Klára', 'novel', 'https://mek.oszk.hu/02400/02491/02491.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Négyen meg a Béka', 'https://mek.oszk.hu/02400/02491', '- Jó - mondta Jutka. - Cseréljük el. Erről mindig egymásra fogunk gondolni. Egy csónak közeledett a tutajhoz. - Hát persze hogy itt vannak! - hallották Palkó felháborodott hangját. - Ilyen mélyre úsztatok! És már <span class="marked">hat óra</span> van! HUSZONKETTEDIK FEJEZET Lehet-e négy Bölcs Nyaralót otthon hagyni? "Táviratot leadtam a szomszéd üdülő gondnokánál" - ez a cédula várta a kirándulásról visszatérő társaságot. - A postás hagyta itt, a sátorajtóra', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4376', 'Fehér Klára', 'novel', 'https://mek.oszk.hu/02400/02491/02491.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Négyen meg a Béka', 'https://mek.oszk.hu/02400/02491', 'Megmosakodtak, megfésülködtek, virágot tettek az asztalra, még jobban kifényesítették a szandáljukat - de csak nem akart este <span class="marked">hat óra</span> lenni. - Írjunk leckét - mondta a Béka -, kezdjük el a Nyári Naplót, amit Éva néni feladott. - Minek az neked? - mondta Jutka. - Ha úgyis más iskolába mész... - Nahát, csak nem gondolod, hogy ezért nem csinálom meg a', true, '18:00', '18:00', '18:00', 1080, 1080, 1080, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4376', 'Fehér Klára', 'novel', 'https://mek.oszk.hu/02400/02491/02491.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Négyen meg a Béka', 'https://mek.oszk.hu/02400/02491', '- Ha úgyis más iskolába mész... - Nahát, csak nem gondolod, hogy ezért nem csinálom meg a leckét! - tiltakozott a Béka. - Jó dolgod van, Béka - mondta Öcsi, de aztán zavartan elhallgatott. - Szegény Béka, igazán... <span class="marked">Háromnegyed hatkor</span> Kari kerékpárra pattant, a gyerekek megigazították a csokrokat, még egy utolsó főpróbát tartottak az indulóból, és aztán füleltek, hallják-e már a vonat fü ttyét vagy a zakatolást.', true, '05:45', '05:45', '05:45', 345, 345, 345, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4376', 'Fehér Klára', 'novel', 'https://mek.oszk.hu/02400/02491/02491.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Négyen meg a Béka', 'https://mek.oszk.hu/02400/02491', 'Béka, igazán... Háromnegyed hatkor Kari kerékpárra pattant, a gyerekek megigazították a csokrokat, még egy utolsó főpróbát tartottak az indulóból, és aztán füleltek, hallják-e már a vonat fü ttyét vagy a zakatolást. <span class="marked">Hat óra</span> után néhány perccel visszaérkezett Kari.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4376', 'Fehér Klára', 'novel', 'https://mek.oszk.hu/02400/02491/02491.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Négyen meg a Béka', 'https://mek.oszk.hu/02400/02491', 'tetszik jönni! - A férjem és a gyerekeim a másik vonattal utaztak Badacsonyba, téged, Teri, átviszlek hajón Füredre, oda jönnek eléd Marczallék - én pedig megyek tovább Badacsonyba. Hol vannak a csomagjaid, gyerekem? <span class="marked">Tizenegykor</span> megy a hajónk. - Éva néni, ne tessék haragudni, nem tudtam már értesítést küldeni, de én nem megyek... - Hanem? - Az úgy volt... - mondta Jutka, és ő is elakadt. Éva néni halványan elmosolyodott. - Hát akkor, te itt', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4376', 'Fehér Klára', 'novel', 'https://mek.oszk.hu/02400/02491/02491.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Albert Savarus', 'https://mek.oszk.hu/03400/03490', 'Amédée aztán négy óráig dolgozott , majd átöltözött, vacsorára lévén hivatalos; estéjét viszttel ütötte el a város arisztokrata szalonjaiban, s végül <span class="marked">tizenegykor</span> hazament, lefeküdt. Nem volt titkolnivalója, józanul, feddhetetlenül élt, mint kevesen; vasárnap és ünnepnap a templomban is pontosan megjelent. És mégis kirítt - hogy megértsék, miért, pár szóval hadd vázoljuk fel', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5466', 'Balzac Honoré de', 'novel', 'https://mek.oszk.hu/03400/03490/03490.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Albert Savarus', 'https://mek.oszk.hu/03400/03490', 'Sétálni a kertben szokott: ötvenszer, hatvanszor is körüljárja; aztán bemegy, megvacsorál, és <span class="marked">hat óra</span>, hét óra tájt aludni tér. - Maga mindezt honnan tudja? - kérdezte Chavoncourt-né. - Először is, asszonyom, a Neuve utcában lakom, a Perron utca sarkán, épp odalátok a házra, ahol ez a titokzatos alak lakik; aztán meg', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5466', 'Balzac Honoré de', 'novel', 'https://mek.oszk.hu/03400/03490/03490.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Albert Savarus', 'https://mek.oszk.hu/03400/03490', 'benedvesíti a l ábát, megkereste azt a víz alámosta gránitpadot, amelyet sűrű sövény koronázott tövises akácból, s amelyet a Bergmann kertben fiatal nyárfák szegélyezte út kísért végig; itt a gránitpad alatt leült. <span class="marked">Egy óra</span> múltán hangokat és lépéseket hallott a feje fölöt t; de csupa olasz szó volt, ami a füléhez ért, ejtőik pedig nők - két fiatal nő.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5466', 'Balzac Honoré de', 'novel', 'https://mek.oszk.hu/03400/03490/03490.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Albert Savarus', 'https://mek.oszk.hu/03400/03490', 'szívbe is vigaszt lopott. Mosolya a remény rózsáit hintette Rodolphe gyászára. Énekelt is, de most nem vidám dalokat, hanem komoly, nemes dallamokat választott Rodo lphe bánatához illőn, akit meghatott ez a figyelem. <span class="marked">Nyolc óra</span> tájt az aggastyán visszavonult szobájába, minden aggály nélkül együtt hagyta a két fiatalt.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5466', 'Balzac Honoré de', 'novel', 'https://mek.oszk.hu/03400/03490/03490.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Albert Savarus', 'https://mek.oszk.hu/03400/03490', 'úgy, ahogyan Albert gyötrődött hazafelé menet a teremből, ahol sorsa megpecsételődött. Kétségbeesett szerelmesünk elhárította a kísérőnek aján lkozókat. Magányosan csatangolt az utcákon tizenegytől egészen éjfélig. Éji <span class="marked">egy órakor</span> Albert, kit az álom már három napja elkerült, könyvtárában ült egy Voltaire-karosszékben, vértelen arccal kuporgott ott, mint akiből tüstént kiszáll a lélek, lecsüngő kézzel, magába roskadtan, akár Mária Magdolna.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5466', 'Balzac Honoré de', 'novel', 'https://mek.oszk.hu/03400/03490/03490.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Albert Savarus', 'https://mek.oszk.hu/03400/03490', 'őrá úgy számíthatunk, mint tulajdon magunkra. - Elhozom majd a hercegnét, hogy megáldjon minket, atyám! - kiáltott fel törtetőnk. És miután kikísérte az agg papot, Albert a hatalom bíborágyán szenderült el. Másnap este <span class="marked">kilenckor</span>, mint elgondolhatják, Watteville báróné szalonjaiban összesereglett a besançoni arisztokrácia, rendkívüli ügyben hívták egybe.', true, '21:00', '21:00', '21:00', 1260, 1260, 1260, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5466', 'Balzac Honoré de', 'novel', 'https://mek.oszk.hu/03400/03490/03490.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Albert Savarus', 'https://mek.oszk.hu/03400/03490', 'meg!... Fitz-James herceget ki fogják nevezni Toulouse-ba... Ön megnyeri Watteville úrnak a perét!... Ha Savarus úrra szavaz, a republikánusok inkább önt követik, mintsem a középet! - És így tovább, és így tovább. <span class="marked">Kilenckor</span> Albert még mindig hiányzott. Ennyi késést a báróné felháborítónak talált. - Drága báróné - mondta neki Chavoncourt-né -, fontos dolgokról lévén szó, ne kicsinyeskedjünk. Talán nehezen szárad a lakk a csizmáján...', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5466', 'Balzac Honoré de', 'novel', 'https://mek.oszk.hu/03400/03490/03490.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Albert Savarus', 'https://mek.oszk.hu/03400/03490', 'csomagolni; leveleket is írt biztosan; utoljára meg rendbe tette a dolgait Girardet úrral, aki eljött hozzá, és hétig nála maradt. Jér ôme levelet vitt Boucher úrnak, aki vacsorára várta az ügyvéd urat. És aztán, <span class="marked">fél nyolckor</span>, útnak indult, kiadva Jérôme-nak háromhavi bérét azzal, hogy keressen új helyet magának.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5466', 'Balzac Honoré de', 'novel', 'https://mek.oszk.hu/03400/03490/03490.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Albert Savarus', 'https://mek.oszk.hu/03400/03490', 'A kulcsait Girardet úrnak adta át, hazavitte őt, és megevett nála egy tányér levest, ahogy Jérôme mondja, mert Girardet úr <span class="marked">fél nyolckor</span> még vacsora előtt volt. Amikor megint beült a kocsijába, Savaron úr olyan volt, akár a halál. Jérôme persze elköszönt a gazdájától, és még hallotta, ahogy odaszól a postakocsisnak: "A genfi útra!" - Megtudakolta Jérôme', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5466', 'Balzac Honoré de', 'novel', 'https://mek.oszk.hu/03400/03490/03490.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Balla József: Szilveszteri meglepetés', 'https://mek.oszk.hu/12900/12952', '<div class="foundtext"> jönnöm.
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Tizenkét szék', 'https://mek.oszk.hu/00400/00412', 'április 15-én, pénteken, Ippolit Matvejevics szokása szerint <span class="marked">fél nyolckor</span> ébredt, és tüstént orrára biggyesztette arany nyergű, ódivatú csíptetőjét; keretes szemüveget nem viselt.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2411', 'Ilf Ilja', 'novel', 'https://mek.oszk.hu/00400/00412/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Tizenkét szék', 'https://mek.oszk.hu/00400/00412', 'június 15-én, a szobor leleplezését követő első éjen tűnt <span class="marked">fel egy</span> ilyen felírás. S akárhogy buzgólkodott is a cári rendőrség s később a szovjet rendő rség, a gyalázatos szó nap nap után pontosan újra megjelent. A zsalugáteres faházakban már duruzsoltak a szamovárok. Itt volt a', true, '00:30', '00:30', '00:30', 30, 30, 30, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2411', 'Ilf Ilja', 'novel', 'https://mek.oszk.hu/00400/00412/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Tizenkét szék', 'https://mek.oszk.hu/00400/00412', 'A Titanic nyomai Ippolit Matvejevics szokása szerint <span class="marked">fél nyolckor</span> ébredt, gut'' Morgen -t dünnyögött, és a mosdóhoz vonult.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2411', 'Ilf Ilja', 'novel', 'https://mek.oszk.hu/00400/00412/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Tizenkét szék', 'https://mek.oszk.hu/00400/00412', 'Az emeletre tölgyfa lépcsősor vezetett fel, valaha fényezett fokokkal, Most csak a gyűrűk meredeztek ki belőlük, de a rézrudaknak, m elyek <span class="marked">egykor</span> a szőnyeget szorították le, hűlt helyük volt.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2411', 'Ilf Ilja', 'novel', 'https://mek.oszk.hu/00400/00412/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Tizenkét szék', 'https://mek.oszk.hu/00400/00412', 'az utcára, és a város központja felé rohant. Sokrétű képességei eleinte nem tudtak méltó érvényesülési teret találni, minthogy közönség még kevés volt, és a lovas rendőröktől őrzött ünnepi tribünök üresen tátongtak. De <span class="marked">kilenc óra</span> körül mindenfelé felharsantak a zen ekarok.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2411', 'Ilf Ilja', 'novel', 'https://mek.oszk.hu/00400/00412/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Tizenkét szék', 'https://mek.oszk.hu/00400/00412', 'Egy irányba lépdelt, robogott, menetelt minden: az új villamoskocsiszín felé, amelyből pont osan délben <span class="marked">egy órakor</span> kellett az első sztargorodi villamosnak kifutnia.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2411', 'Ilf Ilja', 'novel', 'https://mek.oszk.hu/00400/00412/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Tizenkét szék', 'https://mek.oszk.hu/00400/00412', 'Gavrilin, kalauzkabátban és vállán átvetett táskával, kocsiból kocsiba ugrált, kedvesen mosolygott, játékosan meg-megrántotta a csengőt, és az utasok közt meghívókat osztogatott a községi alkalmazottak klubjában, május elsején <span class="marked">kilenc órakor</span> tartandó ünnepi estre, me lynek programja: 1.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2411', 'Ilf Ilja', 'novel', 'https://mek.oszk.hu/00400/00412/html/01.htm', 'deep_extract', false);
