INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Rettenetes évek', 'https://mek.oszk.hu/00400/00409', 'Pontosan egy hónapja, augusztus 2-án, Saarbrückenben játszott a háborúval. Aki most megmenti Franciaországot, Európát menti meg. Rikkancsokat látni, hatalmas plakátokat visznek III. Napóleon fogoly szöveggel . <span class="marked">Fél hat</span>. Charles és barátaink hazatértek. Kilenc óra. Száműzöttek gyűlése, Charles-lal együtt ott vagyok én is. Kérdés: háromszínű lobogó legyen, vagy vörös zászló? Szeptember 4. - Kikiáltották a császár bukását. Egy órakor', true, '05:30', '05:30', '05:30', 330, 330, 330, '{"Szépirodalom, népköltészet | Történelem, helytörténet","Klasszikus világirodalom"}', 'urn:nbn:hu-2408', 'Hugo Victor', 'poems', 'https://mek.oszk.hu/00400/00409/00409.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Rettenetes évek', 'https://mek.oszk.hu/00400/00409', 'Saarbrückenben játszott a háborúval. Aki most megmenti Franciaországot, Európát menti meg. Rikkancsokat látni, hatalmas plakátokat visznek III. Napóleon fogoly szöveggel . Fél hat. Charles és barátaink hazatértek. <span class="marked">Kilenc óra</span>. Száműzöttek gyűlése, Charles-lal együtt ott vagyok én is. Kérdés: háromszínű lobogó legyen, vagy vörös zászló? Szeptember 4. - Kikiáltották a császár bukását. Egy órakor összegyűlnek a száműzöttek. Három órakor a', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet | Történelem, helytörténet","Klasszikus világirodalom"}', 'urn:nbn:hu-2408', 'Hugo Victor', 'poems', 'https://mek.oszk.hu/00400/00409/00409.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Rettenetes évek', 'https://mek.oszk.hu/00400/00409', '. Fél hat. Charles és barátaink hazatértek. Kilenc óra. Száműzöttek gyűlése, Charles-lal együtt ott vagyok én is. Kérdés: háromszínű lobogó legyen, vagy vörös zászló? Szeptember 4. - Kikiáltották a császár bukását. <span class="marked">Egy órakor</span> összegyűlnek a száműzöttek. Három órakor a következőképpen megszövegezett távirat érkezik Párizsból: Azonnal hozzátok a gyerekeket. Azaz: Gyertek . Jules Claretie és Proust urak velünk vacsoráztak. Vacsora közben', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet | Történelem, helytörténet","Klasszikus világirodalom"}', 'urn:nbn:hu-2408', 'Hugo Victor', 'poems', 'https://mek.oszk.hu/00400/00409/00409.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Rettenetes évek', 'https://mek.oszk.hu/00400/00409', 'Gyertek . Jules Claretie és Proust urak velünk vacsoráztak. Vacsora közben François Hugo aláírással távirat érkezik, és közli, hogy ideiglenes kormány alakult: Jules Favre, Gambetta, Thiers. Szeptember 5. - Hajnali <span class="marked">hatkor</span> egy Barbieux aláírású táviratot hoznak: azt kérdezik benne, hány órakor érkezem Párizsba.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet | Történelem, helytörténet","Klasszikus világirodalom"}', 'urn:nbn:hu-2408', 'Hugo Victor', 'poems', 'https://mek.oszk.hu/00400/00409/00409.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Rettenetes évek', 'https://mek.oszk.hu/00400/00409', 'Charles-lal azt a választ küldöm, hogy este <span class="marked">kilenckor</span>. Visszük a gyerekeket. A két-óra-harmincötös vonattal indulunk. Az újságírók szerint az ideiglenes kormánynak Thiers kivételével tagja Párizs minden képviselője. Délben, amikor Brüsszelből éppen indulni készültem', true, '21:00', '21:00', '21:00', 1260, 1260, 1260, '{"Szépirodalom, népköltészet | Történelem, helytörténet","Klasszikus világirodalom"}', 'urn:nbn:hu-2408', 'Hugo Victor', 'poems', 'https://mek.oszk.hu/00400/00409/00409.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Rettenetes évek', 'https://mek.oszk.hu/00400/00409', 'sisak van rajta. Egy nagy kőkockán ül, bélelt csizmát húz fel. Vállán átvetve egy bőrzsák. Aztán leveszi, bemegy a léghajóba, egy fiatalember pedig, a léghajós a kötélzethez kötözi a zsákot Gambetta feje fölé. Ez <span class="marked">fél tizenegykor</span> történt. Gyönyörű idő. Gyenge déli szél. Enyhe őszi napfény. A sárga léghajó hirtelen magasba emelkedik, kosarában három férfi, köztük Gambetta. Aztán felszáll a fehér léggömb, az is három személyt visz, az egyik', true, '10:30', '10:30', '10:30', 630, 630, 630, '{"Szépirodalom, népköltészet | Történelem, helytörténet","Klasszikus világirodalom"}', 'urn:nbn:hu-2408', 'Hugo Victor', 'poems', 'https://mek.oszk.hu/00400/00409/00409.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Rettenetes évek', 'https://mek.oszk.hu/00400/00409', 'Émile Allix hozott egy porosz ágyúgolyóbist: Montrouge-ban szedte <span class="marked">fel egy</span> barikád mögött, ahol a lövedék megölt két lovat.', true, '00:30', '00:30', '00:30', 30, 30, 30, '{"Szépirodalom, népköltészet | Történelem, helytörténet","Klasszikus világirodalom"}', 'urn:nbn:hu-2408', 'Hugo Victor', 'poems', 'https://mek.oszk.hu/00400/00409/00409.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Rettenetes évek', 'https://mek.oszk.hu/00400/00409', 'szabadon bocsátották, fél hétkor eljött hozzám a kis Henriért. Apa és fia boldogok. Október 28. - Felkeresett Edgar Quinet. Nálam vacsorázott Schoelcher és Farcy főhadnagy, aki nevét adta ágyúnaszádjának. Étkezés után, <span class="marked">fél kilenckor</span>, Schoelcherrel kettesben elmentünk a lakására, a De la Chaise utca 16-ba.', true, '08:30', '08:30', '08:30', 510, 510, 510, '{"Szépirodalom, népköltészet | Történelem, helytörténet","Klasszikus világirodalom"}', 'urn:nbn:hu-2408', 'Hugo Victor', 'poems', 'https://mek.oszk.hu/00400/00409/00409.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Rettenetes évek', 'https://mek.oszk.hu/00400/00409', 'A Fenyítések felolvasása miatt hat órára kellett előrehozni a vacsorát, ez a második előadás ugyanis <span class="marked">fél nyolckor</span> kezdődött a Porte-Saint-Martinben.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet | Történelem, helytörténet","Klasszikus világirodalom"}', 'urn:nbn:hu-2408', 'Hugo Victor', 'poems', 'https://mek.oszk.hu/00400/00409/00409.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Rettenetes évek', 'https://mek.oszk.hu/00400/00409', 'ezt mondaná: "Nem akarom, hogy rémkép legyél!" Szegény, drága angyal, talán előre érzi a közelgő csatát. Tegnap szarvast ettünk, tegnapelőtt medvét, az előző két napon antilopot. A Növénykert ajándékából. Ma este <span class="marked">tizenegykor</span> megszólaltak az ágyúk. Hevesen és rövid időre. December 4 . - Kiragasztottunk a kapumra egy felhívást: milyen elővigyázatossági intézkedések foganatosítandók ágyútűz esetén. Ez a felhívás címe. Harci szünet.', true, '23:00', '23:00', '23:00', 1380, 1380, 1380, '{"Szépirodalom, népköltészet | Történelem, helytörténet","Klasszikus világirodalom"}', 'urn:nbn:hu-2408', 'Hugo Victor', 'poems', 'https://mek.oszk.hu/00400/00409/00409.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Rettenetes évek', 'https://mek.oszk.hu/00400/00409', 'ma éjszaka lángba borították a Luxembourg zsúfolt barakkjait: a sebesült és beteg katonákat - meztelenül, éppen csak egy rongyba burkolva - át kellett szállítani az Irgalmasok kórházába. Barbieux látta őket: éjjel <span class="marked">egy óra</span> tájt érkeztek meg. Már tizenhat utcát szórtak meg lövedékekkel. Január 7. - A Feuillantines utcának azt a részét, ahol átszelték gyermekkorom kertjét, súlyos gránáttámadás érte. Mosónőm, akinek nincs már miből tüzet', true, '13:00', '13:00', '13:00', 780, 780, 780, '{"Szépirodalom, népköltészet | Történelem, helytörténet","Klasszikus világirodalom"}', 'urn:nbn:hu-2408', 'Hugo Victor', 'poems', 'https://mek.oszk.hu/00400/00409/00409.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Rettenetes évek', 'https://mek.oszk.hu/00400/00409', 'szegényasszony megjegyzése a frissen kivágott fáról: - Szegény zöld fa, tűzre vetik; váratlanul érte, ezért folyton sír! A pápa azt mondta Dupanloup abbéról: Orléans püspökének vasút közlekedik a fejében. Január 15. <span class="marked">2 órakor</span>. - Dühödt gránátozás e pillanatban. Cirkuszban címmel költeményt írok. Vacsora után felolvastam a verset vasárnapi asztaltársaimnak. Kérik, hogy tegyem közzé. Odaadom az újságoknak. Január 17. - Három nap óta', true, '02:00', '02:00', '02:00', 120, 120, 120, '{"Szépirodalom, népköltészet | Történelem, helytörténet","Klasszikus világirodalom"}', 'urn:nbn:hu-2408', 'Hugo Victor', 'poems', 'https://mek.oszk.hu/00400/00409/00409.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Rettenetes évek', 'https://mek.oszk.hu/00400/00409', 'Fő-bánatuk az, hogy nem ért el a halál, noha homlokodon éj lett a fénysugár; májadat az árnyak zord sasa eszi; versenyt tagadnak meg; s im, a martalóc-fejedelmek örömét, mint <span class="marked">egykor</span> a des Adrets mohó falkáját, tapsolja a világ...', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet | Történelem, helytörténet","Klasszikus világirodalom"}', 'urn:nbn:hu-2408', 'Hugo Victor', 'poems', 'https://mek.oszk.hu/00400/00409/00409.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Rettenetes évek', 'https://mek.oszk.hu/00400/00409', 'hederít ő. Éhség az étele, nincs asztalán terítő. A krumpli csemege és böcsülete nagy ma, s akár Egyiptomban, istenné lett a hagyma. Nincsen szenünk, de a kenyerünk, mint a szén. Gáz sincs; a bús város aluszik feketén. <span class="marked">Hatkor</span> koromsötét. És ájult borzalomba, tüzet okádva zúg fejünk fölött a bomba. Előttem egy gránitszilánk a kalamáris. Meggyilkoltan hever, nem szól egy szót se Párizs. A nemzetőrségünk a falaink körül, sipkába férj, apa', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet | Történelem, helytörténet","Klasszikus világirodalom"}', 'urn:nbn:hu-2408', 'Hugo Victor', 'poems', 'https://mek.oszk.hu/00400/00409/00409.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A kor szerelme', 'https://mek.oszk.hu/05100/05173', 'egész kommunista pártot, köztük Rákosit. Beszélt erről valamit? - A munkája sosem volt téma. - Puritán volt? - Amerika puritánjai hancúrozó playboyok voltak a szüleimhez képest. Vasárnap negyed kettőkor ebéd. Miért nem <span class="marked">egykor</span>? Ameddig itt laksz, fiam, így lesz. Hazamegyek este nyolc előtt pár perccel, apám sétál a szobában. Kérdem, nem vacsorázunk? Látod az órát? Nyolckor ülünk asztalhoz. Hatéves voltam, amikor kiakasztatott az ágyam fölé', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet | Szociológia, társadalomkutatás","Kortárs magyar irodalom"}', 'urn:nbn:hu-7715', 'Pünkösti Árpád', 'essays', 'https://mek.oszk.hu/05100/05173/05173.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A kor szerelme', 'https://mek.oszk.hu/05100/05173', 'voltak a szüleimhez képest. Vasárnap negyed kettőkor ebéd. Miért nem egykor? Ameddig itt laksz, fiam, így lesz. Hazamegyek este nyolc előtt pár perccel, apám sétál a szobában. Kérdem, nem vacsorázunk? Látod az órát? <span class="marked">Nyolckor</span> ülünk asztalhoz. Hatéves voltam, amikor kiakasztatott az ágyam fölé egy kis táblácskát: "Első a kötelesség!" Akár akartam, akár nem, mindennap legalább kétszer láttam. A dolgomat mindig elvégeztem, csak a könnyebbik', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet | Szociológia, társadalomkutatás","Kortárs magyar irodalom"}', 'urn:nbn:hu-7715', 'Pünkösti Árpád', 'essays', 'https://mek.oszk.hu/05100/05173/05173.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A kor szerelme', 'https://mek.oszk.hu/05100/05173', 'Nem tudtam, hogy a szobához reggeli is jár, <span class="marked">nyolckor</span> a bőröndön ültem, hogy a 9.45-ös géppel el tudjunk utazni, Kilenc óra, tíz óra, tizenegy óra, a főzeneigazgató úr sehol!', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet | Szociológia, társadalomkutatás","Kortárs magyar irodalom"}', 'urn:nbn:hu-7715', 'Pünkösti Árpád', 'essays', 'https://mek.oszk.hu/05100/05173/05173.htm', 'deep_extract', false);
