INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A kor szerelme', 'https://mek.oszk.hu/05100/05173', 'Nem tudtam, hogy a szobához reggeli is jár, nyolckor a bőröndön ültem, hogy a 9.45-ös géppel el tudjunk utazni, <span class="marked">Kilenc óra</span>, tíz óra, tizenegy óra, a főzeneigazgató úr sehol!', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet | Szociológia, társadalomkutatás","Kortárs magyar irodalom"}', 'urn:nbn:hu-7715', 'Pünkösti Árpád', 'essays', 'https://mek.oszk.hu/05100/05173/05173.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A kor szerelme', 'https://mek.oszk.hu/05100/05173', 'Nem tudtam, hogy a szobához reggeli is jár, nyolckor a bőröndön ültem, hogy a 9.45-ös géppel el tudjunk utazni, Kilenc óra, tíz óra, <span class="marked">tizenegy óra</span>, a főzeneigazgató úr sehol! Felhív aztán, hogy felébredtem-e. Izgatott kérdésemre nevetve mondta, hogy az indulási idő jelképes: "Majd telefonálnak, hogy futás, ha fel és le tudunk szállni"! A szoba bárszekrényében már', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet | Szociológia, társadalomkutatás","Kortárs magyar irodalom"}', 'urn:nbn:hu-7715', 'Pünkösti Árpád', 'essays', 'https://mek.oszk.hu/05100/05173/05173.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A kor szerelme', 'https://mek.oszk.hu/05100/05173', 'mozdulatlanság, felpolcolt, borogatott láb. - Vécére sem mehetek? - jajdulok fel. - Szó sem lehet róla! - kopog a válasz, hiába nézek kérlelőn Elemérre. Hát ő is ellenem van!? Magamba zuhanok. Tizenharmadika, péntek, <span class="marked">fél egy</span>. Biztos, itt is mindenki lógna haza, mégis megindul köröttem és velem a szaladgálás. Féltucatnyi kémcsőbe csapolják a véremet; Géza, a betegszállítók minisztere megint ölbe kap, irány a röntgen. Bűnös lélek: a', true, '00:30', '00:30', '00:30', 30, 30, 30, '{"Szépirodalom, népköltészet | Szociológia, társadalomkutatás","Kortárs magyar irodalom"}', 'urn:nbn:hu-7715', 'Pünkösti Árpád', 'essays', 'https://mek.oszk.hu/05100/05173/05173.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A kor szerelme', 'https://mek.oszk.hu/05100/05173', 'meg a vére.) Reggel, este vérvétel, és attól függően adnak több vagy kevesebb Heparint, hogy mennyi a véralvadási idő. A legjobb, ha 15-20 perc között van. Egyszer 30 perc, és mindenki ideges, engem kivéve. Legyen akár <span class="marked">egy óra</span> is, gyógyulni akarok! Személyes sérelemnek veszem, ha óvatosságból 15 perc alá engedik. Bátorítanám az orvost, ne sajnálja azt a rohadt injekciót, de mindennap más az ügyeletes, és két emelettel odébb van. Szegény', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet | Szociológia, társadalomkutatás","Kortárs magyar irodalom"}', 'urn:nbn:hu-7715', 'Pünkösti Árpád', 'essays', 'https://mek.oszk.hu/05100/05173/05173.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A kor szerelme', 'https://mek.oszk.hu/05100/05173', '(A kórház másik épületében valaki százezer forintért szereltetett <span class="marked">fel egy</span> óriás védőhálót, hogy a galambok ne piszkítsanak - közvetlenül - a párkányokra.', true, '00:30', '00:30', '00:30', 30, 30, 30, '{"Szépirodalom, népköltészet | Szociológia, társadalomkutatás","Kortárs magyar irodalom"}', 'urn:nbn:hu-7715', 'Pünkösti Árpád', 'essays', 'https://mek.oszk.hu/05100/05173/05173.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A kor szerelme', 'https://mek.oszk.hu/05100/05173', 'Társasházunkban is tudja mindenki, hogy Elemér rendszerint reggel <span class="marked">fél nyolckor</span> indul el a kórházba, és csak este fél nyolckor jön onnan haza.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet | Szociológia, társadalomkutatás","Kortárs magyar irodalom"}', 'urn:nbn:hu-7715', 'Pünkösti Árpád', 'essays', 'https://mek.oszk.hu/05100/05173/05173.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A kor szerelme', 'https://mek.oszk.hu/05100/05173', 'Társasházunkban is tudja mindenki, hogy Elemér rendszerint reggel fél nyolckor indul el a kórházba, és csak este <span class="marked">fél nyolckor</span> jön onnan haza. Hét végén becsönget, és hiába látom, hogy éppoly nyúzott, mint én, belévágom a kérdést: - Ha rákom lett volna, azt is megmondod? - Hű, de nehezet kérdeztél! - szakad ki belőle. - Annyi minden lehetett', true, '19:30', '19:30', '19:30', 1170, 1170, 1170, '{"Szépirodalom, népköltészet | Szociológia, társadalomkutatás","Kortárs magyar irodalom"}', 'urn:nbn:hu-7715', 'Pünkösti Árpád', 'essays', 'https://mek.oszk.hu/05100/05173/05173.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A kor szerelme', 'https://mek.oszk.hu/05100/05173', 'én. Hazalátogatva azt hittem, a környezet riaszt. A fenét! Az önálló élet kezdett átkos porhüvely zavart. Azóta megszoktam, s úgy gondolom, egy darabig még kerülgetjük egymást. (1990) Mire számíthatok, doktor úr? Este <span class="marked">hatkor</span> volt Stockholm mellett a baleset.', true, '18:00', '18:00', '18:00', 1080, 1080, 1080, '{"Szépirodalom, népköltészet | Szociológia, társadalomkutatás","Kortárs magyar irodalom"}', 'urn:nbn:hu-7715', 'Pünkösti Árpád', 'essays', 'https://mek.oszk.hu/05100/05173/05173.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A kor szerelme', 'https://mek.oszk.hu/05100/05173', 'riaszt. A fenét! Az önálló élet kezdett átkos porhüvely zavart. Azóta megszoktam, s úgy gondolom, egy darabig még kerülgetjük egymást. (1990) Mire számíthatok, doktor úr? Este hatkor volt Stockholm mellett a baleset. <span class="marked">Fél nyolckor</span> Koppenhága értesítette Budapestet, hogy éjfélre repülőt küldenek a transzplantációra váró betegért, az orvosokért.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet | Szociológia, társadalomkutatás","Kortárs magyar irodalom"}', 'urn:nbn:hu-7715', 'Pünkösti Árpád', 'essays', 'https://mek.oszk.hu/05100/05173/05173.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A kor szerelme', 'https://mek.oszk.hu/05100/05173', 'volt Stockholm mellett a baleset. Fél nyolckor Koppenhága értesítette Budapestet, hogy éjfélre repülőt küldenek a transzplantációra váró betegért, az orvosokért. Ötévi reménykedés után másnap, 1994. március 8-án reggel <span class="marked">nyolckor</span> elkezdődhetett Koppenhágában a műtét.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet | Szociológia, társadalomkutatás","Kortárs magyar irodalom"}', 'urn:nbn:hu-7715', 'Pünkösti Árpád', 'essays', 'https://mek.oszk.hu/05100/05173/05173.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A kor szerelme', 'https://mek.oszk.hu/05100/05173', 'lehet, hogy a burával együtt visznek el! A Malév gépe reggel meg délután megy. Koppenhágába. Előtte öt-hat órával sehová nem mozdultam. Féltem, hogy éjszaka jön a hívás, hogy nem láthatom a gyerekeimet. Hétfőn este <span class="marked">fél nyolckor</span> arra gondoltam, mivel kedd reggel nincs járat, mégis elosonok a fodrászhoz, Háromnegyed nyolckor megszólalt a telefon ,s a tanár úr csendes, nyugodt hangján közölte, tíz órára legyek Jakab professzor lakásán, repülőt küldenek értünk, éjfélkor indulunk.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet | Szociológia, társadalomkutatás","Kortárs magyar irodalom"}', 'urn:nbn:hu-7715', 'Pünkösti Árpád', 'essays', 'https://mek.oszk.hu/05100/05173/05173.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A kor szerelme', 'https://mek.oszk.hu/05100/05173', 'Hétfőn este fél nyolckor arra gondoltam, mivel kedd reggel nincs járat, mégis elosonok a fodrászhoz, <span class="marked">Háromnegyed nyolckor</span> megszólalt a telefon ,s a tanár úr csendes, nyugodt hangján közölte, tíz órára legyek Jakab professzor lakásán, repülőt küldenek értünk, éjfélkor indulunk.', true, '07:45', '07:45', '07:45', 465, 465, 465, '{"Szépirodalom, népköltészet | Szociológia, társadalomkutatás","Kortárs magyar irodalom"}', 'urn:nbn:hu-7715', 'Pünkösti Árpád', 'essays', 'https://mek.oszk.hu/05100/05173/05173.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A kor szerelme', 'https://mek.oszk.hu/05100/05173', 'lévő altatóorvos - a tanár úr tolmácsolt -, s elmondta a tízórás műtét lefolyását, hogy ne ijedjen meg, ha felébredve nem fog tudni beszélni, mert lélegeztetőgépen lesz. Szavaiból Klára szinte semmire sem emlékszik. <span class="marked">Nyolckor</span> - Jakab professzor asszisztálásával - elkezdődött a műtét.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet | Szociológia, társadalomkutatás","Kortárs magyar irodalom"}', 'urn:nbn:hu-7715', 'Pünkösti Árpád', 'essays', 'https://mek.oszk.hu/05100/05173/05173.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A kor szerelme', 'https://mek.oszk.hu/05100/05173', '- Tiszteletem, Tanár úr! - köszöntötte őt mezítlábas bokáját összecsapva Mányai és Bárdy művész úr, ám vonulás közben a maestró fehér haját szórakozottan lobogtatta a szél. - Könnyű neki, ő a Bartók-Kodály! Hajnali <span class="marked">hatkor</span> beszédelgett Greguss Zoltán, aki még haza sem ment, s rászólt Kodályra: - Hubaykám, kilóg a töke!', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet | Szociológia, társadalomkutatás","Kortárs magyar irodalom"}', 'urn:nbn:hu-7715', 'Pünkösti Árpád', 'essays', 'https://mek.oszk.hu/05100/05173/05173.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A kor szerelme', 'https://mek.oszk.hu/05100/05173', 'ezerarcú, Más a közönség hajnalban (íróasztalosok), délben (színészek), délután (szerkesztők), este (magányosok). Ha a törzsközönség egy részére nem is csupán az úszás jellemző, a többség, húsz-negyven percet tempózik. <span class="marked">Hatkor</span> a munkába indulók állnak sorban.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet | Szociológia, társadalomkutatás","Kortárs magyar irodalom"}', 'urn:nbn:hu-7715', 'Pünkösti Árpád', 'essays', 'https://mek.oszk.hu/05100/05173/05173.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A kor szerelme', 'https://mek.oszk.hu/05100/05173', 'és ahogy jött, eltűnt. Soha nem jelentkezett, de mindenkivel azt üzente szívesen lát bennünket szállásra és egy teli jégszekrényre. Mindenkit. A húszéves találkozóra hiába hívtuk, nem kapta meg a beutazó vízumot. <span class="marked">Egy óra</span> tájt fölmentem a szobába. Nem voltam álmos, de nem bírtam, nem akartam Paul és Vali táncát nézni. Úgy éreztem magam, mint ott a Maros torkolatnál, az ártéri erdő szélén. Arra futottam és megláttam őket. Táncuk közben', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet | Szociológia, társadalomkutatás","Kortárs magyar irodalom"}', 'urn:nbn:hu-7715', 'Pünkösti Árpád', 'essays', 'https://mek.oszk.hu/05100/05173/05173.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A kor szerelme', 'https://mek.oszk.hu/05100/05173', 'három helyen tanított matematikát, így inkább a férj nevelte a három gyermeket: - Azért lettek ilyen becsületesek és ügyetlenek - jegyzi meg Mária néni. A házban pillanatok alatt kialakultak a hírcsatornák. Este 9-<span class="marked">10 óra</span> körül ért a Molnár utca 5-be a hír, hogy mi történt a rádiónál.', true, '10:00', '10:00', '10:00', 600, 600, 600, '{"Szépirodalom, népköltészet | Szociológia, társadalomkutatás","Kortárs magyar irodalom"}', 'urn:nbn:hu-7715', 'Pünkösti Árpád', 'essays', 'https://mek.oszk.hu/05100/05173/05173.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A kor szerelme', 'https://mek.oszk.hu/05100/05173', 'Este aztán suttogva fölteszi a régi lemezt: - <span class="marked">Háromnegyed hatkor</span> otthagyott a kórházban, hogy álmos, megy haza.', true, '05:45', '05:45', '05:45', 345, 345, 345, '{"Szépirodalom, népköltészet | Szociológia, társadalomkutatás","Kortárs magyar irodalom"}', 'urn:nbn:hu-7715', 'Pünkösti Árpád', 'essays', 'https://mek.oszk.hu/05100/05173/05173.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anna Karenina', 'https://mek.oszk.hu/00500/00510', 'Az összeveszés után harmadnap Sztyepan Arkagyics Oblonszkij herceg - Sztyiva, ahogy a társaságban hívták - a szokott időben, azaz reggel <span class="marked">nyolckor</span>, nem a felesége hálójában, hanem a saját dolgozószobájában, a szattyánbőr díványon ébredt fel.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2509', 'Tolsztoj Lev Nyikolajevics', 'novel', 'https://mek.oszk.hu/00500/00510/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Anna Karenina', 'https://mek.oszk.hu/00500/00510', 'estére felöltözzék, s a tükörbe pillantott, örömmel látta, hogy jó napja van, teljes birtokában van az erejének, de ahhoz, ami várta, szüksége is volt rá; külsőleg, érezte, nyugodt, s a mozdulatai kecsesen szabadok. <span class="marked">Fél nyolckor</span>, alighogy lement a szalonba, Konsztantyin Dmitrics Levint jelentette az inas.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2509', 'Tolsztoj Lev Nyikolajevics', 'novel', 'https://mek.oszk.hu/00500/00510/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hetven lettem', 'https://mek.oszk.hu/12900/12945', '- Rendben. Hátha tudok azzal segíteni, hogy kibeszéled magadból a feszültséget, és legalább Anna nénivel is találkozom. Régen láttam őt. - Elmeséltem neki, hogy volt levélváltásunk, és agyon dicsért téged. Ha ma <span class="marked">18 óra</span> után el tudsz jönni hozzánk, az megfelelne.', true, '18:00', '18:00', '18:00', 1080, 1080, 1080, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-126628', 'Végh Miki', 'short stories', 'https://mek.oszk.hu/12900/12945/12945.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hetven lettem', 'https://mek.oszk.hu/12900/12945', 'neki, hogy volt levélváltásunk, és agyon dicsért téged. Ha ma 18 óra után el tudsz jönni hozzánk, az megfelelne. Ne féljél, nem kell sötétben hazabotorkálnod, hazaviszünk kocsival. - Látod, azt nem bánom. Akkor <span class="marked">18 órakor</span> nálatok, szia Dini! Azon ritka alkalom történt tegnap velem, amikor gyakorlatban nem fogadtam meg anyukám tanácsát. Jobbnak láttam e-mailben elküldeni a recepteket, pedig ő a lelkemre kötötte, hogy személyesen adjam át', true, '18:00', '18:00', '18:00', 1080, 1080, 1080, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-126628', 'Végh Miki', 'short stories', 'https://mek.oszk.hu/12900/12945/12945.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hetven lettem', 'https://mek.oszk.hu/12900/12945', 'Tornáztassa, fürdesse, és minden, ha anyukának úgy szimpatikusabb. Nem kínoztam tovább, az utolsó sugárkezeléseken nem vett részt. Anci pedig nem kérette magát. A házban azt hitték, hogy megbolondultam. Átlagban <span class="marked">23 óra</span> magasságában vittem őt naponta haza.', true, '23:00', '23:00', '23:00', 1380, 1380, 1380, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-126628', 'Végh Miki', 'short stories', 'https://mek.oszk.hu/12900/12945/12945.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hetven lettem', 'https://mek.oszk.hu/12900/12945', '- Rendben, akkor a szomszéd utcában várlak <span class="marked">16 óra után öt perccel</span>. Mármint ahol régen szoktalak várni, még mikor nem lettél hűtlen hozzám. - Valamint, amikor néha szántál rám is időt a pénzhajhászás mellett. - Kétségtelen. Ennek a hajhászásnak köszönhető, hogy most a könyvelőnőnek', true, '16:05', '16:05', '16:05', 965, 965, 965, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-126628', 'Végh Miki', 'short stories', 'https://mek.oszk.hu/12900/12945/12945.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hetven lettem', 'https://mek.oszk.hu/12900/12945', 'a markát. Ugyanis keményen megdolgoztam érte. - Én pedig a cseléded voltam. Munkám mellett vezettem a háztartást, minden este meleg vacsorával és nagyon nem utolsó sorban meleg ággyal fogadtalak. - Tehát akkor holnap <span class="marked">16 óra</span> öt perckor a szokott helyen várlak.', true, '16:00', '16:00', '16:00', 960, 960, 960, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-126628', 'Végh Miki', 'short stories', 'https://mek.oszk.hu/12900/12945/12945.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hetven lettem', 'https://mek.oszk.hu/12900/12945', '* Rezsőt sürgős munkához kihívták a telefontól, ezért abban maradtak, hogy délután <span class="marked">16 óra 5 perckor</span> várja Zsófit a szokott helyen.', true, '16:05', '16:05', '16:05', 965, 965, 965, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-126628', 'Végh Miki', 'short stories', 'https://mek.oszk.hu/12900/12945/12945.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hetven lettem', 'https://mek.oszk.hu/12900/12945', 'fel? - Nagy kő esett le a szívemről. Azt hittem, ezután a fontoskodó bevezetés után az következik, hogy keressem én fel önt, de mihamarabb, mert az ügy nem tűr halasztást. Nos, nézem a határidő naplómat. Ma délután <span class="marked">16 órakor</span> tudom fogadni az irodámban. Ugyanis reggel mondta le a délutáni találkozásunkat egy csintalan, csinosnak mondható kolléganője. Gondolom, nem kell elmondanom, hol az irodám, hiszen ön ezt az apróságot már régen', true, '16:00', '16:00', '16:00', 960, 960, 960, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-126628', 'Végh Miki', 'short stories', 'https://mek.oszk.hu/12900/12945/12945.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hetven lettem', 'https://mek.oszk.hu/12900/12945', 'csinosnak mondható kolléganője. Gondolom, nem kell elmondanom, hol az irodám, hiszen ön ezt az apróságot már régen kinyomozta. Elvégre azt is tudja, hogy hétvégén vadászni voltam. - Térjünk a lényegre! Rendben, pontban <span class="marked">16 órakor</span> ott vagyok, de nem szeretném, ha megvárakoztatna!', true, '16:00', '16:00', '16:00', 960, 960, 960, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-126628', 'Végh Miki', 'short stories', 'https://mek.oszk.hu/12900/12945/12945.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hetven lettem', 'https://mek.oszk.hu/12900/12945', 'a hangja, megjelenésében sem csúnya. Ha ez igaz, akkor szívesen firkálnék benne. Guszti, igyekezzél a fejeddel gondolkodni! Ébren vagy, nem úgy, mint az éhes disznó, amelyik makkal álmodik. Úgy intéztem a dolgot, hogy <span class="marked">16 óra 10 perckor</span> érjek csak rá. Addig várakoztattam a titkárságomon, miközben semmit nem csináltam. Telefonon szóltam ki a titkárnőnek, hogy küldheti a firkászt. Csinos, határozottan csinos volt a csaj. Jó alakú, ezért a minijében', true, '16:10', '16:10', '16:10', 970, 970, 970, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-126628', 'Végh Miki', 'short stories', 'https://mek.oszk.hu/12900/12945/12945.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hetven lettem', 'https://mek.oszk.hu/12900/12945', 'Fel sem vetődik magában, elmúlt <span class="marked">17 óra</span>, és még jelét nem mutattam annak, hogy próbálnék a kegyeibe férkőzni.', true, '17:00', '17:00', '17:00', 1020, 1020, 1020, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-126628', 'Végh Miki', 'short stories', 'https://mek.oszk.hu/12900/12945/12945.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hetven lettem', 'https://mek.oszk.hu/12900/12945', 'Ha a rágalmakban egyetlen pontban is vétkesnek talál, meghívom egy gyertyafényes vacsorára, kiengesztelés gyanánt. - Legyen gavallér, vezérigazgató úr! A tréfa kedvéért belenéztem a határidőnaplómba. - Ma este <span class="marked">20 órakor</span> ráér, Barbika? Ha igen, akkor vendégem egy tartalmas vacsorára, az elfogyasztás helyszínét ön határozhatja meg. - Nincsen ellenemre, de fontos lenne tudnom, mi a következő program. - Mi szokott lenni? - Fogyókúrázom,', true, '20:00', '20:00', '20:00', 1200, 1200, 1200, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-126628', 'Végh Miki', 'short stories', 'https://mek.oszk.hu/12900/12945/12945.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hetven lettem', 'https://mek.oszk.hu/12900/12945', 'lenni? - Fogyókúrázom, nem szoktam vacsorázni. * Eredetiben viccnek szántam a vacsorameghívást. Különböző okokból, de főleg azért, mert idegesített a modortalansága. Mindenesetre ő komolyan vette. Végül megbeszéltük, <span class="marked">háromnegyed nyolckor</span> találkozunk Pestnek egy bizonyos forgalmas pontján, ahova ő metróval érkezik.', true, '07:45', '07:45', '07:45', 465, 465, 465, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-126628', 'Végh Miki', 'short stories', 'https://mek.oszk.hu/12900/12945/12945.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hetven lettem', 'https://mek.oszk.hu/12900/12945', 'pillepalackban árusított kannásbort. - Tudom, ha Gyöngyi felkel, és teljes lesz a létszám, márkás ital kerül az asztalra ajándék gyanánt, csak győzzem kivárni. - Úgy mondod, mintha naponta fogyasztanál alkoholt. Reggel <span class="marked">fél nyolckor</span> csörrent meg először a telefon.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-126628', 'Végh Miki', 'short stories', 'https://mek.oszk.hu/12900/12945/12945.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az eltérített felvonó', 'https://mek.oszk.hu/08200/08227', 'mondja, jól figyeljek, mert fontos dologról van szó. Hét órakor nyomd meg a csengőt ennél és ennél a háznál. Vá r téged egy számtan tanár. Ő odaadja neked az érettségi tételt matematikából. Meg van beszélve. Te pedig <span class="marked">fél nyolckor</span> fölhívsz engem, s bediktálod a tételt.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-75471', 'Elekes Ferenc', 'short novel', 'https://mek.oszk.hu/08200/08227/08227.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az eltérített felvonó', 'https://mek.oszk.hu/08200/08227', 'Hogy a repülőn legyen időm gondolkozni a megoldásán, mert <span class="marked">kilenckor</span> indul a gépem Vásárhelyre. Éret tségizek... Fölhívom Jóskát a megbeszélt időben. És diktálom: két iksz a négyzeten, plusz 3 iksz, mínusz... Nem tudtam folytatni, mert közbeszólt Jóska. Azt kérdi mi ez, milyen nyelven', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-75471', 'Elekes Ferenc', 'short novel', 'https://mek.oszk.hu/08200/08227/08227.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Vészi Endre (1916-1987)', 'https://mek.oszk.hu/03300/03312', 'a maga néhány ezer lakosával mégis a teljes valóság. Egyformán lehetne nyersanyaga szociográfusnak, lélekbúvárnak és álomfejtőnek. Áthaladva a domb vájatába épült merőleges utcán, megállít a főút széles léniája. <span class="marked">Egykor</span> félfalusi főutca, országút része, ma félnagyvárosi körút, amely cserélődő sejtjeivel még őrzi a porszagú vidékiességet, de egy-két toronyházzal már kijelölte a jövő irányát.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet | Irodalomtörténet, irodalomtudomány | Katalógusok, bibliográfiák","Magyar irodalom története"}', 'urn:nbn:hu-5290', 'Magyar Elektronikus Könyvtár', 'virtual exhibition', 'https://mek.oszk.hu/03300/03312/html/APU HONLAPJA/PROZAI-MUVEK/semmit3.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Vészi Endre (1916-1987)', 'https://mek.oszk.hu/03300/03312', 'A sok száz éves házakban olajfűtés, éjjel-nappal forró víz, esetleg kondicionált levegő, az <span class="marked">egykor</span> közös nagymosásra létesített kővályúk, csobogók tőszomszédjaként önkiszolgáló villanymosoda.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet | Irodalomtörténet, irodalomtudomány | Katalógusok, bibliográfiák","Magyar irodalom története"}', 'urn:nbn:hu-5290', 'Magyar Elektronikus Könyvtár', 'virtual exhibition', 'https://mek.oszk.hu/03300/03312/html/APU HONLAPJA/PROZAI-MUVEK/semmit3.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Vészi Endre (1916-1987)', 'https://mek.oszk.hu/03300/03312', 'A napi tízórás munkaidőből, különösen ha meszet kellett oltani, 14-<span class="marked">15 óra</span> lett. Malterhordásban, téglahordásban, betonkeverésben, sokféle cipelésben, házimunkában görnyedt az inas. Csak éppen a szakmát nem tanulta. De én szerettem a szakmát, és akármilyen kemények is voltak a munkások, meg a', true, '15:00', '15:00', '15:00', 900, 900, 900, '{"Szépirodalom, népköltészet | Irodalomtörténet, irodalomtudomány | Katalógusok, bibliográfiák","Magyar irodalom története"}', 'urn:nbn:hu-5290', 'Magyar Elektronikus Könyvtár', 'virtual exhibition', 'https://mek.oszk.hu/03300/03312/html/APU HONLAPJA/PROZAI-MUVEK/semmit3.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Vészi Endre (1916-1987)', 'https://mek.oszk.hu/03300/03312', 'a különböző órabéreket. Így például a vasalónő számára az első évben 20 fillér órabért, a második évben 35 fillért ír elő az iparügyi miniszter rendelete, míg 2 év után 45 fillért kap a vasalónő. Hogy mennyi tehát napi <span class="marked">8 óra</span> mellett a heti kereset, ez könnyen megállapítható, de hogyan lehetséges ebből a keresetből csak félig is emberhez méltó színvonalon megélni, azt már kevésbé tudjuk.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet | Irodalomtörténet, irodalomtudomány | Katalógusok, bibliográfiák","Magyar irodalom története"}', 'urn:nbn:hu-5290', 'Magyar Elektronikus Könyvtár', 'virtual exhibition', 'https://mek.oszk.hu/03300/03312/html/APU HONLAPJA/PROZAI-MUVEK/semmit3.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Vészi Endre (1916-1987)', 'https://mek.oszk.hu/03300/03312', 'villamosra, mert kérem, már nem vagyok olyan fiatal. Ezt úgy mondja ez a szegény, megroggyant léptű öreg, mintha külön föl kellene hívni rá a figyelmet. Hány órát dolgozik egy nap? Körülbelül tizenegy órát. Reggel <span class="marked">fél nyolckor</span> bejövök az üzletbe, akkor kisöpröm a boltot.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet | Irodalomtörténet, irodalomtudomány | Katalógusok, bibliográfiák","Magyar irodalom története"}', 'urn:nbn:hu-5290', 'Magyar Elektronikus Könyvtár', 'virtual exhibition', 'https://mek.oszk.hu/03300/03312/html/APU HONLAPJA/PROZAI-MUVEK/semmit3.htm', 'deep_extract', false);
