INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A szépfiú', 'https://mek.oszk.hu/03100/03155', 'Béreld ki vagy vedd meg havi részletre, ami ruhára szükséged van, fizess ki valamit előre, egyszóval segíts magadon, ahogy tudsz, de gyere el hozzánk holnap vacsorára, este <span class="marked">fél nyolckor</span>, Fontaine utca 17. Duroy zavartan szedte fel a pénzt, és azt dadogta: - Igazán kedves vagy, nagyon köszönöm, elhiheted, hogy sohasem felejtem el... A másik félbeszakította: - Ugyan eredj már. Iszunk még egy pohár sört,', true, '19:30', '19:30', '19:30', 1170, 1170, 1170, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5132', 'Maupassant Guy de', 'novel', 'https://mek.oszk.hu/03100/03155/03155.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A szépfiú', 'https://mek.oszk.hu/03100/03155', 'Amikor megitták, az újságíró azt kérdezte: - Akarsz kószálni egy kicsit, vagy <span class="marked">egy óra</span> hosszat? - Persze hogy akarok. Újra megindultak a Madeleine felé. - Mit is csinálhatnánk tulajdonképpen? - kérdezte Forestier. - Azt mondják, hogy Párizsban a kódorgók mindig agyonüthetik valamivel az idejüket, de ez', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5132', 'Maupassant Guy de', 'novel', 'https://mek.oszk.hu/03100/03155/03155.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A szépfiú', 'https://mek.oszk.hu/03100/03155', 'Maradsz még? Én hazamegyek, nekem ebből elég volt. A másik azt mormogta: - Igen, maradok még egy kicsit. Nincs késő. Forestier felállt. - Hát akkor isten veled. Viszontlátásra holnap. Nem felejted el? Fontaine utca 17. <span class="marked">Fél nyolckor</span>. - Rendben van, viszontlátásra holnap. Köszönöm. Kezet szorítottak, és az újságíró elment. Mihelyt eltűnt a tömegben, Duroy szabadnak érezte magát, s újra vidáman tapogatta meg zsebében a két aranyat. Aztán fölkelt, és', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5132', 'Maupassant Guy de', 'novel', 'https://mek.oszk.hu/03100/03155/03155.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A szépfiú', 'https://mek.oszk.hu/03100/03155', 'a cikkemet." Felöltözött. Amikor az utcára ért, úgy találta, hogy még nagyon korán van, és nem jelenhetik meg a barátjánál, aki bizonyára soká alszik. Lassan sétálgatott tehát a külső bulvár fái alatt. Nem volt még <span class="marked">kilenc óra</span>, amikor a Monceau-parkba ért, amely egészen friss volt az öntözés után.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5132', 'Maupassant Guy de', 'novel', 'https://mek.oszk.hu/03100/03155/03155.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A szépfiú', 'https://mek.oszk.hu/03100/03155', 'hozzá. Egymás után odavezette őket az ablakmélyedésbe, s bár iparkodtak halkan beszélni, Duroy észrevette, hogy mind a kettőt tegezi. Aztán betaszítottak két kipárnázott ajtót, és beléptek a főszerkesztőhöz. Az az <span class="marked">egy óra</span> óta tartó értekezlet egyszerű écarté-játszma volt, néhány olyan lapos kalapú úriemberrel, akiket Duroy látott tegnap.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5132', 'Maupassant Guy de', 'novel', 'https://mek.oszk.hu/03100/03155/03155.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A szépfiú', 'https://mek.oszk.hu/03100/03155', 'megfogta, újra kicsúsztak a kezéből, vagy pedig összevissza egymás hegyen-hátán tolakodtak előre, és fogalma sem volt, hogyan mu tassa be, hogyan öltöztesse fel őket, de még arról sem, hogy melyiken kezdje. Amikor már <span class="marked">egy óra</span> hosszat erőlködött, és öt lapot bepiszkított összefüggéstelen kezdőmondatokkal, azt gondolta magában: "Még nem tanultam bele eléggé a mesterségbe.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5132', 'Maupassant Guy de', 'novel', 'https://mek.oszk.hu/03100/03155/03155.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A szépfiú', 'https://mek.oszk.hu/03100/03155', 'nekiült az írásnak. Folytatta a Forestier-né kezdette kalandot, egymásra halmozta a tárcaregénybe illő részleteket, meglepő fordulatokat és dagályos leírásokat, diákos, ügyetlen stílusban, kaszárnyai frázisokkal. <span class="marked">Egy óra</span> alatt befejezte a cikket, őrült zagyvaságot írt össze, és nyugodt lélekkel vitte el a Francia Élet -hez.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5132', 'Maupassant Guy de', 'novel', 'https://mek.oszk.hu/03100/03155/03155.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A szépfiú', 'https://mek.oszk.hu/03100/03155', 'Szóval, érti, arra kérem, hogy vacsorázzék velünk szombaton a Riche-kávéházban, <span class="marked">fél nyolckor</span>. Tudja, hol van? Duroy boldogan fogadta el a meghívást. Az asszony így folytatta: - Csak négyen leszünk, igazi francia négyes. Nagyon mulatságosak az ilyen lumpolások, különösen nekünk, asszonyoknak, akik nem szoktuk', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5132', 'Maupassant Guy de', 'novel', 'https://mek.oszk.hu/03100/03155/03155.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A szépfiú', 'https://mek.oszk.hu/03100/03155', 'hogy két tányért és két poharat szerezzen; az egész lakomát az öltözőasztalkán helyezte el, a piszkos deszkát egy szalvéta takarta, a mosdótál és a vizeskancsó pedig a deszka alatt rejtőzködött. Azután várt. Az asszony <span class="marked">negyed hat</span> felé érkezett meg, s a felaggatott színes rajzok tömegétől megszédítve, felkiáltott: - Ni, milyen csinosan lakik!', true, '05:15', '05:15', '05:15', 315, 315, 315, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5132', 'Maupassant Guy de', 'novel', 'https://mek.oszk.hu/03100/03155/03155.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A szépfiú', 'https://mek.oszk.hu/03100/03155', 'Duroy későn szokott kelni, és másnap <span class="marked">tizenegy óra</span> felé még ágyban volt, amikor a kihordó megjelent az ígért távirattal.', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5132', 'Maupassant Guy de', 'novel', 'https://mek.oszk.hu/03100/03155/03155.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A szépfiú', 'https://mek.oszk.hu/03100/03155', 'Aztán meggondolta, hogy ostobaság lenne megfosztani magát azoktól a kellemes pillanatoktól, amiket az asszony szerezhet neki, és hozzátette: De várlak a lakásunkon, <span class="marked">kilenckor</span>. Egyik szerkesztőségi szolgával küldte el ezt a néhány sort, hogy megtakarítsa a távirat árát, s aztán gondolkozni kezdett, hogyan szerezheti meg az esti étkezés költségeit. Hét órakor még semmi sem jutott az eszébe: a', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5132', 'Maupassant Guy de', 'novel', 'https://mek.oszk.hu/03100/03155/03155.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A szépfiú', 'https://mek.oszk.hu/03100/03155', 'Nem tetszik többet parancsolni? - Nem, nem, ennyi elég, köszönöm. Duroy, amint kezébe kapta a három ezüstpénzt, futva ment le a lépcsőn, és megvacsorázott egy kiskocsmában, ahová a nyomor napjaiban ereszkedett le néha. <span class="marked">Kilenc órakor</span> már a kedvesére várakozott, a kis szoba kandallója előtt melengetve a lábát.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5132', 'Maupassant Guy de', 'novel', 'https://mek.oszk.hu/03100/03155/03155.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A szépfiú', 'https://mek.oszk.hu/03100/03155', 'Gyorsan felöltözött, és Walterhoz ment, bár még csak <span class="marked">nyolc óra</span> volt. Walter már fölkelt, és a Toll -at olvasta. - Nos - mondta komoly arccal, amikor Duroyt észrevette -, most már nem hátrálhat meg. A fiatalember nem felelt semmit. A főszerkesztő így folytatta: - Menjen el tüstént', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5132', 'Maupassant Guy de', 'novel', 'https://mek.oszk.hu/03100/03155/03155.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A szépfiú', 'https://mek.oszk.hu/03100/03155', 'sem vett semmiben, semmire nem szólt egy árva szót sem, nem mondott véleményt, nem fogadott el, nem utasított vissza semmit - és oly gyorsan, hogy egészen elszédült, elkábult bele, nem is értette, miről van szó. Este <span class="marked">kilenc óra</span> felé ért haza; Boisrenard-ral vacsorázott, aki csupa ragaszkodásból egész nap nem hagyta magára.', true, '21:00', '21:00', '21:00', 1260, 1260, 1260, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5132', 'Maupassant Guy de', 'novel', 'https://mek.oszk.hu/03100/03155/03155.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A szépfiú', 'https://mek.oszk.hu/03100/03155', 'volna bebizonyítani lélekjelenlétét, de félt, hogy elveszti gondolatai fonalát, és elárulja belső zavarát; folyvást kísértette az a gyötrő félelem, hogy remegni kezd. A kocsi hamarosan kiért a szabad mezőre. Körülbelül <span class="marked">kilenc óra</span> lehetett. Olyan fagyos téli reggel volt ez, amikor az egész természet csillogó, törékeny és kemény, mint a kristály. A zúzmarás fák mintha jeget izzadnának, a föld peng a lépések alatt: a száraz levegő messzire hordja', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5132', 'Maupassant Guy de', 'novel', 'https://mek.oszk.hu/03100/03155/03155.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A szépfiú', 'https://mek.oszk.hu/03100/03155', 'szintén mutogatta magát. Nem köszöntek egymásnak. Ha egyikük megsebesült volna, akkor kezet szorítanak. Egyébiránt mind a kettő meggyőződéssel esküdözött, hogy hallotta fütyülni a másiknak a golyóját. Másnap délelőtt <span class="marked">tizenegy óra</span> tájban Duroy táviratot kapott: Istenem, hogy féltem!', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5132', 'Maupassant Guy de', 'novel', 'https://mek.oszk.hu/03100/03155/03155.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A szépfiú', 'https://mek.oszk.hu/03100/03155', 'És a vacsorára várva, még majd <span class="marked">egy óra</span> hosszat mozdulatlanul ültek mind a hárman, csak nagy ritkán hullajtottak egy-egy szót, egy közömbös, fölösleges, hétköznapi szót, mintha valami veszedelem, rejtélyes veszedelem lett volna abban, ha túlságosan sok időt', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5132', 'Maupassant Guy de', 'novel', 'https://mek.oszk.hu/03100/03155/03155.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A szépfiú', 'https://mek.oszk.hu/03100/03155', 'Az asszony így felelt: - Igen, igen, természetesen; <span class="marked">nyolc óra</span> tájban jön az asztalos. És mert Duroy felsóhajtott: - Szegény fiú! - felsóhajtott ő is, hosszan, fájdalmas rezignáltsággal. Most már nem néztek rá olyan gyakran, hozzászoktak halála gondolatához, elméjük lassan', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5132', 'Maupassant Guy de', 'novel', 'https://mek.oszk.hu/03100/03155/03155.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A szépfiú', 'https://mek.oszk.hu/03100/03155', 'abban a meghatározhatatlan erőben, amelynek egy asszony sem tudott ellenállni. Rövid levélke értesítette, hogy nemsokára üt a döntő óra. Párizsban vagyok. Látogasson meg. Madeleine Forestier Semmi egyéb. Ezt a reggel <span class="marked">kilenc órakor</span> érkező postával kapta. Még aznap három órakor elment hozzá . Az asszony mindkét kezét odanyújtotta neki, szokása szerint kedvesen, bájosan mosolygott rá, és néhány pillanatig mélyen belenéztek egymás szemébe. Aztán azt', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5132', 'Maupassant Guy de', 'novel', 'https://mek.oszk.hu/03100/03155/03155.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A szépfiú', 'https://mek.oszk.hu/03100/03155', 'Tulajdonképpen senki sem hitt a tangeri expedícióban, ámbár a parlamenti ülésszak utolsó napján egy jobboldali képviselő, Lambert-Sarrazin gróf, a középpártoktól is megtapsolt sze llemes szónoklatában fogadást ajánlott, s mint <span class="marked">egykor</span> egy híres indiai alkirály, bajuszát tette föl a miniszterelnök pofaszakálla ellenében, hogy az új kabinet kénytelen lesz utánozni a régit, és hadsereget küldeni Tangerbe, a tuniszi hadsereg mellé, már csak a szimmetria', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5132', 'Maupassant Guy de', 'novel', 'https://mek.oszk.hu/03100/03155/03155.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A szépfiú', 'https://mek.oszk.hu/03100/03155', 'A meghívó szövege ez volt: Walter főszerkesztő és neje tisztelettel kérik, tekintse meg házuknál december 30-án <span class="marked">9 óra</span> és éjfél között Markovits Károlynak a "Hullámokon járó Krisztus" című festményét, villanyvilágításnál.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5132', 'Maupassant Guy de', 'novel', 'https://mek.oszk.hu/03100/03155/03155.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A szépfiú', 'https://mek.oszk.hu/03100/03155', 'már ritkaság volt. A felesége azt mondta neki: - No lám, most megint kedves kezdesz lenni. Georges pénteken korán felöltözött; azt állította, hogy van még egy-két útja, mielőtt a főszerkesztőékhez megy. Aztán <span class="marked">hat óra</span> tájban távozott, megcsókolta a feleségét, és bérkocsiért ment a Notre-Dame-de-Lorette térre.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5132', 'Maupassant Guy de', 'novel', 'https://mek.oszk.hu/03100/03155/03155.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A szépfiú', 'https://mek.oszk.hu/03100/03155', 'és letette a Fácánkakas előtt - ez ennek a városrésznek egyik jól ismert polgári vendéglője volt. Georges belépett az étterembe, és szép lassan vacsorázgatott, időnként megnézte az óráján, hogy mennyi az idő. <span class="marked">Fél nyolckor</span>, amikor már a kávéját is megitta, elfogyasztott két pohár finom pezsgőt, és lassan elszívott egy jó sz ivart, kilépett a vendéglőből, megfogott egy másik üresen cirkáló kocsit, és elvitette magát a La Rochefoucauld utcába.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5132', 'Maupassant Guy de', 'novel', 'https://mek.oszk.hu/03100/03155/03155.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A szépfiú', 'https://mek.oszk.hu/03100/03155', 'Amikor a megjelölt házhoz értek, még csak <span class="marked">negyed kilenc</span> volt, és több mint húsz percig csöndben várakoztak.', true, '08:15', '08:15', '08:15', 495, 495, 495, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5132', 'Maupassant Guy de', 'novel', 'https://mek.oszk.hu/03100/03155/03155.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A szépfiú', 'https://mek.oszk.hu/03100/03155', 'Egy csütörtöki napot választottak ki, s már reggel <span class="marked">kilenc órakor</span> útra keltek egy hatüléses, négylovas, nagy utazóhintóban.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5132', 'Maupassant Guy de', 'novel', 'https://mek.oszk.hu/03100/03155/03155.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A szépfiú', 'https://mek.oszk.hu/03100/03155', 'gondolta: "Most melegük lehet Walteréknak." És valami nyugtalanság rágódott a szívén. Hátha nem sikerül a dolog? De hát mitől f élhet? Mindenesetre kivágja magát valahogy. Hanem mégiscsak nagy tét forog kockán ma este. <span class="marked">Tizenegy óra</span> tájban elment hazulról, egy ideig őgyelgett, aztán bérkocsiba ült, és megállította a kocsit a Concorde téren a tengerészeti minisztérium árkádjai előtt.', true, '23:00', '23:00', '23:00', 1380, 1380, 1380, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5132', 'Maupassant Guy de', 'novel', 'https://mek.oszk.hu/03100/03155/03155.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A szépfiú', 'https://mek.oszk.hu/03100/03155', 'között. Valami fájdalom kezdődött a fejében, gondolatai kínossá, zavarossá váltak, és fájdalmat okoztak neki. Agyongyötörte magát a találgatással, és kétségbeesett, hogy nem tud semmit. Megnézte a faliórát: <span class="marked">egy óra</span> elmúlt. Azt gondolta magában: - Nem maradhatok így, mert megőrülök. Meg kell tudnom. Felköltöm Suzanne-t, és kivallatom. És elindult a leánya szobája felé, kezében gyertyát tartva, mezítláb, hogy zajt ne üssön. Halkan', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5132', 'Maupassant Guy de', 'novel', 'https://mek.oszk.hu/03100/03155/03155.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A szépfiú', 'https://mek.oszk.hu/03100/03155', 'ébresztettek maguk iránt. Mindazok, akik az újsághírekben mint jelen voltak szoktak szerepelni, elhatározták, hogy ott lesznek ezen az esküvőn. A nagy esemény egy szép, tiszta őszi napon játszódott le. Már <span class="marked">nyolc órakor</span> reggel széles, piros szőnyeget teregetett szét a Royale utcán uralkodó magas lépcsőzeten a Madeleine-templom személyzete - ezzel megállította a járókelőket, és tudtára adta Párizs népének, hogy nagy ceremónia van készülőben.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5132', 'Maupassant Guy de', 'novel', 'https://mek.oszk.hu/03100/03155/03155.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A szépfiú', 'https://mek.oszk.hu/03100/03155', 'a gazdag emberekről, akik ennyi pénzt költenek arra, hogy egybekeljenek. Tíz óra tájban kezdtek megállni a kíváncsiak. Ott maradtak néhány pillanatig, remélvén, hogy mindjárt kezdődik a dolog, aztán odábbálltak. <span class="marked">Tizenegykor</span> rendőrszakaszok érkeztek a térre, s majdnem azonnal hozzáláttak, hogy oszlásra bírják a tömeget, mert minden pillanatban csoportosulás támadt.', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-5132', 'Maupassant Guy de', 'novel', 'https://mek.oszk.hu/03100/03155/03155.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Ella kisasszony ötlete és más elbeszélések', 'https://mek.oszk.hu/12900/12946', 'Cranford-féle füszerszappannal, levetette a shirtingből készült kézelő védőket, aztán csöngetett a szolgának. - Willy, egy kocsit, - szólt s közben, ügyesen visszaigazgatta megint a frizurájából kiszabadult fürtöket. * <span class="marked">Tizenegy óra</span> volt és Brighton Benjámin, a Vészcsillag éjjeli szerkesztője, álmosan virrasztott nyomdájában a kiszedett ólomkolumnák khaosza fölött.', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-126634', 'Szomaházy István', 'short stories', 'https://mek.oszk.hu/12900/12946/12946.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Ella kisasszony ötlete és más elbeszélések', 'https://mek.oszk.hu/12900/12946', 'is fog kapni, meg ugorkát is... De aztán... most már remélem, hogy jól fog bánni a Mariskával... Apolcer ur: Ugy fogok vele bánni, mint a himes tojással... A jó férj: Ebben maradunk... Vasárnap látjuk egymást... Pont <span class="marked">egykor</span> ebédelünk... (Kezét nyujtja Apolcer urnak.) A viszontlátásig... vasárnap... Apolcer ur: Ne féljen semmit... ott leszek... A jó férj (távozóban, félre): Azt hiszem, hogy hatottam némileg a kedélyvilágára... III.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-126634', 'Szomaházy István', 'short stories', 'https://mek.oszk.hu/12900/12946/12946.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Ella kisasszony ötlete és más elbeszélések', 'https://mek.oszk.hu/12900/12946', '* Károly, rendes szokásához hiven, e napon is <span class="marked">fél nyolckor</span> ébredt. Szegény anyja hasztalanul próbált meg vele mindent: Károly már föl sem vette a hideg vizet, melyet hét órakor a nyakába öntöttek, s paplan nélkül is az ártatlan lelkek nyugalmával szunnyadt tovább szétzüllött', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-126634', 'Szomaházy István', 'short stories', 'https://mek.oszk.hu/12900/12946/12946.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Ella kisasszony ötlete és más elbeszélések', 'https://mek.oszk.hu/12900/12946', 'A szegény Károly már nagyon is jól ismerte a csöndes folyosókat, melyeken belül már javában prelegáltak a tanárok, az ajtók mögül kihallatszó éneklésszerü feleléseket, az iskolatársai gúnyos pillantását, mikor <span class="marked">félkilenc</span> táján lihegve a tanterembe lépett.', true, '08:30', '08:30', '08:30', 510, 510, 510, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-126634', 'Szomaházy István', 'short stories', 'https://mek.oszk.hu/12900/12946/12946.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Ella kisasszony ötlete és más elbeszélések', 'https://mek.oszk.hu/12900/12946', 'Károly végig nézett a reggeli zajtól nyüzsgő piacon és elkeseredve dörmögte: - Megint ki fognak állitani, mert mire a gimnáziumot elérem, bizonyosan meg lesz a <span class="marked">félkilenc</span>... Az emir (a történelem tanárát nevezték igy) ismét kivonatot készittet velem az ókorból és oda lesz a gyönyörü délutánom is... Nem fogok elmenni az iskolába... hanem szépen kisétálok a Zuggóhoz... Károly a hóna alá', true, '08:30', '08:30', '08:30', 510, 510, 510, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-126634', 'Szomaházy István', 'short stories', 'https://mek.oszk.hu/12900/12946/12946.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Mi, szemüvegesek', 'https://mek.oszk.hu/02400/02493', 'A körtefa sehol, a fagylaltos bácsi sehol, és nem a fagylaltoskocsi csilingelt, hanem az ébresztő-rádió szólalt meg: "Jó reggelt, kedves hallgatóim, ma szeptember elseje, reggel <span class="marked">hat óra</span>, Egyed és Egon napja van..." Évi felült.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4378', 'Fehér Klára', 'novel', 'https://mek.oszk.hu/02400/02493/02493.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Mi, szemüvegesek', 'https://mek.oszk.hu/02400/02493', '- Akkor nagyon gyorsan megfésülködöm, és felveszem az új blúzomat, és megiszom a kávét, mert pont <span class="marked">fél nyolckor</span> itt lesz Andrea! - kiáltotta Évi, és egyszerre nagyon boldog lett. Mert mit számít az, hogy hogyan csúfolódnak a Hajagosok, és nem baj, ha elmúlt a vakáció, ha az embernek olyan igaz, szívbéli barátnője van, mint', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4378', 'Fehér Klára', 'novel', 'https://mek.oszk.hu/02400/02493/02493.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Mi, szemüvegesek', 'https://mek.oszk.hu/02400/02493', 'van, mint Andrea! A konyhaasztalon a reggeli mellett ott várta a tízórai. Szépen, fóliába csomagolva a sajtos vajas kenyér és két szép piros alma. Egyik természetesen Andreáé. Anyuka még erre is gondolt. Reggel <span class="marked">hatkor</span> anyu már benn dolgozik a laborban.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4378', 'Fehér Klára', 'novel', 'https://mek.oszk.hu/02400/02493/02493.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Mi, szemüvegesek', 'https://mek.oszk.hu/02400/02493', '- Milyen meghatóan jó kislány vagy! Mennyi szeretettel gondolsz most anyukára. Bezzeg amikor... - Mit mikor? - Tudnék mesélni - mondta Világoskék -, de nem bántlak a tanév első napján. Különben is, hol marad Andrea? <span class="marked">Fél nyolc</span> múlt öt perccel. Ez igazán furcsa. Andrea sosem késik. Talán elromlott az ébresztőórája? Talán várni kellett a buszra? Talán... Évi hátára vette az iskolatáskát, kezébe vette a tízórai csomagot. Elhatározta, hogy', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4378', 'Fehér Klára', 'novel', 'https://mek.oszk.hu/02400/02493/02493.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Mi, szemüvegesek', 'https://mek.oszk.hu/02400/02493', 'Hétfejű sárkány a bélyegen Az évnyitónak <span class="marked">tizenegykor</span> vége volt már. A gyerekek vidáman lökdösődve jöttek ki az iskolából. A kis elsősöket papák, mamák, nagyszülők várták, léggömbbel, csokival. Volt gyerek, akit kis autóval, hajas babával vártak, hogy örömteli élményeik', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4378', 'Fehér Klára', 'novel', 'https://mek.oszk.hu/02400/02493/02493.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Mi, szemüvegesek', 'https://mek.oszk.hu/02400/02493', '- Feltéve - mondta Világoskék Testvér -, ha nem jön <span class="marked">fel egy</span> osztálytársad, és nem veszi észre otthon az orrodon az okulárét.', true, '00:30', '00:30', '00:30', 30, 30, 30, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4378', 'Fehér Klára', 'novel', 'https://mek.oszk.hu/02400/02493/02493.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Mi, szemüvegesek', 'https://mek.oszk.hu/02400/02493', 'De ez olyan kitalált drót volna, hogy megbeszélnénk, hogy mondjuk minden este <span class="marked">kilenckor</span> egymásra gondolunk, és elmondjuk egymásnak, hogy mi történt velünk.', true, '21:00', '21:00', '21:00', 1260, 1260, 1260, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4378', 'Fehér Klára', 'novel', 'https://mek.oszk.hu/02400/02493/02493.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Mi, szemüvegesek', 'https://mek.oszk.hu/02400/02493', 'mit kéne csinálnom? - Szerintem semmit - mondta Világoskék -, te találtál ki engem, hogyan lehetnék okosabb nálad? Ebben a pillanatban a nagy falióra ütni kezdett: - Egy... kettő... három... öt... nyolc... kilenc... - <span class="marked">Kilenc óra</span>! - kiáltott fel Évi, és felült, rákönyökölt a párnára. - Kilenc óra, Andrea most rám gondol a forró dróton. Szervusz, barátom, arátom, rátom, átom, om, ooooom. Andrea, ugye most te is ott vagy a vonalban? Zöld Fáni is', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4378', 'Fehér Klára', 'novel', 'https://mek.oszk.hu/02400/02493/02493.htm', 'deep_extract', false);
