INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Naplók, levelek', 'https://mek.oszk.hu/00400/00417', 'Pedig én nem tartozom felelősséggel, mint ő, az ő állása, az betegítheti meg az embert. Mennyit dolgozott régebben is, amikor az ügyvédi vizsgára készült, és egyidejűleg az intézetben szolgált. Kilenc hónapon át napi <span class="marked">tizenegy óra</span> munka. És aztán a fő különbség. Kellett-e vajon valaha is valamiképpen aggódnom az állásomért? Ő megismerte ezt a félelmet. Neki voltak ellenségei az intézetben, akik minden lehetőt megpróbáltak, hogy még ily módon is', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2416', 'Kafka Franz', 'diary', 'https://mek.oszk.hu/00400/00417/html/04.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Naplók, levelek', 'https://mek.oszk.hu/00400/00417', 'kis üzleti ügyem Teplben (Marienbad tőszomszédságában), szeretném egybekötni az odautazással, de tíz nappal előre kell jeleznem a tepli érkezést. Szeretettel köszönt Franz Napló Július 3 . Az első nap Marienbadban F.-<span class="marked">fel egy</span>-egy egymásba nyíló szobában, kulcs mindkét oldalon.', true, '00:30', '00:30', '00:30', 30, 30, 30, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2416', 'Kafka Franz', 'diary', 'https://mek.oszk.hu/00400/00417/html/04.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Naplók, levelek', 'https://mek.oszk.hu/00400/00417', 'véleményem szerint mérvadóak. A legostobább vélekedéssel szemben is a dolog valódiságát tanúsítja az ilyen körülmény. Puszta szemmel csak csekélységeket láthatunk ott, ahol igazság van jelen. [...] A rabbi minden este <span class="marked">fél nyolckor</span> vagy nyolckor kikocsizik. Lassan halad a kocsi, be az erdőbe, gyalog követi őt pár híve. Az erdőben egy általában már megbeszélt helyen kiszáll, és kísérőivel egészen sötétedésig jár-kel az erdei utakon. Ima idejére,', true, '19:30', '19:30', '19:30', 1170, 1170, 1170, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2416', 'Kafka Franz', 'diary', 'https://mek.oszk.hu/00400/00417/html/04.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Naplók, levelek', 'https://mek.oszk.hu/00400/00417', '[...] A rabbi minden este fél nyolckor vagy <span class="marked">nyolckor</span> kikocsizik. Lassan halad a kocsi, be az erdőbe, gyalog követi őt pár híve. Az erdőben egy általában már megbeszélt helyen kiszáll, és kísérőivel egészen sötétedésig jár-kel az erdei utakon. Ima idejére, úgy tíz óra', true, '20:00', '20:00', '20:00', 1200, 1200, 1200, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2416', 'Kafka Franz', 'diary', 'https://mek.oszk.hu/00400/00417/html/04.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Naplók, levelek', 'https://mek.oszk.hu/00400/00417', 'be az erdőbe, gyalog követi őt pár híve. Az erdőben egy általában már megbeszélt helyen kiszáll, és kísérőivel egészen sötétedésig jár-kel az erdei utakon. Ima idejére, úgy tíz óra körül ér haza. Ott voltam tehát <span class="marked">fél nyolc</span> körül a Hotel National előtt; ebben a szállóban lakik.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2416', 'Kafka Franz', 'diary', 'https://mek.oszk.hu/00400/00417/html/04.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Naplók, levelek', 'https://mek.oszk.hu/00400/00417', '(Egyfolytában esik, szakadatlanul ugyanazzal az erővel, és még most <span class="marked">fél tizenegykor</span> sem állt el.) A séta (első ízben marad el a kikocsizás, a rabbi nyilvánvalóan nem akarja ebben az esőben az erdőbe vinni híveit) megkezdődik.', true, '10:30', '10:30', '10:30', 630, 630, 630, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2416', 'Kafka Franz', 'diary', 'https://mek.oszk.hu/00400/00417/html/04.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Naplók, levelek', 'https://mek.oszk.hu/00400/00417', 'nem is ez a munkaidőm. De mi lesz ebből? [Levelezőlap. Marienbad, 1916.] július 20. [...] Álmatlanság ide, fejfájás oda, pocakosodom, nem úgy, mint a direktorom, csak alárendelthez illő mértékben. A tegnapi étrend: <span class="marked">fél tizenegykor</span> két tej, méz, két vaj, két zsömle; tizenegykor negyed kilogramm cseresznye; tizenkettőkor császárhús, spen ót, krumpli, vaníliás metélt, zsömle; háromkor egy csésze tej, két zsömle; ötkor csokoládé, két vaj, két', true, '10:30', '10:30', '10:30', 630, 630, 630, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2416', 'Kafka Franz', 'diary', 'https://mek.oszk.hu/00400/00417/html/04.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Naplók, levelek', 'https://mek.oszk.hu/00400/00417', 'A tegnapi étrend: fél tizenegykor két tej, méz, két vaj, két zsömle; <span class="marked">tizenegykor</span> negyed kilogramm cseresznye; tizenkettőkor császárhús, spen ót, krumpli, vaníliás metélt, zsömle; háromkor egy csésze tej, két zsömle; ötkor csokoládé, két vaj, két zsömle; hétkor zöldség, saláta, kenyér, ementáli; kilenckor kalács, tej.', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2416', 'Kafka Franz', 'diary', 'https://mek.oszk.hu/00400/00417/html/04.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Naplók, levelek', 'https://mek.oszk.hu/00400/00417', 'negyed kilogramm cseresznye; tizenkettőkor császárhús, spen ót, krumpli, vaníliás metélt, zsömle; háromkor egy csésze tej, két zsömle; ötkor csokoládé, két vaj, két zsömle; hétkor zöldség, saláta, kenyér, ementáli; <span class="marked">kilenckor</span> kalács, tej. Na? Franz Napló Július 20 . [...] Könyörülj rajtam, bűnös vagyok lényem minden zugáig. De voltak nem éppen megvetendő hajlamaim, jó kis képességeim, tobzódtam bennük, én, a tanácstalan lény, aki voltam,', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2416', 'Kafka Franz', 'diary', 'https://mek.oszk.hu/00400/00417/html/04.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Naplók, levelek', 'https://mek.oszk.hu/00400/00417', 'utazásom is, mint amilyennek, hál'' isten, a tiéd mutatkozik, de kellemetlenül sok akadálya van még, korántsem dőlt még el a dolog. Amellett na gyon rossz a vasúti összeköttetés is éppen Münchennel. Azt hiszem, reggel <span class="marked">nyolc óra</span> tájt indulok (egyetlen lehetőség), és csak este hat óra huszonnégykor érkezem meg, tehát csak péntek este.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2416', 'Kafka Franz', 'diary', 'https://mek.oszk.hu/00400/00417/html/04.htm', 'deep_extract', false);
