INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Torkolat', 'https://mek.oszk.hu/02900/02978', 'jólétben él a német nép!" Minden reggel fél hétkor keltek, a fürdőszobában mindenkire öt perc jutott, hétkor már a reggelizőasztalt ülték körbe, ahol a házigazda elmondatta a gyerekekkel aznapi programjukat. A nevelőnő <span class="marked">fél nyolckor</span> elvitte a kicsiket az iskolába, majd miután visszajött - mivel egy személyben volt komorna és konyhalány is -, a nagyságos asszonnyal bevásárolni ment.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4959', 'Magyar Elektronikus Könyvtár', 'anthology', 'https://mek.oszk.hu/02900/02978/02978.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Torkolat', 'https://mek.oszk.hu/02900/02978', 'A szerb határőrök a Jugoszlávia-Egyesült Államok mérkőzést nézik, a buszsávban várjuk, míg vége van, vámvizsgálat után még tíz utast visszahívnak, fertőtlenítő vízben mossanak kezet; reggel <span class="marked">fél kilenc</span> körül a röszkei vámudvaron állunk, a finánc borotvahabbal a füle mögött érkezik, azt mondja, mindjárt befejezik a reggelit, addig pakoljunk le a buszról, valószínűleg halat ettek, mert bő egy órával később bukkannak', true, '08:30', '08:30', '08:30', 510, 510, 510, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4959', 'Magyar Elektronikus Könyvtár', 'anthology', 'https://mek.oszk.hu/02900/02978/02978.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Torkolat', 'https://mek.oszk.hu/02900/02978', 'arcát akarva felidézheted. Azt képzeled, hogy az idő hiába pusztította el sejtjeid több milliárdját, elég egy gyönge pillanat, s azt képzeled, hogy élsz. NŐK Petyhüdt kéz, négy ujján gyűrű, arany. Szatyrot cipel. <span class="marked">Egykor</span> bársonyosan simított. Ugyan! Ki hiszi el? Indiai fátyolruhában dagadt térdek, bütykös cipők. A viselőjében, szegényben ki lát igazi nőt? Májfoltok púderfolt mögött, ráncok rózsásra kenve. Egy sugárzónak szánt mosoly -', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4959', 'Magyar Elektronikus Könyvtár', 'anthology', 'https://mek.oszk.hu/02900/02978/02978.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Torkolat', 'https://mek.oszk.hu/02900/02978', 'Magányos percek, ismételgeted, és gondolataid ismeretlen utakon kalandoznak. Emlékek között kutakodnak virradatig. A jövőre nem gondolsz. Rádöbbensz, hogy ami ismeretlen, a múltadban keresendő. És akkor, ott, éjjel <span class="marked">egykor</span>, kettőkor, háromkor ezt magad is elhiszed.', true, '13:00', '13:00', '13:00', 780, 780, 780, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4959', 'Magyar Elektronikus Könyvtár', 'anthology', 'https://mek.oszk.hu/02900/02978/02978.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az úszó város', 'https://mek.oszk.hu/04600/04643', 'nevét fölírta. Pár perc mulva már fölszolgálták az első villásreggelit s nemsokára az összes utas vidáman falatozott az asztaloknál. Én odafönt maradtam a hídon, hogy végignézzem a beszállást és a podgyászok átvételét. <span class="marked">Fél egykor</span> már minden és mindenki a hajón volt.', true, '00:30', '00:30', '00:30', 30, 30, 30, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-6969', 'Verne Jules', 'novel', 'https://mek.oszk.hu/04600/04643/04643.htm', 'deep_extract', false);
