INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az úszó város', 'https://mek.oszk.hu/04600/04643', 'Napjában négyszer jelezték így az evés idejét: félkilenckor reggelire, félegykor villásreggelire, négyórakor ebédre és <span class="marked">félnyolckor</span> teára. A födélzet pár perc alatt néptelen lett s az utasok az ebédlőkbe tódultak. Az ebédlők mindegyikében négy sor asztal volt, melyek fölött, a hajó falába illesztve álltak a pohárszékek, jól megrakva mindenféle', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-6969', 'Verne Jules', 'novel', 'https://mek.oszk.hu/04600/04643/04643.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az úszó város', 'https://mek.oszk.hu/04600/04643', 'Ebből azt következtettem, hogy a szél még jobban erősödött s hogy a gőzös, kijutva a Szent-György csatornából, már érezni kezdi a nyilt oceánon tornyosuló hullámok erősebb rohamát. Az álmatlan éjszaka után úgy <span class="marked">hat óra</span> tájban fölmentem a fedélzetre.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-6969', 'Verne Jules', 'novel', 'https://mek.oszk.hu/04600/04643/04643.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az úszó város', 'https://mek.oszk.hu/04600/04643', 'legalább friss levegőt szívhasson. Legtöbbjük elátkozta a francia szállító társulatot, mely a programjában azt hirdette, hogy a Great-Eastern sziklaszilárdan jár a tengeren s födélzetén a tengeri betegség ismeretlen. <span class="marked">Kilenc óra</span> felé, három-négy mérföldnyire a szél alatt, valami alaktalan tömeget pillantottunk meg.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-6969', 'Verne Jules', 'novel', 'https://mek.oszk.hu/04600/04643/04643.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az úszó város', 'https://mek.oszk.hu/04600/04643', 'számlálták a kerekek forgását, amelyek nagyon lassan járnak az ő vágyaikhoz képest. Ah, uram! ha a katlanok alatt is úgy lángolna a tűz, mint az ő szíveikben, akkor elég gőzünk is volna és gyorsabban hal adnánk! XI. <span class="marked">Fél egykor</span> a kormányosmester ezt a rövid jelentést függesztette ki a nagy szalon ajtajára: Ész.', true, '00:30', '00:30', '00:30', 30, 30, 30, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-6969', 'Verne Jules', 'novel', 'https://mek.oszk.hu/04600/04643/04643.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az úszó város', 'https://mek.oszk.hu/04600/04643', 'helyen Anderson kapitány, mint lelkipásztor. Dean Pitferge barátom mellém telepedett és hiúz szemeit fürkészve jártatta körül a tömegen. Azt hiszem, hogy nem annyira az áhitat, mint inkább a kiváncsiság hozta őt ide. <span class="marked">Féltizenegykor</span> a parancsnok fölkelt és megkezdődött az istentisztelet.', true, '10:30', '10:30', '10:30', 630, 630, 630, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-6969', 'Verne Jules', 'novel', 'https://mek.oszk.hu/04600/04643/04643.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az úszó város', 'https://mek.oszk.hu/04600/04643', 'sem lehetett látni a gőzös körül. Tíz óra tájban hajót jeleztek szél alatt, a gőzös orra felől; nagy háromárbocos vitorlás hajó volt, mely a széllel futott, de a nemzetiséget a nagy ködben nem lehetett megtudni. <span class="marked">Tizenegy óra</span> felé a szél alábbhagyott és északnyugatnak fordult.', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-6969', 'Verne Jules', 'novel', 'https://mek.oszk.hu/04600/04643/04643.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az úszó város', 'https://mek.oszk.hu/04600/04643', 'a kerekek mögött elveszett a háttérben. A gőzös, melyet hatalmas gépezete hajtott, zúgva szelte a nyugtalan hullámokat s meg sem érezte a tenger háborgását, mely pedig a legnagyobb hajót i s ingadozásba hozta volna. <span class="marked">Fél egykor</span> megtudtam, hogy tegnap dél óta csak százhuszonhét mérföldet haladtunk.', true, '00:30', '00:30', '00:30', 30, 30, 30, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-6969', 'Verne Jules', 'novel', 'https://mek.oszk.hu/04600/04643/04643.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az úszó város', 'https://mek.oszk.hu/04600/04643', 'tükörlapjai vertek vissza. Csípős hideg szél fújdogált és finom jégdarab lepte el a hajó födélzetét; majd sűrű szürkés köd szállt föl, úgyhogy a gőzös állandóan kürtölt, nehogy összeütközzék valami szembe jövő hajóval. <span class="marked">Fél tizenegykor</span> a köd szétoszlott s rögtön aztán egy csavargőzös tűnt föl a szemhatáron.', true, '10:30', '10:30', '10:30', 630, 630, 630, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-6969', 'Verne Jules', 'novel', 'https://mek.oszk.hu/04600/04643/04643.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az úszó város', 'https://mek.oszk.hu/04600/04643', 'egymástól a két ellenfelet. Mielőtt elváltunk, fogadást tettünk, hogy innentúl még gondosabban felügyelünk a titokteljes dráma szereplőire és minden erőnkből rajta leszünk, hogy a katasztrófát távol tartsuk. <span class="marked">Tizenegy óra</span> felé az angol utasok gyűjtést rendeztek az induláskor megsebesült matrózok javára, akik közül egyik-másik még most is ágyban feküdt sőt a skót vitorla-mester örökre megsántult, mert eltörte a lábát.', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-6969', 'Verne Jules', 'novel', 'https://mek.oszk.hu/04600/04643/04643.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az úszó város', 'https://mek.oszk.hu/04600/04643', 'amelynek Északi Korona a neve. XXIV. Rossz éjszakánk volt. A Great-Eastern ismét táncolni kezdett, úgyhogy sem állni sem ülni sem járni nem lehetett, s minden, ami mozdulni tudott a hajóban, ismét lábra kelt. Reggel <span class="marked">hat órakor</span> nagy nehezen fölmásztam a födélzetre s onnan a hajóhídra, amely üres és elhagyatott volt, - de mégsem egészen, mert mihelyt felértem, a derék Dean Pitferge orvos üdvözölt.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-6969', 'Verne Jules', 'novel', 'https://mek.oszk.hu/04600/04643/04643.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az úszó város', 'https://mek.oszk.hu/04600/04643', 'sűrű fekete bajusza alól, mintha nem is a mi hajónk táncolt volna ebben a rémséges viharban. Megdöbbentett a kapitány makacssága, mellyel szembe szállt, küzködött a fölzúdult elemekkel. Az Atlanti-oceán képe <span class="marked">félnyolckor</span> szörnyű, rettenetes volt. A hajó előrésze csaknem mindig víz alatt bukdácsolt s én elképedve néztem a gigászi gőzös harcát a hullámokkal. Egy pillanatra magam is értettem és méltányolta m a parancsnok konokságát, aki', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-6969', 'Verne Jules', 'novel', 'https://mek.oszk.hu/04600/04643/04643.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az úszó város', 'https://mek.oszk.hu/04600/04643', 'm a parancsnok konokságát, aki nem akart meghátrálni: de ebben az egy pillanatban megfeledkeztem arról, hogy a tenger hatalma és ereje végtelen és semmiféle emberi alkotmány nem dacolhat vele. Egyszerre csak, úgy <span class="marked">nyolc óra</span> tájban, heves lökést éreztünk: hihetetlen tömegű hullám rohanta meg a hajót, mely egészen oldalt dőlt.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-6969', 'Verne Jules', 'novel', 'https://mek.oszk.hu/04600/04643/04643.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az úszó város', 'https://mek.oszk.hu/04600/04643', 'A harmadik hajó, mellyel este <span class="marked">hat óra</span> tájban találkoztunk szintén közel ment el hozzánk; ez a Philadelphia volt, az Inmat-társaság egyik legszebb személyszállító gőzöse.', true, '18:00', '18:00', '18:00', 1080, 1080, 1080, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-6969', 'Verne Jules', 'novel', 'https://mek.oszk.hu/04600/04643/04643.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az úszó város', 'https://mek.oszk.hu/04600/04643', 'nagyon is járt országúton haladtunk sőt a nagy Europe gőzöst is vártuk, de nem jött; ez a kerekes hajó 3200 tonnás és Havre meg New-York között közlekedik, de most valószínűleg északnak tartott s azért nem láthattuk. <span class="marked">Félnyolc</span> tájban ránk esteledett és fölkelt a hold.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-6969', 'Verne Jules', 'novel', 'https://mek.oszk.hu/04600/04643/04643.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az úszó város', 'https://mek.oszk.hu/04600/04643', 'tartott s azért nem láthattuk. Félnyolc tájban ránk esteledett és fölkelt a hold. Anderson kapitány a nagy szalonban ájtatos fölolvasást tartott a bibliából, melynek szakaszai közben az utasok zsoltárokat énekeltek. <span class="marked">Kilenc órakor</span> ennek is vége volt: s a nap eltelt anélkül, hogy Harry Drake segédei kihívták volna Fabiant.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-6969', 'Verne Jules', 'novel', 'https://mek.oszk.hu/04600/04643/04643.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az úszó város', 'https://mek.oszk.hu/04600/04643', 'eljárása lehangolt. - Föltétlenül. - Barátunk, Harry Drake a kardot választja. - Jól van. És hol lesz a párbaj? New-Yorkban? - Nem; itt a hajón. - Hát legyen a hajón, ha önöknek úgy tetszik. És mikor? Holnap? - Ma este <span class="marked">hat órakor</span> a hátulsó födélzeten, mely ebben az órában üres és néptelen.', true, '18:00', '18:00', '18:00', 1080, 1080, 1080, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-6969', 'Verne Jules', 'novel', 'https://mek.oszk.hu/04600/04643/04643.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az úszó város', 'https://mek.oszk.hu/04600/04643', 'Világos, hogy az éjszakai negyedórák tulajdonosai, akik közt magam is voltam, minden reményről lemondtak s a nappaliak közül is csak azok értek valamit, amelyek négy és <span class="marked">hat óra</span> közé estek. Az a nyolc-tíz úr tehát, akiknek ezek a negyedórák jutot tak osztályrészül, kereskedni kezdtek a negyedórákkal s a vásár oly élénken folyt, hogy szinte a londoni börzére képzeltem magamat. Négy óra tizenhat', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-6969', 'Verne Jules', 'novel', 'https://mek.oszk.hu/04600/04643/04643.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az úszó város', 'https://mek.oszk.hu/04600/04643', 'Másnap, kedden, április 9-én, reggeli <span class="marked">tizenegy órakor</span> a Great-Eastern fölhúzta macskáit s készülődött, hogy fölmenjen a Hudson folyó torkolatába.', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-6969', 'Verne Jules', 'novel', 'https://mek.oszk.hu/04600/04643/04643.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az úszó város', 'https://mek.oszk.hu/04600/04643', 'New-Jersey zöldellő dombsorát, az öböl roppant erődítéseit, majd az alacsonyan fekvő nagy város körvonalait is, melyek a Hudson meg az East-River közt terülnek el, mint a Lyon a Rhône és Saône folyók közt. <span class="marked">Egy órakor</span>, miután végigmentünk New-York rakodópartjai mellett, a Great-Eastern horgonyt vetett a Hudson folyóban és a vasmacskái úgy belekapaszkodtak a folyam kábeldrótjaiba, hogy az elutazáskor szét kellett tépni a kábelt.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-6969', 'Verne Jules', 'novel', 'https://mek.oszk.hu/04600/04643/04643.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az úszó város', 'https://mek.oszk.hu/04600/04643', 'a börze vagy a vásárcsarnok; ez a «bar-room» különös intézmény: éjjel-nappal nyitva van, mindenki bemehet és ingyen kap sajtot, kétszersültet és jeges vizet. - Nos, doktor, - kérdeztem, - hát mikor indulunk? - Ma este <span class="marked">hat órakor</span>. - A Hudson-vonattal? - Nem; a Saint-John gőzösön; ez is úszó város, valóságos Great-Eastern , de csak folyón s az a kitűnő előnye van a Great-Eastern fölött, hogy amerikai módra épült, tehát a kazánja könnyen', true, '18:00', '18:00', '18:00', 1080, 1080, 1080, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-6969', 'Verne Jules', 'novel', 'https://mek.oszk.hu/04600/04643/04643.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az úszó város', 'https://mek.oszk.hu/04600/04643', 'Holnap reggel öt órakor Albanyban leszünk; <span class="marked">hat órakor</span> fölülünk a newyorki vonatra s estére már a Niagara mellett vacsorázunk.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-6969', 'Verne Jules', 'novel', 'https://mek.oszk.hu/04600/04643/04643.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az úszó város', 'https://mek.oszk.hu/04600/04643', 'egész sereg néger pincér szolgált ki bennünket. Vacsorázás közben elbeszélte, hogy a hajón négyezer és néhányszáz utas van, köztük ezerötszáz kivándorló, akiket a födélzet alá helyeztek el. Vacsora után lefeküdtünk. <span class="marked">Tizenegy óra</span> tájban hirtelen lökés ébresztett föl.', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-6969', 'Verne Jules', 'novel', 'https://mek.oszk.hu/04600/04643/04643.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az úszó város', 'https://mek.oszk.hu/04600/04643', 'doktor, mert nem sok az időnk. - Helyes! Így hát este helyett majd csak éjjel érünk a Niagarához. Ez ugyan nem nagyon volt ínyemre, de bele kellett nyugodnom, mert úgysem változtathattam rajta. Csakugyan, a Saint-John <span class="marked">nyolc órakor</span> kötött ki Albanyban, amikor a mi vonatunk már régen elment.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-6969', 'Verne Jules', 'novel', 'https://mek.oszk.hu/04600/04643/04643.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az úszó város', 'https://mek.oszk.hu/04600/04643', 'A Bőrharisnya nagy eposzának gyönyörű színtere, az <span class="marked">egykor</span> vad, félelmes vidék ma már jól művelt, termékeny terület; itt épültek a történelmi nevezetességű városok: Róma, Syracusa, Palmyra; de nevezetességüket nem az Egyesült-Államok, hanem az ókor történetének köszönhetik.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-6969', 'Verne Jules', 'novel', 'https://mek.oszk.hu/04600/04643/04643.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az úszó város', 'https://mek.oszk.hu/04600/04643', 'az Egyesült-Államok, hanem az ókor történetének köszönhetik. A doktor magánkívül volt örömében; engem állandóan Sólyomszemnek szólított s nem is akart felelni, ha én meg viszont nem Nagy-Kígyónak szólítottam őt. Este <span class="marked">tizenegy órakor</span> átszálltunk Rochesterben, keresztülvágtunk a Tennessee folyón, mely számos zuhatagban omlott alá a vasúti híd alatt.', true, '23:00', '23:00', '23:00', 1380, 1380, 1380, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-6969', 'Verne Jules', 'novel', 'https://mek.oszk.hu/04600/04643/04643.htm', 'deep_extract', false);
