INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az úszó város', 'https://mek.oszk.hu/04600/04643', 'megsüketülve, bőrig ázva sem nem láthattuk, sem nem hallhattuk egymást ebben a barlangban, m elyet az eléje boruló vízfüggöny éppen olyan áttörhetetlen páncéllal zár el, mintha gránitsziklák állnának előtte. <span class="marked">Kilenc órakor</span> már ismét ott voltunk a kis fogadóban és levetettük a kölcsönzött ruhákat.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-6969', 'Verne Jules', 'novel', 'https://mek.oszk.hu/04600/04643/04643.htm', 'deep_extract', false);
