INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Az úszó város', 'https://mek.oszk.hu/04600/04643', 'Kedden, április 16-án kellett indulnia a Great-Eastern -nek; <span class="marked">tizenegy órakor</span> tehát odahajtattam a harminchetedik «hajó-kiállóhoz», ahol már várt a kis helyi gőzös, mely az utasokat a nagy úszó városra szállította.', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-6969', 'Verne Jules', 'novel', 'https://mek.oszk.hu/04600/04643/04643.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Cikkek és karcolatok II.', 'https://mek.oszk.hu/00900/00901', 'A cimborák lenézik kopott ruhádat, <span class="marked">egykor</span> oly előzékeny hölgyek fintorgó mosollyal haladnak el melletted.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2900', 'Mikszáth Kálmán', 'articles', 'https://mek.oszk.hu/00900/00901/html/19.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Cikkek és karcolatok II.', 'https://mek.oszk.hu/00900/00901', 'küldöttség volt a legérdekesebb, mert a király a kihallgatáson alkalmasint nagyon megkeserítette őket, így szólván: Üdvözlöm önöket székhelyükön. * De kezdjük a nevezetes színházi est történetét elejéről. A király pont <span class="marked">fél nyolckor</span> jelent meg nagy éljenriadás közt Tisza Lajossal, ki balján foglalt helyet, a jobboldali helyet a miniszterelnöknek hagyván, ki legott átjött a szomszéd páholyból, s a két Tisza egész végig ott maradt mellette.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2900', 'Mikszáth Kálmán', 'articles', 'https://mek.oszk.hu/00900/00901/html/19.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Cikkek és karcolatok II.', 'https://mek.oszk.hu/00900/00901', 'főúr: elhozta az ötös fogatot meg a fiát is. Hanem a két ékessége közül a fogata tetszett itt jobban. Herceg csak egy volt, ti. Herczeg Mihály, akinek két szép kis leánykája fölért három nem szép nagy lánykával. <span class="marked">Kilenc óra</span> után mindinkább türelmetlenebbül szedték elő az órákat.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2900', 'Mikszáth Kálmán', 'articles', 'https://mek.oszk.hu/00900/00901/html/19.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Cikkek és karcolatok II.', 'https://mek.oszk.hu/00900/00901', 'S ha önök nem lennének sokkal szegényebbek nélküle, szívesen bevennők őt férfi számba is, mint ahogy <span class="marked">egykor</span> a művelt Bethlen Katalint akarták az erdélyi rendek.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2900', 'Mikszáth Kálmán', 'articles', 'https://mek.oszk.hu/00900/00901/html/19.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Cikkek és karcolatok II.', 'https://mek.oszk.hu/00900/00901', 'Floquetnek beszélt: az ő ideája volt a szombat. Erre a szélsőbaloldalról is felkelt Mocsáry Lajos: ő is a szombat mellett van. S így ebből tudtuk meg nagy idő után, kik a pártoknak a vezérei. A T. HÁZBÓL [okt. 7.] <span class="marked">10 órakor</span> kezdődött az ülés, de már tíz előtt ki volt függesztve az országház kapujára egy biztató fehér táblácska magyar felirattal: JELA jegyek mind elfogytak.', true, '10:00', '10:00', '10:00', 600, 600, 600, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2900', 'Mikszáth Kálmán', 'articles', 'https://mek.oszk.hu/00900/00901/html/19.htm', 'deep_extract', false);
