INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Cikkek, tárcák', 'https://mek.oszk.hu/07400/07469', 'Avagy van-e ebben a házában ember, aki Irálytant nem tanult vala, s aki az elégiát nem nevezte <span class="marked">egykor</span> alagyának?! Ugyebár nincsen. Ifjúkorunk hajnalán, midőn a fogalmazási képességet részben elsajátítottuk, mindnyájan Laky Demeter főtisztelendő úr Iránytanából tanultunk irályt s versszaktant, valamint műfajokat is,', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-11061', 'Mikszáth Kálmán', 'articles', 'https://mek.oszk.hu/07400/07469/07469.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Cikkek, tárcák', 'https://mek.oszk.hu/07400/07469', 'Úgy emlegetik ezt, mint ahogy talán emlegették <span class="marked">egykor</span> a bibliai ifjak valamelyikét, aki benn volt már a tüzes kemencében, de mégsem égett meg, hanem épségben jött ki onnan.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-11061', 'Mikszáth Kálmán', 'articles', 'https://mek.oszk.hu/07400/07469/07469.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Cikkek, tárcák', 'https://mek.oszk.hu/07400/07469', 'A pártoskodásnak az a neme, mely a mi parlamenti köreinkben divatos, mely <span class="marked">egykor</span> melegség volt, most csak tartalmatlan sablon, mintha feszélyezte volna.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-11061', 'Mikszáth Kálmán', 'articles', 'https://mek.oszk.hu/07400/07469/07469.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Cikkek, tárcák', 'https://mek.oszk.hu/07400/07469', 'saját ágyneműjében, a saját nyakkendőjével fognak megfojtani. Wlassics szemrehányást tett Rosenbergnek a vacsoránál. - Te ugyan hamar ejtetted el Szilágyit! - Háromnegyed hétig kitartottam mellette. És te? - Engem csak <span class="marked">fél nyolckor</span> sikerült kapacitálni. Körülbelül ily negyedórák határolták el a kemény karaktereket a puhányoktól. Szilágyi igen keserű volt ezekben a napokban, s midőn egyes hízelgők mézes náddal kezdték előtte leírni a jövőjét,', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-11061', 'Mikszáth Kálmán', 'articles', 'https://mek.oszk.hu/07400/07469/07469.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Cikkek, tárcák', 'https://mek.oszk.hu/07400/07469', 'a Szilágyi néha mégis hiányzik nekünk. A MAI ÜLÉS [8] (Az országgyűlésből) Az elmúlt vakációra való tekintettel amúgy is tizenegy órára volt kitűzve az ülés, hadd legyen idejük a tisztelt honatyáknak gyülekezniök. De <span class="marked">tizenegy óra</span> is régen elmúlt, féltizenkettőre is járt már az idő, de az ülés még mindig nem kezdődött meg.', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-11061', 'Mikszáth Kálmán', 'articles', 'https://mek.oszk.hu/07400/07469/07469.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Cikkek, tárcák', 'https://mek.oszk.hu/07400/07469', 'Szluha István: Tíz óra helyett <span class="marked">féltizenegy</span> tétessék. A házszabályokkal való ily eklatáns visszaélés mód nélkül felháborította a jobboldalt, mely kész volt ezeket a módosítványokat el is fogadni, csak hogy a Házat megmentsék a szégyentől, hogy a magyar parlament', true, '10:30', '10:30', '10:30', 630, 630, 630, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-11061', 'Mikszáth Kálmán', 'articles', 'https://mek.oszk.hu/07400/07469/07469.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Cikkek, tárcák', 'https://mek.oszk.hu/07400/07469', 'S hogy volt egy király, aki ennyire megbízott nemeseiben s kezükbe adta, hogy neveljenek <span class="marked">fel egy</span> csecsemőt nagy gonddal, nagy szeretettel, mert ha felnevelik, az őket fogja legelőször is elütni az örökségtől.', true, '00:30', '00:30', '00:30', 30, 30, 30, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-11061', 'Mikszáth Kálmán', 'articles', 'https://mek.oszk.hu/07400/07469/07469.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Cikkek, tárcák', 'https://mek.oszk.hu/07400/07469', 'De senki sem a propozíciókra gondol, hanem a bársonyszövetre, amelybe a Bánffy Dezső feje lesz végeredményképp betakarva - mint <span class="marked">egykor</span> ama szerencsétlen Bánffy Dénesé.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-11061', 'Mikszáth Kálmán', 'articles', 'https://mek.oszk.hu/07400/07469/07469.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Vágyak és ösztönök', 'https://mek.oszk.hu/06300/06361', 'Virslit párol minden héten kétszer, véletlenül se mást, ezt rádobja a kifőzött tésztára, és kész az ebéd, ami neki <span class="marked">egy óra</span> m unka. Amikor Hajnalka bevitte a levest a szobába, Viola szólt, hogy most legyenek csendben, mert esznek a fiatalok. A levest nem a tányér tetejéről kanalazták, hanem minden merítésnél a tányér alját érintve,', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9252', 'Pásty Júlia', 'short novel', 'https://mek.oszk.hu/06300/06361/06361.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Vágyak és ösztönök', 'https://mek.oszk.hu/06300/06361', 'Másnap délelőtt a férfi telefonált, hogy délután megy a fürdőbe, és utána 18-<span class="marked">19 óra</span> tájt amikor hazaér, az asszony menjen el hozzá taxival, melyet ő fog fizetni.', true, '19:00', '19:00', '19:00', 1140, 1140, 1140, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9252', 'Pásty Júlia', 'short novel', 'https://mek.oszk.hu/06300/06361/06361.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Vágyak és ösztönök', 'https://mek.oszk.hu/06300/06361', 'Hortenzia már elmondta beszélgetésük alkalmával, hogy <span class="marked">nyolckor</span> szokott kelni. De Leander azt mondta, hogy minden rendes asszony ötkor kell, és tesz-vesz. Hortenziának eszébe jutott az a mondás, hogy miért megy reggel korán a férfi kenyeret venni - mert puha. Talán nála is az a', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9252', 'Pásty Júlia', 'short novel', 'https://mek.oszk.hu/06300/06361/06361.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Vágyak és ösztönök', 'https://mek.oszk.hu/06300/06361', 'taxival megy az állomásra, akkor jöjjenek hozzá, és vegyék fel őt, ne kelljen gyalogolni korán reggel. Aztán felhívta, hogy ne készítsen neki ennivalót. Eszébe sem jutott az asszonynak. Harmadszor azt mondta, hogy <span class="marked">hatkor</span> ébressze őt fel. - Én, aki nyolcig alszom minden nap, ő meg ötkor kel reggelenként?! Egyszer volt egy kis gyenge sikere, és máris parancsol! Ez az ember, teljesen felforgatja az életemet - gondolta az asszony. Csak', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9252', 'Pásty Júlia', 'short novel', 'https://mek.oszk.hu/06300/06361/06361.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Vágyak és ösztönök', 'https://mek.oszk.hu/06300/06361', 'felforgatja az életemet - gondolta az asszony. Csak magára gondol a nárcisztikus ember. Hortenzia már várta, hogy elutazzon, mert hiányoztak a barátnők, akikkel az utóbbi időkben nem is találkozott. Végül is másnap <span class="marked">hatkor</span> felébresztette az asszony. Erre azt mondta Leander, hogy már négy óra óta ébren van. A megbeszélt időben Hortenzia a ház előtt várakozott. Amikor az állomásra érkeztek, Leander megindult a két bőrönddel, sietett, pedig', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9252', 'Pásty Júlia', 'short novel', 'https://mek.oszk.hu/06300/06361/06361.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Vágyak és ösztönök', 'https://mek.oszk.hu/06300/06361', 'Időnként lehallgatta az üzeneteket. Egész nap ette a finom levest, a maradék húst megsütötte hagymával. Úgy gondolta, nem adja a férfinak, majd akkor fogadja, ha ő akarja, és nem olyankor, ha parancsolja neki. - <span class="marked">Tizenegykor</span> érkezem, ha hazaértél, és ha tudsz, várjál!', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9252', 'Pásty Júlia', 'short novel', 'https://mek.oszk.hu/06300/06361/06361.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Vágyak és ösztönök', 'https://mek.oszk.hu/06300/06361', 'de ő nem szereti a hangos zenét. Majd megemlítette Nefelejcset, hogy mennyire szerette, hogy most már mindent megadna neki. - Így szokott ez lenni - mondta Hortenzia, - ezért kell a mostani nővel foglalkozni! Reggel <span class="marked">fél nyolckor</span> a férfi ébresztette az asszonyt, és boldog névnapot kívánt.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9252', 'Pásty Júlia', 'short novel', 'https://mek.oszk.hu/06300/06361/06361.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('79 nap remény', 'https://mek.oszk.hu/02700/02795', 'nem visel meg a dialízis, amellett arra is kíváncsi vagyok, hogy miként reagál a szervezetem a salakmentes, kitisztult állapotra. És az meddig tart?... Vajon a veséim mit szólnak hozzá?... Túl vagyok a művesekezelésen. <span class="marked">Hat óra</span> hosszáig tartott. Az erek preparálása fájdalmatlanul, gyorsan elkészült, semmi kellemetlenséget nem éreztem, úgyszintén a dialízis közben sem. Olvasgattam, beszélgettem a nővérrel, aki velem volt állandóan. Az orvosok', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet | Orvostudomány, állatorvostan","Sebészet"}', 'urn:nbn:hu-4774', 'Németh András', 'documentary novel', 'https://mek.oszk.hu/02700/02795/02795.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('79 nap remény', 'https://mek.oszk.hu/02700/02795', 'Olyan jóleső fáradtság volt a tagjaimban, és mintha egy acélsisak esett volna le a fejemről. Tisztábban is hallottam, mint máskor, a beszédem is frissebbé vált. Ezeket a feleségemnek is elmondtam, együtt örültünk. <span class="marked">Nyolc óra</span> tájban jött a papom. Én előtte mondtam a szobatársaimnak, hogy áldozni szeretnék, de ők csak nyugodtan maradjanak az ágyukban, mi biztosan nem fogunk zavarni. Ahogy az atya leült az ágyam mellé, a betegtársaim szép', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet | Orvostudomány, állatorvostan","Sebészet"}', 'urn:nbn:hu-4774', 'Németh András', 'documentary novel', 'https://mek.oszk.hu/02700/02795/02795.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('79 nap remény', 'https://mek.oszk.hu/02700/02795', 'a család, illetve azok a testvéreim, akik Szegeden laktak. A többiek egyébként sem jöhettek volna szóba, mint donorok, mert mindnek családja van. Édesanyám, feleségem és három testvérem jött be az Adjunktushoz. Kb. <span class="marked">egy óra</span> hosszáig tárgyaltak. Utána visszajöttek. Elmondták, hogy az Adjunktus részletesen, világosan beszélt az állapotomról, a veseátültetés mai kilátásairól, veszélyeiről. A donor veszélyeztetettségéről és végül abban', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet | Orvostudomány, állatorvostan","Sebészet"}', 'urn:nbn:hu-4774', 'Németh András', 'documentary novel', 'https://mek.oszk.hu/02700/02795/02795.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('79 nap remény', 'https://mek.oszk.hu/02700/02795', 'A nővér a szolgálati ideje alatt (3-<span class="marked">4 óra</span>) nem hagyhatja el a kó rtermet, csak komoly szükség esetén.', true, '04:00', '04:00', '04:00', 240, 240, 240, '{"Szépirodalom, népköltészet | Orvostudomány, állatorvostan","Sebészet"}', 'urn:nbn:hu-4774', 'Németh András', 'documentary novel', 'https://mek.oszk.hu/02700/02795/02795.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('79 nap remény', 'https://mek.oszk.hu/02700/02795', 'akiket a legalkalmasabbnak talált a jelentkezők közül, ha nekem is megfelel, a dialízis utá n a kórteremben föl fognak keresni, hogy megismerkedjenek velem, hiszen hetekig össze leszünk zárva. (Remélem.) Délután <span class="marked">negyed hatkor</span> befejeződött a kezelés. Úgy éreztem magam, mint aki fürdés után tisztába öltözik. Friss voltam, kíváncsian vártam a nővéreket. Meghallottam a folyosóról behallatszó viháncolásukat, amit az ajtó előtt abbahagytak, és', true, '17:15', '17:15', '17:15', 1035, 1035, 1035, '{"Szépirodalom, népköltészet | Orvostudomány, állatorvostan","Sebészet"}', 'urn:nbn:hu-4774', 'Németh András', 'documentary novel', 'https://mek.oszk.hu/02700/02795/02795.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('79 nap remény', 'https://mek.oszk.hu/02700/02795', 'Kiderült, hogy az Adjunktus telefonált neki, éhgyomorra jelentkezzen ma <span class="marked">fél nyolckor</span> befekvésre, mert a steril szoba elkészült és csak a fertőtlenítése hiányzik.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet | Orvostudomány, állatorvostan","Sebészet"}', 'urn:nbn:hu-4774', 'Németh András', 'documentary novel', 'https://mek.oszk.hu/02700/02795/02795.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('79 nap remény', 'https://mek.oszk.hu/02700/02795', 'a boldog új évet kívánók egymásutánja nem is hagyott vele törődni. Embernek, egész embernek éreztem magam. Ehhez a még soha nem ízlelt korty pezsgő és a már majdnem elfelejtett forró virsli íze is hozzájárult. <span class="marked">Egy óra</span> felé Laci öcsém elbúcsúzott és még egyszer buékot kívánva visszament a kórtermébe.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet | Orvostudomány, állatorvostan","Sebészet"}', 'urn:nbn:hu-4774', 'Németh András', 'documentary novel', 'https://mek.oszk.hu/02700/02795/02795.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('79 nap remény', 'https://mek.oszk.hu/02700/02795', 'precíz Elza nővér megjelenése, aki katonás, határozott modorával a legkisebb izmomat is megmozgatta. Eleinte tartottam tőle, de hamarosan összebarátkoztunk. Január 7. - Fiatal úr, még lustálkodunk? - robbant be Rózsa <span class="marked">hat órakor</span> nagy hangon. - A hasára süt a nap! Látom viszont, hogy a kis veséje annál szorgalmasabban dolgozik. - Az teszi a magáét - mondtam kissé nyűgösen, és fölkészültem a mai élénk agytornára. - És hogy érezzük magunkat mi', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet | Orvostudomány, állatorvostan","Sebészet"}', 'urn:nbn:hu-4774', 'Németh András', 'documentary novel', 'https://mek.oszk.hu/02700/02795/02795.htm', 'deep_extract', false);
