INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hétköznapok ünneplőben', 'https://mek.oszk.hu/04500/04530', 'Igazán normálisan viselkedtek, csak néha hallatszott <span class="marked">fel egy</span>-egy üdvrivalgás, ha jó dobás esett.', true, '00:30', '00:30', '00:30', 30, 30, 30, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-6825', 'Kiss Péter', 'short stories', 'https://mek.oszk.hu/04500/04530/04530.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hétköznapok ünneplőben', 'https://mek.oszk.hu/04500/04530', 'Fárasztó volt, miután a bulit követően ötkor kerültek ágyba, a gyerekek, pedig szokás szerint <span class="marked">fél nyolckor</span> már kornyikáltak. A férfi é rezte, hogy valamit akar mondani a felesége, de mindig csak halogatja azt. Este az ágyban, miután kettesben maradtak bökte ki Fruzsina a mondandóját. - Elhagylak Szasa. A lányt elviszem.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-6825', 'Kiss Péter', 'short stories', 'https://mek.oszk.hu/04500/04530/04530.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Utazás a koponyám körül', 'https://mek.oszk.hu/00700/00717', 'skarlát óta, amin gyermekkoromban átestem, nem voltam soha beteg (vakbél nem számít), titokban számítok rá, hogy ezzel imponálni fogok Cininek. Futóan eszembe jutnak a délutáni vonatok, de rögtön elfelejtem. Reggel már <span class="marked">nyolckor</span> jönnek valami korrektúráért. Aztán titkárom, Dénes, jelentkezik, az iratszekrényt, amit tegnap olyan olcsón vettem, politúrozni kell, de jó lesz személyesen elintézni, rémesen becsaphatják az embert: ha magam megyek', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2716', 'Karinthy Frigyes', 'novel', 'https://mek.oszk.hu/00700/00717/00717.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Utazás a koponyám körül', 'https://mek.oszk.hu/00700/00717', '(valahol tanultam is) még fokozottabban szoktak jelentkezni a tünetek, mint heveny állapotban. A vonatdübörgéssel és szédüléssel együtt beveszem a "rezsibe", műsoromba iktatom, napi teendőim közé számítom fel. Este, <span class="marked">hat órakor</span> jön a szédülés - eleinte furcsa, hogy minden kóvályog, tompán kering bennem, de aztán megszokom.', true, '18:00', '18:00', '18:00', 1080, 1080, 1080, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2716', 'Karinthy Frigyes', 'novel', 'https://mek.oszk.hu/00700/00717/00717.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Utazás a koponyám körül', 'https://mek.oszk.hu/00700/00717', 'Erzsi volt itt, sokáig várt, aztán ennyit írt csak: "Aki beteg, haljon meg, de ne császkáljon, mikor vendége érkezik, hogy utoljára lássa." Egy keddi napon délelőtt <span class="marked">tizenegykor</span> nyílik az ajtó és fehér egyenruhás tisztikara élén, mint egy haditörvényszék elnöke, ünnepélyesen bevonul a Tanár.', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2716', 'Karinthy Frigyes', 'novel', 'https://mek.oszk.hu/00700/00717/00717.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Utazás a koponyám körül', 'https://mek.oszk.hu/00700/00717', 'Bolondok ezek a szegények - az a munkás is -, mit is mondott a másik a "rögtön-masinával"? pedig fel akartam írni, hogy elmesélem K. Fricinek... igaz, hopp, jó, hogy eszembe jut... őt is meg kell látogatnom - <span class="marked">hatkor</span> a Zugliget felé menet, megállok a Central előtt, ott szo kott üldögélni...', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2716', 'Karinthy Frigyes', 'novel', 'https://mek.oszk.hu/00700/00717/00717.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Utazás a koponyám körül', 'https://mek.oszk.hu/00700/00717', 'magamról, az egész életemről, úgy, ahogy sikerült, ahogy itt áll most a bécsi utca szélén, és köszöne ttel visszaköpi a csodálatos ajándékot, amire olyan büszke volt, aki adta, ami ennyit ért annak, aki kapta. De este <span class="marked">nyolc óra</span> felé a hideg márciusi szélben ott ülök mégis a Café de France teraszán.', true, '20:00', '20:00', '20:00', 1200, 1200, 1200, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2716', 'Karinthy Frigyes', 'novel', 'https://mek.oszk.hu/00700/00717/00717.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Utazás a koponyám körül', 'https://mek.oszk.hu/00700/00717', '- Hát kérem - mondja hivatalos természetességgel, de halkan, ahogy fontos, elkerülhetetlen dolgot mondunk -, holnap lesz szerencsém, ugyebár, <span class="marked">fél kilenckor</span> reggel, az S. klinika négyes számú műhelyében, ahol éppen dolgom van reggel. - Hogy én... minek? - Egy kis diagnosztikai próbát csinálunk. Feleségemnek megmagyarázza, miről van szó. A diagnosztikai próba némi', true, '08:30', '08:30', '08:30', 510, 510, 510, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2716', 'Karinthy Frigyes', 'novel', 'https://mek.oszk.hu/00700/00717/00717.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Utazás a koponyám körül', 'https://mek.oszk.hu/00700/00717', 'kivált belőlem. Nem mutatom, azzal próbálom magyarázni magamnak, hogy kényelmetlennek érzem a korai felkelést és elmenést ebben az állapotban. De ezt szégyenkezésből nem árulom el, és megígérem, hogy ott leszek. Másnap <span class="marked">kilenckor</span> őnagysága nagy ribilliót csap ágyam mellett.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2716', 'Karinthy Frigyes', 'novel', 'https://mek.oszk.hu/00700/00717/00717.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Utazás a koponyám körül', 'https://mek.oszk.hu/00700/00717', '"Odafelé - felelem - elég drága, de visszafelé apró dobozban hoznak - az urna, úgy tudom, vámmentes." Délelőtt <span class="marked">tizenegykor</span> indul a Bécsi gyors, lesz kis fülkém, fekhetem.', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2716', 'Karinthy Frigyes', 'novel', 'https://mek.oszk.hu/00700/00717/00717.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Utazás a koponyám körül', 'https://mek.oszk.hu/00700/00717', 'fekszem kifeszülve, és nem bírom tovább. ISTEN NEVÉBEN - ÉSZAK FELÉ Az álom, külső időben is, elég hosszú lehetett: már sötétedik, mikor felkeltenek. Kábultan, k óvályogva cihelődöm. Még három óránk van, pont <span class="marked">kilenc órakor</span> indul a vonatom Berlinen át. Külön hálófülkém lesz. Őnagysága vállalja, éjszaka, a határvizsgálatokat, reggelig alhatom. Április huszonnyolcadika van. Élénk, csípős kis szelek fütyülnek a "bé csi hegyeken". Felkészülök', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2716', 'Karinthy Frigyes', 'novel', 'https://mek.oszk.hu/00700/00717/00717.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Utazás a koponyám körül', 'https://mek.oszk.hu/00700/00717', 'fogom. Szabatos Gyulán ak írok, és Szórakozott Gyulának, Cininek és a grófnőnek - azt hallom, egész jól el tudták olvasni. Miután néhányszor megtiszteltem a mosdótálat, ez a borongós délután is elmúlik. <span class="marked">Tizenegykor</span> indul majd a vonat Trelleborg felé, ez már Skandinávia.', true, '23:00', '23:00', '23:00', 1380, 1380, 1380, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2716', 'Karinthy Frigyes', 'novel', 'https://mek.oszk.hu/00700/00717/00717.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Utazás a koponyám körül', 'https://mek.oszk.hu/00700/00717', 'kicsi, de pompásan fel van szerelve. Fél füllel valamit hallok, hogy tengeren megyünk át - nyilván rosszul értettem, kábult vagyok, hogy mehet a vonat tengeren, vagy valami hídról van szó? Igyekszem gyorsan elaludni, <span class="marked">hat órakor</span> érkezünk meg reggel, s máris elég hűvös a levegő.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2716', 'Karinthy Frigyes', 'novel', 'https://mek.oszk.hu/00700/00717/00717.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Utazás a koponyám körül', 'https://mek.oszk.hu/00700/00717', 'de nem haragos. Vidáman és közömbösen f ütyörész. A világ, mintha lengene, és mintha magasabban volna, olyan tiszta és üde. Megfinomodott szaglásom felfogja a tenger sós illatát. Mi az, úgy látszik, nem lesz vizsgálat. <span class="marked">Kilenc óra</span> elmúlt, és a szolga nem jelentkezett, hogy felemelje és gurítani kezdje ágyamat, a folyosókon át.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2716', 'Karinthy Frigyes', 'novel', 'https://mek.oszk.hu/00700/00717/00717.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Utazás a koponyám körül', 'https://mek.oszk.hu/00700/00717', 'Nyugodtan kell aludnia, holnap reggel <span class="marked">fél nyolckor</span> operálják. AVDELNING 13 Úgy látszik, a határozott közlés után rögtön mélyen elaludtam, nem emlékszem egyetlen gondolatra se az estéről, éccaka se riadtam fel, tíz órát aludtam egyfolytában, időérzéklés nélkül. Reggel', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2716', 'Karinthy Frigyes', 'novel', 'https://mek.oszk.hu/00700/00717/00717.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Utazás a koponyám körül', 'https://mek.oszk.hu/00700/00717', 'levették a pántot, ő mikrolámpát süllyesztett az üregbe, s annak fénye mellett, a kicsit pirosabb, jobb oldali kisagyvelőn, a pia mater második lemeze alatt megpillantotta, aztán kicsit megtapogatta a duzzanatot. <span class="marked">Tizenegy óra</span> volt, két órája folyt a műtét.', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2716', 'Karinthy Frigyes', 'novel', 'https://mek.oszk.hu/00700/00717/00717.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Utazás a koponyám körül', 'https://mek.oszk.hu/00700/00717', 'mondja, adja le, részletenként a főszerkesztőnek, onnan a nyomdába, délre lapzárta. (Nagyon helyesen csak adatokat mond, minden szubjektív hozzászólás nélkül, ahogy orvos létére hozzá és hozzá m illik.) "... a műtét <span class="marked">kilenckor</span> kezdődött, és egy óra előtt alig lesz vége...', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2716', 'Karinthy Frigyes', 'novel', 'https://mek.oszk.hu/00700/00717/00717.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Utazás a koponyám körül', 'https://mek.oszk.hu/00700/00717', 'a műtét kilenckor kezdődött, és <span class="marked">egy óra</span> előtt alig lesz vége... Itt hallgatóztam imént az ajtónál, kihallatszik a beteg nyögése... ...a professzor csodálatos ember... ...igen, villamostűvel... Percenként mérik a vérnyomást... Közben oxigénb elégzést kap. Ha', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2716', 'Karinthy Frigyes', 'novel', 'https://mek.oszk.hu/00700/00717/00717.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Utazás a koponyám körül', 'https://mek.oszk.hu/00700/00717', 'lépten-nyomon megállítják. Mi újság, mit tud, mik az utolsó hírek? Sz. különösen meleg és odaadó, elkísérteti magát a szigetig, részletesen akar tudni mindent. Valaki azt is megkérdezi tőle, nincs-e nála kéziratom? * <span class="marked">Egy óra</span> felé törzskávéházamban kezdenek feketére gyülekezni.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2716', 'Karinthy Frigyes', 'novel', 'https://mek.oszk.hu/00700/00717/00717.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Utazás a koponyám körül', 'https://mek.oszk.hu/00700/00717', 'Feldolgozni való gondolatanyagom elég volt, bár az a gyanúm, alapjában semmi egyébbel nem foglalkoztam, mint időméréssel, akár a rabok, vagy az alvó ember alsó tudata, aki azzal aludt el, hogy reggel <span class="marked">fél nyolckor</span> fel kell majd kelnie. Így semmi rendkívülit nem találtam rajta, hogy megint sötét van, illetve hogy megint álmos vagyok. A nap szegényes benyomásait fáradtságomnak tulajdonítottam, s elégedetten regisztráltam el,', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2716', 'Karinthy Frigyes', 'novel', 'https://mek.oszk.hu/00700/00717/00717.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Utazás a koponyám körül', 'https://mek.oszk.hu/00700/00717', 'Maga Kerstin jön. - Ne tessék erőlködni... - Jó, jó... Csukja, be az ajtót, fröken Kerstin. És jöjjön közelebb. És most mondja meg nekem, de kertelés nélkül - mikor operáltak meg engem? - Hogy hány órakor kezdték? Hát <span class="marked">nyolckor</span>. - Azt tudom. De mikor nyolckor? - Hát ma reggel. - Ú... ú... úgy. Na, köszönöm. És milyen nap van ma maga szerint? - Hétfő. - Ú... ú... úgy. Na jó. Nem kell semmi. - Megigazítanám a párnát. - Hagyja csak, jó lesz. -', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2716', 'Karinthy Frigyes', 'novel', 'https://mek.oszk.hu/00700/00717/00717.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Utazás a koponyám körül', 'https://mek.oszk.hu/00700/00717', '- Jó, jó... Csukja, be az ajtót, fröken Kerstin. És jöjjön közelebb. És most mondja meg nekem, de kertelés nélkül - mikor operáltak meg engem? - Hogy hány órakor kezdték? Hát nyolckor. - Azt tudom. De mikor <span class="marked">nyolckor</span>? - Hát ma reggel. - Ú... ú... úgy. Na, köszönöm. És milyen nap van ma maga szerint? - Hétfő. - Ú... ú... úgy. Na jó. Nem kell semmi. - Megigazítanám a párnát. - Hagyja csak, jó lesz. - De tessék csak hagyni... Kerstin', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2716', 'Karinthy Frigyes', 'novel', 'https://mek.oszk.hu/00700/00717/00717.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Utazás a koponyám körül', 'https://mek.oszk.hu/00700/00717', 'egy sereg viccel kedve skedtem, szelíddel és borsossal vegyesen, hogy a humorista is babérhoz jusson. Jól aludtam, a porokból csak fél adagot kértem, mert másnap délelőttre kilátásba helyezték a kötés eltávolítását. Ez <span class="marked">fél tizenegykor</span> következett be. Olivecrona és Söjkvist együtt végezték az ünnepélyes aktust. Behunyt szemmel, mámoros boldogsággal élveztem a halk pattanásokat és nyisszanásokat, ahogy átvágják és lefejtik a hatalmas köteg gézt és', true, '10:30', '10:30', '10:30', 630, 630, 630, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2716', 'Karinthy Frigyes', 'novel', 'https://mek.oszk.hu/00700/00717/00717.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Utazás a koponyám körül', 'https://mek.oszk.hu/00700/00717', 'Május 25-én, három héttel a műtét után, <span class="marked">hat óra</span> felé, belemerülve és szinte feldühödve számo lgatásaimba, amik most már órákra vonatkoztak, mint a raboknál, a benyitó Olivecronát azzal fogadtam, hogy megbolondulok, ha nem enged felülni legalább.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2716', 'Karinthy Frigyes', 'novel', 'https://mek.oszk.hu/00700/00717/00717.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Utazás a koponyám körül', 'https://mek.oszk.hu/00700/00717', 'nem van kiírva, amihez tartozom. Dühösen fizetek, és édes anyanyelvemen végre kereken és folyékonyan fejezem ki véleményemet az esze tokjáról - ezúttal nem azzal a céllal, sőt isten mentsen tőle, hogy meg értsen. Este <span class="marked">tizenegykor</span> még egész világos van. Itt is, a városban is, ahol nyolctól kezdve azért ég a sok villany - soha ilyen gusztusos, tarka és takaros várost és ilyen tündéri ragyogását a zöldeknek és kékeknek és pirosnak. Autón jöttünk', true, '23:00', '23:00', '23:00', 1380, 1380, 1380, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2716', 'Karinthy Frigyes', 'novel', 'https://mek.oszk.hu/00700/00717/00717.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A tündérkirálynő', 'https://mek.oszk.hu/13600/13602', 'tied leszek koporsóm bezártáig..." - Csukd el, fiam, elég volt a cigányozás. - Lefekszünk? - Azt gondolom, hogy miután nem megyünk pezsgőzni, tegyük el magunkat holnapra. Jó éjszakát, öregem. - Jó éjszakát, apa. Holnap <span class="marked">hatkor</span> kelsz? - Hatkor, de ne zavartasd magad a fürdőszobával. Majd én megfürdöm, ha elmentél az iskolába. Az apa átment a másik szobába. Két szobás lakást tartottak Szepezdy és fia. Három szoba volt ez eredetileg, de a három', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131068', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13602/13602.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A tündérkirálynő', 'https://mek.oszk.hu/13600/13602', 'bezártáig..." - Csukd el, fiam, elég volt a cigányozás. - Lefekszünk? - Azt gondolom, hogy miután nem megyünk pezsgőzni, tegyük el magunkat holnapra. Jó éjszakát, öregem. - Jó éjszakát, apa. Holnap hatkor kelsz? - <span class="marked">Hatkor</span>, de ne zavartasd magad a fürdőszobával.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131068', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13602/13602.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A tündérkirálynő', 'https://mek.oszk.hu/13600/13602', 'egyéb holmi közé. Aztán lefeküdt és megint eloltotta a világosságot. Melegség és fájdalmas szeretet ömlött el a szívén. Halkan súgta a sötétségbe: - Mama... De a súgásra nem jött válasz, csak a mély csend. II. Reggel <span class="marked">hatkor</span> Szepezdy Pali egy szempillantás alatt kiugrott az ágyból.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131068', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13602/13602.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A tündérkirálynő', 'https://mek.oszk.hu/13600/13602', 'egyedül élt özvegy édesanyjával. Ez a hasonló helyzet is összébb kötötte őket. Mire reggelivel is, leckével is készen lettek, még mindig csak negyednyolcra járt. Korán volt még iskolába menni. A cistercita gimnáziumban <span class="marked">nyolckor</span> kezdődött a tanítás. Katolikus fiúknak ugyan fél nyolckor, mert tanítás előtt mind a nyolc osztály növendékei résztvettek a rendház templomának miséjén, de a más vallásuak nem. Szepezdy Pali református volt, Székács', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131068', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13602/13602.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A tündérkirálynő', 'https://mek.oszk.hu/13600/13602', 'is összébb kötötte őket. Mire reggelivel is, leckével is készen lettek, még mindig csak negyednyolcra járt. Korán volt még iskolába menni. A cistercita gimnáziumban nyolckor kezdődött a tanítás. Katolikus fiúknak ugyan <span class="marked">fél nyolckor</span>, mert tanítás előtt mind a nyolc osztály növendékei résztvettek a rendház templomának miséjén, de a más vallásuak nem.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131068', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13602/13602.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A tündérkirálynő', 'https://mek.oszk.hu/13600/13602', 'A gimnázium kapuján csak ők mentek be, nem járt itt most senki: a katolikusok <span class="marked">fél nyolc</span> óta misén voltak. Végighaladtak a néptelen tornaudvaron, benyitottak a belső kapun és aztán a folyosón az első terembe baloldalt. Az volt a nyolcadik osztály. Éppen csengetésre értek be. Az osztály már együtt volt és', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131068', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13602/13602.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A tündérkirálynő', 'https://mek.oszk.hu/13600/13602', 'perfektuma "bebéka." Ovidius. Die Kraniche des Ibykus. Az ázsiai világvárosok alakulása. Szénhidrátok. Elsőfokú egyenlet két ismeretlennel. Nem tudtad dél óta megtanulni? Én hiába kínlódom itt veled, ha nem tanulsz... <span class="marked">Hat óra</span>. Sietni tovább. Márkusék nem messze laknak. Márkus Aladár nyolcadikos, amíg azt oktatja, elvégzi a saját leckéjét is. Sötét falépcsőn felmenni, balra fordulni, keresztülmenni a komor és mindig újságba merült családfő', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131068', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13602/13602.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A tündérkirálynő', 'https://mek.oszk.hu/13600/13602', 'Éósz: a rózsaujjú hajnal. Ha feleselsz velem, megint szólok apádnak. A hastingsi ütközet. Növénysejt és növényszövet. Nem hallottad, mit mondtam? Holnap második tízpercben gyere a nyolcadik elé. Végre, végre <span class="marked">nyolc óra</span>. Az utcán már egészen sötét van, a hűvös tavaszi este ködébe mélabús és rejtelmes fényfoltokat vetnek az utcai gázlámpák. Gyér járókelők sietnek haza. Egy kocsma ajtaja kitárul, hangos énekszó ömlik ki, majd becsukódik', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131068', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13602/13602.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A tündérkirálynő', 'https://mek.oszk.hu/13600/13602', 'az utcai gázlámpák. Gyér járókelők sietnek haza. Egy kocsma ajtaja kitárul, hangos énekszó ömlik ki, majd becsukódik az ajtó és ollóként vágja ketté a nóta hangosságát, A gyalogjárón esti békák másznak keresztül. <span class="marked">Félkilenc</span>. Itthon vagyunk. Az asztal megterítve, az apa már ott ül és újságot olvasva várja haza a fiát. Kellemes lámpafény és étvágygerjesztő ételszag. - Jaj de fáradt vagyok, apa. - Sokat dolgoztál, öregem, persze. Várjál', true, '08:30', '08:30', '08:30', 510, 510, 510, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131068', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13602/13602.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A tündérkirálynő', 'https://mek.oszk.hu/13600/13602', 'A kis Eberle báró úgy fellelkesedett beszélgetés közben, mikor Szepezdy Barna a régi huszáréletről adott elő egy pár történetet, hogy hevében odarikkantott a didergő pincérnek: - Bontsál <span class="marked">fel egy</span> rezervét, hé. A pincér izgatott boldogsággal rohant volna máris teljesíteni a parancsot, de az őrnagy utána kiáltott és visszahívta. Leintette a rendelést. Nem kell semmiféle rezervé, itt lumpolás nem lesz. A kis báró', true, '00:30', '00:30', '00:30', 30, 30, 30, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131068', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13602/13602.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A tündérkirálynő', 'https://mek.oszk.hu/13600/13602', 'a mi szerény agglegényi háztájunkkal. Jösz? Az ügyvédet meghívom feketére, mindjárt tárgyalhatsz is vele, ha akarsz. - Topp. Kitűnő. De hogyan találok el a lakásodra? - Természetesen érted jövök. Itt vagyok pontban <span class="marked">egykor</span>. Félkettőkor eszünk. Helyes? - Pompás. You are a dear. Egy órakor izenj fel értem. Kézcsók, kézfogások. A két huszár vitte befelé a szép asszonyt a gyér, de annál jobban izguló közönséggel telt étterembe, Szepezdy', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131068', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13602/13602.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A tündérkirálynő', 'https://mek.oszk.hu/13600/13602', 'feketére, mindjárt tárgyalhatsz is vele, ha akarsz. - Topp. Kitűnő. De hogyan találok el a lakásodra? - Természetesen érted jövök. Itt vagyok pontban egykor. Félkettőkor eszünk. Helyes? - Pompás. You are a dear. <span class="marked">Egy órakor</span> izenj fel értem. Kézcsók, kézfogások. A két huszár vitte befelé a szép asszonyt a gyér, de annál jobban izguló közönséggel telt étterembe, Szepezdy Barna pedig bölcs derűvel lépett ki az Ó-kaszinó boltíves, hatalmas', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131068', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13602/13602.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A tündérkirálynő', 'https://mek.oszk.hu/13600/13602', 'cipőjét, a másik lábammal az Eberle báró cipőjét. Akkor aztán mindkét lábamat gyorsan behúztam a szék alá. A két gavallér ettől kezdve egy álló óráig taposta egymás lábát, mert azt hitték, hogy velem flörtölnek. Csak <span class="marked">egy óra</span> mulva jöttek rá, mikor leejtettem a zsebkendőmet és mind a ketten utána kaptak, hogy egymással enyelegnek.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131068', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13602/13602.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A tündérkirálynő', 'https://mek.oszk.hu/13600/13602', 'Ebből a két órából voltaképpen csak <span class="marked">egy óra</span> telt el magával az interjúval.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131068', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13602/13602.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A tündérkirálynő', 'https://mek.oszk.hu/13600/13602', 'természetes hőfoka miatt az uszodát már tavasszal rendesen megnyitották, az idén pedig olyan korán köszöntött be a rendkívül enyhe idő, hogy a megnyitás a megszokott határidőt is jóval megelőzte. Egy vasárnap reggel <span class="marked">hat órakor</span> megnyíltak a nagy faépület pénztárai: a férfi oldalon is, a női oldalon is.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131068', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13602/13602.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A tündérkirálynő', 'https://mek.oszk.hu/13600/13602', 'be a rendkívül enyhe idő, hogy a megnyitás a megszokott határidőt is jóval megelőzte. Egy vasárnap reggel hat órakor megnyíltak a nagy faépület pénztárai: a férfi oldalon is, a női oldalon is. Mindakét pénztárnál már <span class="marked">félhat</span> tájban kezdett megjelenni a fiatalság s mikor a hatórai harangütésre pontosan felszaladtak a pénztárablakok, kacagó, kiabáló, sikoltozó tolongás kezdődött.', true, '05:30', '05:30', '05:30', 330, 330, 330, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131068', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13602/13602.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A tündérkirálynő', 'https://mek.oszk.hu/13600/13602', 'Dühösen belekavart a fakanállal egy rotyogó fazékba, aztán hozzátette: - Dejszen tudom én, hol szorítja a cipő. Ma van az utolsó nap, hogy a főispánék, meg az alispánék visszaadják a vizitet. És nem jönnek. Már <span class="marked">egy óra</span> mindjárt. Na ne itasd itt az egereket, ugorj le a földszintre és kérjél egy kis szegfűszeget Ásónétól, a mienk elfogyott. Kató megtörölte a szemét és lement a földszintre. Ahogy leért a lépcső aljára, abban a', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131068', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13602/13602.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A tündérkirálynő', 'https://mek.oszk.hu/13600/13602', 'Hetenként kétszer póló-tréninget tartottak félhéttől félnyolcig, ilyen napokon a felnőttek csak <span class="marked">félnyolckor</span> jöttek uszodába. Pali ott ült a nem úszók számára elválasztott rész partján, mert oda ilyenkor jobban sütött a nap. Mellette ült Székács. A nyolcadik osztály két első tanulója. Beszélgettek. Az osztályvizsga esélyeit', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131068', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13602/13602.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A tündérkirálynő', 'https://mek.oszk.hu/13600/13602', 'öregem. Goethe bácsi azt írta, hogy: "Ich liebe dich, was geht''s dich an?" Ne gyere ilyen öreg dolgokkal. Az egész rajongást megkontrázom. - Eh, szamár vagy. Nem értesz hozzá. - Te nem értesz hozzá, te vagy a szamár. <span class="marked">Fél nyolc</span>, gyerünk öltözni. Mentek öltözni. De Pali megvárta, míg a barátja felöltözik, ő maga kint ácsorgott még a napon a kettőjük közös kabinja előtt. Nézte a kicsiket, akik fejesre tanították egymást a kis trambulinon. Csak', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131068', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13602/13602.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A tündérkirálynő', 'https://mek.oszk.hu/13600/13602', 'a folytonos szórakozást... én itt úgy únom magamat, hogy az elmondhatatlan. Adjatok tanácsot, mivel foglaljam el magam. Mert a meghívásokat most már nem bírom, azokat sorra úgyis lemondom. Keresztrejtvényt is csak <span class="marked">egy óra</span> hosszat fejthetek, akkor beleúnok.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131068', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13602/13602.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A tündérkirálynő', 'https://mek.oszk.hu/13600/13602', 'meg is fagyott rajta a mosoly, mert a tanár tekintetében valami baljóslatút vett észre. - Mi van Palival? - Miért mi van? Tudtommal most teszi az írásbelit. - Igen ám, de megtörtént vele, ami eddig soha: elkésett. <span class="marked">Nyolckor</span> kezdtük az írásbelit kivételesen, mert rendes körülmények között hétkor kezdjük, de most az inspekciós tanárok miséit nem lehetett összeegyeztetni, egyszóval nyolckor együtt voltak az érettségizők mind, csak a te fiad hiányzott.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131068', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13602/13602.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A tündérkirálynő', 'https://mek.oszk.hu/13600/13602', 'Nyolckor kezdtük az írásbelit kivételesen, mert rendes körülmények között hétkor kezdjük, de most az inspekciós tanárok miséit nem lehetett összeegyeztetni, egyszóval <span class="marked">nyolckor</span> együtt voltak az érettségizők mind, csak a te fiad hiányzott.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131068', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13602/13602.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A tündérkirálynő', 'https://mek.oszk.hu/13600/13602', 'írásbelit kivételesen, mert rendes körülmények között hétkor kezdjük, de most az inspekciós tanárok miséit nem lehetett összeegyeztetni, egyszóval nyolckor együtt voltak az érettségizők mind, csak a te fiad hiányzott. <span class="marked">Negyed kilenc</span> után öt perccel érkezett be képéből kikelve, rendkívül izgatottan.', true, '08:15', '08:15', '08:15', 495, 495, 495, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131068', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13602/13602.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A tündérkirálynő', 'https://mek.oszk.hu/13600/13602', '- Igen, igen, de az én fiam fél nyolcra ment misére, mert az írásbelijök <span class="marked">nyolckor</span> kezdődött. A te fiadat pedig negyed kilenc tájban láttam lóhalálában kirohanni a főpostáról. - Nem tudom, mi dolga volt ott, majd meghallom tőle otthon. A dolgozata különben brilliáns, most hallottam Váraditól. Ettől', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131068', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13602/13602.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A tündérkirálynő', 'https://mek.oszk.hu/13600/13602', 'a főorvos. - Szervusz, Barna. Mi van a fiaddal? - Mi volna vele? Éppen érettségizik a te fiaddal együtt. - Igen, igen, de az én fiam fél nyolcra ment misére, mert az írásbelijök nyolckor kezdődött. A te fiadat pedig <span class="marked">negyed kilenc</span> tájban láttam lóhalálában kirohanni a főpostáról.', true, '08:15', '08:15', '08:15', 495, 495, 495, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131068', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13602/13602.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A tündérkirálynő', 'https://mek.oszk.hu/13600/13602', 'szépen, hogy min, hogyan lehet segíteni. Hát most halljuk. Mindenekelőtt mondd meg nekem, miért késtél el? A fiú habozott. Lesütötte a szemét. Vállat vont. - Tanultam a ligetben és nem néztem az órát. Mire észrevettem, <span class="marked">nyolc óra</span> volt. Már nem tudtam odaérni idejére. Az őrnagy hallgatott. De mikor nagysokára megszólalt, fátyolos volt a szeme. És a hangja küszködött valamivel. - Tudod, mi történt most, fiam? Most hazudtál nekem először', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131068', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13602/13602.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A tündérkirálynő', 'https://mek.oszk.hu/13600/13602', 'Arra kérlek, deríttesd ki nekem, haladéktalanul, hogy mit csinált a fiam a főpostán reggel <span class="marked">negyed kilenckor</span>. Nagyot nézett a postaigazgató. - Tudod te, hogy mit kérsz tőlem? Egyszerűen a hivatalos titok megsértését. De látom, milyen izgatott vagy és én tudom, mi az: izgatottnak lenni a gyerekért. Maradj itt, végy egy ujságot', true, '08:15', '08:15', '08:15', 495, 495, 495, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131068', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13602/13602.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A tündérkirálynő', 'https://mek.oszk.hu/13600/13602', 'Mély részvétet érzett a törékeny, esendő, beteges öreg iránt. Egyetlen fia meghalt orosz fogságban. Jó negyedóra alatt mindent kinyomozott Rehák és már jött is vissza az eredménnyel. - Mindent tudok. A fiad ma reggel <span class="marked">fél nyolckor</span> megjelent a telefónnál és kapcsolást kért a budapesti Dunapalotával.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131068', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13602/13602.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A tündérkirálynő', 'https://mek.oszk.hu/13600/13602', 'Rehák és már jött is vissza az eredménnyel. - Mindent tudok. A fiad ma reggel fél nyolckor megjelent a telefónnál és kapcsolást kért a budapesti Dunapalotával. Véletlenül erős volt a forgalom és soká kapta a számot. <span class="marked">Nyolc óra</span> előtt öt perccel dringend kérte a számot.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131068', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13602/13602.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A tündérkirálynő', 'https://mek.oszk.hu/13600/13602', 'budapesti Dunapalotával. Véletlenül erős volt a forgalom és soká kapta a számot. Nyolc óra előtt öt perccel dringend kérte a számot. Éliásné nevű kezelőnőnk, aki látásból ismeri a gyereket, kihallgatta a beszélgetést. <span class="marked">Nyolc óra</span> után tíz perccel kapta meg a gyerek a számot.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131068', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13602/13602.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('A tündérkirálynő', 'https://mek.oszk.hu/13600/13602', 'pillanat mulva érezte, hogy ez jót tett neki. Kevésbbé ideges volt. Gondolatai megkönnyebbedtek. Kért még egy dupla törkölyt. Még valaki másnak is gusztusa támadt a törkölyre. Az egészből általános pálinkázás lett. <span class="marked">Tizenegy órakor</span> Szepezdy őrnagy elrikkantotta magát: - Egy üveg pezsgőt ide, hé!', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131068', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13602/13602.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Harmatos rózsa', 'https://mek.oszk.hu/05200/05261', 'ki - a messzelátóval. Mosolygott magán. Fölállította a távcsövet. A Lázár-portán még minden csöndes volt. Lassan teltek az órák, már hat, hét óra, még mindig üres a kapitányék udvara. Végre megjelennek a cselédek. <span class="marked">Fél nyolckor</span> félig öltözötten kiszaladnak a gyerekek, erővel kell őket becipelni, utánuk a nagy leány, a kapitány leánya is kijön.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-7804', 'Móricz Zsigmond', 'novel', 'https://mek.oszk.hu/05200/05261/05261.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Harmatos rózsa', 'https://mek.oszk.hu/05200/05261', 'háta közepéig. Zsolt megremeg, ha ő is kijön! Biztosra veszi, hogy ő nem így lép ki. Azt a szépséges, tökéletes jelenségét nem tudja semmiféle lazasággal elképzelni, csak teljes toalettben és harmonikus lélekkel. Végre <span class="marked">nyolc óra</span> tájban összegyűlnek a lugasban reggelizni.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-7804', 'Móricz Zsigmond', 'novel', 'https://mek.oszk.hu/05200/05261/05261.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Harmatos rózsa', 'https://mek.oszk.hu/05200/05261', 'sugaráért. S büs zke volna rá, ha ezt a keresztet holtig kellene viselnie. Úgy tetszenék neki, nem halhat már meg boldogtalanul, úgy rémlenék, joggal vezekel a boldogságért. És mindezt az erős délelőtti napsütésben. <span class="marked">Tizenegy órakor</span> reggelihez hívták, és ő meglepetve vette é szre, hogy minden bánata és ijedtsége mellett hatalmas étvágya volt.', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-7804', 'Móricz Zsigmond', 'novel', 'https://mek.oszk.hu/05200/05261/05261.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Harmatos rózsa', 'https://mek.oszk.hu/05200/05261', 'Ittas szemekkel, megértés nélkül bámult Sarudynéra, aki megcsókolgatta a bravúrosan dolgozó kis zongorásfiút, s négykézzel magyarázta, hogy őneki mára elég volt, mert az urának reggel <span class="marked">fél nyolckor</span> át kell venni a postát... Vége volt a mulatságnak, mindenki észrevette, hogy reggel van, világos van, megvirradt. Zsolt úgy érezte magát, mintha a vízár kivetette volna a partra, s most kedvetlenül hever a sárban, míg', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-7804', 'Móricz Zsigmond', 'novel', 'https://mek.oszk.hu/05200/05261/05261.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Harmatos rózsa', 'https://mek.oszk.hu/05200/05261', 'Mert nincs kétség benne, hogy Jenőne k minden sikerül, hogy nagy tehetség, s hogy <span class="marked">egykor</span> az ország élén fog állani, és hogy sohasem lesz egy pillanata életében, amit ne vele, érte éljen!', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-7804', 'Móricz Zsigmond', 'novel', 'https://mek.oszk.hu/05200/05261/05261.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Harmatos rózsa', 'https://mek.oszk.hu/05200/05261', 'Így bizony! Zsolt mintha tollal kaparnák a szívét; úgy bánnak a nagy komoly emberrel, mint a gyermekkel, és az hagyja! Mindnyájan átmentek a másik szobába, s a beteg behunyta a szemét. - Hány óra? - Egy. - Még <span class="marked">egy óra</span>... jön a tanár. - Gyulának még nem mertük megmondani, hogy tanárt hívattunk Pestről. Nem akarta engedni, mert igen drága, s nincs pénze... Zsoltnak megrándult a szeme. - De az ember mindent meg kell hogy tegyen: mert', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-7804', 'Móricz Zsigmond', 'novel', 'https://mek.oszk.hu/05200/05261/05261.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Csak azért is', 'https://mek.oszk.hu/13600/13679', 'együtt jár, hogy a vágy, amely valami gyönyörűség felé viszi őket, erősebb, mint ők maguk. Nem ők tudnak ilyenkor csökönyös ellentállást kifejteni, hanem a sóvárgás, amely legyőzhetetlenül viszi őket valamerre. Ödön <span class="marked">hat órakor</span> befogatott. Mikor a homokfutó előállott, csak úgy kutyafuttában köszönt vendégének, gyorsan és felületesen ment be megcsókolni a kisgyereket és köszönni feleségének. Látszott rajta, hogy ezen a kellemetlen percen', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131261', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13679/13679.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Csak azért is', 'https://mek.oszk.hu/13600/13679', 'a sturmra. Még velem is kezet fogott, én mondtam neki: jóéjszakát, kapitány uram, ő mondta nekem: szervusz, Géza fiam. Aztán már csak akkor láttam, mikor visszahozták. - Még élt? - Nem. Azonnal meghalt. Reggel <span class="marked">hatkor</span> ment rohamra és mindjárt el is esett.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131261', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13679/13679.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Csak azért is', 'https://mek.oszk.hu/13600/13679', 'hogy nem tanulhattak tőle semmit, de másnap reggel már érezték a hiányát. Reggel hét és nyolc között - mert hétkor mindennap pontosan nyitottak - az iskolába menő gyerekek nagy forgalmában azt sem tudták, hol a fejük. <span class="marked">Negyed kilenckor</span> mind a ketten lerogytak egy-egy székre, de onnan is minduntalan fel kellett állni, mert akkor következtek a hivatalba menők, később pedig a délelőtti vásárlást végző szakácsnék vagy háziasszonyok.', true, '08:15', '08:15', '08:15', 495, 495, 495, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131261', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13679/13679.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Csak azért is', 'https://mek.oszk.hu/13600/13679', 'Ottilia áll. el. tanítónő. - A Bándy Antal lánya! - kiáltott fel Etelka. Az idegen hölgy ugyancsak meglepetve meredt a papírkereskedőnére. - Az vagyok. Honnan tetszik ismerni? Etelka megmondta, hogy kicsoda. Ebből <span class="marked">egy óra</span> hosszat tartó megbeszélés következett.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131261', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13679/13679.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Csak azért is', 'https://mek.oszk.hu/13600/13679', 'osztálytársának rendszeresen, rendes trafikáron, maga pedig bátyjával együtt sokkal olcsóbb cigarettát szívott. Így is sikerült egy kis mellékjövedelemre szert tenni. Lassanként kialakult a megnépesedett család élete. <span class="marked">Hatkor</span> keltek, hétkor már nyitották az üzletet.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131261', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13679/13679.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Csak azért is', 'https://mek.oszk.hu/13600/13679', 'sokkal olcsóbb cigarettát szívott. Így is sikerült egy kis mellékjövedelemre szert tenni. Lassanként kialakult a megnépesedett család élete. Hatkor keltek, hétkor már nyitották az üzletet. Az előbbi tulajdonos csak <span class="marked">félnyolckor</span> nyitott, ők hétkor. A haditervet minden napra már előző este megbeszélték: hova kell menni tárgyalni, vásárolni, információt keresni, ki megy ide, ki megy oda, ki marad az üzletben és meddig, ki főz és mit. Kettőtájban', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131261', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13679/13679.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Csak azért is', 'https://mek.oszk.hu/13600/13679', 'Ha kilesték, hogy egy nevelőnő, aki kisgyereket sétáltatott, véletlenül betért a szomszédüzletbe és ott játékot vett, <span class="marked">egy óra</span> hosszat tárgyalták az eseményt.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131261', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13679/13679.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Csak azért is', 'https://mek.oszk.hu/13600/13679', 'hát gondolom, benézek. Nagyságos asszony tudja, hogy ma milyen nap van. - Hogyne tudnám. Hanauer úr ismer engem: a pénzt még ma meg fogja kapni. - Na igen, hodne. Csak mondom. És hány órakor lesz meg az a pénz? Mert én <span class="marked">egy óra</span> mulva visszajövök. Azt is akarom még önök figyelmeztetni, hogy doktor Lórántnak ne tessék a kezibe pénzet adni. Doktor Lóránt volt a Hanauer ügyvédje és egyszersmind házgondnoka. - Nem szoktunk mi Lóránttal ilyesmit', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131261', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13679/13679.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Csak azért is', 'https://mek.oszk.hu/13600/13679', '- Nagyon helyes. Hát csak mondom, hogy doktor Lóránt én ma reggel kidobtam. Már nem házgondnok. Szabálytalanságok csinált. Többrendbeli szabálytalanságok. Micsoda idők vannak máma, az egész világtól elment az esze. Hát <span class="marked">egy óra</span> mulva benézek, de ha még nincs meg a pénz, ráér délután, egész délután itthon leszek Lilike lányommal.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131261', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13679/13679.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Csak azért is', 'https://mek.oszk.hu/13600/13679', 'hogy önnél megürült a házgondnoki állás, de én nem vagyok erre jó jelölt. Én nagyon drága ember vagyok. Hanauer jóízűen nevetett. Tetszett neki a felelet. - Das ist ein verfluchter Kerl. Maga csak nézze be hozzám <span class="marked">hat órakor</span>, majd mindenféle dolgok beszélgetünk.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131261', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13679/13679.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Csak azért is', 'https://mek.oszk.hu/13600/13679', 'Délután ötkor beszéltem a rádiósokkal, a legszebben ment a dolog, úgy volt, hogy <span class="marked">fél nyolckor</span> egész biztosan megkapom a pénzt.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131261', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13679/13679.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Csak azért is', 'https://mek.oszk.hu/13600/13679', 'Gondoltam, elhozom ide a pénzt <span class="marked">nyolckor</span>, aztán elmegyek az estélyre és örömömbe még le is iszom magamat francia pezsgővel.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131261', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13679/13679.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Csak azért is', 'https://mek.oszk.hu/13600/13679', 'a legszebben ment a dolog, úgy volt, hogy fél nyolckor egész biztosan megkapom a pénzt. Gondoltam, elhozom ide a pénzt nyolckor, aztán elmegyek az estélyre és örömömbe még le is iszom magamat francia pezsgővel. <span class="marked">Fél nyolckor</span> megint találkoztunk. Technikai akadályok. Azt hittem, ott rögtön meghalok. Holnap meglesz a pénz. Ez a borzasztó. Ez a huszonnégy óra különbség. Egy családnak az egzisztenciája múlik rajta. Én azt jól tudom.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131261', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13679/13679.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Csak azért is', 'https://mek.oszk.hu/13600/13679', 'Megigérte, hogy holnap reggel már <span class="marked">nyolckor</span> benéz. És elment. Miklós az est folyamán nem is jelentkezett többé. Nyilván holtbiztosra vette az Örs segítségét, elment arra a bizonyos estélyre. És örömében bizonyára ivott egy nagyot, ahogy előre kitervelte. A nők', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131261', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13679/13679.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Csak azért is', 'https://mek.oszk.hu/13600/13679', 'elvesztik. Másnap reggel nehéz szívvel láttak neki a munkának. Az órát nézték. Ha a kis mutató a tizre ér, vége lesz mindennek, a bolt nem lesz az övék többé. Csak jönne legalább az a Borbás. Jött is az pontosan. <span class="marked">Nyolckor</span>, ahogy igérte. Nem sokat teketóriázott. Letett Etelka elé egy négyezer pengős csekket. - Honnan vetted ezt a pénzt? - kérdezte Etelka elképedve. - Sehonnan. Volt nekem. Igen takarékosan élek. Van még nekem több is. Ezt', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131261', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13679/13679.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Csak azért is', 'https://mek.oszk.hu/13600/13679', 'Csak halkan beszélgethettek, mert bár az iskolásgyerekek serege a <span class="marked">nyolc óra</span> elteltével már elmaradt, vevő azért bőven jött-ment az üzletben.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-131261', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/13600/13679/13679.htm', 'deep_extract', false);
