INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Nevető Dekameron', 'https://mek.oszk.hu/08100/08196', 'a már elkészült jóféle túróstésztát villával és késsel szépen beleraktam a tányérba. Összeragasztottam a hússzeleteket, ami nagyon jó volt. Miután a levest is kikanalaztam a szájamból, felálltam és megnéztem az órámat. <span class="marked">Félegy</span> volt, tizenkettőre a hivatalban kellett lennem, gyorsan kihátráltam a szobából.', true, '00:30', '00:30', '00:30', 30, 30, 30, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-75449', 'Karinthy Frigyes', 'humorous sketches', 'https://mek.oszk.hu/08100/08196/08196.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Nevető Dekameron', 'https://mek.oszk.hu/08100/08196', 'Készíttessen bölcsőt, doktor úr, - mondta. - Azt hiszem, szükség lesz rá. - Igen, - mondta az orvos és áttelefonált a D-osztályba, van-e ott hely, át kell majd szállíttatnia valakit innen a C-osztályból. IX. Egy reggel <span class="marked">hatkor</span> ébredt az orvos és ásítva eszébe jutott, hogy az almafán valószínűleg lesz már ehető gyümölcs, lemegy és megnézi.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-75449', 'Karinthy Frigyes', 'humorous sketches', 'https://mek.oszk.hu/08100/08196/08196.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Nevető Dekameron', 'https://mek.oszk.hu/08100/08196', 'lángja: a hatalmas és halált megvető, dicső francia katonák újra fényesre mosták lobogónkat vérben és könnyben, de tisztára mosták! Ünnepeljünk; a francia nemzet nek nagy ünnepe van! M. Intrépide tábornok ma este <span class="marked">hat órakor</span> tönkre tette Irksome összevont csapatait s ezzel az angolok egész hadművelete meghiusult.', true, '18:00', '18:00', '18:00', 1080, 1080, 1080, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-75449', 'Karinthy Frigyes', 'humorous sketches', 'https://mek.oszk.hu/08100/08196/08196.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Nevető Dekameron', 'https://mek.oszk.hu/08100/08196', 'Még nem győzött egyik fél se. Hadat üzentek: Amerika, Spanyolország, Norvégia, Dánia, Svájc, Uruguai. Az irányzat lanyha. Diplomáciai viszonyt szakítottak: Belgium, Ar kanzas, Madagaszkar, Kína, Elő-India. Nap kél: <span class="marked">6 óra 25 perc</span>. Elpusztultak: Szerbia, Montenegró, Alaska. A Múzeum egész nap zárva. TÁRCA --- Egy élet Írta: S. K. A tudós asszony mosolyogva jött ki a másik szobába. - Fiú! - mondta vidáman. Kurta Pál felsóhajtott. - Hálaistennek!', true, '06:25', '06:25', '06:25', 385, 385, 385, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-75449', 'Karinthy Frigyes', 'humorous sketches', 'https://mek.oszk.hu/08100/08196/08196.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Nevető Dekameron', 'https://mek.oszk.hu/08100/08196', 'meg van írva. Csakhogy meg van írva, most alhatom legalább még egy kicsit. De milyen jó így. Féltízkor szólt a vekker, szóval azóta elment harminckét perc és a Földközi tenger, az összesen negyvennyolc. Szóval úgy <span class="marked">féltizenegy</span> lehet, akkor már szedik is a krokit, mindjárt elmegyek ebédelni, aztán.', true, '10:30', '10:30', '10:30', 630, 630, 630, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-75449', 'Karinthy Frigyes', 'humorous sketches', 'https://mek.oszk.hu/08100/08196/08196.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Nevető Dekameron', 'https://mek.oszk.hu/08100/08196', 'mindjárt elmegyek ebédelni, aztán. Most maradok még négy percig az ágyban, aztán mégis megírom. Aoaoiá-o-á-ó! Volt ez négy perc? Persze, kelj már föl, te disznó. Takarítóné! Hány óra van! Mit beszél? Megbolondult? <span class="marked">Háromnegyed hat</span>? Reggel? Mi-i...i? Este háromnegyed hat? Hát miért igazította be a vekkert, maga romlott, perverz nő? Akkor vége mindennek. Akkor már föl se kelek ma. Jóéjszakát. NEVELÉS Ne lármázz, Pistike, hagyj olvasni, ülj le', true, '05:45', '05:45', '05:45', 345, 345, 345, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-75449', 'Karinthy Frigyes', 'humorous sketches', 'https://mek.oszk.hu/08100/08196/08196.htm', 'deep_extract', false);
