INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Nevető Dekameron', 'https://mek.oszk.hu/08100/08196', '- Édes kutyusom, - epedte a hang - ma este <span class="marked">kilenckor</span> várlak. Az öreg csak tizenegykor jön haza. Eljössz? Hm. Elmenjek? Szegény öreg, aki csak tizenegykor jön haza! Nekem az öreg határozottan szimpatikusabb, mint a kutyus. - Nem megyek - mondtam határozottan. - Miért? -', true, '21:00', '21:00', '21:00', 1260, 1260, 1260, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-75449', 'Karinthy Frigyes', 'humorous sketches', 'https://mek.oszk.hu/08100/08196/08196.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Nevető Dekameron', 'https://mek.oszk.hu/08100/08196', 'vagyok, tegye le a kagylót? Hát nem sokkal egyszerűbb, ha én vagyok a kutyus? Hátha akkor hamarabb leteszi. - Igen, én vagyok - epedtem vissza. - Édes kutyusom, - epedte a hang - ma este kilenckor várlak. Az öreg csak <span class="marked">tizenegykor</span> jön haza. Eljössz? Hm. Elmenjek? Szegény öreg, aki csak tizenegykor jön haza! Nekem az öreg határozottan szimpatikusabb, mint a kutyus. - Nem megyek - mondtam határozottan. - Miért? - Azért, mert megúntalak, kérlek', true, '23:00', '23:00', '23:00', 1380, 1380, 1380, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-75449', 'Karinthy Frigyes', 'humorous sketches', 'https://mek.oszk.hu/08100/08196/08196.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Nevető Dekameron', 'https://mek.oszk.hu/08100/08196', 'a kutyus? Hátha akkor hamarabb leteszi. - Igen, én vagyok - epedtem vissza. - Édes kutyusom, - epedte a hang - ma este kilenckor várlak. Az öreg csak tizenegykor jön haza. Eljössz? Hm. Elmenjek? Szegény öreg, aki csak <span class="marked">tizenegykor</span> jön haza! Nekem az öreg határozottan szimpatikusabb, mint a kutyus. - Nem megyek - mondtam határozottan. - Miért? - Azért, mert megúntalak, kérlek alássan. Nagyon utálatos vagy egy kicsit, hát gondoltam, mostan éppen', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-75449', 'Karinthy Frigyes', 'humorous sketches', 'https://mek.oszk.hu/08100/08196/08196.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Nevető Dekameron', 'https://mek.oszk.hu/08100/08196', 'az egész mustárt. - A Pistit? - kérdeztem dühösen. - Dehogy. A Dávidot - zokogta nőm. Csodálkoztam, mert nőm eddig nem szólt róla, hogy Dávid nevű gyermekünk is van. De nőm már eltűnt a könyv 68. és 69. oldalai közt. <span class="marked">Egy órakor</span> jöttem haza. Nőm még ágyban volt, a fején borogatás. Két gyertya égett az asztalkán. Üveges szemekkel nézett rám. - Meghalt - mondta tompán. - Szent Isten, ki halt meg? - Steerforth - zokogta nőm és eltűnt a 238-239-ik', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-75449', 'Karinthy Frigyes', 'humorous sketches', 'https://mek.oszk.hu/08100/08196/08196.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Nevető Dekameron', 'https://mek.oszk.hu/08100/08196', 'Soha nem történt még meg, hogy <span class="marked">egy óra</span> ne jelezte volna pontosan a lejárt száz percet, ami az elítélt kivégzéséhez kell.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-75449', 'Karinthy Frigyes', 'humorous sketches', 'https://mek.oszk.hu/08100/08196/08196.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Nevető Dekameron', 'https://mek.oszk.hu/08100/08196', 'Este a szónak szoros és a szónak átvitt értelmében fel hagyja húzni magát, hogy reggel <span class="marked">fél nyolckor</span> keltse fel azt az urat, aki este lefeküdt az ágyba.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-75449', 'Karinthy Frigyes', 'humorous sketches', 'https://mek.oszk.hu/08100/08196/08196.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Nevető Dekameron', 'https://mek.oszk.hu/08100/08196', 'összetéveszti azt az emb ert, aki lefekszik, azzal, aki felkel. Este a szónak szoros és a szónak átvitt értelmében fel hagyja húzni magát, hogy reggel fél nyolckor keltse fel azt az urat, aki este lefeküdt az ágyba. <span class="marked">Fél nyolckor</span> aztán csodálkozik, hogy ugyanaz az ember, aki este megbízta, hogy feltétlenül keltse fel, dühösen a falhoz vágja és pofonveri és belelő, mikor fontoskodva és abban a reményben, hogy most majd meg fogják őt dícsérni, beleordít a fülébe.', true, '19:30', '19:30', '19:30', 1170, 1170, 1170, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-75449', 'Karinthy Frigyes', 'humorous sketches', 'https://mek.oszk.hu/08100/08196/08196.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Nevető Dekameron', 'https://mek.oszk.hu/08100/08196', 'IDEGES ÚR ELALSZIK Ideges úr egy kissé ideges és szórakozott megint, <span class="marked">tizenegy órakor</span> este tehát elhatározza, hogy most hazamegy és lefekszik, miután reggel hétkor kell felébredni, amiatt az izé, amiatt a dolog miatt, na, mi is az.', true, '23:00', '23:00', '23:00', 1380, 1380, 1380, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-75449', 'Karinthy Frigyes', 'humorous sketches', 'https://mek.oszk.hu/08100/08196/08196.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Nevető Dekameron', 'https://mek.oszk.hu/08100/08196', 'megoldásra: a fe jét, lefelé fordítva, az ágy közepére teszi, két lábát két ellenkező irányba, balkarját két szétzilált matrác közt lenyujtja a földre, a jobbjával pedig az odahúzott asztallábba kapaszkodik. Reggel <span class="marked">hatkor</span> jön rá, hogy elfelejtette behúnyni a szemét, azért nem tudott elaludni.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-75449', 'Karinthy Frigyes', 'humorous sketches', 'https://mek.oszk.hu/08100/08196/08196.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Nevető Dekameron', 'https://mek.oszk.hu/08100/08196', 'gondold meg. Elmondom neked röviden és határozottan, hogy én hogyan élek mostanában... Nem is, nem így mondom el. Hanem elmondom neked például egy napomat, ahogyan mostanában csinálom. Hát először is. Felkelés: reggel <span class="marked">nyolckor</span>. Kiugrás az ágyból. Mosdás: friss tiszta vízben. Öltözködés. Kávéház: nincs többé. Az utcámban van egy kis kávémérés: kávémérésben szerény reggeli. Szerény, de egészséges, egyszerű reggeli, ami egyben felüdít és', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-75449', 'Karinthy Frigyes', 'humorous sketches', 'https://mek.oszk.hu/08100/08196/08196.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Nevető Dekameron', 'https://mek.oszk.hu/08100/08196', 'az ágyból. Mosdás: friss tiszta vízben. Öltözködés. Kávéház: nincs többé. Az utcámban van egy kis kávémérés: kávémérésben szerény reggeli. Szerény, de egészséges, egyszerű reggeli, ami egyben felüdít és táplál. Most <span class="marked">fél kilenc</span> van. Figyelsz? - Ó, Csupa fül vagyok. - Fél kilenc van, most tehát kezdődik a munka. Írás. Igen, írás, korán délelőtt. Friss aggyal, tiszta, zavartalan képzetekkel. Ez tart egészen tizenegyig. Most otthagyom az', true, '08:30', '08:30', '08:30', 510, 510, 510, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-75449', 'Karinthy Frigyes', 'humorous sketches', 'https://mek.oszk.hu/08100/08196/08196.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Nevető Dekameron', 'https://mek.oszk.hu/08100/08196', 'Kávéház: nincs többé. Az utcámban van egy kis kávémérés: kávémérésben szerény reggeli. Szerény, de egészséges, egyszerű reggeli, ami egyben felüdít és táplál. Most fél kilenc van. Figyelsz? - Ó, Csupa fül vagyok. - <span class="marked">Fél kilenc</span> van, most tehát kezdődik a munka.', true, '08:30', '08:30', '08:30', 510, 510, 510, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-75449', 'Karinthy Frigyes', 'humorous sketches', 'https://mek.oszk.hu/08100/08196/08196.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Nevető Dekameron', 'https://mek.oszk.hu/08100/08196', 'elmélyedés alakuló könyvtáramban: erőgyüjtés a munkára, mint mikor a méhecske gyüjti a hímport. Barátom legyintett. - Hímport... Pardon, egy pillanatra. Jegyzem az előadást. - Tessék. Tehát: négytől hatig komoly munka. <span class="marked">Hatkor</span> torna, uzsonna. Hétkor séta a parkban. Nyolckor egészséges, üdítő, friss vacsora. Frugális vacsora. Utána egy kis séta, megint olvasás, aztán tíz órakor be az ágyba és tíz perc mulva alszom, azoknak az embereknek', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-75449', 'Karinthy Frigyes', 'humorous sketches', 'https://mek.oszk.hu/08100/08196/08196.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Nevető Dekameron', 'https://mek.oszk.hu/08100/08196', 'munkára, mint mikor a méhecske gyüjti a hímport. Barátom legyintett. - Hímport... Pardon, egy pillanatra. Jegyzem az előadást. - Tessék. Tehát: négytől hatig komoly munka. Hatkor torna, uzsonna. Hétkor séta a parkban. <span class="marked">Nyolckor</span> egészséges, üdítő, friss vacsora.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-75449', 'Karinthy Frigyes', 'humorous sketches', 'https://mek.oszk.hu/08100/08196/08196.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Nevető Dekameron', 'https://mek.oszk.hu/08100/08196', 'néhány ilyen mókát csinált. Végre egy kapuban véglegesen megállt. - Letzti! - mondta, hátbavágott és eltűnt. Egy ideig vártam rá, de hogy nem jött, elúntam a topogást és lassan és gondolkodva visszamentem a kávéházba. <span class="marked">Nyolckor</span> odajött értem. - Vacojázni! Vacojázni! tapsikált és elvitt egy vendéglőbe. A vendéglőben kiderült, hogy Margit úrhölgy egy kedves, vékony kis aranylánccal lett közben gazdagabb. Gyermetegen játszott az aranylánccal;', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-75449', 'Karinthy Frigyes', 'humorous sketches', 'https://mek.oszk.hu/08100/08196/08196.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Nevető Dekameron', 'https://mek.oszk.hu/08100/08196', 'Míg az ügyvéd ezt előadta, lett <span class="marked">tizenegy óra</span>. Ekkor bementünk a terembe, ahol a bíró azzal fogadott, hogy elkéstem, miután pedig tanuskodni polgári kötelesség, ötven korona pénzbírságra ítél . Ezután a vádlott kihallgatása következett. Vádlott előadta, hogy a', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-75449', 'Karinthy Frigyes', 'humorous sketches', 'https://mek.oszk.hu/08100/08196/08196.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Nevető Dekameron', 'https://mek.oszk.hu/08100/08196', '- hiszen maga kapott egy golyót a könyökébe. Várjon, majd bekötöm, semmi az egész. - De nem láttam senkit - nyöszörgött Leonidas. - Persze, hogy nem látott, - mondta Fuksz - mert azok is fedezékben vannak. Na, emelje <span class="marked">fel egy</span> kicsit a vállát, hogy a könyökét beköthessem.', true, '00:30', '00:30', '00:30', 30, 30, 30, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-75449', 'Karinthy Frigyes', 'humorous sketches', 'https://mek.oszk.hu/08100/08196/08196.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Mélység és magasság', 'https://mek.oszk.hu/11600/11692', '- Vihetsz belőle holnapra, csak körítést kell hozzá csinálnod. Adhatok még? - Na ne, pofátlan nem akarok lenni. Még eleszem a család elől. - Dehogy eszed. Legfeljebb ebből nem kerül a jégre. Na, add a tányérod. Elmúlt <span class="marked">kilenc óra</span>, amikor hazaindult. Leparkolt a ház előtt. Látta, csak Bella szobájában van világosság. Ma talán időben elaludtak a kis gézengúzok - gondolta. Első útja a szobájukba vitte. Lehangolt indulattal állapította meg, ismét', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-107999', 'V. Pócsay Rozika', 'novel', 'https://mek.oszk.hu/11600/11692/11692.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Mélység és magasság', 'https://mek.oszk.hu/11600/11692', 'egyszerűbb. - Akkor a liget Hermina úti bejáratánál lenne jó. - Melyik busszal jössz? - A hetessel vagy piros hetessel. - Akkor célszerűbb lenne a Thököly-Hungária úti megállójában. - Rendben. - Nálam öt perc múlva <span class="marked">egy óra</span>, mikor indulsz? - Hűha! Várjál csak... hátra van még egy kis frizura igazítás... mondjuk, tíz perc múlva. - Ragyogó! Fél kettő és háromnegyed között várlak! Elköszönök, nehogy miattam késs, szia! - mondta nevetve. -', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-107999', 'V. Pócsay Rozika', 'novel', 'https://mek.oszk.hu/11600/11692/11692.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Mélység és magasság', 'https://mek.oszk.hu/11600/11692', '- Reggel hétre mindig bent vagy, míg legtöbben <span class="marked">fél nyolc</span> után esnek be, és még nem hallottam, hogy kifogást emeltél volna ellene.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-107999', 'V. Pócsay Rozika', 'novel', 'https://mek.oszk.hu/11600/11692/11692.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Mélység és magasság', 'https://mek.oszk.hu/11600/11692', 'Kis cédulákat nyomtatnék ki csupa-csupa nagy, színes betűkkel: "a munkaidő kezdete hét óra harminc!!!" <span class="marked">Fél nyolc</span> előtt öt perccel körbejárnék, és a hiányzókat ezzel fogadnám, mindaddig, amíg nem értenének belőle.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-107999', 'V. Pócsay Rozika', 'novel', 'https://mek.oszk.hu/11600/11692/11692.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Mélység és magasság', 'https://mek.oszk.hu/11600/11692', 'Mindent egyre nyűgösebbnek éreztem. A kedélyállapotom egyre vacakabb lett. Ráadásul amikor csütörtökön este hívtam anyut, elkeseredetten beszélt velem, amiért három hete nem voltam otthon. Hiába magyaráztam neki, <span class="marked">egy óra</span> szabadidőm nincs, nem hogy egy hétvége, sírt, és nem tudtam megnyugtatni.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-107999', 'V. Pócsay Rozika', 'novel', 'https://mek.oszk.hu/11600/11692/11692.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Mélység és magasság', 'https://mek.oszk.hu/11600/11692', 'Reggel flottul ment minden, alig múlt el <span class="marked">negyed nyolc</span>, amikor beért. Meglepetten vette tudomásul, ő az első, neki kell nyitnia a lépcsőház ajtót. Mi történhetett a lánnyal, amióta náluk van, hétkor mindig bent van. Aggódott miatta, de nem tehetett semmit. Fél nyolckor', true, '07:15', '07:15', '07:15', 435, 435, 435, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-107999', 'V. Pócsay Rozika', 'novel', 'https://mek.oszk.hu/11600/11692/11692.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Mélység és magasság', 'https://mek.oszk.hu/11600/11692', 'el negyed nyolc, amikor beért. Meglepetten vette tudomásul, ő az első, neki kell nyitnia a lépcsőház ajtót. Mi történhetett a lánnyal, amióta náluk van, hétkor mindig bent van. Aggódott miatta, de nem tehetett semmit. <span class="marked">Fél nyolckor</span> Erika kopogott be hozzá: - Hello Viktor!', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-107999', 'V. Pócsay Rozika', 'novel', 'https://mek.oszk.hu/11600/11692/11692.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Mélység és magasság', 'https://mek.oszk.hu/11600/11692', 'FENT 1. Az utazás előtti két hetet szívesen kitöröltem volna az életemből. Viktor úgy döntött, a hátralévő két hétvégét a kicsikkel tölti. Természetesnek vettem, hiszen tíz napig nem látja majd őket. Hétfőn reggel <span class="marked">hat órakor</span> felhívott, Nielka egész éjszaka hányt, nagyon magas a láza, óránként kell vizes lepedőbe csavarnia, csak így tudja normál szinten tartani testhőmérsékletét.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-107999', 'V. Pócsay Rozika', 'novel', 'https://mek.oszk.hu/11600/11692/11692.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Mélység és magasság', 'https://mek.oszk.hu/11600/11692', 'fejtágítót. Mivel két hét múlva külföldre megy, őt keddtől iskolázták be, ami annyit jelent, ez idő alatt végig ott kell lennie. - Szóval értsem úgy, utazásig nem találkozunk - jegyeztem meg lehangoltan. - Az előadások <span class="marked">kilenckor</span> kezdődnek, a reggelekről nem mondok le.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-107999', 'V. Pócsay Rozika', 'novel', 'https://mek.oszk.hu/11600/11692/11692.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Mélység és magasság', 'https://mek.oszk.hu/11600/11692', 'tartottam. Közben elővettem a mobilom, miért nem azon hívott. Annyira lemerült a nyavalyás, hogy ki is kapcsolt. A helyemről hívtam, de az ő telefonja is ki volt kapcsolva. Többször próbálkoztam, hiába. Másnap reggel <span class="marked">hatkor</span> csengettek. Mivel nem néztem ki, folyamatosan nyomta az illető a gombot. Összekapkodtam a holmijaimat, és indultam át Ági néniékhez, amikor megszólalt a mobilomon a Török induló. - Szia Vikó! - szóltam bele izgatottan.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-107999', 'V. Pócsay Rozika', 'novel', 'https://mek.oszk.hu/11600/11692/11692.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Mélység és magasság', 'https://mek.oszk.hu/11600/11692', 'válaszolni. Boldogan feküdtem le, még nincs minden veszve. TIZEDIK FEJEZET ROSSZ MONDATOK ROSSZKOR 1. Kora reggel furcsa mocorgásra ébredtem. Felültem, hirtelen azt sem tudtam, hol vagyok. Felkapcsoltam a kislámpát, <span class="marked">fél hat</span> volt. Kellett pár perc, mire tisztult az agyam. Ilyen vékonyak lennének a falak, így áthallatszik minden? - morfondíroztam. Viktor elköhintette magát, abból sejtettem, kint van az erkélyen. A kellemes, langyos víz', true, '05:30', '05:30', '05:30', 330, 330, 330, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-107999', 'V. Pócsay Rozika', 'novel', 'https://mek.oszk.hu/11600/11692/11692.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Mélység és magasság', 'https://mek.oszk.hu/11600/11692', 'szünet nélkül ment a duma. Négy óra elmúlt, mire megszabadultam onnan. Kerestelek, de mondták a lányok, félkor elrohantál. Kétszer hívtalak, de nem vetted fel. - Sajnos láttam, amint most elővettem a telcsit. Tudod, <span class="marked">fél hatkor</span> indult a busz, és nekem még haza kellett mennem a csomagokért.', true, '05:30', '05:30', '05:30', 330, 330, 330, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-107999', 'V. Pócsay Rozika', 'novel', 'https://mek.oszk.hu/11600/11692/11692.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Mélység és magasság', 'https://mek.oszk.hu/11600/11692', 'Jaj, atyaúristen! - kiáltotta, és abban a pillanatban megszakadt a vonal. Visszamentem a családhoz. Őrült nehéz volt jókedvet színlelni. Anyu nagyon kifáradt a készülődésben, így elég gyorsan takarodót fújt Gyuri. <span class="marked">Egy óra</span> hosszat vártam, de nem hívott Viktor.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-107999', 'V. Pócsay Rozika', 'novel', 'https://mek.oszk.hu/11600/11692/11692.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Mélység és magasság', 'https://mek.oszk.hu/11600/11692', 'Az elsőben leírta, hogy Nielka magára rántotta a karácsonyfát. Semmi baja nem lett az ijedtségen kívül, de egész éjszaka a karjában sétált vele. Amikor fáradtan ledőlt az ágyra, Danika feküdt a hasára sírva. Hajnali <span class="marked">hat órakor</span> normalizálódott a helyzet. Fél tizenegykor ébredt fel, kereste a telefonját, hogy felhívjon. A szőnyeg alatt találta meg kikapcsolva. Majd egyre elkeseredettebb, feldúltabb hangvételűek sorakoztak. Pokoli rosszul', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-107999', 'V. Pócsay Rozika', 'novel', 'https://mek.oszk.hu/11600/11692/11692.htm', 'deep_extract', false);
