INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Mélység és magasság', 'https://mek.oszk.hu/11600/11692', '- gondoltam. Munkaidő végén újból próbálkoztam, hasonló eredménnyel. Hazamentem, ledobtam a táskámat, kabátomat, ledőltem és hagytam, hadd legyen úrrá rajtam a keserűségem. Szerettem volna meghalni. Elmúlott <span class="marked">nyolc óra</span>, amikor megszólalt a Török induló.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-107999', 'V. Pócsay Rozika', 'novel', 'https://mek.oszk.hu/11600/11692/11692.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Mélység és magasság', 'https://mek.oszk.hu/11600/11692', 'a fotelhez. Lerogyott rá. Rólam tudomást sem vett, pillanatok alatt mély álomba zuhant. Próbáltam ébresztgetni, hogy feküdjön le, de meg sem mozdult. Betakartam hát, hagytam, hadd aludja ki magát. Elmúlott délelőtt <span class="marked">tizenegy óra</span>, mire magához tért. Percekig csak nézett, míg végül megszólalt: - Bocsáss meg, én kicsi egyetlenem, bocsáss meg, nagyot vétettem ellened, de esküszöm, nem tudtam, mit vállalok. Meg kéne fürdenem, napok óta nem láttam', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-107999', 'V. Pócsay Rozika', 'novel', 'https://mek.oszk.hu/11600/11692/11692.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Mélység és magasság', 'https://mek.oszk.hu/11600/11692', 'Karcsi, a főosztvez nem engedte. Nagyon féltékeny rá. - Oké. Hagyjunk valami mesélnivalót holnapra is. Aludj egy kicsit, amíg átmegyünk anyukádékhoz. 3. Amíg Viktor aludt, én olvastam. Fél hatra értünk át a szüleihez. <span class="marked">Hat órakor</span> hatalmas autó állt meg a ház előtt.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-107999', 'V. Pócsay Rozika', 'novel', 'https://mek.oszk.hu/11600/11692/11692.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Mélység és magasság', 'https://mek.oszk.hu/11600/11692', 'Vacsora után - ígéretéhez híven - az ölébe vont, és közösen olvastuk a regényemet. Igazi elismerésnek éreztem, hogy a negyedik fejezetnél alig tudtam rábeszélni, hagyjuk abba, pihenni is kéne valamicskét. Másnap <span class="marked">kilenc órakor</span> indultunk városnézésre. A Szent Márk téren (Piazza San Marco) Velence központjában kezdtünk, ami történelmi események színhelye. Három oldalról középületek határolják. A Szent Márk székesegyház (Basilica di San Marco)', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-107999', 'V. Pócsay Rozika', 'novel', 'https://mek.oszk.hu/11600/11692/11692.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Mélység és magasság', 'https://mek.oszk.hu/11600/11692', 'a hasimat, és beszélt az odaképzelt babáinkhoz. Én annyira magamba szuggeráltam, ikreink lesznek, meggyőződéssel hittem, csak úgy lehet. Napjaink eközben mind pörgősebbek, zsúfoltabbak lettek. Viktor nekem maximum <span class="marked">egy óra</span> túlmunkát engedélyezett. Sokat sétáltunk. November huszonnegyedikén reggel következett be a várva várt nagy nap, amikor megjelent a tesztlapon a babahírnök, a két vonalka. De meg ám, és nem csak sejtés szintjén, hanem', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-107999', 'V. Pócsay Rozika', 'novel', 'https://mek.oszk.hu/11600/11692/11692.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Mélység és magasság', 'https://mek.oszk.hu/11600/11692', 'Fél ötkor hívott Érd határából, hogy kereket kell cserélnie, mert belement egy nagy szögbe és defektet kapott a bal hátsó kerék, de siet haza, hogy sétálhassunk még egy jót. Ötkor hazamentem, nekiálltam vacsorát főzni. <span class="marked">Hat óra</span> elmúlt, és Viktor sehol. Kezdtem nyugtalankodni. Felhívtam, háromszor időzített le, de csak muzsikált a telefonja a világba. Felhívtam anyukáékat, rettenetesen felidegesítettem őket az aggódásommal. Apuka a mentőket', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-107999', 'V. Pócsay Rozika', 'novel', 'https://mek.oszk.hu/11600/11692/11692.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Mélység és magasság', 'https://mek.oszk.hu/11600/11692', 'A gyöngyösi rendőrségről jöttünk. Ön Ligeti Viktor neje? - Igen, én vagyok, a hölgy az anyukája, a fiú az öccse. - Bocsásson meg asszonyom, üljön le, és próbáljon meg erős lenni, rossz hírt kell közölnöm. A férjét este <span class="marked">nyolc órakor</span> tragikus baleset érte a Mátrafüred és Mátraháza közötti szerpentinen.', true, '20:00', '20:00', '20:00', 1200, 1200, 1200, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-107999', 'V. Pócsay Rozika', 'novel', 'https://mek.oszk.hu/11600/11692/11692.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Mélység és magasság', 'https://mek.oszk.hu/11600/11692', 'Anyuka válasza után felhívta a fehérvári rendőrséget, ahol elmondták, délután <span class="marked">hat óra</span> előtt kaptak bejelentést az árokparton fekvő félmezítelen férfiről, aki körül semmiféle okmányt nem találtak.', true, '18:00', '18:00', '18:00', 1080, 1080, 1080, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-107999', 'V. Pócsay Rozika', 'novel', 'https://mek.oszk.hu/11600/11692/11692.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Mélység és magasság', 'https://mek.oszk.hu/11600/11692', 'van a műtőben. HUSZONEGYEDIK FEJEZET AZ ŐRÜLET HATÁRÁN 1. Rettenetes éjszakánk volt. Beszélni egyikünknek sem volt kedve, csak sóhajtoztunk, egymásra nézni sem mertünk. Vártuk megbabonázva a telefonhívást. Reggel <span class="marked">fél nyolckor</span> szólalt meg apuka mobilja, a kórházból hívott egy női hang, aki sajnálkozva mondta, a férfi sajnos belehalt sérüléseibe.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-107999', 'V. Pócsay Rozika', 'novel', 'https://mek.oszk.hu/11600/11692/11692.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Mélység és magasság', 'https://mek.oszk.hu/11600/11692', 'megmagyarázni, nem tesznek azzal jót, ha otthon idegeskedem. Végül apuka elfogadta az érvemet. Ketten mentünk Fehérvárra. Végtelen keserűségemben azért fohászkodtam, ha meg kellett halnia, ő legyen a fehérvári férfi. <span class="marked">Kilenc óra</span> után ez a reményem is szétfoszlott.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-107999', 'V. Pócsay Rozika', 'novel', 'https://mek.oszk.hu/11600/11692/11692.htm', 'deep_extract', false);
