INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'Amikor megpihent, leporolta kötényét és hívta a fiát. Szívszorító látvány volt az öcsémet apám ölében látni. Nagyon nehezen viseltem, hogy egy lényt szeretnek mellettem. Délután lekváros kenyér volt az uzsonna. Este <span class="marked">hatkor</span> vacsora, utána lábmosás, este már nem mostunk fogat.', true, '18:00', '18:00', '18:00', 1080, 1080, 1080, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'Este meghallgattuk a rádióban az esti mesét, és <span class="marked">fél nyolckor</span> kötelezően lefeküdtünk. Már az ágyban voltam, mikor anyám imádkozni tanított. Én Istenem, jó Istenem, becsukódik már a szemem, de a ti ed nyitva atyám, amíg alszom, vigyázzál rám, vigyázz édes apukámra, anyukámra, kis', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
