INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'szűzhártyán keresztül a micsodáját. - Azt a nagyot - mondtam neki - amit én a szomszéd embernek láttam, amikor kivette a kertben pisilés közben? Most már meg kell figyelni, vajon az én szüleim is basznak? Minden este <span class="marked">fél nyolckor</span> feküdtem le az öcsémmel, és mikor a szüleim megérkeztek, én addigra mindig aludtam.', true, '19:30', '19:30', '19:30', 1170, 1170, 1170, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
