INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'PLESO: Ez jó lenne, de az embereink Brnikon csak <span class="marked">23.15</span>-ig dolgoznak. Várunk természetesen, de siessenek! "ARÉNA": Köszönjük! A riporterek 20 percet késtek a sűrű köd miatt. Azonnal keresik a kapcsolatot a repülőtérrel Brnikben. Mariján Kajfes jelentkezik, a repülő tíz perc', true, '23:15', '23:15', '23:15', 1395, 1395, 1395, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'vannak Brnik felé. Újra hívjuk a repülőteret Brnikben. Milyen helyzetben van a repülőgép? Éppen leszállásra készülődik - válaszol röviden Mariján Kajfes. Három perccel később jelentkezik az első pilóta, Csamer Vagner. <span class="marked">Egy óra</span> húsz percet repültünk, jó időjárási viszonyaink voltak.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'egy autót, amely ik érkezéskor átviszi a gyógyszert Zágrábba. Az Aréna riporterei időben érkeztek, hogy átvegyék a gyógyszert a német kollégáktól. A Bildcajtung és az Abendcajtung újság munkatárasai Brnikig kísérték. <span class="marked">23.33</span> h : München felé felszállt a repülő a német újság t udósítóival.', true, '23:33', '23:33', '23:33', 1413, 1413, 1413, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'riporterei időben érkeztek, hogy átvegyék a gyógyszert a német kollégáktól. A Bildcajtung és az Abendcajtung újság munkatárasai Brnikig kísérték. 23.33 h : München felé felszállt a repülő a német újság t udósítóival. <span class="marked">00.07</span> h: Kaptuk a jelentést, hogy a Pleso reptérről a tudósítókat szállító külön repülő átrepült a jugoszláv-ausztriai határon.', true, '00:07', '00:07', '00:07', 7, 7, 7, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'Attól kezdve nappal húsz percet aludt a lányom, éjjel már <span class="marked">egykor</span> ébren volt. Ha égett a villany és játékot adtam neki, akkor játszott és hallgatott, de különben üvöltött. Cumit adtam neki, amit el is fogadott. Napközben egyedül nem lehetett hagyni a szobában, mert azt igényelte,', true, '13:00', '13:00', '13:00', 780, 780, 780, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'Egyszer sétáltunk, és örömmel fedezett <span class="marked">fel egy</span> házszámot. - Ott a hatos! - mutat ta. Egyéves múlt Emese, tavaszodott már, amikor járni kezdett. Az első lépéseit nem hozzánk, felénk tette, hanem távolodott, és azt mondta: ögyedül. Szafárizöld anyagot vettem, és', true, '00:30', '00:30', '00:30', 30, 30, 30, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'meghal valaki. Ugyan ki halna meg? - gondoltam. Nincs is beteg a családban, és különben sem vagyok babonás. A következő csütörtökön nyolc hónap terhességgel szülési fájdalmak jelentkeztek. Még délután varrtam, este <span class="marked">nyolckor</span> már a gyerekeimet se tudtam megfürdetni, csak tűrtem a fájdalmat, és a férjemet vártam haza, mint Csocsoszán és milliónyi asszony a Földön.', true, '20:00', '20:00', '20:00', 1200, 1200, 1200, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'Útközben mondtam az Imrének, hogy közeledik <span class="marked">kilenc óra</span>, az én időm. Beértünk a kórházba, a szülőasztalra feküdtem, és máris megkezdődött a kitoló szak. Negyedóra múlva pont kilenckor farfekvéssel megszültem a fiam. Kórházi csend volt. Miért nem sír a gyerekem? A magyar', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'nem is tudtam, mi lesz a gyerekeimmel. Útközben mondtam az Imrének, hogy közeledik kilenc óra, az én időm. Beértünk a kórházba, a szülőasztalra feküdtem, és máris megkezdődött a kitoló szak. Negyedóra múlva pont <span class="marked">kilenckor</span> farfekvéssel megszültem a fiam.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'Esténként tévét néztek a gyerekek, de Miska <span class="marked">fél kilenckor</span> zavarta Lehelt aludni, akkor is, ha öt perc volt a film végéig.', true, '08:30', '08:30', '08:30', 510, 510, 510, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
