INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'fizikai munkás és takarítónő is. Itt egyedül t akarítottam, a piszkos vizet az udvarra kellett vinni, még a vécébe se önthettem. Azt hittem, útközben meghalok, annyira kifáradtam, hisz szünet nélkül dolgoztam. Este <span class="marked">fél kilenckor</span> közeledtem az Imre utca felé, majdnem két órával több idő elment a munkára , utazásra, mint otthon.', true, '20:30', '20:30', '20:30', 1230, 1230, 1230, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
