INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'könnyebb a munka, este hatig vagyok, és még színházba is mehetek. Szőregen két váltásban kellene dolgozni, az első műszak hajnali fél hatkor kezdődik, négykor kellene kelni, és délután kettőkor érnék haza. Petőházán <span class="marked">hatkor</span> keltem, és déli egy óráig dolgoztam, a másik műszak meg egytől nyolcig tartott, és öt perc alatt otthon voltam.', true, '18:00', '18:00', '18:00', 1080, 1080, 1080, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'Már azt hittem, lerohad a lábam, amikor <span class="marked">hatkor</span> jött a főnöknő, és újra leltároztunk, hogy megvan-e minden.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'mint te - mondta. Mi lyen igaza van, na végre, eszébe jutott. Múltkor azt mondta, sokáig nem lesz szeretkezés, mert számára nagyon fárasztó volt. Néhány otthon töltött nap után újra Magyarországra utaztam. A vonat <span class="marked">egy óra</span> késéssel indult Petőházáról. Sok csomaggal érkeztem Szegedre, de örültem, hogy sikerült átmenteni az italokat. Az Imre utcai ház előtt, ahogy a zsebemben kotorásztam, először az otthoni kulcs került a kezembe, aztán a', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'Ha elülnek a galambok, eljön kilőni őket, mert Margit néninek ártanak. Mikor lesz már este? Csak ne jöjjön közbe semmi, arra gondoltam, és beleremegtem a vágyba. Csak az fájt, miért kell a galambnak elpusztulni? <span class="marked">Fél nyolckor</span> már tudtam, éln i fognak a galambok, mert nem jött Laci.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'ekem is vacakolt a szívem, én meg az infarktustól féltem. Amikor egyedül maradtam, tévét se nézhettem, mert Attila elrejtette a tévé irányítóját. Lajos bácsi ajtajára egy cédulát írtam, azonnal jöjjön át a szomszédba. <span class="marked">Kilenckor</span> ért haza, nagyon mérges volt, de elhozta a saját távirányítóját, és közösen néztük a tévét, mert szerinte az nekem jár.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'Majd bevittük az utcáról a kenyeret, a tejet, és <span class="marked">fél hatkor</span> nyitottunk. A boltban először ismerkedtem az áruval, majd elvesztem, olyan nagy a bőség. Aztán beálltam a pult mögé, és szolgáltam a vevőket, sajtot mértem, felvágottat szeleteltem, melyek szépek, jó illatúak. Én csak', true, '05:30', '05:30', '05:30', 330, 330, 330, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'a tejes hűtőt, hogy este még többet kelljen kipakolni, mert minden este ki kel l mosni. Azonkívül a kenyérpolcot is le kell mosni, aztán a zsemletartót, utána a boltot felsöpörni és felmosni. Ez nekem zárás után még <span class="marked">egy óra</span>, mert Ildi hazamegy. Míg én dolgozom, a tulajdonos a pénzt számolja, és csokit eszeget. Esténként lihegve a fáradtságtól érkeztem a buszmegállóhoz, ha lenne kivel beszélni, akkor se lenne kedvem. A buszokat nem fűtik,', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'mondta Ella, majd hétfőn szó l, kire esik a választása, mert biztos lesz még több jelentkező. Másnap kora hajnalban ébredtem, de nem volt kedvem felkelni. Gondoltam, majd utazom a későbbi vonattal, és visszaaludtam. <span class="marked">Kilenckor</span> szólt Margit néni, keres valaki telefonon.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'jár enni. Valószínűleg azt a hangot szokta meg, állítólag képes egész a másik utcába is elmenni. Ferihez mentem, éppen füstölőt csinált. Azonnal vitatkozni kezdett. - Hol voltál ilyen sokáig? Miért nem adtál <span class="marked">fel egy</span> lapot? Ott a telefon - miért nem hívtál, ha aggódsz értem? Már arra gondoltam, hogy a jeges úton elcsúsztál, mert te olyan vagy. Aztán az is eszébe jutott, biztos találtam valakit. Érdekes, arra nem gondolt, hogy', true, '00:30', '00:30', '00:30', 30, 30, 30, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'külvilágtól. Lenke Szegeden találkozik a fiával, és bejött engem is meglátogatni. - Szép a munkahelyed - mondta. Aztán arról beszélt, hogy élnek Jugoszláviában. Két-három órát várakoznak pénzükért a bankban. Esetenként <span class="marked">egy óra</span> alatt elfogy a dinár, de az emberek még remélnek és várakoznak, mert van olyan nap, hogy kétszer is hoznak pénzt.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'Ez nem puszi, hanem csók - mondtam neki. Hát akkor csók! Nagyon akart csókolózni, de én nem akartam, mert nős ember, pedig de jó a csókja! Amikor egyedül maradtam, azt hittem, megzavarodok, annyira kívántam őt. Éjjel <span class="marked">egykor</span> már ébren voltam, mert fájt a fogam, gyógyszert vettem be, és aztán visszaaludtam.', true, '13:00', '13:00', '13:00', 780, 780, 780, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'mondta, ké t-három perc múlva újra van merevedése, ekkor valaki kopogott az ablakon. Most mit csinálunk - kérdezte? Semmit. Többszöri kopogás után autóajtó csapódása hallatszott, aztán csend. Árkosz búcsúzott, kedden <span class="marked">kilenckor</span> itt lesz, és megyünk moziba. Ha nem tud jönni, akkor csütörtökön találkozunk. Elkísérlek, mondtam neki. Kezünket fogva mentünk a buszhoz, akkor már nagyon szenvedtem. A kútnál megmosta a kezét, mert az illatomat nem', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'még nem volt bent. Később meg nem lehet hívni, mert tíz után a telefont kikapcsolják. Átköltözésem után az első március tizenötödikét alig vártam. A Klauzál téren, a Kossuth szobornál volt a központi ünnepség. Már <span class="marked">tizenegykor</span> ott álltam, és vártam az ünnepséget.', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'Tíz óra tizenöt perckor még Pesten volt Göncz Árpád, aztán helikopterrel érkezett Szegedre <span class="marked">tizenegy óra harminc perckor</span>. Huszonhárom fok volt akkor Szegeden, a hűvösbe húzódtam, nekitámaszkodtam a korlátna k, és átadtam magam a boldog ünneplésnek. Egy évvel azelőtt apám ravatalánál álltam dermedten. Azóta ott hagytam a szülőföldemet és', true, '11:30', '11:30', '11:30', 690, 690, 690, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'között. Micsoda különös illata van a bőrének. Engem még férfi ennyire nem kívánt. Gyere, Árkosz! Gyere, hisz remegek érted. Remélem, estére találkozunk, mozi ba megyünk és szeretkezünk. Délután aludtam és olvastam. Már <span class="marked">nyolckor</span> Árkosz kopogott az ablakon, sikerült korábban eljönnie, így több időt tölthetünk együtt.', true, '20:00', '20:00', '20:00', 1200, 1200, 1200, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'Egyszer Szilveszter napján reggel <span class="marked">fél hatkor</span> láttam Jocit, alig cipelte a sok kenyeret.', true, '05:30', '05:30', '05:30', 330, 330, 330, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'hisz úgy tudja, dolgozom. Kiszaladtam az utcára, és megálltam a sarkon. Árkosz, gyere! - mondogattam magamban, ekkor nem tudott tovább menni, megállt talán ötven méterre tőlem, megfordult, és indult felém. Volt <span class="marked">egy óra</span> szab adideje, és ment sétálni.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'élni. A saját házamban nem volt ennyi szép élményem. Szabadnapom estéjén olyan türelmetlen voltam, hogy nem tudtam olvasni, állandóan Árkoszt vártam. Már zenét se hallgattam, csak ültem csendben, és a kopogását vártam. <span class="marked">Fél nyolckor</span> telefonáltam. Jössz? Jövök! Várlak! Szerbusz. Már kimentem az utcára várni, amikor a félhomályban megláttam sziluettjét, majd kibontakozó valóságos alakját. Valamikor így vártam gyerekeimet az utcán, és amikor a', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'Lehel már néhány napja kint tartózkodott a tanyán, amikor Ica váratlanul kiment hozzá. Amikor Lehel meglátta őt, kiabált, és csomagolni kezdett. Aztán Ica jött el. Ennyire kapaszkodni valaki után n em szabad. Reggel <span class="marked">nyolckor</span> 170/110 volt a vérnyomásom. Kaptam gyógyszert és az orvos egy hét múlva ellenőrzésre rendelt vissza. Egy ruházati boltban sok alkalom van az eladóknak egymással beszélgetni. Egész nap Ibolya elkeseredett panaszát', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'Árkosz érkezett. Hiányoztam? - kérdezte. Mindig türelmetlenül várlak, és nagyon hiányzol! Ő jelenti nekem az életet, tudhatom, hogy jön, jönnie kell, a mágnes húzza felém. Mégis néha elbizonytalanodom. Már reggel <span class="marked">kilenckor</span> is volt nálam, csak korábban távoztam otthonról.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'viszont már voltak a helyszínen, csak nem tetszett nekik az épület. Május végén azonban hívott egy személy tanyavásárlási szándékkal. Neki az irányár és a hely is megfelelt. Csak azt kérdezte, hány helyiség lakható? <span class="marked">Hatkor</span> találkoztunk a bolt előtt a családdal, és autóval kivittek a tanyára.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'Hajnali ötkor keltem az albérletben, és este <span class="marked">kilenckor</span> minden tárgyam a tanyáról a szegedi lakásomban volt.', true, '21:00', '21:00', '21:00', 1260, 1260, 1260, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'egy péksüteményt akartam venni, de az összeragadt kifliken láttam, hogy tegnapi. Egy boltba mentem, ott is csak régi kiflit találtam, akkor inkább kekszet vet tem. A peronon ültem, és várakoztam. A vonat indulási ideje <span class="marked">9 óra 36 perc</span>, és fél tízkor még sehol egy sínbusz.', true, '09:36', '09:36', '09:36', 576, 576, 576, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'a pénzt, mert nem tudt am volna kifizetni a lakást. Hajnali fél háromkor csengetésre ébredtem. Amikor kinéztem, Icát láttam, de elegem volt belőle, és először tettem olyat, hogy nem engedtem be. Így is ébren voltam <span class="marked">egy óra</span> hosszat, de ha beengedem, reggelig nem alszom.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'utcanevekben nincs fantázia. A lányom mindig visszavágott. Talán az Aleja Marsala utca névben van? Már jeleztem neki, hogy halkabban, de ő nem hagyta magát. Délre értünk a Dankó Pista utcába. Addig öt óra vá rakozás és <span class="marked">egy óra</span> utazás. Egy vigasztalt bennünket, hogy már itthon vagyunk. A vámhivatalban közölték velünk, hogy van másfél óra szabadidőnk, menjünk ebédelni. Hazajöttünk, én aludtam is, mert nekem az fontosabb volt, mint az evés. Úgy', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
