INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'emlékeztem semmire. Nem tudom, hol és ki ébresztett, az utazásra se emlékszem, pedig megfogtam az ápoló nyakát, aki az ágyra tett. Valaki szólt, hogy nem szabad aludni két óra hosszát. Most mennyi az idő? - kérdeztem. <span class="marked">Fél egy</span> - válaszol valaki. A műtőben az utolsó időpont, amit láttam 11 óra 48 perc. Görcseim vannak, érzem, hogy vérzek, kábult vagyok és aludnék, de nem szabad. A szobatársaim beszélnek hozzám, amikor úgy érzik, hogy', true, '00:30', '00:30', '00:30', 30, 30, 30, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'A műtőben az utolsó időpont, amit láttam <span class="marked">11 óra 48 perc</span>. Görcseim vannak, érzem, hogy vérzek, kábult vagyok és aludnék, de nem szabad. A szobatársaim beszélnek hozzám, amikor úgy érzik, hogy megszunnyadok. Me gjelent az orvos, csak az alakjára emlékszem, mintha vérzésről', true, '11:48', '11:48', '11:48', 708, 708, 708, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
