INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'azt mondta Simon, viszi az egyiket, de nem vitte. A terhemet, a csomagomat nekem kell cipelni, tudtam én ezt már régen, de mégis néha azt hiszem, hogy valaki akár néhány percre is megszabadít tőle. Január 30-án, kedden <span class="marked">12 óra 55 perckor</span> megkaptam a magyar telefont, életem harmadik telefonját.', true, '12:55', '12:55', '12:55', 775, 775, 775, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'Na most mit csináljak? Nemsokára jön Simon. Akármilyen nagyon szeretek is szexelni, azért most nem tudnék. Hazudjak, hogy fáj a fejem, azt nem lehet, mert úgy ragyogok a boldogságtól. Vagy talán nem is jön? Alig múlt <span class="marked">egy óra</span>, már csengetett. Ilyen korán jön Simon? - siet hozzám, úgy látszik, nagyon kívánja már. Nem nyomtam meg a kapucsengőt, mégis nemsokára már itt fent csengetett. Kinéztem, az autója a szokott helyen állt. Sz egény', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'azt mondta, nincs ideje az őseivel foglalkozni, fáradt, tizenhárom órát dolgozik, de azért eljön már pénteken. Szombaton csak két-három órája lesz a nagymamára. Bántot t a dolog, hisz Olgáékhoz menni van ideje. Éjjel <span class="marked">egy órakor</span> sem aludtam, olyan izgatott voltam.', true, '13:00', '13:00', '13:00', 780, 780, 780, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Acita', 'https://mek.oszk.hu/06300/06374', 'ember kapcsolatáról beszél, az szép. Szeretet, segítség, összhang, de kinek kell egy ötvenöt éves ember, akinek nincs semmije. Ott már valami nagy baj van. Rossz hangulatom volt, mert Petőházára kellett menni. Reggel <span class="marked">nyolckor</span> már a házunk előtt voltam. Talán tíz percig várakoztam az ajtóban, a néhányszori csengetés után, mire Erika végre kinyitotta az ajtót. Amikor bementem a lakásba, csak annyit kérdezett: Ivott kávét? Aztán leültek', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-9267', 'Pásty Júlia', 'novel', 'https://mek.oszk.hu/06300/06374/06374.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'tetszik. Mondom, hogy keveset tud az életről. Még az elemi kifejezéseket sem. Majd megneveljük. Apám szólt már a ma este miatt? - Még nem szólt. Miről van szó? - Ma estére néhány vendéget hívtunk a maga tiszteletére. <span class="marked">Félkilenc</span>, szmoking. Megismertetjük a legközvetlenebb barátainkkal. Délután apámnál lesz az irodában. Egész napját elfoglaltuk, úgy látom. Nem sok? - Ó, dehogy... Ki vagyok tüntetve. De nem voltunk már eleget a vízben? Mozogni', true, '08:30', '08:30', '08:30', 510, 510, 510, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'nem érintette. Felmentek az asztalhoz. Az orosz gróf már nem volt sehol. - Öltöznünk kell, Tihácskám. Könnyű a nőknek, de nekünk komoly dolgaink vannak még. Ja igaz, estére úgy készültünk, hogy nálunk vacsorázol. <span class="marked">Félkilenc</span>, szmoking. Van szmokingod? - Van. Csináltattam még kutyafuttában, mielőtt utaztam. - Helyes. Most üdvözöld a hölgyeket és gyerünk. Húsz perc mulva már taxiban ültek. Pethő visszatért feleségére és leányára. Termetöket', true, '08:30', '08:30', '08:30', 510, 510, 510, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'kezdte átfutni az eléje rakott dolgokat. Csakugyan formaságok voltak. Odakanyarította nevét a szükséges helyekre. - Köszönöm. Mára végeztünk. Már tudniillik a hivatalos ügyekkel. Este nálunk vacsorázol. Tudod mit: <span class="marked">nyolckor</span> légy készen, érted megyek és felfuvarozlak magam.', true, '20:00', '20:00', '20:00', 1200, 1200, 1200, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'laktál. - Öt évig. De az egészen más város volt. Hónapok elmúltak anélkül, hogy a Belvárosban, vagy a Dunaparton megfordultam volna. Ezzel a Budapesttel én most kezdek ismerkedni. És el vagyok tőle ragadtatva. Szóval <span class="marked">nyolckor</span> várlak. - Úgy van. Ami pedig a jövőt illeti, egyszersmindenkorra: én mindenben rendelkezésedre állok. Ha központi fűtés kell, én hozom neked a legjobb és legolcsóbb vállalkozót. Ha vizum kell, elküldöd az útleveledet,', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'ha lesz valami? - Nekem most nem lehet telefonálni. De talán én hívhatnám magát. - Hogyne. A Gellértben lakom. Holnap reggel már talán tudok mondani valamit. Ha megmondja, mikor hív fel, otthon leszek. Mondjuk, <span class="marked">kilenckor</span>? - Köszönöm szépen. De most rohanok, a Deák Ferenc-utcában kell felkeresnem egy házgondnokot és máris elkéstem. Szívből köszönöm és viszontlátásra. Anna eltűnt, mint egy látomás. És ő csak ekkor tudta megnézni. Fehér', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'Már teljesen felöltözködött, leült a készülék elé várakozni, rágyújtott, s még mindig nem múlt el <span class="marked">fél kilenc</span>. Ekkor csakugyan csengett a telefon. Mohón és lámpalázasan kapta fel a hallgatót. Még arcát is ragyogóan nyájasra igazította. De ez a mosoly azonnal buta vigyorgássá meredt: Pethő hangja szólt a vonalon. - Csak azt', true, '08:30', '08:30', '08:30', 510, 510, 510, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'a kezét, mint jutalmul a kutya fejét szokás megütögetni. Az időt ődöngéssel ütötte agyon. Hajókázott a Dunán és imádta a város két partjának látványát. Kiment a Margitszigetre, elhatározta, hogy ott ebédel egyedül. <span class="marked">Egy órakor</span> evett. A pincérrel telefonáltatott a Hullámfürdőbe Pethő ügyvéd úrnak, hogy Balog tanár úr bocsánatot kér, nem jöhet, mert találkozott egy régi osztálytársával. Aztán nagyot sétált, nézegetett, taxit vett, felment a', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
