INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'elvileg teljesen lehetetlen, de a maga ajánlása ő nála olyan sokat nyom a latban, hogy lesz állásom. Kikérdezett, hogy mit tudok, aztán rögtön felhívott valami gyárat, ahol valami kálisóval foglalkoznak. Holnap reggel <span class="marked">kilenckor</span> oda kell mennem jelentkezni. A hivatalos óra és a fizetés kérdése holnap dől el. De valószínű, hogy kétszázötven pengőt megkaphatok. - Az nem nagyon sok. - Az nem nagyon sok? Abból én meg tudok élni, kedves Balog. Majd', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'történetét, mindent. Az asszony csuklójára pillantott. De azon nem volt karkötő-óra. - Hány óra? - Most fél nyolcra jár az idő. Elvesztette a karkötő-óráját? Anna könnyedén elpirult. - Elromlott, óráshoz adtam. De ha <span class="marked">fél nyolc</span>, akkor, sajnos, mennem kell. Izenetet kell leadnom valahol. Fizessünk. Ismétlem, hogy nem voltam vendége. - Jó. Nem erőszakoskodom. De ezt a beszélgetést most nem lehet abbahagyni. Akárhova megy, elviszem taxin. - Nem,', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'reggel kilenctől háromig egyhuzamban dolgozni, félóra ebédszünettel, hetenként egyszer délután is be kell mennie, évente két heti szabadságra van igénye, adóját és betegsegélyző-járulékait a cég fizeti. Holnap reggel <span class="marked">kilenckor</span> már be is áll, egyelőre a levelezési osztályon kap próba-beosztást.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'nem tudom, mi lesz velem ma este. Lóg valami elfoglaltságom a levegőben, de biztosat még nem tudok. Ha szabad leszek, szívesen elmennék veled vacsorázni. A régi szép időkről még nem is beszélgettünk. Hívjál fel engem <span class="marked">fél kilenckor</span>. Legfeljebb azt felelem, hogy el vagyok foglalva, s akkor kitűzünk egy másik estét. Helyes? Most szaladok, Isten veled. Felszedte az asztalon heverő cigarettatárcáját, táskáját, miegymást és máris sietett a', true, '08:30', '08:30', '08:30', 510, 510, 510, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'nézett rá. Ettől a pillantástól megszégyenülten háta mögé kapta két kezét és képzeletben csúfondárosan lerajzolta a mosolyognivaló alakot, a jó vidékit, aki önfeledt mosollyal álmélkodik keze elegáns voltán. Este pont <span class="marked">félkilenckor</span> felvette a telefonhallgatót: - Szíveskedjék összekötni D''Aubigny grófnéval.', true, '20:30', '20:30', '20:30', 1230, 1230, 1230, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'együtt vacsorázunk. De még beletelik egy félóra, amig kész leszek. Te már felöltöztél? - Hogy-hogy felöltöztem? Le sem vetkeztem. - Úgy értem, hogy természetesen vegyél szmokingot, én kis estélyit veszek. Pont <span class="marked">kilenckor</span> lent találkozunk a portásnál.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'Le sem vetkeztem. - Úgy értem, hogy természetesen vegyél szmokingot, én kis estélyit veszek. Pont kilenckor lent találkozunk a portásnál. A kocsimat elküldtem, taxit veszünk. Előre örülök, szervusz. Nem ugyan <span class="marked">kilenckor</span>, de féltíz előtt öt perccel Yvonne kilépett a felvonóból.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'kimegy az Ilona-uccába, s ideje volna, ha Tihamér megnézné a lakóházat, amelyet örökölt. - Vegyél taxit, Titikém, az én kocsim ma egész napra a Daisyé. Szólj be értem a Lánchíd-kávéházba. Ott van egy tárgyalásom. Pont <span class="marked">tizenegykor</span> várlak. Pontosak voltak mind a ketten, tizenegy után pár perccel már ott rázkódtak az Ilona-utca egyenetlen kövezetén. Tihamér sohasem járt még ezen a vidéken. Kissé csalódottan állapította meg, hogy ennek az utcának', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'látni, hogy ezt már nem is szeretem. Most mit csinálsz? - Semmit. Újságot olvastam. Aztán szép lassan felöltözködöm. - Én is felöltözöm, de az valamivel tovább tart, mint nálad. Egész csomó telefonom is van. Tudod mit, <span class="marked">tizenegykor</span> átszólok hozzád. Majd kieszelünk valamit. A telefonban cuppanás hallatszott. Utána kis kacagás. Aztán kattant egyet a letett hallgató. Tihamér nem tette le. Minden ok nélkül tartotta tovább, fülére szorítva. Úgy ült', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'előtt okvetlen megmutatja Annának a rajzot. Ez legalább nyilt vallomás is lesz. Hadd tudja meg ezt a szép és félénk szerelmet, akkor aztán, ha a sors úgy rendelte, esetleg ne is lássák egymást soha többé. Este <span class="marked">tizenegykor</span> már otthon volt. Tétlenül cigarettázott féltizenkettőig, végül már kitette maga elé az óráját és a percmutatót figyelte. Fél tizenkettő előtt harminc másodperccel elindult, összeszorította fogát és vállat vont, mint a', true, '23:00', '23:00', '23:00', 1380, 1380, 1380, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'Attól megtudta, hogy szombat van, a hivatal szombatonként <span class="marked">egy órakor</span> már hazaereszti alkalmazottait.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'találják meg igazi érvényességüket. És Titi, mialatt odaadással gyönyörködött benne, azt gondolta, hogy nem kilenc pengőt, hanem kilenc földkerekséget megér, ha ezt az arcot nevetésre lehet indítani. VIII. Egyik este <span class="marked">tizenegy óra</span> tájban ment haza Pethőéktől, ahol elég mulatságos vacsorán vett részt.', true, '23:00', '23:00', '23:00', 1380, 1380, 1380, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'törődött vele, csak a ruhának örült. Soká nézte magát a tükörben és lelkesen meg volt elégedve. Aki a tükörből gondosan vizsgáló szemmel visszatekintett rá, azt a legszigorúbb bírálattal is elegáns embernek nevezhette. <span class="marked">Fél kilenckor</span> taxiba ült és elvitette magát a Kis Royalba.', true, '08:30', '08:30', '08:30', 510, 510, 510, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'hozzá és parádi vizet. Üldögélt a szmokingban és nézegette a közönséget. Remekül érezte magát. Már nem haragudott Annára. Maga elé nézett, belegondolta Annát cigarettája füstjébe és a cigányzene cimbalomfutamaiba. <span class="marked">Tizenegy óra</span> tájt eszébe jutott, hogy még el kellene mennie valahová, megmutatni az emberiségnek a szmokingot.', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'fogom böjtös napra invitálni. - Péntek? Hát ma nem szombat van? A követ saját homlokára csapott és elmosolyodott. - Öregszem. A titkárom délután külön figyelmeztetett, hogy péntek van és a futár indul Varsóba. Én pedig <span class="marked">nyolckor</span> a legnagyobb lelki nyugalommal elkezdtem öltözködni azzal, hogy szombat van.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'Pasaréti-út tizenkilenc, este <span class="marked">háromnegyed kilenc</span>, szmoking. Névjegyet nem kell dobni. Dömsödy barátságosan a vállára csapott: - Nagyon szívesen látlak, öregem, majd egy kicsit elbeszélgetünk a kolozsvári dolgokról. - Köszönöm szépen, a legnagyobb örömmel. A követ', true, '20:45', '20:45', '20:45', 1245, 1245, 1245, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'magára? - Rajtam kevés fordul meg. De ha tehetek valamit... - Majd én megmondom, mit tehet. Erről még beszélünk. Otthon a szállóban meglepő hír várta. «Zahár Emil tanár úr és neje Zoborhelyről itt voltak. Holnap reggel <span class="marked">kilenckor</span> újra eljönnek.» Zahár, a történelemtanár és neje, Marica, a hajdani szerelem, akivel egyszer olyan ijesztően izgalmas perceket élt át a csőszkunyhóban, akivel a ponorszegi erdőben jött össze titkos találkára.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'Mindenesetre elég kényelmetlen időben jönnek, <span class="marked">nyolckor</span> kell költetnie magát. Valóban jöttek kilenckor. A hallban fogadta őket. Első érzése a megdöbbenés volt: hajdani szerelméről, Maricáról elképedve látta, milyen jelentéktelen, formátlan és mégcsak nem is csinos.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'izgalmas perceket élt át a csőszkunyhóban, akivel a ponorszegi erdőben jött össze titkos találkára. Vajjon mit akarnak? Mindenesetre elég kényelmetlen időben jönnek, nyolckor kell költetnie magát. Valóban jöttek <span class="marked">kilenckor</span>. A hallban fogadta őket. Első érzése a megdöbbenés volt: hajdani szerelméről, Maricáról elképedve látta, milyen jelentéktelen, formátlan és mégcsak nem is csinos. Láthatóan nagyon ki akart öltözködni s ennek', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'Mi ezt szintén megcsináljuk, de öt-<span class="marked">hat óra</span> alatt és kevesebb mennyiségű, kevésbbé idegtépő munka után.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'Goll Elemér, ott van maga mögött a széken egy esti lap, adja csak ide. A szép fiú odahozta az ujságot. A grófné átvette, nem köszönte meg és lapozni kezdett benne. - Lássuk csak. Herakles-mozgó. «Árkon-bokron át.» <span class="marked">Háromnegyed nyolc</span>. Maga hol lesz fél nyolckor, Balog? - Ahol parancsolja. - Nem, nem, magához alkalmazkodom. Mondja meg, hol lesz, odamegyek magáért a kocsimmal. Elviszem a moziba. Utána együtt ehetünk valahol, aztán haza is fuvarozom.', true, '07:45', '07:45', '07:45', 465, 465, 465, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'a széken egy esti lap, adja csak ide. A szép fiú odahozta az ujságot. A grófné átvette, nem köszönte meg és lapozni kezdett benne. - Lássuk csak. Herakles-mozgó. «Árkon-bokron át.» Háromnegyed nyolc. Maga hol lesz <span class="marked">fél nyolckor</span>, Balog? - Ahol parancsolja. - Nem, nem, magához alkalmazkodom. Mondja meg, hol lesz, odamegyek magáért a kocsimmal. Elviszem a moziba. Utána együtt ehetünk valahol, aztán haza is fuvarozom. Jegyekről már délelőtt', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'meg, hol lesz, odamegyek magáért a kocsimmal. Elviszem a moziba. Utána együtt ehetünk valahol, aztán haza is fuvarozom. Jegyekről már délelőtt gondoskodjék, mert hallom, hogy nagyon jól megy. - Elintézem, grófné, <span class="marked">fél nyolckor</span> otthon leszek a Gellértben. Nem is tudom, hogyan köszönjem meg a kitüntetést... - Ne nekem köszönje, hanem a barátjának, aki cserben hagyott a színházzal. Igy került maga a krédóba. Totó udvariasan, de méltatlankodva', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'Titivel megismételtette a leckét: <span class="marked">fél nyolckor</span> várjon a Gellértben, jegyekről gondoskodjék.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'Titi megélénkülve, frissebben folytatta útját. Most érezte először, hogy amire olyan mélységesen vágyódik, az nem reménytelen. S a reményért érzett hála olyan melegséggel öntötte el, hogy ez még szerelmesebbé tette. <span class="marked">Félnyolc</span> előtt öt perccel kiállt a szálló kapujába.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'Megállapodtak a találkában és Titi este <span class="marked">fél nyolckor</span> ott ült a Budapesti Ujság párnázott ajtajú főszerkesztői szobájában.', true, '19:30', '19:30', '19:30', 1170, 1170, 1170, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'papírra, mintha onnan akarná leolvasni, mi lesz rajta. És a papír fehérsége valóban megihlette, egy pillanat alatt megtalálta az összefogó gondolatot, amelyet keresett. Kitette az óráját, elkezdett dolgozni. Nekifogott <span class="marked">háromnegyed kilenckor</span>. Tíz órakor felvette a telefonkagylót és felhívta a Budapesti Ujságot. Kapcsoltatta a főszerkesztőt. - Itt Balog Tihamér beszél. Szerencsém van, hogy megtalállak. - Szombat van, öregem, nehéz nap. Csak éppen ettem', true, '08:45', '08:45', '08:45', 525, 525, 525, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'Ott pukkadjon meg valamennyi, ahol van." De megint csak oda érkezett, hogy szmokingban megérkezni előkelő házhoz <span class="marked">háromnegyed kilenckor</span> nagyon kellemes, ragyogóra öltözött asszonyok között keresni névkártyáját, tündöklően terített asztalnál mókázni, országos nevű urakkal "kérlek Titikém"-barátságban lenni, hazakíséréskor valamelyik dámához lopva', true, '08:45', '08:45', '08:45', 525, 525, 525, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'Mikor beszélünk? A színházat halasszuk el a jövő hétre, az estéim most elég zsúfoltak. Nincs kedve ma délután velem uzsonnázni? Most már korán van sötét, jókor abba kell hagynom a munkát. Nem akar eljönni a Zserbóba <span class="marked">fél hatkor</span>? - Boldogan. - Helyes. Fél hat, Zserbó. Viszontlátásra. Háromtól ötig Annával üldögélt kávéházban. Büszkén mutogatta neki az ujságíró-igazolványt és a szabadjegyet. Jókedve volt, sokat nevettek. Megfejtettek egy német', true, '05:30', '05:30', '05:30', 330, 330, 330, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'el a jövő hétre, az estéim most elég zsúfoltak. Nincs kedve ma délután velem uzsonnázni? Most már korán van sötét, jókor abba kell hagynom a munkát. Nem akar eljönni a Zserbóba fél hatkor? - Boldogan. - Helyes. <span class="marked">Fél hat</span>, Zserbó. Viszontlátásra. Háromtól ötig Annával üldögélt kávéházban. Büszkén mutogatta neki az ujságíró-igazolványt és a szabadjegyet. Jókedve volt, sokat nevettek. Megfejtettek egy német keresztrejtvényt a Leipziger', true, '05:30', '05:30', '05:30', 330, 330, 330, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', '"A váciutcai déli korzó járókelői ma <span class="marked">egy óra</span> tájban hangos szóváltásra lettek figyelmesek.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'kihozni belőle semmit. Aztán lassacskán derengett valami neki. Letépte ezt a lapot is, most már komponálni kezdte a gondolatához tartozó csoportokat. Három feketét hozatott egymásután az elmulasztott ebéd helyett. <span class="marked">Nyolc órakor</span> készen volt a rajzzal. A nagy és népes rajz alapgondolata az volt, hogy mindenki párbajozik. A papír egyik területén viaskodó párok csoportosultak. A középen Hitler és Chamberlain párbajozik Godesbergben, Hitlernek', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'Megyek haza. - Mi az, beültél egy másik bridzsbe? - Ördögöt bridzsbe. Amott a harmadik szobában vad chemin folyik. A brazil úgy nyer, hogy rossz nézni. A házigazda eddig nyolcezret leadott. Szervusztok. Totó, holnap <span class="marked">tizenegykor</span> összeülünk az urakkal, érted megyek.', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'százast és odadobta tétnek. Ezt megnyerte. Ott hagyta, megnyerte. Még egyszer otthagyta. Egyszerre csak nyolcszáz pengő volt előtte. Akkor visszaült. Most már kártyázott visszavonhatatlanul. Közben bőven ivott. Reggel <span class="marked">fél nyolckor</span> úgy kelt fel, hogy minden nála lévő pénzét elvesztette és kilencszáz pengővel adós maradt.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'A termet, fegyvereket, orvosokat mi mind elintézzük, te várjál bennünket a Gellértben hétfőn délelőtt pont <span class="marked">fél tizenegykor</span>, érted megyünk. - Köszönöm, pontos leszek. Végrendeletet csináljak? - Titikém, ne nevess, a legbámulatosabb dolgok is megtörténhetnek. Vérmérgezést is kaphatsz egy karcolástól. - Sőt, Mester le is vághatja a fejemet,', true, '10:30', '10:30', '10:30', 630, 630, 630, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'Mohón láttak neki a hideg holminak, a rádión megkeresték Newyorkot és nagy érdeklődéssel hallgatták, csak ő nem értett belőle semmit. De közben vidáman ivott és evett. És sokáig nézte a Gauguin-képet. Megint reggel <span class="marked">fél nyolckor</span> került haza. Nagyon megdícsérte magát az óvatosságáért, hogy a nyolcszáz pengőt otthon hagyta, mert ha a pénzt magával viszi, biztosan megkereste volna a fizetőpincért valamelyik helyiségben, hogy annak az egész', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'Aztán még ujságot olvasott és végre <span class="marked">félkilenckor</span> aludni próbált. Rögtön érezte is, hogy már szendereg. De ez a jóérzés alig tartott tíz percig. Ismét egészen ébren érezte magát. Gondolatai zsúfoltan és vérmesen zakatoltak. Felkattantotta a világítást, elszívott egy', true, '08:30', '08:30', '08:30', 510, 510, 510, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'lezuhanyozta magát, bevette a szert és dideregve, pihenést sóvárogva lefeküdt megint. Most már ment az alvás. Egyhuzamban aludt este tízig. Akkor valamit enni hozatott, megivott két üveg sört és megint elaludt. <span class="marked">Nyolckor</span> telefoncsengetésre ébredt, akkorra kérte a költést.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'Meg aztán hivatalban nem is nagyon szeretik, ha a tisztviselők magánügyben telefonálnak. Majd délután háromkor beszél vele, vagy sértetlenül, vagy bekötözve. Vagy, ha nagyobb baj történik, még ráér neki telefonáltatni. <span class="marked">Féltizenegykor</span> percnyi pontossággal jöttek érte.', true, '10:30', '10:30', '10:30', 630, 630, 630, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'náluk a művészvilág híres neveivel fog találkozni. Valóban nem kevesebb, mint négy országos primadonnát ismert ott meg egy bokrétába kötve. Ez a ház arról volt nevezetes, hogy itt kétszer terítettek vacsorára. Először <span class="marked">kilenc órakor</span> tálaltak. Aztán féltizenkettőkor az olyan színházi vendégeknek, akik aznap este felléptek s csak ilyen későn tudtak jönni. A mulatság ennélfogva igen későn ért véget. A hang itt szerfölölt mulatságos volt és még az', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'Számos háznál az volt a divat, hogy a vacsora csak ürügyül szolgált olyan <span class="marked">tizenegykor</span> kezdődő kirándulásokra, amelyek három-négy tánchelyiségen is végigmentek, hogy valahol bablevessel végezzék, vagy záróra után valahonnan cigányt vigyenek haza.', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'múlva nagy esemény következett. A grófné meghívta Titit a műterembe vacsorára. - Csak még az uram egy rokona lesz itt, Nostitz gróf, aki szintén fest. Mást nem hívok. Könnyű hideg vacsorát kapnak. De vegyen szmókingot. <span class="marked">Háromnegyed kilenc</span>, legyen pontos. A pontatlanság sértő, figyelmeztetem. Titi háromnegyed előtt tíz perccel érkezett. A Szent György-téren megállította a kocsit, s mivel nem esett az eső, onnan gyalog ment. A másik vendégnek még nyoma', true, '08:45', '08:45', '08:45', 525, 525, 525, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'fizetett. A lányok kezébe nyomott tíz-tíz pengő társaságpénzt és valahogyan kivergődött. A portás nyomban a karja alá nyúlt, atyai gyengédséggel segítette a kocsiba és a pengőért mélyen leemelte kék sapkáját. Másnap <span class="marked">egy órakor</span> kettesben ebédelt Ferenczy szerkesztővel és egy-kettőre megállapodott vele.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'Innen azzal a kocsival, amelyet lent váratott a kapu előtt, <span class="marked">fél nyolckor</span> elment egy másik cocktailre. Itt Side-Cart kapott, abból is megivott kettőt. Fél kilenckor moziban volt találkája Dohna gróffal, Totóval és egy kölni házaspárral. A kölni férj, Von Meynen nevezetű, igen nagy német', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'az ízeket, már meg tudott különböztetni egymástól nyolc-tízfélét is. Innen azzal a kocsival, amelyet lent váratott a kapu előtt, fél nyolckor elment egy másik cocktailre. Itt Side-Cart kapott, abból is megivott kettőt. <span class="marked">Fél kilenckor</span> moziban volt találkája Dohna gróffal, Totóval és egy kölni házaspárral.', true, '08:30', '08:30', '08:30', 510, 510, 510, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'De mint az iszákos, aki utálja önmagát és azért iszik, hogy ezt az utálatot elfelejtse, ő is a grófné szépségére gondolt és a furcsa szavakat mondogatta magában: "Vagy eljön az ideje, vagy nem." Reggel <span class="marked">kilenckor</span> már felhívta a grófnét és elmondta neki a kellemes ujságot.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'látott Budapesten. Unalmában végigfejtette valamennyi lap rejtvényét. Azok sem tartottak örökké. Szeretett volna járkálni, de félt, hogy a grófné közben megérkezik. Öt órakor a várakozás kezdett gyötrelmessé fajúlni. <span class="marked">Hat órakor</span> kaján önkínzással kezdte remélni, hogy a grófné nem is jön.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'évvel élt Indiában egy emberszabású majom. Annak volt két fia. Az egyiktől származom én, a másiktól az egész emberiség. - Jó, jó, azért ne legyen megsértve. Most pedig programmot fogunk csinálni. Nézze meg az óráját. - <span class="marked">Negyed nyolc</span>. - Rosszul jár. Az enyém pontos. Igazítsa vissza öt perccel. Úgy. Én most felmegyek a kilences számú szobába, mert ezt a szerencsés számot kaptam, fürdőt rendelek magamnak, aztán felhozatok valami vacsorát. - Nem', true, '07:15', '07:15', '07:15', 435, 435, 435, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'számot kaptam, fürdőt rendelek magamnak, aztán felhozatok valami vacsorát. - Nem eszünk együtt? - vágott közbe riadtan Titi. - Nem. Most elbúcsúzunk. Maga elmehet a városba járkálni. Vacsorázzék valahol. Reggel pont <span class="marked">kilenckor</span> itt reggelizünk, aztán felviszem Pestre.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'követte példáját. A pincérnek intett, hogy írják a fizetnivalót a számlájára. Udvariasan felsegítette a bundát. Kimentek. A grófné még megállt és kezet nyujtott. - Aztán nehogy elcsavarogjon nekem az éjszakában. Pont <span class="marked">kilenckor</span> itthon kell lenni. Titinek lesüllyedt a szíve. Kétség és remény között bukdácsolt, mint viharban a repülőgép. Nem tudta, hányadán áll. A grófné még közömbösen hozzátette: - Kilenckor reggeli. Legyen pontos. Azzal', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'A grófné még közömbösen hozzátette: - <span class="marked">Kilenckor</span> reggeli. Legyen pontos. Azzal sarkon fordult és köszönés nélkül otthagyta. Ő szinte sóbálvánnyá vált a fejére zuhant örömtől. Mint fejbesújtott bálvány, nem tudott jódarabig megmoccanni. Jó sokára jutott hozzá, hogy', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'azt, aki védtelen. - Férfi vagyok, - sóhajtotta magának szorongva - bestia vagyok. A szobájában pizsamát öltött, gyorsan megborotválkozott, kölni vízzel öblögetett és óráját kitette az asztalra, állandóan nézte. Pont <span class="marked">kilenckor</span> magára kapta a télikabátot. A világosságot eloltotta. Óvatosan lépett ki, a folyosón nem járt egy lélek sem. Odaosont a kilences számú szobához. Halkan kopogtatott. - Ki az? - szólt ki egy rideg hang, amelyben a grófné', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
