INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'a kulcsot visszafordította. Hátha - mondta elhaló eszméletével. Hosszú ideig feküdt még így megalázottan, még mindíg remélve a lehetetlent, megélte a virradat szürke pillantását az ablakon, aztán elaludt. Reggel pont <span class="marked">kilenckor</span> léptek be mindketten az étterembe.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'A grófné megkövetelte, hogy minden reggel <span class="marked">kilenckor</span> telefont kapjon. Titi azonban ritkán feküdt le három, négy óra előtt. A háziközponttal költette fel magát kilenckor, akkor felhívta a grófnét, az álomtól mámorosan és az előző éjszaka sok whiskyjétől zúgó fejjel', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'A háziközponttal költette fel magát <span class="marked">kilenckor</span>, akkor felhívta a grófnét, az álomtól mámorosan és az előző éjszaka sok whiskyjétől zúgó fejjel elmondta, hogy hol volt, hogyan folyt le a vacsora, kik voltak jelen, ki milyen ruhát hordott és micsoda új mendemondát hordtak össze a városból.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'Ha négy órakor vette be a szert, reggel <span class="marked">kilenc órakor</span> még félig eszméletlen kábulatban telefonált, de a telefon kiverte az álmot égő szeméből.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'közt csellengő, lábatlankodó valakinek, akit könyökkel szó nélkül hátratolnak, ha már nagyon útban van. Cárnői kegyencnek, aki nehéz katonai szolgálatot teljesít naphosszat, de a csók rapportjára nem rendelik. Hétfőn <span class="marked">egy órakor</span> megjelent a Hungáriában. A cocktailt abban a teremben tartották, ahol a bálok szoktak lezajlani. Már sűrű tömeg vendég lökdösődött és köszöngetett egymásnak, mikor bement. A társaság magváig nem is lehetett látni: a', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'ütögetett és egész este tréfásan kérdezgette tőle, hogy hány óra. Ő belement a tréfába, mindannyiszor szolgálatkészen zsebébe nyúlt és megjátszotta a kellő megdöbbenést. De Gyöngyös Terkával óvakodott foglalkozni. <span class="marked">Egy óra</span> felé egy Székács nevű fiatal színésszel jött el a vendéglátó háztól.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'egy játékbarlangba, s ezt az összes lapok megírják. Ez intő jel, gondolta magában, most már vigyázni kell. Ha megint a lapokba kerül valami ilyen alapon, botrányhőssé nőheti ki magát. De hogyan történhetett, hogy <span class="marked">egy órakor</span> már eljött a vendéglátó háztól?', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Whisky szódával', 'https://mek.oszk.hu/14000/14046', 'alaposabban. Röntgenfelvételt is csináltak róla. - Gyomorfekély, - mondták ki a szentenciát - szokott szeszt fogyasztani? - Sokat és erőset. - Igen. Valószínűleg gyomorfekély. Holnap reggelig ne egyék semmit. Reggel <span class="marked">nyolckor</span> hozza magával ezt a cédulát és próbareggelit fog kapni.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-132669', 'Harsányi Zsolt', 'novel', 'https://mek.oszk.hu/14000/14046/14046.htm', 'deep_extract', false);
