INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hippokratész', 'https://mek.oszk.hu/06200/06298', 'Nem permete ztem ugyan fokhagymaázalékkal, mint <span class="marked">egykor</span>, és nem teremtettem minden almában hat kukacnak kényszerlakhelyet, ahogy kísérletező koromban sikerült.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-8992', 'Horváth Dezső', 'essays', 'https://mek.oszk.hu/06200/06298/06298.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hippokratész', 'https://mek.oszk.hu/06200/06298', 'Amikor még annyira korszerűtlen volt a Magyar Televízió, hogy egyszemélyes szegedi szerkesztője, operatőre, szövegírója, és buszra loholója voltam, csak kezébe kellett nyomnom a déli <span class="marked">egykor</span> induló kalauznak a filmet, és fölvitte.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-8992', 'Horváth Dezső', 'essays', 'https://mek.oszk.hu/06200/06298/06298.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hippokratész', 'https://mek.oszk.hu/06200/06298', 'annyira korszerűtlen volt a Magyar Televízió, hogy egyszemélyes szegedi szerkesztője, operatőre, szövegírója, és buszra loholója voltam, csak kezébe kellett nyomnom a déli egykor induló kalauznak a filmet, és fölvitte. <span class="marked">Fél nyolckor</span> már láthattam is a képernyőn.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-8992', 'Horváth Dezső', 'essays', 'https://mek.oszk.hu/06200/06298/06298.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hippokratész', 'https://mek.oszk.hu/06200/06298', 'pedig mi akarna lenni? Kis türelem, minden kiderül. A reggeli csúcsforgalmat úgy akarták orvosolni az öregátkosban, hogy elkezdték emlegetni a lépcsőzetes munkakezdést. Ezzel volt tele a világ. Ha a hivatalokban is <span class="marked">8-kor</span> ke zdődik a munkaidő, meg az iskolákba is akkor csöngetnek be először, akkor egymás lépét és máját könyöklik ki a népek a buszokon és villamosokon, és a hidakon is eldugul a forgalom.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-8992', 'Horváth Dezső', 'essays', 'https://mek.oszk.hu/06200/06298/06298.htm', 'deep_extract', false);
