INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hippokratész', 'https://mek.oszk.hu/06200/06298', 'került haza belső területre, hogy életét áldozza a hazáért. Nagyon bátran viselkedett. Igazi hős volt, akinek az emlékét az újságíró-társadalom kegyelettel és szeretettel fogja megőrizni. Temetése csütörtökön délután <span class="marked">5 órakor</span> lesz a szegedi helyőrségi kórházból." Annyi derült csak ki tehát, hogy Kardos Imre a Délmagyarország munkatársa is volt, és 1944.', true, '05:00', '05:00', '05:00', 300, 300, 300, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-8992', 'Horváth Dezső', 'essays', 'https://mek.oszk.hu/06200/06298/06298.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hippokratész', 'https://mek.oszk.hu/06200/06298', 'Ha jól látom, az utolsó járat <span class="marked">háromnegyed 9-kor</span> indul vissza, de Makón egy órát várnom kellene, és csak fél éjfélkor érnék Szegedre.', true, '08:45', '08:45', '08:45', 525, 525, 525, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-8992', 'Horváth Dezső', 'essays', 'https://mek.oszk.hu/06200/06298/06298.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hippokratész', 'https://mek.oszk.hu/06200/06298', 'meg nem ette, baj van! Ha jól látom, az utolsó járat háromnegyed 9-kor indul vissza, de Makón egy órát várnom kellene, és csak fél éjfélkor érnék Szegedre. Kemény beszélgetés vár rám, föltehetően el is fáradok. Ha déli <span class="marked">12-kor</span> ke zdek itthon kászálódni, és az éjjeli 12 táján érkezem vissza, testvérek között is a nap 24 órájának a fele.', true, '12:00', '12:00', '12:00', 720, 720, 720, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-8992', 'Horváth Dezső', 'essays', 'https://mek.oszk.hu/06200/06298/06298.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hippokratész', 'https://mek.oszk.hu/06200/06298', 'vár rám, föltehetően el is fáradok. Ha déli 12-kor ke zdek itthon kászálódni, és az éjjeli 12 táján érkezem vissza, testvérek között is a nap 24 órájának a fele. Ekkor jutott eszembe a vasút. Azt mondja az internet, <span class="marked">fél 7</span> előtt pár perccel is indul egy vonat, és ugyanúgy másfél óra alatt futja meg az utat Újszegedig, ahogy a busz teszi meg odaúton.', true, '06:30', '06:30', '06:30', 390, 390, 390, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-8992', 'Horváth Dezső', 'essays', 'https://mek.oszk.hu/06200/06298/06298.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hippokratész', 'https://mek.oszk.hu/06200/06298', 'Szíven ütött tehát a tévéműsornak az a pontja, amelyik 23 <span class="marked">10 -kor</span> ígérte a szóban forgó utazást.', true, '10:00', '10:00', '10:00', 600, 600, 600, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-8992', 'Horváth Dezső', 'essays', 'https://mek.oszk.hu/06200/06298/06298.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hippokratész', 'https://mek.oszk.hu/06200/06298', 'Át kellett tehát előbb konvertálnom a tizenkettes számrendszerre, hogy megtudjam, esti <span class="marked">tizenegy óra</span> után tíz perccel indul a menet.', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-8992', 'Horváth Dezső', 'essays', 'https://mek.oszk.hu/06200/06298/06298.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hippokratész', 'https://mek.oszk.hu/06200/06298', 'és loholhasson hírül adni ugyanazt a blöfföt az ő lapja is, amit az összes többi hírül ád. Védekezik a jámbor újságolvasó, nem veszi meg egyikét se, inkább leül rádiója vagy televíziója elé. Azelőtt nálunk este <span class="marked">fél nyolckor</span> nyílt ki a képernyő. Kürtölték már akkor a híradó szignálját. Ma inkább léggömbkilövőnek mondjuk ezt is, mert tengerkék semmiből forog elő a földgömböt imitáló léggömb. Azonnal tudjuk, annak sincsen magja, ami ezután', true, '19:30', '19:30', '19:30', 1170, 1170, 1170, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-8992', 'Horváth Dezső', 'essays', 'https://mek.oszk.hu/06200/06298/06298.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hippokratész', 'https://mek.oszk.hu/06200/06298', 'Az elmúlt hetekben erőt vettem magamon, már <span class="marked">hatkor</span> leültem a készülék elé, és végigpötyögtettem az összes híradót.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-8992', 'Horváth Dezső', 'essays', 'https://mek.oszk.hu/06200/06298/06298.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hippokratész', 'https://mek.oszk.hu/06200/06298', 'végül azonban, úgy hírlik, tisztességgel szenderült bele az örökkévalóságba. Nyugodjon békében. A sorompók kitolása Senki ne vádoljon ásatag nosztalgiával, amikor csúfondárosan elsóhajtom magamat: boldog öregátkos! <span class="marked">Fél nyolckor</span> már bent volt hivatalában a hadúr, piros levű golyóstoll ával aláhúzogatta a lapokban azokat a sorokat, amelyek piszkálták a csőrét.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-8992', 'Horváth Dezső', 'essays', 'https://mek.oszk.hu/06200/06298/06298.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hippokratész', 'https://mek.oszk.hu/06200/06298', 'amikor csúfondárosan elsóhajtom magamat: boldog öregátkos! Fél nyolckor már bent volt hivatalában a hadúr, piros levű golyóstoll ával aláhúzogatta a lapokban azokat a sorokat, amelyek piszkálták a csőrét. <span class="marked">Nyolckor</span> már nálunk csörrent, eligazítást szólván a dolgok helyes látásáról.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-8992', 'Horváth Dezső', 'essays', 'https://mek.oszk.hu/06200/06298/06298.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Maradék emberek az emberkertből', 'https://mek.oszk.hu/12700/12765', 'Flaviu egyébként szótlan, elég mogorva embernek tűnt, olyannak, akit csak néha villanyoz <span class="marked">fel egy</span>-egy téma, a továbbiakban pedig jobb szeret néma szemlélődő maradni.', true, '00:30', '00:30', '00:30', 30, 30, 30, '{"Szépirodalom, népköltészet","Határontúli magyar irodalom"}', 'urn:nbn:hu-123957', 'Igor Csaba, T.', 'short stories', 'https://mek.oszk.hu/12700/12765/12765.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Maradék emberek az emberkertből', 'https://mek.oszk.hu/12700/12765', 'csak több nap múltán. Érdekes azért volt a dolog, mert emberrablásról szó sem lehetett. Ő maga mondta az ismerőseinek, hogy most elmegy vagy két napra, mert várják valahova. Azóta se került elő. Kissé nagyobb port vert <span class="marked">fel egy</span> újabb hét után az, hogy Mare Flaviu és Cimpoiașu Ioan is eltűntek.', true, '00:30', '00:30', '00:30', 30, 30, 30, '{"Szépirodalom, népköltészet","Határontúli magyar irodalom"}', 'urn:nbn:hu-123957', 'Igor Csaba, T.', 'short stories', 'https://mek.oszk.hu/12700/12765/12765.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Maradék emberek az emberkertből', 'https://mek.oszk.hu/12700/12765', 'Nem kérdezősködök többet. De... ilyen cipővel aligha lehet. Menjen át a másik házba, s vegyen egy pár gumicsizmát! Van hol aludjon? - Nincs. - Nem baj, majd ott alszik a másik házban. Na menjen, mert mindjárt kezdenek. <span class="marked">Egy órakor</span> ebéd! Az jó, gondolta Zsóka, mert már kezdett is éhes lenni. Átment hát a hosszú barakkba, ott voltak a gumicsizmák kitéve. Kiválasztott egy olyan párat, ami nagyjából illett a lábára, felhúzta. Közben körülnézett. A', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Határontúli magyar irodalom"}', 'urn:nbn:hu-123957', 'Igor Csaba, T.', 'short stories', 'https://mek.oszk.hu/12700/12765/12765.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Maradék emberek az emberkertből', 'https://mek.oszk.hu/12700/12765', 'finomság volt érezhető a mozdulataiban. Olyan, amilyent Zsóka az elmúlt másfél év alatt egyetlen partnerétől sem tapasztalt. Aztán, a gazda finoman kézenfogta és lekísérte a hálóbarakkba. - Jó éjszakát! Reggel <span class="marked">fél nyolckor</span> kezdünk! - ezzel vált el tőle. A következő nap péntek volt. Nem is dolgoztak estig, csak úgy négy óráig. Ezután a szüretelők fizetésének a kiadása következett az éppen elmúlt hétre, majd a hétfő utáni munkák', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Határontúli magyar irodalom"}', 'urn:nbn:hu-123957', 'Igor Csaba, T.', 'short stories', 'https://mek.oszk.hu/12700/12765/12765.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Maradék emberek az emberkertből', 'https://mek.oszk.hu/12700/12765', 'Ebben a mostani időben éppen tél eleje volt. Karácsony közeledtével az idő egészen vigasztalanul szürke volt. Hó még nem esett, de az eget teljes egészében vastag felhők takarták el. Olyan vastagok, hogy reggel <span class="marked">kilenc órakor</span> még nem akaródzott az embernek felkelni, gondolva, hogy még éjszaka van.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Határontúli magyar irodalom"}', 'urn:nbn:hu-123957', 'Igor Csaba, T.', 'short stories', 'https://mek.oszk.hu/12700/12765/12765.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hajsza a detektív után', 'https://mek.oszk.hu/16600/16627', 'Igaz viszont, hogy végső megoldásként eladhatnám még Edith ékszereit is, de ha ilyen áldozatra kérném őt, ez elhidegítené tőlem és házaséletünk pokollá válnék. Nem, erről szó sem lehet, nyugodtan akarok élni. Reggel <span class="marked">nyolc óra</span> felé tehát felkerestem Roswellt, akit még ágyban találtam.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-140313', 'Galopin Arnould', 'novel', 'https://mek.oszk.hu/16600/16627/16627.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hajsza a detektív után', 'https://mek.oszk.hu/16600/16627', 'a bútoraimért csupán tízezer frankot kaptam és a különbözetet csak akkor bocsátom rendelkezésére, ha látom, hogy sikerrel kecsegtet az üzlet. Jelenlegi helyzetemben meg kell próbálnom minden lehetőséget... II. Reggel <span class="marked">10 óra</span> volt, amikor hazaértem a Rue Marbeuf-ra.', true, '10:00', '10:00', '10:00', 600, 600, 600, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-140313', 'Galopin Arnould', 'novel', 'https://mek.oszk.hu/16600/16627/16627.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hajsza a detektív után', 'https://mek.oszk.hu/16600/16627', 'Tehát holnap megnyitjuk az üzletet... de előbb néhány formaságot kellene elintéznem. Nagyon lekötelezne, ha erre a célra most átadna nekem kétezer frankot. - Itt van, tessék. - Köszönöm. Jöjjön értem holnap reggel <span class="marked">kilenc órakor</span>. Addig mindent előkészítek és ön éppen annyira tisztában lesz mindennel, mint jómagam. - Meglehetősen elmésnek találom ötletét, csak azt nem tudom, hogyan fogunk betevőket szerezni... - Ennél semmi sem egyszerűbb a', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-140313', 'Galopin Arnould', 'novel', 'https://mek.oszk.hu/16600/16627/16627.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hajsza a detektív után', 'https://mek.oszk.hu/16600/16627', 'takarékosan kell élnünk! - Talán azt akarja ezzel mondani, hogy én tettem tönkre?! - Nem erről van most szó... Ha azt akarja, hogy kiláboljunk a bajból, akkor egy ideig mérsékelnünk kell kiadásainkat... Nem válaszolt. <span class="marked">Egy óra</span> mulva már egy kis montmartre-i szálloda egyszerű, de aránylag kényelmesen bútorozott szobájában ültünk.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-140313', 'Galopin Arnould', 'novel', 'https://mek.oszk.hu/16600/16627/16627.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hajsza a detektív után', 'https://mek.oszk.hu/16600/16627', 'Tudtam, hogy sorozatos balszerencsém nagyon csökkentette előtte tekintélyemet, de most biztos voltam benne, hogy nemsokára újból a régi Edgar Pipe leszek számára, Edgar Pipe, akinek <span class="marked">egykor</span> oly gyakran mondogatta, haját simogatván: «Drága kis Edgarom, micsoda édes gazember vagy te...» Ez az édes gazember rövidesen újból meg fogja mutatni, hogy mit tud.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-140313', 'Galopin Arnould', 'novel', 'https://mek.oszk.hu/16600/16627/16627.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hajsza a detektív után', 'https://mek.oszk.hu/16600/16627', '- Látom, de nagyon veszélyes mesterséget választott... - Kockázat nélkül semmit sem lehet elérni. Három óra volt... Magamra kaptam felöltőmet és feltettem kalapomat. - Hova megy, Bobby... hát máris egyedül hagy? - <span class="marked">Egy óra</span> mulva visszajövök. - És ma éjjel? - Bizony, ma éjjel kénytelenek leszünk egymás társaságát nélkülözni, ami nagyon rosszul fog esni nekem, mert nem indulok valami kellemes kirándulásra... de remélem, megéri majd a', true, '13:00', '13:00', '13:00', 780, 780, 780, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-140313', 'Galopin Arnould', 'novel', 'https://mek.oszk.hu/16600/16627/16627.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hajsza a detektív után', 'https://mek.oszk.hu/16600/16627', 'mert hiszen Chancer maga fogja igazolni, hogy az ő jelenlétében tapogattam végig a pénzszekrényt. Határozottan okos gondolat volt visszatérnem a kastélyba: úgy éreztem, mintha súlyos kő esett volna le szívemről. <span class="marked">Egy óra</span> mulva megint otthon voltam. Felütöttem a vastag törvénykönyvet és megelégedéssel konstatáltam, hogy még mindig a helyén van valamennyi csinos kis ezerfrankos. - Még néhány ilyen sikeres üzlet, mondtam magamban és', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-140313', 'Galopin Arnould', 'novel', 'https://mek.oszk.hu/16600/16627/16627.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hajsza a detektív után', 'https://mek.oszk.hu/16600/16627', 'Gyorsan odébbálltam, mert vihart szimatoltam. Azt hiszem, ha nem sikerül rövidesen nagyobb összeghez jutnom, akkor házasságunk pokollá válik. Beugrottam egy taxiba és a St. Lazare-pályaudvarra vitettem magam. <span class="marked">Egy óra</span> tíz percet mutatott az óra, igazán nem volt veszíteni való időm.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-140313', 'Galopin Arnould', 'novel', 'https://mek.oszk.hu/16600/16627/16627.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hajsza a detektív után', 'https://mek.oszk.hu/16600/16627', 'folytathatta mindennapi ballépéseit. Ha minden magánnyomozó ilyen tökéletes titoktartással dolgozott volna, akkor erősen megcsappant volna a válások és egyéb tragikusan végződő házasságok és viszonyok száma. Már <span class="marked">nyolc óra</span> felé haladt az idő, amikor megszólalt a csengő az előszobában.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-140313', 'Galopin Arnould', 'novel', 'https://mek.oszk.hu/16600/16627/16627.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hajsza a detektív után', 'https://mek.oszk.hu/16600/16627', 'Éjféltájt elindultunk a Montmartre-ra és végiglátogattuk az éjjeli mulatóhelyeket, mint <span class="marked">egykor</span>, gazdagságunk idején. Edithnek kicsapongó jókedve volt: észrevette az ezres bankókat a tárcámban, amelyeket feleim gavallérságának köszönhettem és valószínűleg túlbecsülte számukat. Meg voltam róla győződve, hogy', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-140313', 'Galopin Arnould', 'novel', 'https://mek.oszk.hu/16600/16627/16627.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hajsza a detektív után', 'https://mek.oszk.hu/16600/16627', 'hallottam, mintha nehéz kapu csapódott volna be. Felcsillant bennem a remény, mert azt hittem, hogy a gróf végre sétára indult, de megint csalódtam, - pár perc mulva az öreg újból ott motoszkált a szomszéd szobában... <span class="marked">Egy óra</span> multán ismét bejött, letelepedett karosszékébe és csendesen horkolni kezdett.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-140313', 'Galopin Arnould', 'novel', 'https://mek.oszk.hu/16600/16627/16627.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hajsza a detektív után', 'https://mek.oszk.hu/16600/16627', 'Szerencsére hat órára már egészen besötétedik és Chancerék <span class="marked">fél nyolckor</span> szoktak asztalhoz ülni. Nézze, Edith, döntenünk kell, ezt a lehetetlen helyzetet amúgy sem bírom már sokáig folytatni. Minél többet gondolkozom a dolgon, annál egyszerűbbnek látom a megoldást. Különben is óvatos leszek', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-140313', 'Galopin Arnould', 'novel', 'https://mek.oszk.hu/16600/16627/16627.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hajsza a detektív után', 'https://mek.oszk.hu/16600/16627', 'Csak hajnaltájt nyomott el az álom és <span class="marked">tizenegy óra</span> felé járt már az idő, amikor felébredtem.', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-140313', 'Galopin Arnould', 'novel', 'https://mek.oszk.hu/16600/16627/16627.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hajsza a detektív után', 'https://mek.oszk.hu/16600/16627', 'volna és a kirándulásom is meghiúsult volna. Mureaux-ban kiszálltam. Alkonyodott. Attól féltem, hogy a csendőr is ugyanazt az utat fogja választani mint én, de szerencsére betért a söntésbe két úti társával. Most <span class="marked">hat óra</span> volt, tehát még jó másfél óra időm volt.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-140313', 'Galopin Arnould', 'novel', 'https://mek.oszk.hu/16600/16627/16627.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hajsza a detektív után', 'https://mek.oszk.hu/16600/16627', 'mielőtt elmegyünk, még válaszolnom kell annak az S. C.-nek. Majd meghívom ide holnapután délelőttre. - Hát nem Versaillesba akart menni holnapután? - De csak délután, délelőtt szabad vagyok. Edith öltözni ment. <span class="marked">Egy óra</span> mulva elkészült és bejött értem a dolgozószobámba.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-140313', 'Galopin Arnould', 'novel', 'https://mek.oszk.hu/16600/16627/16627.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hajsza a detektív után', 'https://mek.oszk.hu/16600/16627', 'életemben bambább embert még nem láttam. Továbbmentem, de nem mert követni. Érezte, hogy «leégett», hogy nevetségessé tettem és nem tudta, hogyan viselkedjék. Amikor hátrafordultam, még mindig ugyanazon a helyen állt. <span class="marked">Egy óra</span> mulva a versaillesi igazságügyi palotában voltam.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-140313', 'Galopin Arnould', 'novel', 'https://mek.oszk.hu/16600/16627/16627.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hajsza a detektív után', 'https://mek.oszk.hu/16600/16627', 'Nyomott hangulatban küldtem el Savarynénak a sürgős közlést: «Ha érdekli, asszonyom, az álbáró Pierrelatte hűsége, keresse fel őt holnap délelőtt <span class="marked">tizenegykor</span> lakásán. Egy jóakarója.» XXVIII. Másnap féltizenegykor Edith elment. Istenem, milyen csinos volt szenvedő arcocskája... Távollétének minden perce egész órának tűnt előttem. Irodámban úgy jártam fel és alá, mint a', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-140313', 'Galopin Arnould', 'novel', 'https://mek.oszk.hu/16600/16627/16627.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Hajsza a detektív után', 'https://mek.oszk.hu/16600/16627', 'veszélyes játékba. Nyomott hangulatban küldtem el Savarynénak a sürgős közlést: «Ha érdekli, asszonyom, az álbáró Pierrelatte hűsége, keresse fel őt holnap délelőtt tizenegykor lakásán. Egy jóakarója.» XXVIII. Másnap <span class="marked">féltizenegykor</span> Edith elment. Istenem, milyen csinos volt szenvedő arcocskája... Távollétének minden perce egész órának tűnt előttem. Irodámban úgy jártam fel és alá, mint a ketrecbezárt tigris. Negyed tizenkettőkor már el akartam', true, '10:30', '10:30', '10:30', 630, 630, 630, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-140313', 'Galopin Arnould', 'novel', 'https://mek.oszk.hu/16600/16627/16627.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Cilike mint asszony', 'https://mek.oszk.hu/14100/14150', 'meglátni, hanem még Abbáziát is! Az Európa-szálló terraszán ültek és kávéztak, mikor Laci ezt mondta s csak éppen a tekintélyes pincérek miatt nem perdült Cilike táncra. De a kávéscsészét majd feldöntötte örömében. <span class="marked">Egy óra</span> mulva már ott ültek a karcsu kis hajón, amely átvitte őket Fiuméból Abbáziába.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-133333', 'Tutsek Anna', 'novel', 'https://mek.oszk.hu/14100/14150/14150.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Cilike mint asszony', 'https://mek.oszk.hu/14100/14150', 'biztatta. - Siess, siess, én már meg is reggeliztem. Olyan éhes voltam, mint egy farkas! A te reggelid is vár már. Siess, kis álomszuszék! Én azalatt fölmegyek a fedélzetre, mindenki ott van már. Csodaszép idő van! <span class="marked">Egy óra</span> mulva már megérkezünk Velencébe.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-133333', 'Tutsek Anna', 'novel', 'https://mek.oszk.hu/14100/14150/14150.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Cilike mint asszony', 'https://mek.oszk.hu/14100/14150', 'Telt egyik perc a másik után, Cilikének olyan lassan, mintha minden perc <span class="marked">egy óra</span> lett volna. Úgy érezte, hogy már napok, hetek óta várakozik! Istenem, hol marad olyan soká Laci. A tolongás körülötte nemhogy apadt volna, hanem nőttön-nőtt. Valaki elkiáltotta magát: - Beszállás Budapest felé! Be', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-133333', 'Tutsek Anna', 'novel', 'https://mek.oszk.hu/14100/14150/14150.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Cilike mint asszony', 'https://mek.oszk.hu/14100/14150', 'Idő az volt elég, mert Kula felől csak <span class="marked">tizenegy órakor</span> este érkezett be a vonat, de olyan sötét volt már, hogy akkor sem láthattak volna semmit belőle, ha maga a paradicsomkert lett volna előttük.', true, '23:00', '23:00', '23:00', 1380, 1380, 1380, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-133333', 'Tutsek Anna', 'novel', 'https://mek.oszk.hu/14100/14150/14150.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Cilike mint asszony', 'https://mek.oszk.hu/14100/14150', 'velök, senki sem fog tudni róla. A haditervet következőképpen állapitották meg: Reggel hétkor indul Laci lóháton, Cilike és Ilonka kocsival utána; az országuton szépen egymás mellett haladhatnak a kocsi és a lovas. <span class="marked">Egy óra</span> alatt Ujvidéken vannak, onnan pedig vasúton - már amikor a vonat indul - Titelre mennek.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-133333', 'Tutsek Anna', 'novel', 'https://mek.oszk.hu/14100/14150/14150.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Cilike mint asszony', 'https://mek.oszk.hu/14100/14150', 'Igen, hiszen nem igy képzelték ők el <span class="marked">egykor</span> jövendő életüket... A várakozás hosszu évei alatt milyen rózsás képeket festettek maguk elé csendes, nyugalmas, békés családi életről, otthon - kis szülővárosukba - édesapa és édesanya közelében... ugyanugy, mint ahogy', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-133333', 'Tutsek Anna', 'novel', 'https://mek.oszk.hu/14100/14150/14150.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Cilike mint asszony', 'https://mek.oszk.hu/14100/14150', 'a lakásban ajtócsapkodás, jövés-menés zaja. Laci készen felöltözve éppen a kardját csatolta fel. - Próba-alarm, asszonykám, - nyugtatta meg Cilikét, aki ijedten ült föl ágyában. - Csak aludj nyugodtan tovább. Legkésőbb <span class="marked">egy óra</span> mulva itthon vagyok. Azzal már szaladt is, Cilike pedig álmosan, fázva, dideregve bujt vissza az ágyba s nyomban el is aludt, olyan mélyen, hogy csak arra ébredt föl, mikor Ilonka rázni, költögetni kezdte. - Ébredj,', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-133333', 'Tutsek Anna', 'novel', 'https://mek.oszk.hu/14100/14150/14150.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Cilike mint asszony', 'https://mek.oszk.hu/14100/14150', 'Ekkor átszaladt hozzám és tőlem kért kölcsön egy fehér ruhát, akkor tudtuk meg, hogy <span class="marked">egy óra</span> mulva lesz az esküvője. A déli vonattal már el is utaztak, a néni kétségbe volt esve, hogy Ilusnak nincs semmi stafirungja, de ők azt mondták, hogy majd utólag is el lehet mindent késziteni - és most Bécsben vannak,', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-133333', 'Tutsek Anna', 'novel', 'https://mek.oszk.hu/14100/14150/14150.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Cilike mint asszony', 'https://mek.oszk.hu/14100/14150', 'Józsi vigasztalólag szólt: - Most már nincs más hátra, mint szépen összecsomagolni s holnap reggel <span class="marked">fél nyolckor</span> indulunk. Nekem most dolgom van, délben majd felnézek magukhoz, s aztán együtt megyünk el ebédelni valamerre. Na ne búsuljanak, meglássák pár hónap mulva megint együtt leszünk mindnyájan! Búsan ballagtak haza az', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-133333', 'Tutsek Anna', 'novel', 'https://mek.oszk.hu/14100/14150/14150.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Cilike mint asszony', 'https://mek.oszk.hu/14100/14150', 'hogy majd én gondoskodom mindenről. - Hiszen az mindegy, - mosolygott Cilike, - most már aztán mi visszük ki magát a mi kocsinkon. Reggel hétre legyen készen! - Pontos leszek, mint egy katona, - mondta Józsi. - És <span class="marked">félegykor</span> ott leszek maguknál, s elmegyünk a Pannónia-szállóba ebédelni.', true, '00:30', '00:30', '00:30', 30, 30, 30, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-133333', 'Tutsek Anna', 'novel', 'https://mek.oszk.hu/14100/14150/14150.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Cilike mint asszony', 'https://mek.oszk.hu/14100/14150', 'a többi élelemhez, amit utravalónak vettek - és aztán gyorsan lefeküdtek. Másnap reggel még alig virradt, már fölkeltek, hogy hét órára, mire a kocsi rendelve volt, mindennel elkészüljenek. De hét óra elmult, <span class="marked">negyednyolc</span> is - a kocsi csak nem jelentkezett.', true, '07:15', '07:15', '07:15', 435, 435, 435, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-133333', 'Tutsek Anna', 'novel', 'https://mek.oszk.hu/14100/14150/14150.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Cilike mint asszony', 'https://mek.oszk.hu/14100/14150', '- De hiszen ha még sokáig várunk ugy elkésünk, - mondta Józsi, - <span class="marked">fél kilenckor</span> indul a vonat, s most már fél nyolc!', true, '08:30', '08:30', '08:30', 510, 510, 510, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-133333', 'Tutsek Anna', 'novel', 'https://mek.oszk.hu/14100/14150/14150.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Cilike mint asszony', 'https://mek.oszk.hu/14100/14150', '- De hiszen ha még sokáig várunk ugy elkésünk, - mondta Józsi, - fél kilenckor indul a vonat, s most már <span class="marked">fél nyolc</span>! Az állomás jó háromnegyed órányira van. Itt hamar intézkedni kell. Pista, - fordult aztán a katonához, - rakd össze a podgyászokat és hord ki rendre a kapu elé és vigyázz mindenre, amig visszajövünk. Cilike kérem,', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-133333', 'Tutsek Anna', 'novel', 'https://mek.oszk.hu/14100/14150/14150.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Cilike mint asszony', 'https://mek.oszk.hu/14100/14150', 'Közben telt-mult az idő, eltelt <span class="marked">egy óra</span>, két óra, indulásnak hire-nyoma sincs.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-133333', 'Tutsek Anna', 'novel', 'https://mek.oszk.hu/14100/14150/14150.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Cilike mint asszony', 'https://mek.oszk.hu/14100/14150', 'kell jönni. - Cilike, maga egy lángész! - kiáltott Józsi, - magának teljesen igaza van! Azzal már sietett is el, hogy beszéljen az állomás katonai parancsnokával. Cilike eszméje tényleg fényesen bevált. Nem telt bele <span class="marked">egy óra</span>, s a tüzoltóság már künn is volt, már szivattyuzták is a vizet a kútból, már kapott is a lokomotiv elegendő vizet, aztán be lehetett szállani s már indult is a vonat.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-133333', 'Tutsek Anna', 'novel', 'https://mek.oszk.hu/14100/14150/14150.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Cilike mint asszony', 'https://mek.oszk.hu/14100/14150', 'Hamarosan meg is tudták, hogy ma többet nem megy vonat; a legközelebbi - egy tehervonat - holnap délben <span class="marked">egy órakor</span> indul, de ez nem ajánlatos, mert ha a délután négykor induló gyorsvonatot várják be, azzal hamarább lesznek Budapesten, mert a tehervonatot Szabadkán utóléri a gyors és persze el is hagyja.', true, '13:00', '13:00', '13:00', 780, 780, 780, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-133333', 'Tutsek Anna', 'novel', 'https://mek.oszk.hu/14100/14150/14150.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Cilike mint asszony', 'https://mek.oszk.hu/14100/14150', '- Előbb telefonáljunk, vajjon ott vannak-e még a hivatalban, - szólt Józsi, - hiszen mindjárt <span class="marked">hat óra</span>! Bementek a kávéházba, Józsi telefonált, tényleg a határrendőrségnél már nem volt hivatalos óra, csak holnap reggel lehet odamenni. - Mennyi nehézség, mennyi nehézség mindenfelé! - sóhajtott Cilike a hajdani szép,', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-133333', 'Tutsek Anna', 'novel', 'https://mek.oszk.hu/14100/14150/14150.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Cilike mint asszony', 'https://mek.oszk.hu/14100/14150', 'felé a kis kormos kéményseprő és a szegény rongyos baka... VÉGE. A BOLDOGSÁG UTJA - Te vagy az, Márta? - Nem, nagymama; én vagyok, Gizi, - válaszol egy rózsás arcu, fiatal leányka, ki éppen a szobába lépett. - Márta <span class="marked">hat órakor</span> jön haza. Most még csak fél hat. - Még csak! - sóhajt az öreg asszony s szomoru arccal teszi félre a kötését. Szegény kötés! Már egy órája, hogy lehullottak a szemek, s az öreg vak asszony minden ujabb kisérletére,', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-133333', 'Tutsek Anna', 'novel', 'https://mek.oszk.hu/14100/14150/14150.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Cilike mint asszony', 'https://mek.oszk.hu/14100/14150', 'a szegény rongyos baka... VÉGE. A BOLDOGSÁG UTJA - Te vagy az, Márta? - Nem, nagymama; én vagyok, Gizi, - válaszol egy rózsás arcu, fiatal leányka, ki éppen a szobába lépett. - Márta hat órakor jön haza. Most még csak <span class="marked">fél hat</span>. - Még csak! - sóhajt az öreg asszony s szomoru arccal teszi félre a kötését. Szegény kötés! Már egy órája, hogy lehullottak a szemek, s az öreg vak asszony minden ujabb kisérletére, hogy rendbehozza, csak mind lejebb', true, '05:30', '05:30', '05:30', 330, 330, 330, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-133333', 'Tutsek Anna', 'novel', 'https://mek.oszk.hu/14100/14150/14150.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Cilike mint asszony', 'https://mek.oszk.hu/14100/14150', 'lehetett volna, - ha tudott volna akarni. De nem tudott akarni. Igen gyönge volt ahhoz. Ahelyett, hogy segitségére lett volna testvérének, csak folytonosan nehéz gondot, bánatot és bajt okozott neki. De miként <span class="marked">egykor</span> édesanyja, ugy Márta is az iránta való gyöngédségnek, szeretetnek kiapadhatatlan forrását őrizte szivében, bárha anyjánál erősebb és határozottabb természetü volt.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-133333', 'Tutsek Anna', 'novel', 'https://mek.oszk.hu/14100/14150/14150.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Cilike mint asszony', 'https://mek.oszk.hu/14100/14150', 'álmosnak s Gizit nagyon rosszkedvünek találta. Be is ment mindjárt szobájába s lefeküdt. Márta előbb segitett nagyanyjának levetkőzni, aztán ismét elővette foldozását. Meg akarta várni, mig Kálmán hazajön. Éjfél után <span class="marked">egy óra</span> már elmult, mikor hallotta a kulcsot megfordulni az előszoba ajtajában.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-133333', 'Tutsek Anna', 'novel', 'https://mek.oszk.hu/14100/14150/14150.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Cilike mint asszony', 'https://mek.oszk.hu/14100/14150', 'elkésziteni a reggelit. Aztán a bejáró asszonnyal, aki egyuttal főzött is nekik, megbeszélni az ebédet, amelynél a fő szempont volt mindig, hogy sokba ne kerüljön, mégis jó legyen. Közben elérkezett az indulás órája. <span class="marked">Kilenc órakor</span> volt az első leckéje és Márta maga volt a pontosság.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-133333', 'Tutsek Anna', 'novel', 'https://mek.oszk.hu/14100/14150/14150.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Tóték ; Macskajáték', 'https://mek.oszk.hu/06300/06350', 'a karunk, mozog a kezünk, és múlik az idő. Csöndben dolgoznak. Jól érzik magukat? MARISKA és ÁGIKA Mi nagyon! ŐRNAGY És a kedves Tót úr? Fényváltozás. POSTÁS oldalt feltűnik, órájára néz. Tizenegy múlt... És Tót úr <span class="marked">kilenckor</span> szokott lefeküdni... Komoran csóválja a fejét. Egy tábori lapot vesz elő. "Sötétedéskor, amikor legfenyegetőbb a partizánveszély, szórakozásra, társaságra vágyik. Ilyenkor nem szereti, ha valaki aludni megy, sőt, az', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-9240', 'Örkény István', 'plays', 'https://mek.oszk.hu/06300/06350/06350.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Tóték ; Macskajáték', 'https://mek.oszk.hu/06300/06350', 'vendégeink is elálmosodtak. ŐRNAGY Nekem ez se használ. Én a legszívesebben reggelig hajtogatnám a dobozokat. Tóték rémülten merednek rá. MARISKA Még hogy reggelig? TÓT bárgyún nevet. Hahaha... Fényváltozás. Elmúlt <span class="marked">egy óra</span>. ŐRNAGY Nincs későn? Szóljanak, kérem. ÁGIKA Nincs. Nincs. Nincs. MARISKA álmosan. De azért lassan-lassan kezdenek kialudni a gyantaszedők tábortüzei... ŐR NAGY Mondja meg a Tót úr. Ő is, a két nő is Tótra néz, aki nem', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-9240', 'Örkény István', 'plays', 'https://mek.oszk.hu/06300/06350/06350.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Tóték ; Macskajáték', 'https://mek.oszk.hu/06300/06350', 'Mondja meg a Tót úr. Ő is, a két nő is Tótra néz, aki nem reagál, Mariska megrázza. TÓT önfeledten hintázik. Hoppla hó... Hoppla hó... Észbe kap, fölrezzen. Nem szóltam semmit, őrnagy úr. Fényváltozás. Megint elmúlik <span class="marked">egy óra</span>. Tóték teljesen elcsigázva hajtogatják a dobozokat. ŐRNAGY El sem akartam hinni, amikor a maguk kedves fia biztatott, hogy itt nemcsak az egészségem fog helyreállni, hanem jól is fogom érezni magam... És mi történt?', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-9240', 'Örkény István', 'plays', 'https://mek.oszk.hu/06300/06350/06350.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Tóték ; Macskajáték', 'https://mek.oszk.hu/06300/06350', 'München ide majdnem száz kilométer, de azért este <span class="marked">8-kor</span>, német pontossággal, majdnem libasorban befutottak a parkba az autók.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-9240', 'Örkény István', 'plays', 'https://mek.oszk.hu/06300/06350/06350.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Tóték ; Macskajáték', 'https://mek.oszk.hu/06300/06350', 'parancsoló, elegáns jelenség. Előtte egy kis asztal - a telefonnal és néhány könyvvel. München ide majdnem száz kilométer, de azért este 8-kor, német pontossággal, majdnem libasorban befutottak a parkba az autók. <span class="marked">8.30</span>-kor a lány, nem az én Schwesterem, hanem a szobalány, kinyitotta az ebédlőajtót, és előbb engem gurított az asztalfőhöz, aztán én mutattam meg mindenkinek a helyét.', true, '08:30', '08:30', '08:30', 510, 510, 510, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-9240', 'Örkény István', 'plays', 'https://mek.oszk.hu/06300/06350/06350.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Tóték ; Macskajáték', 'https://mek.oszk.hu/06300/06350', 'is meg akarna zavarodni az idegrendszere. Bár tévednék. Tegnap (azóta nem volt időm befejezni ezt a levelet) Erzsike nagyban készült a csütörtöki vacsorára. Én, szokás szerint, segédkeztem neki. Ötven fánkot sütöttünk. <span class="marked">Fél nyolckor</span> Erzsike bement átöltözni, ami szintén így szokott történni.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-9240', 'Örkény István', 'plays', 'https://mek.oszk.hu/06300/06350/06350.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Tóték ; Macskajáték', 'https://mek.oszk.hu/06300/06350', 'időm befejezni ezt a levelet) Erzsike nagyban készült a csütörtöki vacsorára. Én, szokás szerint, segédkeztem neki. Ötven fánkot sütöttünk. Fél nyolckor Erzsike bement átöltözni, ami szintén így szokott történni. Pont <span class="marked">nyolckor</span>, szokás szerint, leszűrtem a tyúklevest, kihalásztam belőle a májat, amelyet egy kis külön levessel külön kis lábosba raktam.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-9240', 'Örkény István', 'plays', 'https://mek.oszk.hu/06300/06350/06350.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Tóték ; Macskajáték', 'https://mek.oszk.hu/06300/06350', 'kihalásztam belőle a májat, amelyet egy kis külön levessel külön kis lábosba raktam. Ez a nagy művész él-hal a csirkemájért... Megszólal a telefon. ORBÁNNÉ telefonál . Viktor? Maga az? Növekvő ingerültséggel. <span class="marked">Nyolc óra</span>, és maga még otthon van? Ezekből a fánkokból, amelyekre most öröm ránézni, tíz perc múlva töpörtyű lesz... Pamutipar? Micsoda Pamutipar? Ja úgy. Ez ek szerint magának a Pamutipar kórusa fontosabb. Köszönöm. EGÉRKE És', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-9240', 'Örkény István', 'plays', 'https://mek.oszk.hu/06300/06350/06350.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Elbeszélések', 'https://mek.oszk.hu/00300/00311', 'A kápolnában, ahol Csehország királyait koronázták <span class="marked">egykor</span>, és ahol Vencel király vértanúságot szenvedett, Laquedem felhívta figyelmemet a gemmás falakra: csupa achát és ametiszt.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2310', 'Apollinaire Guillaume', 'short stories', 'https://mek.oszk.hu/00300/00311/00311.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Elbeszélések', 'https://mek.oszk.hu/00300/00311', 'Az ébresztőórára pillantottam: tizen <span class="marked">egy óra</span> volt. Megmártottam fejem a mosdóban; miközben nedves hajamat dörzsöltem, az idegen úr így kiáltott: - Engem nem szokás megvárakoztatni! Kócos hajjal átsiettem a szobába; az ismeretlen úr épp a pástétom maradéka fölé', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2310', 'Apollinaire Guillaume', 'short stories', 'https://mek.oszk.hu/00300/00311/00311.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Elbeszélések', 'https://mek.oszk.hu/00300/00311', 'Erkölcseim patyolattiszták, mondtam, éjfél után <span class="marked">egy órakor</span> feküdtem le, egy perccel sem később.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2310', 'Apollinaire Guillaume', 'short stories', 'https://mek.oszk.hu/00300/00311/00311.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Elbeszélések', 'https://mek.oszk.hu/00300/00311', 'Igen ritkán kerül sor olyan kis teológiai viszályokra, amilyenek <span class="marked">egykor</span> eretnek vallások keletkezéséhez vezettek, pedig gyakran megesik, hogy katolikus papok kilépnek az Egyházból.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2310', 'Apollinaire Guillaume', 'short stories', 'https://mek.oszk.hu/00300/00311/00311.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Elbeszélések', 'https://mek.oszk.hu/00300/00311', 'Megparancsolta, hogy keressem <span class="marked">fel egy</span> hónap múltán. Szomorú voltam, és szégyenkeztem, visszatértem az üres kolostorba, és zokogtam. De a refrén - Három férfi volt... - megint ott szólt a lelkemben. Teljes erőmmel eltaszítottam - mint valami kísértést.', true, '00:30', '00:30', '00:30', 30, 30, 30, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2310', 'Apollinaire Guillaume', 'short stories', 'https://mek.oszk.hu/00300/00311/00311.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Elbeszélések', 'https://mek.oszk.hu/00300/00311', 'szokás nevezni, édesebb volt, mint az olasz, pedig azt a hölgyek nyelvének mondj ák. S mivel hannoveri tájszólásban beszélt, ahol az sz -t sohasem ejtik s -nek, szavai csakugyan bűbájosan csengtek. Ilse apja <span class="marked">egykor</span> Amerikában élt, ott feleségül vett egy angol leányt, majd egy esztendő múlva hazajött a szülői házba.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2310', 'Apollinaire Guillaume', 'short stories', 'https://mek.oszk.hu/00300/00311/00311.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Elbeszélések', 'https://mek.oszk.hu/00300/00311', 'Egy fiúcska, aki betegség folytán ol y kopasz lett, mint Caesar volt <span class="marked">egykor</span>, dorombjának patkóját fogai közé szorította, és jobbjával pengette a hangszert, így kísérvén a jámbor éneket.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2310', 'Apollinaire Guillaume', 'short stories', 'https://mek.oszk.hu/00300/00311/00311.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Elbeszélések', 'https://mek.oszk.hu/00300/00311', 'volna, csak fokozták kíváncsiságomat. - De hát miért van szüksége arra, hogy ilyen gyorsan le tudja vetni a ruháját? - töprengtem. És mindenféle feltételezés fordult meg agyamban... Egy éjjel, hazafelé menet - <span class="marked">egy óra</span> lehetett, talán negyed kettő -, a nevemet hallottam, igen halkan.', true, '13:00', '13:00', '13:00', 780, 780, 780, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2310', 'Apollinaire Guillaume', 'short stories', 'https://mek.oszk.hu/00300/00311/00311.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Elbeszélések', 'https://mek.oszk.hu/00300/00311', 'elkísérni és megnézni a kosarát... az ön ellenőrzésével, persze, a lakásán. - Nincs kifogásom ellene - felelte. - De ne zavarjon; kövessen, és egy szót se szóljon. Engedelmeskedtem. Reggel kilencig bolyongtunk így. <span class="marked">Hat óra</span> körül a Vásárcsarnok környékére értünk.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2310', 'Apollinaire Guillaume', 'short stories', 'https://mek.oszk.hu/00300/00311/00311.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Elbeszélések', 'https://mek.oszk.hu/00300/00311', 'rongyokba öltözött férfi térdelt egy szemétdomb előtt, rothadt élelmiszermaradékokat keresgélt, s amit csak talált, mohón felfalta. Nem viselt kalapot, haja kétoldalt lelógott - olyan vörös volt, mint a Krisztusé. <span class="marked">Fél nyolckor</span> az Austerlitz-hídon egy báránybőrrel megrakott szekér haladt el mellettünk, melynek bűze - bár elég szemetet szagoltam hajnal óta - elborzasztott.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2310', 'Apollinaire Guillaume', 'short stories', 'https://mek.oszk.hu/00300/00311/00311.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Elbeszélések', 'https://mek.oszk.hu/00300/00311', 'Gyalog jártam be Toszkána jó részét, s egy este <span class="marked">hat óra</span> felé kedves kisvárosba érkeztem; úgy terveztem, hogy itt alszom.', true, '18:00', '18:00', '18:00', 1080, 1080, 1080, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2310', 'Apollinaire Guillaume', 'short stories', 'https://mek.oszk.hu/00300/00311/00311.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Elbeszélések', 'https://mek.oszk.hu/00300/00311', 'Égő tekintetüket a Messiásra szögezték, szívük ujjongott, a nők, gyermekek, aggastyánok megragadták egymás kezét, és szorosan összefonódva táncolni kezdtek, mint <span class="marked">egykor</span> Dávid a frigyszekrény előtt, "Hozsánna!" énekelték , és víg himnuszokat daloltak...', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2310', 'Apollinaire Guillaume', 'short stories', 'https://mek.oszk.hu/00300/00311/00311.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Elbeszélések', 'https://mek.oszk.hu/00300/00311', 's a rendőrség utasítása ellenére, mely minden hírközlést megtiltott, így kiáltoztak: - Meghalt a Messiás! Fantasztikus részletek a Messiás hirtelen haláláról! Ereimben megfagyott a vér, és ájultan összerogytam. Hajnali <span class="marked">egy óra</span> körül ocsúdtam fel, s amikor megérintettem magam mellett a holttestet, megremegtem az irtózattól.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2310', 'Apollinaire Guillaume', 'short stories', 'https://mek.oszk.hu/00300/00311/00311.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Naplók, levelek', 'https://mek.oszk.hu/00400/00417', 'Pont félúton van, a vonatok pont ellenvonatai egymásnak, mindkettőnk, Maga is, én is, négy óra körül indulunk otthonról és hét órakor - én <span class="marked">fél nyolc</span> tájt - érkezünk Gmündbe. Másnap este aztán ugyanúgy utazunk, csak vonatot váltva, haza. Nekem nagyon tetszik ez, csak az nem, hogy ugyanolyan hosszú utazás terhét rovom ki Magára is, mint magamra. De hátha Magának', true, '19:30', '19:30', '19:30', 1170, 1170, 1170, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2416', 'Kafka Franz', 'diary', 'https://mek.oszk.hu/00400/00417/html/03.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Naplók, levelek', 'https://mek.oszk.hu/00400/00417', 'Akkor pedig (a lehető leghamarabb, tehát, mondjuk, már <span class="marked">fél nyolckor</span>, ismét az Askanischer Hofban szállok meg) találkozzunk ott, ahol Te akarod.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2416', 'Kafka Franz', 'diary', 'https://mek.oszk.hu/00400/00417/html/03.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Naplók, levelek', 'https://mek.oszk.hu/00400/00417', 'olyan lazán, mintha elég volna csak finoman kifordítanom a zsebeimet, és ismét nyomban kiesnének. Bezártam az üzletet, az alkalmazottak, idegen emberek, kalapjukkal a kezükben távolodtak. Júniusi este volt, már este <span class="marked">nyolc óra</span> ugyan, de még világos. Nem volt kedvem sétálni, soha sincs kedvem sétálni, de haza sem akartam menni. Mikor az utolsó tanoncom is befordult a sarkon, a bezárt bolt előtt leültem a földre. Egy ismerősöm arra jött a', true, '20:00', '20:00', '20:00', 1200, 1200, 1200, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2416', 'Kafka Franz', 'diary', 'https://mek.oszk.hu/00400/00417/html/03.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Naplók, levelek', 'https://mek.oszk.hu/00400/00417', 'Bruder elöljárósági tisztviselő csak este <span class="marked">kilenc óra</span> tájban tért haza az irodájából.', true, '21:00', '21:00', '21:00', 1260, 1260, 1260, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2416', 'Kafka Franz', 'diary', 'https://mek.oszk.hu/00400/00417/html/03.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Naplók, levelek', 'https://mek.oszk.hu/00400/00417', 'Maga ott ül az irodájában, és a körmére koppint a tanítványainak, én ellenben - ma különlegesen csöndes nap volt - <span class="marked">egy óra</span> hosszat küszködtem, persze hiába, az alvással, aztán uszodába mentem, úsztam, majd tornáztam, majd a séta után aludttejet ittam egy tejcsarnokban, most pedig itt ülök a parkban, és írok Magának.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2416', 'Kafka Franz', 'diary', 'https://mek.oszk.hu/00400/00417/html/03.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Naplók, levelek', 'https://mek.oszk.hu/00400/00417', 'Különben a priccsen feküdtem, nem gondoltam sem a múltra, sem a vasútra, a legközelebbi vonat csak este tíz és <span class="marked">tizenegy óra</span> között haladt át, egyszóval nem gondoltam semmire.', true, '23:00', '23:00', '23:00', 1380, 1380, 1380, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2416', 'Kafka Franz', 'diary', 'https://mek.oszk.hu/00400/00417/html/03.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Naplók, levelek', 'https://mek.oszk.hu/00400/00417', 'az időbeosztásom: fél háromig hivatal, utána ebéd ottho n, utána egy vagy két óra újságolvasás, levélírás vagy hivatali munka, utána fel a lakásomba (Te is ismered) aludni vagy csak úgy heverészni alvás nélkül, utána <span class="marked">kilenckor</span> le a szüleimhez vacsorázni (jó sétaút), tízkor megint vissza villamossal, s utána virrasztás, ameddig az erőm vagy a másnap délelőttől, a hivatali fejfájástól való rettegés engedi.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2416', 'Kafka Franz', 'diary', 'https://mek.oszk.hu/00400/00417/html/03.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Naplók, levelek', 'https://mek.oszk.hu/00400/00417', 'Délután levél E.-nek, átnéztem Pick A vak vendég című történetét, és javításokat jegyeztem föl, olvastam egy kicsit Strindbergtől, utána nem aludtam, <span class="marked">fél kilenckor</span> otthon, tíz órakor vissza, a fejfájástól való félelmemben, amely már kezdődik, és mert éjjel is nagyon keveset aludtam, már nem dolgoztam, részben azért sem, mert féltem, hogy elrontok egy tegnap írt, tűrhető részt.', true, '08:30', '08:30', '08:30', 510, 510, 510, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2416', 'Kafka Franz', 'diary', 'https://mek.oszk.hu/00400/00417/html/03.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Naplók, levelek', 'https://mek.oszk.hu/00400/00417', 'Az örökös próbálkozás, hogy sok délutáni alvással késő éjszakáig dolgozhassam, értelmetlen volt, hiszen már az első két hét után láthattam, az idegeim nem engedik meg, hogy <span class="marked">egy óra</span> után térjek aludni, mert ilyenkor már egyáltalán nem alszom el, a másnap elviselhetetlen, és tönkreteszem magam.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2416', 'Kafka Franz', 'diary', 'https://mek.oszk.hu/00400/00417/html/03.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Naplók, levelek', 'https://mek.oszk.hu/00400/00417', 'Túlságosan sokáig feküdtem tehát délután, éjjelente viszont ritkán dolgoztam egy óránál tovább, de legkorábban mindig <span class="marked">tizenegy óra</span> tájban fogtam hozzá. Ez tévedés volt. Nyolc vagy kilenc órakor kell elkezdenem, az éjszaka kétségkívül a legalkalmasabb idő (szabadság !), de hozzáférhetetlen számomra. Szombaton látni fogom F.-et. Ha szeret, nem', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2416', 'Kafka Franz', 'diary', 'https://mek.oszk.hu/00400/00417/html/03.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Naplók, levelek', 'https://mek.oszk.hu/00400/00417', 'és tönkreteszem magam. Túlságosan sokáig feküdtem tehát délután, éjjelente viszont ritkán dolgoztam egy óránál tovább, de legkorábban mindig tizenegy óra tájban fogtam hozzá. Ez tévedés volt. Nyolc vagy <span class="marked">kilenc órakor</span> kell elkezdenem, az éjszaka kétségkívül a legalkalmasabb idő (szabadság !), de hozzáférhetetlen számomra.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2416', 'Kafka Franz', 'diary', 'https://mek.oszk.hu/00400/00417/html/03.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Naplók, levelek', 'https://mek.oszk.hu/00400/00417', 'Nagyon szép vo lna tőled, ha reggel - a házmesterné ugyanis aligha fog felkelteni - egy kellemes, derűs álommal idejében, úgy <span class="marked">fél nyolc</span> tájt ébresztenél. Ha lehet, úgy intézd, hogy az álom, mielőtt felébrednék tőle, véget is érjen, és mindkettőnknek meghozza a valahol már készülődő boldog befejezést. Sokszor üdvözöllek, Franz [A lapszélen]: Werfel', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2416', 'Kafka Franz', 'diary', 'https://mek.oszk.hu/00400/00417/html/03.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Naplók, levelek', 'https://mek.oszk.hu/00400/00417', 'semmire a munkámmal, s így a lakásnak sem a csöndjét, sem a zaját nem volt módom kitapasztalni, hanem inkább a saját belső nyug talanságom, de ezt az érzést inkább nem boncolgatom. [...] Napló Március 13 . Egy este: <span class="marked">hat órakor</span> lefeküdtem a kanapéra. Mintegy nyolc óráig aludtam. Képtelen voltam felkelni, az óraütésre vártam, és kábulatomban semmit sem hallottam meg. Kilenckor felkeltem. Nem mentem már haza vacsorára, Maxhoz sem, ahol ma', true, '18:00', '18:00', '18:00', 1080, 1080, 1080, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2416', 'Kafka Franz', 'diary', 'https://mek.oszk.hu/00400/00417/html/03.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Naplók, levelek', 'https://mek.oszk.hu/00400/00417', 'érzést inkább nem boncolgatom. [...] Napló Március 13 . Egy este: hat órakor lefeküdtem a kanapéra. Mintegy nyolc óráig aludtam. Képtelen voltam felkelni, az óraütésre vártam, és kábulatomban semmit sem hallottam meg. <span class="marked">Kilenckor</span> felkeltem. Nem mentem már haza vacsorára, Maxhoz sem, ahol ma összejövetel volt. Okok: étvágytalanság, félelem a késő esti hazatéréstől, de mindenekelőtt az a gondolat, hogy tegnap nem írtam semmit, egyre jobban', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2416', 'Kafka Franz', 'diary', 'https://mek.oszk.hu/00400/00417/html/03.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Naplók, levelek', 'https://mek.oszk.hu/00400/00417', 'De tíz órakor befejezik, eddig legalábbis így volt, megesett, hogy m ár <span class="marked">kilenckor</span> abbahagyták, és akkor, ha még bírják az idegeim, élvezhetik a csodálatos csöndet.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2416', 'Kafka Franz', 'diary', 'https://mek.oszk.hu/00400/00417/html/03.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Nyakigláb Apó', 'https://mek.oszk.hu/02000/02039', 'azt mondta, hogy te ezt elvárod tőlem), de éppen most ütötte el az óra a hetet, és tíz perc múlva indulnom kell, tornaruhában, az atlétikai pályára. Gondolod, hogy bejuthatok a csapatba? A te Jerusha Abbottod Ui. (<span class="marked">9 óra</span>.) Sally McBricte éppen most dugta be fejét az ajtómon.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Gyermek- és ifjúsági irodalom"}', 'urn:nbn:hu-4023', 'Webster Jean', 'novel', 'https://mek.oszk.hu/02000/02039/html/index.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Nyakigláb Apó', 'https://mek.oszk.hu/02000/02039', '(Szól a kápolnába hívó harang.) <span class="marked">9 óra 45 perc</span> Egy új, törhetetlen fogadalmat tettem magamban: ezentúl este soha, sohasem fogok tanulni, bármennyi munkám gyűlik is össze a nap folyamán.', true, '09:45', '09:45', '09:45', 585, 585, 585, '{"Szépirodalom, népköltészet","Gyermek- és ifjúsági irodalom"}', 'urn:nbn:hu-4023', 'Webster Jean', 'novel', 'https://mek.oszk.hu/02000/02039/html/index.htm', 'deep_extract', false);
