INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Nyakigláb Apó', 'https://mek.oszk.hu/02000/02039', 'Bárki földjén átjárhatok, bárki tulajdonának szépségét megbámulhatom, bárki patakjába belegázolhatok; és éppen úgy élvezhetem mindezt, mintha az én tulajdonom lenne - és még fizetnem sem kell érte. Vasárnap este van, <span class="marked">tizenegy óra</span> elmúlt, és a házban azt hiszik, hogy már valami szépet álmodom, de feketekávét ittam vacsora után - és így a szép álomból nem lett semmi.', true, '23:00', '23:00', '23:00', 1380, 1380, 1380, '{"Szépirodalom, népköltészet","Gyermek- és ifjúsági irodalom"}', 'urn:nbn:hu-4023', 'Webster Jean', 'novel', 'https://mek.oszk.hu/02000/02039/html/index.htm', 'deep_extract', false);
