INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Bezzeg az én időmben', 'https://mek.oszk.hu/02400/02483', 'Itt állok mezítláb, bokáig érő rózsaszínű hálóingben, mindjárt <span class="marked">fél nyolc</span>, első óra történelem, a kedvenc tantárgyam, a kedvenc tanárnőm...', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4534', 'Fehér Klára', 'novel', 'https://mek.oszk.hu/02400/02483/02483.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Bezzeg az én időmben', 'https://mek.oszk.hu/02400/02483', 'kávét az utcán issza... Már egy alig használt fehérneműdarab is jól jönne, akárkié. Kinyitom a szennyesládát. De ott sincs semmi. Minden a kádban, nagymosáshoz áztatva. És a szekrényeken lakat. Hol lehetnek a kulcsok? <span class="marked">Háromnegyed nyolc</span>. Boda olyan pontosan jön be az órára. Kár is ma iskolába menni. Mi lenne, ha visszafeküdnék az ágyba? Gyermekem hiányos öltözéke miatt a novemberi hidegben nem mehetett iskolába... Ezt nem, inkább a halált, de ezt nem!', true, '07:45', '07:45', '07:45', 465, 465, 465, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4534', 'Fehér Klára', 'novel', 'https://mek.oszk.hu/02400/02483/02483.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Bezzeg az én időmben', 'https://mek.oszk.hu/02400/02483', 'hogy minden szekrény zárva legyen. Anyu sose zárja be a fiókját. Érdekes, most igen. De talán az én szekrényemben is akad még valami. Nem baj, ha kicsit rongyos. Nem, sajnos, a kicsit rongyost már tegnap felvettem... <span class="marked">Háromnegyed nyolc</span> múlt. Még egy... egy nagyszerű ötlet! Apu fehérneműi. Ing... nem, ezt nem tudom használni... atlétatrikó... ez kombinénak megtenné, és... és... hát igen... tizenöt éves vagyok, de még sose volt a kezemben férfiholmi.', true, '07:45', '07:45', '07:45', 465, 465, 465, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4534', 'Fehér Klára', 'novel', 'https://mek.oszk.hu/02400/02483/02483.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Bezzeg az én időmben', 'https://mek.oszk.hu/02400/02483', 'Ági! Kovács Ági integet messziről. Bevárom, úgyis mindegy. - Hová rohansz? - kérdi Ági, és liheg közben. - Hová, te víziló? Hát első óránk történelem... - Dehogyis... Még a múlt héten kihirdették, hogy elmarad. <span class="marked">Fél kilenckor</span> orvosi vizsgálat. - Micsoda? - állok meg, és kiver a veríték. Tényleg... ma csütörtök van... a múlt héten kihirdették. - Na, mi az? - bámul Ági. - Mit vágsz ilyen rémült képet? Csak kellemesebb az orvosiba menni, mint', true, '08:30', '08:30', '08:30', 510, 510, 510, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4534', 'Fehér Klára', 'novel', 'https://mek.oszk.hu/02400/02483/02483.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Bezzeg az én időmben', 'https://mek.oszk.hu/02400/02483', 'Hétfőn reggel Zsóka első órája mértan, akkor nála van a körzőkészlet, és azt <span class="marked">kilenckor</span> átviszi Marinak. Mariv al az udvar közepén találkozik, mert Mari akkor már szalad énhozzám, és hozza a földrajzi atlaszt, én azalatt a tornaöltöző ablakán kiadom neki a német szótárt, mert nekünk az első óránk német,', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4534', 'Fehér Klára', 'novel', 'https://mek.oszk.hu/02400/02483/02483.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Bezzeg az én időmben', 'https://mek.oszk.hu/02400/02483', 'Zsóka is, Mari is úgy issza a kávét, mintha még hajnali <span class="marked">hat óra</span> volna. De ha gyorsan innák is, akkor sem várhatom meg őket, mert le kell operálnom a kabátomról a Regendorf haját. A Regendorf haja, az egy rozsdaszínű szőrmedarab, életem egyik megkeserítője. Marinak is, Zsókának is', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4534', 'Fehér Klára', 'novel', 'https://mek.oszk.hu/02400/02483/02483.htm', 'deep_extract', false);
