INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Bezzeg az én időmben', 'https://mek.oszk.hu/02400/02483', 'Rozmár Róbertnek hívják, és szerencsét hoz. - Köszönöm szépen. Eltehetem? - Muszáj eltenni, mert különben náthás lesz. Van zsebe? - De mekkora - nyugtattam meg, és becsúsztattam Rozmár Róbertet a Regendorf hajához. <span class="marked">Fél tizenegykor</span> kezdődik a mozi. Bőven van időnk. A Tisza Kálmán téren fél méter vastag hótakaró. Jó volna hólabdát készíteni , megdobni egymást, de vigyázni kell a kabátomra. Ezt megmondom Lacinak is. - Jó - mondja -, azért', true, '10:30', '10:30', '10:30', 630, 630, 630, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4534', 'Fehér Klára', 'novel', 'https://mek.oszk.hu/02400/02483/02483.htm', 'deep_extract', false);
