INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Pacsirta', 'https://mek.oszk.hu/00700/00754', 'a Magyar Király előtt, s a jó időről meg a rossz időről beszélgetve, a Baross kávéházig kísérte, és Pacsirta, a szülei boldog meglepetésére, pár perc késedelemmel érkezett haza a vacsorához, melyet rendszerint <span class="marked">nyolc óra</span> tájban szoktak elkölteni. Vajkayék ezt nem tudták elfelejteni. Évek múlva is erre a titokzatos esti sétára gondoltak, és Cifra Gézát családi legendával övezték, mely egyre nőtt bennük, anélkül, hogy valami is táplálná.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2753', 'Kosztolányi Dezső', 'novel', 'https://mek.oszk.hu/00700/00754/00754.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Pacsirta', 'https://mek.oszk.hu/00700/00754', 'De anya mosolygott rá, szívesen, marasztalóan, mint <span class="marked">egykor</span>, régen. - Nem késik a vonat? - kérdezte tőle. - Nem - felelt Cifra Géza. Erre úgy képzelte, hogy most már igazán mehet. Tisztelegni akart, aztán mégis inkább megemelte sapkáját, civilmódra. A két öreg kifelé indult.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2753', 'Kosztolányi Dezső', 'novel', 'https://mek.oszk.hu/00700/00754/00754.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Pacsirta', 'https://mek.oszk.hu/00700/00754', 'megjegyzését. Vállat vont. Majd alig hallhatóan mondta: - Ugyan. Zsebóráját nézegette. - Mit is mondott? - kérdezte. - Kicsoda? - Ő - szólt az öregúr, és felesége megértette, hogy Cifra Gézáról van szó. - Öt húszkor. - <span class="marked">Fél hat</span> - felelt az apa -, most érkezett meg.', true, '05:30', '05:30', '05:30', 330, 330, 330, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2753', 'Kosztolányi Dezső', 'novel', 'https://mek.oszk.hu/00700/00754/00754.htm', 'deep_extract', false);
