INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Pacsirta', 'https://mek.oszk.hu/00700/00754', 'Rendetlenül folyt a háztartás, már elmúlt <span class="marked">egy óra</span>, és csak most lett készen. Nem volt benne gyakorlata. Halkan lépett be. Azt hitte, hogy ura elszenderedett. De Ákos a zajra ijedten nyitotta föl szemét. - Aludtál? - kérdezte tőle az asszony. - Nem. - Azt hittem,', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2753', 'Kosztolányi Dezső', 'novel', 'https://mek.oszk.hu/00700/00754/00754.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Pacsirta', 'https://mek.oszk.hu/00700/00754', 'színlap, megállapodtak. Figyelemmel olvasták: A GÉSÁK, vagy egy japán teaház története. ÉNEKES JÁTÉK HÁROM FELVONÁSBAN Írta: Owen Hall. Zenéjét szerzette: Sidney Jones. Fordították: Fáy Béla és Makai Emil. Kezdete este <span class="marked">fél 8-kor</span>, vége 10 után. Zányi nem játszott, amit sajnáltak. Csak Szolyvay. A többi színészt nem ismerték. HATODIK FEJEZET (melyben Vajkayék a Gésák sárszegi előadását nézik végig) Hétfőn délután beszélgettek. - Neked azonban', true, '19:30', '19:30', '19:30', 1170, 1170, 1170, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2753', 'Kosztolányi Dezső', 'novel', 'https://mek.oszk.hu/00700/00754/00754.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Pacsirta', 'https://mek.oszk.hu/00700/00754', 'Zegzugos boltíveken át botorkáltak, míg a fogadó első emeletére értek, a vörös márvány lépcsőre, melynek széles fokain <span class="marked">egykor</span> Ákos feleségével, leányával a bálterembe ment.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2753', 'Kosztolányi Dezső', 'novel', 'https://mek.oszk.hu/00700/00754/00754.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Pacsirta', 'https://mek.oszk.hu/00700/00754', 'Nem okozott bennük nagyobb izgalmat ilyen találkozás, mintha egy család tagjai látják egymást a közös lakásban. Csak az volt a kérdés, mikor találkoznak. Mindenkinek megvolt a maga órája. Mályvády például mindig <span class="marked">fél nyolckor</span> haladt át a téren diákjaival, kikhez éppoly barátian nyájas volt az iskolán kívül, amilyen szigorú az iskolában.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2753', 'Kosztolányi Dezső', 'novel', 'https://mek.oszk.hu/00700/00754/00754.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Pacsirta', 'https://mek.oszk.hu/00700/00754', 'levegőt, megölt. Szunyogh nyolc után jelent meg, és hallván a gimnázium kis harangját, mely az előadás kezdetét jelezte, sokszor szaladt is föltűrt gallérú felöltőjében, mivel félt az igazgatótól, és nem mert elkésni. <span class="marked">Kilenckor</span> Gál doktor jelent meg. Tízkor Priboczay végezte már ismert körömtisztogatási műveletét a patika előtt. Tizenegy órakor Környey tűnt föl, többnyire könnyű gigjén, melyet maga hajtott, s egy erős tűzoltó-paripa, egy', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2753', 'Kosztolányi Dezső', 'novel', 'https://mek.oszk.hu/00700/00754/00754.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Pacsirta', 'https://mek.oszk.hu/00700/00754', 'jelezte, sokszor szaladt is föltűrt gallérú felöltőjében, mivel félt az igazgatótól, és nem mert elkésni. Kilenckor Gál doktor jelent meg. Tízkor Priboczay végezte már ismert körömtisztogatási műveletét a patika előtt. <span class="marked">Tizenegy órakor</span> Környey tűnt föl, többnyire könnyű gigjén, melyet maga hajtott, s egy erős tűzoltó-paripa, egy vasder es, villámgyorsan röpített.', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2753', 'Kosztolányi Dezső', 'novel', 'https://mek.oszk.hu/00700/00754/00754.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Pacsirta', 'https://mek.oszk.hu/00700/00754', 'tegnapi futó színházi bemutatkozás ellenére is sokat foglalkoztatta Vajkay Ákost. Valaha térdeire ültette, barackokat nyomott fejére. De ez régen volt. Nem említette neki, és ő bizonyára nem is emlékezett rá. Vajkayék <span class="marked">egykor</span> sokat jártak az Ijas-házba, az ő tiszta, vendégszerető otthonukba, a tarligeti villájukba, míg egy sötét véletlen el nem söpörte a híres, gyönyörű családot.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2753', 'Kosztolányi Dezső', 'novel', 'https://mek.oszk.hu/00700/00754/00754.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Pacsirta', 'https://mek.oszk.hu/00700/00754', 'a nyomdába, hog y legyen olvasnivalójuk a sárszegi parasztoknak is. Ijasnak csak a budapesti telefont kellett még felvennie a Dreyfus-pör tárgyalásáról meg a legújabb politikai eseményekről. Iparkodott, mert a telefon <span class="marked">kilenckor</span> szokott jelentkezni. NYOLCADIK FEJEZET (melyben Pacsirta levele olvasható, teljes terjedelmében) Ákos másnap délután épp indult hazulról, mikor a kapuban eléje jött a levélhordó. Ajánlott levelet hozott. Pacsirta írt.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2753', 'Kosztolányi Dezső', 'novel', 'https://mek.oszk.hu/00700/00754/00754.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Pacsirta', 'https://mek.oszk.hu/00700/00754', 'rendszerint emelkedettebb, lelkesebb lett, mint ahogy akarta. Ákos megint elolvasta a hosszú levelet, melyben Pacsirta mindenről részletesen beszámolt. Így: Tarkövi puszta, 1899 szeptember 4. Hétfő este, <span class="marked">fél 7</span> órakor. Édes jó szüleim! Bocsássatok meg, hogy most írok tinektek, de eddig annyira elfoglalt a pusztai élet sok öröme, és vendéglátó rokonaim annyira gondoskodtak szórakoztatásomról, hogy levélírásra csak ma este', true, '18:30', '18:30', '18:30', 1110, 1110, 1110, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2753', 'Kosztolányi Dezső', 'novel', 'https://mek.oszk.hu/00700/00754/00754.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Pacsirta', 'https://mek.oszk.hu/00700/00754', 'Szüretre készülődnek, a hordókat már kihozták a pincékből, Béla bácsi nagyban kénezi a dongáit. Hallom, nagy szüreti mulatság lesz, jó termés ígérkezik. Most pedig elmondom, hogy töltöm itteni napjaim. Korán kelek, már <span class="marked">hatkor</span>, nézem a fönséges napfölkeltét, sétálgatok Etelka nénivel, majd segédkezem a háztartásban.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2753', 'Kosztolányi Dezső', 'novel', 'https://mek.oszk.hu/00700/00754/00754.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Pacsirta', 'https://mek.oszk.hu/00700/00754', 'Roppant tartóztatnak, veszekednek velem, hogy még egy hétig legyek a vendégük, de én, bármily kellemes lenne még egy kis üdülés, semmi szín alatt nem maradok tovább, péntek este ígéretemhez híven otthon leszek a félkilences (<span class="marked">8 óra 25 perc</span>) vonattal. Alig várom, hogy újra szívemre ölelhesselek mindkettőtöket. Sietek zárni soraimat. Még ma éjszaka el akarom küldeni a kocsissal, ki éjfél után áthajt Tarkőre a leányokért. Sokszor csókol és ölel titeket', true, '08:25', '08:25', '08:25', 505, 505, 505, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2753', 'Kosztolányi Dezső', 'novel', 'https://mek.oszk.hu/00700/00754/00754.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Pacsirta', 'https://mek.oszk.hu/00700/00754', 'Nem tudná megérteni azt sem, miért fáj úgy minden szava, mintha kést forgatnának szívében, miért oly különös minden észrevétele, az is, hogy kígyóút van a dombon, az is, hogy rododendronok nyílnak a virágágyakban, az is, hogy már <span class="marked">hatkor</span> meggyújtják a lámpát, és szüretre készülődnek.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2753', 'Kosztolányi Dezső', 'novel', 'https://mek.oszk.hu/00700/00754/00754.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Pacsirta', 'https://mek.oszk.hu/00700/00754', 'cifrázta. Soha szebben nem játszott, mint ennek a társaságnak csütörtök estéken. Odaadóan, de tisztes távolból Kárász István felé fordult, olykor rátekintve, olyan tekintettel, melyben közös emlékek szunnyadozhattak. <span class="marked">Egykor</span> a lakodalmán is ő muzsikált, és sok ezres bankót kihegedült zsebéből.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2753', 'Kosztolányi Dezső', 'novel', 'https://mek.oszk.hu/00700/00754/00754.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Pacsirta', 'https://mek.oszk.hu/00700/00754', 'Ez úgy esett meg, hogy felesége, mikor <span class="marked">kilenc óra</span> lett, nyugtalankodni kezdett, mert ebben az időben, mióta eszét tudta, mindig otthon volt már az ura.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2753', 'Kosztolányi Dezső', 'novel', 'https://mek.oszk.hu/00700/00754/00754.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Pacsirta', 'https://mek.oszk.hu/00700/00754', 'mutatkozott. Szaporázta az eső, mosta a nyári portól piszkos kocsikat, bugyborékolt. Néhány zöld láng lobogott a pályatest fölött, az üres sínek messzeségében. Kőszénfüst szállt, a levegőben a kén sátáni szaga érzett. <span class="marked">Fél kilenc</span> elmúlt, de még egyetlen csengettyű sem szólt.', true, '08:30', '08:30', '08:30', 510, 510, 510, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2753', 'Kosztolányi Dezső', 'novel', 'https://mek.oszk.hu/00700/00754/00754.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Pacsirta', 'https://mek.oszk.hu/00700/00754', 'áthálózzák és összekötik, erős kötelékkel. Hordárok dőltek a málhaházban gyalulatlan deszkaládákhoz, melyeken hátrányos ákom-bákomok komorlottak. Vajkayék az indóház üveges tornácán ültek le egy terített asztal mellé. <span class="marked">Kilenc óra</span> után Cifra Géza, kinek megint éjjeli szolgálata volt - úgy látszik, valakit helyettesített -, kilépett az állomásfőnökségtől, melynek kenetlen ajtaja nyikorgott.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2753', 'Kosztolányi Dezső', 'novel', 'https://mek.oszk.hu/00700/00754/00754.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Pacsirta', 'https://mek.oszk.hu/00700/00754', 'mint uráéi, s okkal jobban fájtak, épp érthetetlen, titokzatos voltuknál fogva. Közben pedig így beszéltek: - Jobban vagy? - Jobban. - Hány óra? - Tíz múlt. Tíz után mégis benépesedett az indóház. Elállt az eső, és <span class="marked">negyed tizenegykor</span> várták a gyorsat. A sárszegi értelmiség egyetlen szórakozása az volt, hogy akár érkezett valakije, akár nem, kisétált a vonat elé, hogy szemügyre vegye az utasokat, beleringassa magát pár percig a nagyvárosi élet', true, '10:15', '10:15', '10:15', 615, 615, 615, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2753', 'Kosztolányi Dezső', 'novel', 'https://mek.oszk.hu/00700/00754/00754.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Pacsirta', 'https://mek.oszk.hu/00700/00754', '- Megszöktél, öreg - mondta szemrehányóan -, vén párduc, cserbenhagytál. Hánykor kerültél haza? - Három felé - szólt Ákos. - Akkor kialudtad magad - mondta Környey, beleásítva kesztyűs markába. - Mi valamikor reggel <span class="marked">kilenckor</span> kászolódtunk haza. A tejre mutatott. - Látom azonban, te megint elzüllöttél. - Fáj a fejem - szólt Ákos. - Tanulj tőlem - kacsintott a vén bűnös. - Pincér, egy csizma sört. No, öreg. - Nem, azt már nem merem. Semmit,', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2753', 'Kosztolányi Dezső', 'novel', 'https://mek.oszk.hu/00700/00754/00754.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Pacsirta', 'https://mek.oszk.hu/00700/00754', 'Természetesen követték őt a párducok, vagy tízen, kik a kaszinói kárlátóról jöttek, melyen ma délután <span class="marked">hatkor</span> hideg malacvelőt ettek ecetes uborkával, és jól "bevörösboroztak".', true, '18:00', '18:00', '18:00', 1080, 1080, 1080, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2753', 'Kosztolányi Dezső', 'novel', 'https://mek.oszk.hu/00700/00754/00754.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Pacsirta', 'https://mek.oszk.hu/00700/00754', 'Ebédre korhelylevest, citromos, vöröshagymás kaviárpépet készítettek, egymás után dugaszolták ki az ásványvizes üvegeket meg a söröspalackokat, mert a szeszmérgezés ellenmérge tudvalevően a sör. Csak délelőtt <span class="marked">tizenegykor</span> mentek el pár percre a férjek Priboczayhoz, ki a Mária gyógytárban, mint hű mulatótársuk, régi párduc, szakszerűen gyógykezelte, kikúrálta őket.', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2753', 'Kosztolányi Dezső', 'novel', 'https://mek.oszk.hu/00700/00754/00754.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Pacsirta', 'https://mek.oszk.hu/00700/00754', 'A párducok cihelődtek. Az asszony Füzes Ferinek magyarázta: - Üdülni ment, kérem. - A levegőváltozás - szólt Füzes Feri, mint kellemes társalgó - igen egészséges. - De a vonat annyit késik. Nagyon aggódunk az urammal. <span class="marked">Nyolc óra</span> huszonötkor kellett volna érkeznie, és még most sincs itt.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-2753', 'Kosztolányi Dezső', 'novel', 'https://mek.oszk.hu/00700/00754/00754.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Két évszázad határán', 'https://mek.oszk.hu/08300/08360', 'A történelemre gondolunk, amelyben olyan gyakran előfordult, hogy a belső nehézségek leküzdésére a hatalom kifelé fordította a tekintetét, és meggyőzte az embereket: minden jóra fordul, ha visszaszerezzük mindazt, ami <span class="marked">egykor</span> a miénk volt. Nehézség meg van bőven. Ok is az elkeseredettségre, hiszen oly nagyon eltávolodtak egymástól a szomszédok. Anyagiakban is, de az életről való gondolkodásban is. Micsoda furcsa átok ül rajtunk, ki tudja', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-75840', 'Nagy István Attila', 'essays', 'https://mek.oszk.hu/08300/08360/08360.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Két évszázad határán', 'https://mek.oszk.hu/08300/08360', 'ez a rendőr - kommentálják az esetet a helybeliek -, március 15-én legalább negyven zászló lengett a faluban, mégse szólt senki. De ez új fiú. Nem tudni, meddig bírja itt, mert azért ez már nem a ré gi világ. Reggel <span class="marked">negyed hatkor</span> egymásnak adják a szót a kakasok.', true, '05:15', '05:15', '05:15', 315, 315, 315, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-75840', 'Nagy István Attila', 'essays', 'https://mek.oszk.hu/08300/08360/08360.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Két évszázad határán', 'https://mek.oszk.hu/08300/08360', 'pedig a kegyeit keresték. Nyolc órát töltött a cellában, végre előkerült a tolmács. A vizsgálat vége az lett, hogy ismét kitoloncolták. Hiába tárulkozott ki a vizsgálatot vezető tisztviselőnő előtt, nem segített. Éjjel <span class="marked">tizenegykor</span> ott állt a komp fedélzetén. Tele volt gyűlölettel Veronika, Nagy-Britannia, az angol szó iránt. Értelmetlennek tartotta a helyzetet, ami megfosztotta a lány látásától. Nézte az angolokat és a franciákat. Örültek,', true, '23:00', '23:00', '23:00', 1380, 1380, 1380, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-75840', 'Nagy István Attila', 'essays', 'https://mek.oszk.hu/08300/08360/08360.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Két évszázad határán', 'https://mek.oszk.hu/08300/08360', 'mindig előretekintünk, s nem látjuk, ami a lábunk előtt hever. Át kellett rendeznem a könyvtáramat. Il yenkor minden könyvet egyenként kézbe vesz az ember, megforgatja, belelapoz. Ezt tettem én is. Meglepetten fedeztem <span class="marked">fel egy</span>-egy "új" könyvet az ismerősök között.', true, '00:30', '00:30', '00:30', 30, 30, 30, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-75840', 'Nagy István Attila', 'essays', 'https://mek.oszk.hu/08300/08360/08360.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Két évszázad határán', 'https://mek.oszk.hu/08300/08360', 'Victor Hugo: Nyomorultak című alkotása <span class="marked">fél nyolckor</span> kezdődik. Abban az időpontban, amikor hétvégén a gyerekek egészen biztosan tovább alszanak. A műsorszerkezetből látszik, hogy minden különösebb érdeksérelem nélkül későbbi időpontra is tehető lenne a program, s akkor', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-75840', 'Nagy István Attila', 'essays', 'https://mek.oszk.hu/08300/08360/08360.htm', 'deep_extract', false);
