INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Önéletrajz', 'https://mek.oszk.hu/00500/00518', 'velük. Ez hízelgett nekem, mert nem vettem észre a csapdát; gyanútlanul és hálás szívvel elfogadtam a meghívást. Egy egész pályát bocsátottak rendelkezésemre. A fiúk elmagyarázták a játék szabályait. Hozzátették, hogy <span class="marked">egy óra</span> hosszat játszunk, és aki a legkevesebbszer üt tízet egy óra alatt, az vendégül látja az együttest osztrigára és sörre.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2517', 'Twain Mark', 'biographies', 'https://mek.oszk.hu/00500/00518/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Önéletrajz', 'https://mek.oszk.hu/00500/00518', 'Hozzátették, hogy egy óra hosszat játszunk, és aki a legkevesebbszer üt tízet <span class="marked">egy óra</span> alatt, az vendégül látja az együttest osztrigára és sörre.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2517', 'Twain Mark', 'biographies', 'https://mek.oszk.hu/00500/00518/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Önéletrajz', 'https://mek.oszk.hu/00500/00518', 'Másrészt viszont könyörtelenül szigorú szavakkal illetett, amiért aljas és fortélyos mesterkedéssel rávettem, hogy hencegjen és dicsekedjék a gyatra játékával egy profi jelenlétében, aki kezdőnek hazudja magát, pedig <span class="marked">egy óra</span> alatt több golyót tud a biliárdasztal lyukaiba taszítani, mint amennyit ő egy nap alatt a papírkosárba dobna.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2517', 'Twain Mark', 'biographies', 'https://mek.oszk.hu/00500/00518/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Önéletrajz', 'https://mek.oszk.hu/00500/00518', 'a szerencse - addig üssem a vasat, amíg meleg! -, törjek be az előadók közé. Így is történt. Meghirdettem egy előadást a Sandwich szigetekről, és a hirdetményt ezzel fejeztem be: "Beléptidíj egy dollár. A termet <span class="marked">fél nyolckor</span> nyitják, a hecc nyolckor kezdődik.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2517', 'Twain Mark', 'biographies', 'https://mek.oszk.hu/00500/00518/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Önéletrajz', 'https://mek.oszk.hu/00500/00518', 'A termet fél nyolckor nyitják, a hecc <span class="marked">nyolckor</span> kezdődik. " Én próféta lelkem! A hecc valóban megkezdődött nyolckor, amikor életemben először talál tam magamat a közönség előtt, mert tetőtől talpig átjárt és megbénított a félelem. Két percig tartott ez az állapot:', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2517', 'Twain Mark', 'biographies', 'https://mek.oszk.hu/00500/00518/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Önéletrajz', 'https://mek.oszk.hu/00500/00518', 'Meghirdettem egy előadást a Sandwich szigetekről, és a hirdetményt ezzel fejeztem be: "Beléptidíj egy dollár. A termet fél nyolckor nyitják, a hecc nyolckor kezdődik. " Én próféta lelkem! A hecc valóban megkezdődött <span class="marked">nyolckor</span>, amikor életemben először talál tam magamat a közönség előtt, mert tetőtől talpig átjárt és megbénított a félelem.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2517', 'Twain Mark', 'biographies', 'https://mek.oszk.hu/00500/00518/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Önéletrajz', 'https://mek.oszk.hu/00500/00518', '1868 tavaszának háromezer szava nyolc-<span class="marked">kilenc óra</span> alatt egyáltalán nem több, mint a mai teljesítményem, amikor félannyi idő alatt feleannyit írok együltőhelyemben.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2517', 'Twain Mark', 'biographies', 'https://mek.oszk.hu/00500/00518/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Önéletrajz', 'https://mek.oszk.hu/00500/00518', 'hogy a gondviselés lépjen közbe. Már éppen indulni készültem New Yorkba. A soküléses bérkocsi ott állt a kapunál, rajta a csomagom. Barney, a kocsis, már a bakon ült és a gyeplőt fogta. Sötét volt: este nyolc vagy <span class="marked">kilenc óra</span>. Búcsút vettem a tornácon összegyűlt családtól; Charleyval együtt kimentünk, és beszálltunk a kocsiba. Elhelyezkedtünk a kocsis háta mögött az üres üléseken, a kocsi hátulján; ezeket az üléseket csak ideiglenesen', true, '21:00', '21:00', '21:00', 1260, 1260, 1260, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2517', 'Twain Mark', 'biographies', 'https://mek.oszk.hu/00500/00518/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Önéletrajz', 'https://mek.oszk.hu/00500/00518', 'az ügy befejeződött. A csengő többé nem szólalt meg. - Azt hiszem, csalódott a jóember - jegyeztem meg röviden. - Elment a zöldséggel és a csecsebecsékkel, de érzésem szerint nagyon elégedetlen. Elaludtunk, és reggel <span class="marked">háromnegyed nyolckor</span> lerohantam, hogy elérjem a 8.29-es vonatot New Yorkba.', true, '07:45', '07:45', '07:45', 465, 465, 465, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2517', 'Twain Mark', 'biographies', 'https://mek.oszk.hu/00500/00518/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Önéletrajz', 'https://mek.oszk.hu/00500/00518', 'Elaludtunk, és reggel háromnegyed nyolckor lerohantam, hogy elérjem a <span class="marked">8.29</span>-es vonatot New Yorkba. Az egész földszinten égett a gázvilágítás. Az új kabátom és az ócska esernyőm eltűnt, valamint a vadonatúj finom cipőm is. A tornácra nyíló nagy hátsó ablak tárva-nyitva állt. Kiléptem rajta, és', true, '08:29', '08:29', '08:29', 509, 509, 509, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2517', 'Twain Mark', 'biographies', 'https://mek.oszk.hu/00500/00518/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Önéletrajz', 'https://mek.oszk.hu/00500/00518', 'is szántam neki. 35 A világ sokat veszít az illem követelményei miatt - nyer is vele, de azért sokat veszít. Ezt bizonyítja a következő történet. Egyszer Bostonba indultam a lelkészünkkel s egyben régi barátommal. Este <span class="marked">kilenckor</span> már tizenkét órája úton voltunk, majdnem harminc mérföldet tettünk meg; félholt voltam a fáradtságtól és a hidegtől.', true, '21:00', '21:00', '21:00', 1260, 1260, 1260, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2517', 'Twain Mark', 'biographies', 'https://mek.oszk.hu/00500/00518/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Önéletrajz', 'https://mek.oszk.hu/00500/00518', 'ajánlotta, hogy vegyek részvényeket. Nekem semmi áron nem kellettek. Tűzbe jött. Arra kért, hogy csak ötszáz dollárért vegyek belőle: annyi részvényt ad ötszáz dollárért, amennyit akarok. Felajánlotta, hogy markoljak <span class="marked">fel egy</span> csomót, és töltsünk meg vele egy kalapot: odaadja az egész kalapra valót ötszázért.', true, '00:30', '00:30', '00:30', 30, 30, 30, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2517', 'Twain Mark', 'biographies', 'https://mek.oszk.hu/00500/00518/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Önéletrajz', 'https://mek.oszk.hu/00500/00518', 'A megsemmisülés nem kelt bennem rettegést, hiszen kipróbáltam már, mielőtt megszülettem - százmillió éven át -, és ebben az életben többet szenvedtem <span class="marked">egy óra</span> alatt, mint amennyit emlékezetem össze tud szedni az egész korábbi százmillió évről.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2517', 'Twain Mark', 'biographies', 'https://mek.oszk.hu/00500/00518/html/01.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Önéletrajz', 'https://mek.oszk.hu/00500/00518', 'Indiába: abba az egyetlen idegen országba, amelyről ébren is álmodom, s amelyet szívből vágyom újra látni. 46 A Washington Square egyik padján következett be legtartalmasabb találkozásom Louis Stevensonnal. Több mint <span class="marked">egy óra</span> hosszat levegőztünk: nag yon kellemes és meghitt találkozás volt.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2517', 'Twain Mark', 'biographies', 'https://mek.oszk.hu/00500/00518/html/02.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Önéletrajz', 'https://mek.oszk.hu/00500/00518', 'Naponta kétszer-háromszor tölthettem egy-egy negyedórát a beteg szobájában, legkésőbb este hétkor, sőt még azt is megengedték, hogy <span class="marked">kilenckor</span> belépjek egy pillanatra jó éjszakát kívánni.', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2517', 'Twain Mark', 'biographies', 'https://mek.oszk.hu/00500/00518/html/02.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Önéletrajz', 'https://mek.oszk.hu/00500/00518', 'megveszem, ha kedve van hozzá, és rögtön átköltöztetjük, amint el tudja viselni az utazást. Tetszett neki: örült. S az arca - az utóbbi hetekben oly hófehér, márványfehér arca - ragyogott. 1904. június 5. Vasárnap este <span class="marked">11 óra 15 perc</span>. Két órája halott. Lehetetlen. A szavaknak nincs értelme. De igazak; tudom, anélkül, hogy felfognám. Az életem volt, és most elhagyott; a kincsem volt, és most koldus vagyok. Milyen hirtelen, milyen váratlanul történt!', true, '11:15', '11:15', '11:15', 675, 675, 675, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2517', 'Twain Mark', 'biographies', 'https://mek.oszk.hu/00500/00518/html/02.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Önéletrajz', 'https://mek.oszk.hu/00500/00518', 'értettem. Csak néztem rá és csodálkoztam - és nem is képzeltem, hogy mi történt! Akkor Clara megszólalt: - Ez igaz? Katy, ez igaz? Nem lehet igaz! - Katy zokogásba tört ki, és akkor én is megértettem. Húsz perccel múlt <span class="marked">kilenc óra</span>. Öt perccel azelőtt még beszélt. Hallott engem, és azt mondta az ápolónőnek: - Altatódalt énekel nekem. Nem is gondoltak rá, hogy a halálához közeledik. Boldog volt és beszélt - s egy pillanat alatt eltávozott ebből az', true, '09:00', '09:00', '09:00', 540, 540, 540, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2517', 'Twain Mark', 'biographies', 'https://mek.oszk.hu/00500/00518/html/02.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Önéletrajz', 'https://mek.oszk.hu/00500/00518', 'Az utolsó négy hónap alatt ötször is volt kínos légszomja - <span class="marked">egy óra</span> hosszat, vagy még tovább is tartott -, s az a szörnyű félelem gyötörte, hogy fulladásos halál vár rá.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2517', 'Twain Mark', 'biographies', 'https://mek.oszk.hu/00500/00518/html/02.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Önéletrajz', 'https://mek.oszk.hu/00500/00518', 'A kérésnek örömmel tettem eleget, mert Mr. Bryce-t jó néhány esztendeje ismerem, főként vendégszerető londoni asztalánál találkoztam vele, és nemcsak tisztelem és nagyra becsülöm, hanem csodálom is. Vártam is rá <span class="marked">egy óra</span> hosszat, de aztán föl kellett adnom a dolgot, bár ez az egy óra nem telt el rosszul, mert Andrew Carnegie, bármilyen régen ismerem is, még sohasem bizonyult érdektelen megfigyelési alanynak, s tegnap meg éppen elemében találtam.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2517', 'Twain Mark', 'biographies', 'https://mek.oszk.hu/00500/00518/html/02.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Önéletrajz', 'https://mek.oszk.hu/00500/00518', 'Vártam is rá egy óra hosszat, de aztán föl kellett adnom a dolgot, bár ez az <span class="marked">egy óra</span> nem telt el rosszul, mert Andrew Carnegie, bármilyen régen ismerem is, még sohasem bizonyult érdektelen megfigyelési alanynak, s tegnap meg éppen elemében találtam.', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2517', 'Twain Mark', 'biographies', 'https://mek.oszk.hu/00500/00518/html/02.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Önéletrajz', 'https://mek.oszk.hu/00500/00518', 'ünnepi vacsorákon, de ezek a frakkok gyakran inkább ingatlanok, mint személyes ingóságok; annyi por tapad rájuk, hogy magot lehetne vetni beléjük, és gabonát termeszteni rajtuk. 57 Stormfield, 1909. dec. 24. de. <span class="marked">11 óra</span> Jean meghalt! Próbálta már valaki leírni minden apró eseményét annak a huszonnégy órának, amely egy drága hozzátartozója hirtelen és váratlan halálát megelőzte? Beleférne egyetlen könyvbe? Beleférne két könyvbe? Nem', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2517', 'Twain Mark', 'biographies', 'https://mek.oszk.hu/00500/00518/html/02.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Önéletrajz', 'https://mek.oszk.hu/00500/00518', 'és még elkapnád. - Lehajoltam, és megcsókoltam a kezét. Meghatódott - láttam a szemén -, és viszonzásul hirtelen megcsókolta a kezemet. Ezután a szokásos: - Aludj jól, kedves! felkiáltással elváltunk. Ma reggel <span class="marked">fél nyolckor</span> ébredtem, és hangokat hallottam az ajtóm előtt.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2517', 'Twain Mark', 'biographies', 'https://mek.oszk.hu/00500/00518/html/02.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Önéletrajz', 'https://mek.oszk.hu/00500/00518', 'arcra, amelyet úgy szeretett, aztán kiment, éppoly némán, mint ahogyan érkezett. Szóval tudja. A délután kellős közepén havazni kezdett. Milyen kár, hogy Jean nem láthatja! Nagyon szerette a havat. Nem szűnt a havazás. <span class="marked">Hat órakor</span> megérkezett a halottaskocsi, és elvitte szomorú terhét.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2517', 'Twain Mark', 'biographies', 'https://mek.oszk.hu/00500/00518/html/02.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Önéletrajz', 'https://mek.oszk.hu/00500/00518', 'akivel együtt játszottak kicsi korukban, és szeretett öreg Katyje vezette el távoli, gyermekkori otthonába, ahol ismét édesanyja oldalán fekszik majd, Susy és Langdon társaságában. December 26. - A kutya reggel <span class="marked">nyolckor</span> meglátogatott. Szegény árva, nagyon gyöngéd volt! Ezután az én szobám lesz a tanyája. A vihar egész éjszaka dühöngött; tombolt egész délelőtt. A hó hatalmas felhőkben száll a táj fölött, csodálatos, fenséges - és nincs', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus világirodalom"}', 'urn:nbn:hu-2517', 'Twain Mark', 'biographies', 'https://mek.oszk.hu/00500/00518/html/02.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Kötéltánc', 'https://mek.oszk.hu/06900/06983', 'mellékutcák irányában szertefutkostak. Távolról recsegő hangok, üvöltés, valami durv a és egyenletes ütemre, mintha gyülevész csapat közeledne. Egy lövés dördült el. III A nagy, politikai fordulat délelőttje volt. <span class="marked">Tizenegy órakor</span>, a Horosek-klinika egyik folyosóján: - Jertek fel hozzám, - mondta Tölgy doktor.', true, '11:00', '11:00', '11:00', 660, 660, 660, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-10102', 'Karinthy Frigyes', 'short novel', 'https://mek.oszk.hu/06900/06983/06983.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Kötéltánc', 'https://mek.oszk.hu/06900/06983', 'és világosan feküdt előtte az álombéli út. Kinyitotta hát lelkét a zsongító, édes benyomásoknak: ismét felhangzott az emberi zaj, kocsik zörögtek, jártak a villamosok, a sarkon virágot árultak. Megnézte az óráját, <span class="marked">fél hat</span> volt, sietnie kellett. Régi dal kísértett fel fülében, gyermekes szövegű chanson, azt kezdte dúdolni. Hétre pontosan szállására ért. A nagy szállodaszoba a folyosóra nyílt, kinyitotta a terasz ajtaját, lámpát gyújtott', true, '05:30', '05:30', '05:30', 330, 330, 330, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-10102', 'Karinthy Frigyes', 'short novel', 'https://mek.oszk.hu/06900/06983/06983.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Kötéltánc', 'https://mek.oszk.hu/06900/06983', 'kellett. Régi dal kísértett fel fülében, gyermekes szövegű chanson, azt kezdte dúdolni. Hétre pontosan szállására ért. A nagy szállodaszoba a folyosóra nyílt, kinyitotta a terasz ajtaját, lámpát gyújtott odakint. <span class="marked">Fél nyolckor</span> a földszintről telefonáltak, hogy egy hölgy keresi, sürgősen beszélni óhajt vele.', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-10102', 'Karinthy Frigyes', 'short novel', 'https://mek.oszk.hu/06900/06983/06983.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Kötéltánc', 'https://mek.oszk.hu/06900/06983', 'a táborba, az árkokból jött egyenesen. Testőrsége már berendezte a betonsátrat fogadására, őrjáratok cirkáltak mindenfelé. Kalp István, aki parancs szerint itt kellett, hogy bevárja, már-már azt hitte, nem érkezik meg. <span class="marked">Hat óra</span> v olt, s az alkonyattalan afrikai éjszaka, mint valami színpadi fogás, hirtelen kioltotta a napot.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-10102', 'Karinthy Frigyes', 'short novel', 'https://mek.oszk.hu/06900/06983/06983.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Kötéltánc', 'https://mek.oszk.hu/06900/06983', 'és mégis volt az egészben valami erőltetett, természetellenes. Kalp Istvánban nyugtalan utóérzés támadt. Félni kezdett: szerette volna már, ha a parancsnok itt van. Sötét lett odakint, és a tábor elcsendesedett. <span class="marked">Nyolc órakor</span> lefeküdt. Még az ágyba is magával vitt néhány iratot, hogy elűzze a rossz gondolatokat. De az afrikai éj erősebb volt, valami zúgott, és valami zengett, azután, messziről, egészen halkan, szinte derülten, fojtott, mély', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-10102', 'Karinthy Frigyes', 'short novel', 'https://mek.oszk.hu/06900/06983/06983.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Kötéltánc', 'https://mek.oszk.hu/06900/06983', 'óriási betűkkel hirdették már, hogy Raganza megérkezett. A város pillanatra megkönnyebbült. Az optimisták hinni kezdtek már, sőt nyíltan hirdették, hogy minden rendbe jött, a forradalmat sikerült csírájában elfojtani. <span class="marked">Nyolc órakor</span> izgatott csoportok jelentek meg a városháza előtt, kézzel-lábbal magyarázva az eseményeket.', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-10102', 'Karinthy Frigyes', 'short novel', 'https://mek.oszk.hu/06900/06983/06983.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Kötéltánc', 'https://mek.oszk.hu/06900/06983', 'valaha. Senki nem kételkedett benne, hogy véglegesen és visszavonhatatlanul felül került. A szeme friss volt, megfiatalodott, a Tanács így látta őt, egész délután, mialatt a forradalmárok büntetésének ügyét tárgyalták. <span class="marked">Hat órakor</span> kocsiba ült, hogy felkeresse Ernát.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-10102', 'Karinthy Frigyes', 'short novel', 'https://mek.oszk.hu/06900/06983/06983.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Kötéltánc', 'https://mek.oszk.hu/06900/06983', 'Igen, ők azok, igazad van, holnap reggel <span class="marked">hat órakor</span> ebben az épületben. Csavargók csatlakoznak a menet hez, vitatkoznak, az épületben összeszedi bátorságát, és kérdez valamit az egyik katonától. A katona komoran néz maga elé, és nem felel. Erre maguk közt kezdenek', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Klasszikus magyar irodalom"}', 'urn:nbn:hu-10102', 'Karinthy Frigyes', 'short novel', 'https://mek.oszk.hu/06900/06983/06983.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Vastag sapka', 'https://mek.oszk.hu/02800/02838', 'hogy minden más ruhája csak másodrendű öltözéknek minősült, úgy nézett ezekre a másodrendű ruhákra a szekrényben, mint valami ételmaradékokra, a melyek csak a legvadabb éhség esetén kerülhetnek szóba. A munkaidő <span class="marked">nyolc órakor</span> kezdődött, s a fantasztikus pulóver fél nyolckor még olyan nedves volt, hogyha aki azt felveszi, úgy átfázik és átnedvesedik az utcai hidegben, amíg beér a munkahelyére, hogy már előre jelezheti a betegszabadságot, a', true, '08:00', '08:00', '08:00', 480, 480, 480, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4817', 'Podmaniczky Szilárd', 'short stories', 'https://mek.oszk.hu/02800/02838/02838.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Vastag sapka', 'https://mek.oszk.hu/02800/02838', 'A munkaidő nyolc órakor kezdődött, s a fantasztikus pulóver <span class="marked">fél nyolckor</span> még olyan nedves volt, hogyha aki azt felveszi, úgy átfázik és átnedvesedik az utcai hidegben, amíg beér a munkahelyére, hogy már előre jelezheti a betegszabadságot, a munkaerő-kiesést, előre bevásárolhatja a majdani', true, '07:30', '07:30', '07:30', 450, 450, 450, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4817', 'Podmaniczky Szilárd', 'short stories', 'https://mek.oszk.hu/02800/02838/02838.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Vastag sapka', 'https://mek.oszk.hu/02800/02838', 'megpróbálni? - Drága asszonyom, ne pazarolja rám az idejét, inkább fürödjék egyet. A skandináv rejtvények engemet tökéletesen kielégítenek. - Hát jól van - mondta az asszony, és nekibátorodott a mellúszásnak. Már közel <span class="marked">hat óra</span> volt, mikor az asszony ismét a kabinos elé lépett, és mondta, szeretne átöltözni.', true, '06:00', '06:00', '06:00', 360, 360, 360, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4817', 'Podmaniczky Szilárd', 'short stories', 'https://mek.oszk.hu/02800/02838/02838.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Vastag sapka', 'https://mek.oszk.hu/02800/02838', 'Ja? Jó, írjunk ilyet. Most már sok az időpont. El se als zom, csak az éjfél jönne már. Eltéveszt? Tíz óra. Kétszer. Most melyik? Hol volt a gyilkosság? A hamis paplakban. Húzzál el egy békacombot az orrom előtt. <span class="marked">Egy óra</span>. Ismétlés. Fogtam a porpisztolyt és a tévére fogtam. Időnként felolvasom a Bibliát. Hát azt én nem tudom. Itt nincsen, nem látom. Ó, édes. A rádiót nézzük? Legalábbis én nem. Na várjunk csak! Hol a középcsatár? El se', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4817', 'Podmaniczky Szilárd', 'short stories', 'https://mek.oszk.hu/02800/02838/02838.htm', 'deep_extract', false);
INSERT INTO entries (title, link, snippet, is_literature, time_min_str, time_max_str, time_focus_str, time_min_m, time_max_m, time_focus_m, categories, urn, author, genre, source_url, source_type, is_fallback) VALUES ('Vastag sapka', 'https://mek.oszk.hu/02800/02838', 'esznek, itt meg gyerek alatt puhítják a húst. Hányat álmodok, ha elalszom egy indigón? Früstök. Lehet, hogy már közben izé. Húzok akkor egyet. Ebből húznom kell. A piros ceruza meg még mindig nálam van. Faragatlan. <span class="marked">Egy óra</span>, szétesek. Funkciós bordal. 21 után 24 jön. Messze van a hegy, de addig elmászok. Pro-kontyra. Megvigasztalom azt, aki vérmérgezést kapott. Teljesen lehullott a fáknak a lombja, kopaszak, mint egy egér. Egy gyöngébb', true, '01:00', '01:00', '01:00', 60, 60, 60, '{"Szépirodalom, népköltészet","Kortárs magyar irodalom"}', 'urn:nbn:hu-4817', 'Podmaniczky Szilárd', 'short stories', 'https://mek.oszk.hu/02800/02838/02838.htm', 'deep_extract', false);
